/* हवलदारनी — निःशुल्क पूर्वावलोकन (आवरण, शीर्षक पृष्ठ, अंतराल और अध्याय 1–31) */
window.chaptersData = [{"chapter": 0, "title": "हवलदारनी", "content": "<div class=\"kr-cover\"><img src=\"cover-hi.jpg\" alt=\"हवलदारनी — पुस्तक का आवरण\"></div>"}, {"chapter": 0, "title": "शीर्षक पृष्ठ", "content": "<div class=\"tp\"><h3>हवलदारनी</h3>\n<h3><i>एक जवाब, बहुत देर से</i></h3>\n<h3>एक उपन्यास</h3>\n<p class=\"bold-line\"><b>शारदा अशोक यदुवंशी</b></p>\n<p class=\"scenebreak\">***</p>\n<p>हवलदारनी: एक जवाब, बहुत देर से</p>\n<p>कॉपीराइट © शारदा अशोक यदुवंशी, 2026</p>\n<p>सर्वाधिकार सुरक्षित। यह एक काल्पनिक रचना है। इसके नाम, पात्र, स्थान और घटनाएँ लेखिका की कल्पना से उपजे हैं या काल्पनिक रूप में इस्तेमाल किए गए हैं। किसी भी जीवित या मृत व्यक्ति, घटना या स्थान से कोई समानता केवल संयोग है।</p>\n<p>लेखिका की लिखित अनुमति के बिना इस पुस्तक का कोई भी अंश किसी भी रूप में, फ़ोटोकॉपी, रिकॉर्डिंग या किसी भी इलेक्ट्रॉनिक या यांत्रिक माध्यम से, पुनः प्रकाशित, वितरित या प्रसारित नहीं किया जा सकता; समीक्षा में दिए गए छोटे उद्धरण इसके अपवाद हैं।</p>\n<p class=\"scenebreak\">***</p>\n<p><i>उन सबके नाम,<br>जिनकी लड़ाई सरहद पर नहीं,<br>आँगन में लड़ी गई—</i></p>\n<p><i>फ़ौजियों की माँएँ, पत्नियाँ, बच्चे,<br>और वे प्रेमिकाएँ,<br>जो किसी गिनती में नहीं आईं।</i></p>\n<p><i>जिनके अपने लौट आए,<br>और जिनके कभी नहीं लौटे।</i></p>\n<p class=\"scenebreak\">***</p>\n<p><i>ग्यारह साल तक नैना यही मानती रही कि एक वादा टूट गया था।</i></p>\n<p><i>वह इक्कीस साल की थी, जब सरहद से आई पंद्रह दिन की चुप्पी उससे सही नहीं गई, और उसने अपने ख़ून से तीन पंक्तियाँ लिखीं: मैं इंतज़ार कर रही हूँ। तुमने वादा किया है कि लौटोगे। ज़िंदा लौटना, विक्रम।</i></p>\n<p><i>विक्रम लौटा। पर वह ज़िंदगी नहीं लौटी जो दोनों ने साथ चाही थी, और उन तीन पंक्तियों का जवाब कभी लिखकर नहीं आया।</i></p>\n<p><i>ग्यारह साल बाद, फ़रवरी की एक साधारण शाम, एक छोटी-सी दुकान में एक किताब उसे रोक लेती है। उसे हाथ में लेते ही, बिना किसी वजह के, उसके भीतर सब कुछ एक पल के लिए थम जाता है, जैसे बारिश से ठीक पहले हवा साँस रोक लेती है।</i></p>\n<p><i>और उस किताब में उसे अपना ही ख़त मिलता है। वही तीन पंक्तियाँ, वही लिखावट, जो उसने ग्यारह साल पहले अपने ख़ून से लिखकर सिर्फ़ एक इंसान को भेजी थीं।</i></p>\n<p><i>वह ख़त यहाँ तक कैसे पहुँचा?</i></p>\n<p><i>एक जवाब, बहुत देर से।</i></p>\n<p><i>हर उस दिल के लिए, जिसने कभी सच्चा प्यार किया, और फिर चुपचाप इंतज़ार किया।</i></p>\n<p class=\"scenebreak\">***</p></div>"}, {"chapter": 1, "title": "अंतराल — कहीं, एक फाइल पहले ही खुल चुकी थी", "content": "<h1>अंतराल — कहीं, एक फाइल पहले ही खुल चुकी थी</h1>\n<p>उसके करीब रहने वाले लोगों को उसकी ज़िंदगी की पूरी तस्वीर समझ आने से बहुत पहले, दिल्ली के किसी और हिस्से में, एक अलग कमरे में, विक्रम राठौड़ की ज़िंदगी से जुड़े कुछ फ़ैसले लिए जाने शुरू हो चुके थे—उसकी जानकारी के बिना।</p>\n<p>एक मेज़ के दो ओर दो आदमी बैठे थे। उनके बीच एक पतली-सी फाइल रखी थी। ऊपर जलती फ्लोरोसेंट रोशनी भी उस कमरे की सोची-समझी सादगी को कम नहीं कर पा रही थी—एक ऐसा गुमनाम-सा दफ़्तर, जिसके बाहर कोई तख़्ती नहीं थी, और जिसकी मौजूदगी का कोई परिचय नहीं दिया जाता था।</p>\n<p>बरसों बाद भी विक्रम ख़ुद कभी नहीं जान पाएगा कि ऐसी कोई बैठक हुई थी।</p>\n<p>दोनों में वरिष्ठ अधिकारी की उम्र साठ के पार थी। चाँदी जैसे बाल अब भी उसी पुराने फौजी अंदाज़ में छोटे कटे हुए थे, जिसे उसने कभी पूरी तरह छोड़ा नहीं था। उसके भीतर एक ऐसी स्थिरता थी, जो दशकों तक हर कमरे में सबसे धैर्यवान आदमी बने रहने के बाद ही आती है।</p>\n<p>उसके बगल में उससे कम उम्र का एक आदमी बैठा था—इतना साधारण कि भीड़ में किसी की नज़र उस पर दोबारा न पड़े। और यही साधारण दिखना उसके काम ने उसे धीरे-धीरे सिखाया था।</p>\n<p>उस कमरे के लिए, और उसके बाद ऐसे हर कमरे के लिए, उसका नाम था—कामथ।</p>\n<p>“कैप्टन विक्रम राठौड़।”</p>\n<p>वरिष्ठ अधिकारी ने एक तस्वीर मेज़ पर उसकी ओर सरका दी।</p>\n<p>“इसकी पूरी पृष्ठभूमि खंगालो। सिर्फ सर्विस रिकॉर्ड नहीं—निजी ज़िंदगी भी।”</p>\n<p>वह एक पल रुका।</p>\n<p>“और उसके बाद इस पर चुपचाप नज़र बनाए रखना। मैं ठीक-ठीक जानना चाहता हूँ कि यह आदमी आगे चलकर क्या बनता है—इससे बहुत पहले कि हम कभी इसे यह बताएँ कि हम इसे देख रहे हैं… या क्यों।”</p>\n<p>“जी, सर।”</p>\n<p>कामथ ने अपनी नोटबुक की ओर हाथ बढ़ाते हुए कहा।</p>\n<p>हालाँकि उस समय वह ख़ुद भी नहीं जानता था कि आख़िर वे विक्रम में तलाश क्या रहे थे।</p>\n<p>उस दिन उन दोनों ने विक्रम राठौड़ के बारे में फिर कोई बात नहीं की।</p>\n<p>लेकिन उसका नाम उन रास्तों पर चलना शुरू कर चुका था, जिन्हें किसी बाहरी आदमी की नज़र के लिए बनाया ही नहीं गया था।</p>\n<p>और कहीं बहुत दूर—इन सब घटनाओं से अभी कई वर्ष पहले खड़ा—विक्रम राठौड़ नाम का एक युवा सैनिक इस बात से पूरी तरह अनजान था कि उसकी ज़िंदगी अब चुपचाप केवल उसकी अपनी नहीं रह गई थी।</p>\n<p>और यह समझने में कि आख़िर ऐसा क्यों हुआ था—</p>\n<p>अभी कई साल बाकी थे।</p>"}, {"chapter": 2, "title": "अध्याय 1 — पीतल की ट्रे", "content": "<h1>अध्याय 1 — पीतल की ट्रे</h1>\n<p>उसने उसे देखा ही नहीं। कम-से-कम उस रात तो नहीं।</p>\n<p>इक्कीस वर्ष का विक्रम राठौड़ उस विवाह में बस एक बाराती था। सामने अग्नि जल रही थी—हर फेरे के साथ उसकी लौ हवा में झुकती और फिर सीधी हो जाती—और उसी रोशनी में लाल-सुनहरे जोड़े में सजी एक अनजान लड़की किसी और के साथ फेरे ले रही थी। उसके लिए वह भी उस भीड़ का ही एक चेहरा थी—इतना अनजान कि कुछ देर बाद याद भी न रहता।</p>\n<p>उसे क्या मालूम था कि यही अनजान चेहरा एक दिन उसे भीतर से इस तरह तोड़कर रख देगा, जिसके लिए कोई ट्रेनिंग उसे तैयार नहीं कर पाई थी।</p>\n<p>उन दिनों विक्रम सेना से छुट्टी पर घर आया हुआ था। विश्वविद्यालय की ओर से तीन साल कबड्डी खेलकर उसका शरीर पहले ही गठ चुका था; फौज ने उसमें बस एक कसाव और जोड़ दिया था। लंबा कद, चौड़े कंधे, छरहरा बदन, गोरा रंग और गहरी, ठहरी हुई आँखें—जो सामने वाले को देखती पूरी थीं, मगर अपने भीतर झाँकने की जगह बहुत कम देती थीं।</p>\n<p>शादी में कई निगाहें उसकी ओर उठीं, कुछ लौट-लौटकर भी आईं। विक्रम को इसका भान तक नहीं हुआ।</p>\n<p>वर्दी उस शाम उसने पहन नहीं रखी थी, पर कुछ वर्दियाँ शरीर से उतर जाने के बाद भी आदमी के साथ चलती रहती हैं।</p>\n<p>शादी कविता के गाँव कोसली में थी। बादशाहपुर से पटौदी रोड होते हुए करीब सत्तर किलोमीटर का रास्ता था और पहुँचते-पहुँचते लगभग दो घंटे लग गए थे।</p>\n<p>हाईवे से कुछ पीछे, ढाबों की कतार के पार मैरिज हॉल था—टीन की छत वाली साधारण-सी इमारत, जिसकी चारदीवारी पर नंगे बल्बों की झालर लटक रही थी। आधे बल्ब शाम पूरी होने से पहले ही बुझ चुके थे, और बाकी हवा के हर झोंके पर काँपते हुए जैसे अपनी बारी का इंतज़ार कर रहे थे।</p>\n<p>अंदर लकड़ी के ऊँचे चबूतरे पर मंडप सजा था। लाल कपड़े से ढके खंभों पर गेंदे की मालाएँ लटक रही थीं, जिनकी पंखुड़ियाँ रस्मों के शुरू होने से पहले ही किनारों से मुरझाकर भूरी पड़ने लगी थीं।</p>\n<p>गाँव का दोस्त चौधरी उसके साथ आया था। उसने बुफे के पास अपने और विक्रम के बैठने की जगह ढूँढ़ ली।</p>\n<p>गर्म घी और सरसों के तड़के की महक खाने से पहले ही उन तक पहुँच गई थी। स्टील की प्लेटें थीं; दाल, जीरा चावल, गरम लैंपों के नीचे रखा शाही पनीर, तंदूर से लगातार आती रोटियाँ, छोले, कचूमर और एक ओर करीने से रखी पूरियाँ।</p>\n<p>विक्रम ने बिना ज़्यादा ध्यान दिए प्लेट में खाना ले लिया।</p>\n<p>बैठने के बाद खाने में भी उसका कोई खास मन नहीं लगा। बीच-बीच में उसकी निगाह भीड़ के पार मंडप की ओर चली जाती—किसी आकर्षण से नहीं, बस यूँ ही।</p>\n<p>दुल्हन अग्नि के सामने बैठी थी। लौ की सुनहरी काँप उसके झुके चेहरे पर आती-जाती रही, और वह गहनों के बोझ तले, रस्मों के बीच, पूरी तरह शांत थी।</p>\n<p>उसकी शादी विक्रम के ही गाँव के एक लड़के से हो रही थी। गाँव का रिश्ता था, इसलिए आना लगभग तय था; वरना साझा उपनाम के अलावा विक्रम दूल्हे को भी मुश्किल से जानता था।</p>\n<p>उसने दुल्हन को देखा और कुछ महसूस नहीं किया।</p>\n<p>न कोई उत्सुकता।</p>\n<p>न कोई आकर्षण।</p>\n<p>यहाँ तक कि वह साधारण जिज्ञासा भी नहीं, जो किसी अनजान चेहरे को देखकर कुछ क्षण के लिए ठहर जाती है।</p>\n<p>उसने खाना ख़त्म किया, दोबारा मिठाई लेने गया और बाकी समय चौधरी की उन लोगों पर चलती टिप्पणियाँ आधे मन से सुनता रहा, जिन्हें दोनों इतनी अच्छी तरह जानते भी नहीं थे कि उन पर इतनी चर्चा की जाए।</p>\n<p>कई महीने बाद उसे समझ आना था कि उस शाम उसकी आँखों से क्या छूट गया था।</p>\n<p>अग्नि के चारों ओर लाल-सुनहरे जोड़े में फेरे लेती वही स्त्री, जिसे उस रात उसने ठीक से देखा तक नहीं था, एक दिन गाँव के एक आँगन में उसके सामने चाय की ट्रे लिए खड़ी होगी—</p>\n<p>बस एक पल ज़्यादा।</p>\n<p>और वही एक पल उस उदासीनता में पहली दरार डालेगा।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>शादी के बाद कविता बादशाहपुर आ गई।</p>\n<p>मध्यम कद, छरहरा शरीर और ऐसा व्यक्तित्व कि राह चलते किसी की निगाह अनायास उठ जाए। रंग साफ़ था, मगर सबसे पहले ध्यान उसकी आँखों पर जाता—हल्की नीली-सलेटी, जैसे बारिश से ठीक पहले का आसमान। हरियाणा के उस इलाके में उनका रंग इतना असामान्य था कि शादी में भी लोगों के बीच उनकी चर्चा हुई थी।</p>\n<p>लेकिन उनकी खूबसूरती से अलग भी उनमें कुछ था—एक तेज़, परखती हुई नज़र। कमरे में दाखिल होते ही जैसे वह बोलने से पहले वहाँ मौजूद लोगों और माहौल को पढ़ लेती हो।</p>\n<p>कमर से नीचे तक आते घने बालों में तेल लगाकर वह लंबी चोटी बाँधती थी, जैसे गाँव की अधिकतर नई बहुएँ बाँधती थीं। फिर भी उस सादगी में वह साधारण नहीं लगती थी—जैसे मिट्टी के साधारण दीये में जलती कोई सीधी, ऊँची लौ।</p>\n<p>पीठ सीधी। ठोड़ी सहज ही कुछ ऊँची।</p>\n<p>उसे देखकर कई बार नई-नई ब्याही लड़की से अधिक ऐसी स्त्री का आभास होता था, जो ऐसे जीवन की प्रतीक्षा में हो, जो अब तक आया ही नहीं।</p>\n<p>शादी के कुछ ही महीने बाद विक्रम अगली छुट्टी पर गाँव लौटा।</p>\n<p>और उसी छुट्टी में उसने पहली बार रामफल के घर जाने की एक वजह ढूँढ़ ली।</p>\n<p>उसके पिता के लिए कोई संदेश था, ज़मीन के किसी काग़ज़ की बात थी—ऐसा काम जो चाहें तो अगले दिन तक भी रुक सकता था।</p>\n<p>लेकिन विक्रम ने ख़ुद से यह सवाल ही नहीं किया कि उसे उसी दिन जाना क्यों ज़रूरी लगा।</p>\n<p>कविता बिना कहे चाय ले आई।</p>\n<p>पीतल की ट्रे।</p>\n<p>ससुर घर पर होते तो दो प्याले, नहीं होते तो एक।</p>\n<p>ट्रे से अदरक और इलायची की भाप उठती, और पीतल पर प्याला रखने की हल्की खनक आँगन की चुप्पी में दूर तक सुनाई देती।</p>\n<p>प्याले के नीचे की तश्तरी में अक्सर चाय की दो-चार बूँदें छलक जातीं, मानो डालते समय हाथ एक क्षण के लिए ठहर गया हो।</p>\n<p>और चाय रख देने के बाद भी कविता तुरंत नहीं जाती थी—एक क्षण और रुकती, बस उतना ही, और देखती रहती।</p>\n<p>पहले-पहल विक्रम ने इसे संयोग माना।</p>\n<p>फिर एक गर्म दोपहर उसे पहली बार लगा कि वह जो देख रहा है, केवल उसका भ्रम नहीं।</p>\n<p>आँगन लगभग खाली था। उन दोनों के अलावा वहाँ एक कुत्ता बैठा था—आवारा, मगर ऐसा जिसे पूरा गाँव अपना मानता था और कोई भी अपना नहीं।</p>\n<p>विक्रम फिर ज़मीन के किसी काग़ज़ का संदेश लेकर आया था।</p>\n<p>रामफल घर पर नहीं था। उसका पिता भीतर के कमरे में सो रहा था।</p>\n<p>कविता हमेशा की तरह चाय लाई। कुर्ती की बाँह कोहनी तक चढ़ी हुई थी। कलाई में पड़ी पतली सोने की चूड़ी ट्रे से हल्के से टकराई और एक छोटी-सी आवाज़ हुई।</p>\n<p>उसने चाय पास रखे छोटे स्टूल पर रख दी।</p>\n<p>“धन्यवाद,” विक्रम ने कहा।</p>\n<p>कविता वहीं खड़ी रही।</p>\n<p>“गरम है।”</p>\n<p>“पता है।”</p>\n<p>“तो धीरे पीना।”</p>\n<p>विक्रम ने चाय की चुस्की ली।</p>\n<p>कविता की आँखें एक क्षण उसके गले पर ठहरीं।</p>\n<p>प्याला खाली हुआ तो उसने ट्रे आगे कर दी। विक्रम ने प्याला रखा।</p>\n<p>उँगलियाँ नहीं छुईं।</p>\n<p>“तुम बहुत आते हो,” कविता ने कहा।</p>\n<p>“काम होता है।”</p>\n<p>“काम…”</p>\n<p>उसके होंठों से हल्की-सी साँस निकली। हँसी शायद ऐसी ही होती, अगर दोनों में से कोई उसे हँसी मानने को तैयार होता।</p>\n<p>“रामफल तो काम के लिए कभी घर पर नहीं मिलता।”</p>\n<p>“मुझे पता है।”</p>\n<p>कविता ने उसकी ओर देखा।</p>\n<p>“मुझे पता है कि तुम्हें पता है।”</p>\n<p>बात वहीं ख़त्म हो गई।</p>\n<p>मगर कुछ बातें ख़त्म होकर भी ख़त्म नहीं होतीं।</p>\n<p>एक दूसरी दोपहर कविता फिर सामने बैठी थी। विक्रम चाय पी रहा था और वह उसकी ओर सीधे देखने के बजाय प्याले को देख रही थी।</p>\n<p>“किशोरावस्था में सोचती थी,” उसने अचानक कहा, “मेरा पति कैसा होगा।”</p>\n<p>विक्रम ने उसकी ओर देखा।</p>\n<p>“कैसा?”</p>\n<p>“ठहरा हुआ। ऐसा आदमी जो मुझे सच में देखे… सिर्फ मेरे आर-पार नहीं। जैसे शादी की तस्वीरें पुरानी पड़ जाने के बाद अक्सर आदमी अपनी पत्नी को देखना ही भूल जाते हैं।”</p>\n<p>विक्रम कुछ क्षण चुप रहा।</p>\n<p>फिर पूछा, “मिला?”</p>\n<p>कविता के चेहरे पर एक भाव आया और उतनी ही जल्दी चला गया। विक्रम समझ नहीं पाया वह क्या था।</p>\n<p>“नहीं,” उसने सहज स्वर में कहा, “अभी तक तो नहीं।”</p>\n<p>वह मुड़कर चली गई।</p>\n<p>विक्रम वहीं बैठा रहा।</p>\n<p>मुँह में चीनी और इलायची का स्वाद बचा था, और मन में यह साफ़ अहसास कि अभी-अभी कुछ ऐसा कहा गया था जिसमें एक भी अनुचित शब्द नहीं था—</p>\n<p>फिर भी बात उतनी निर्दोष नहीं थी जितनी सुनाई दी थी।</p>\n<p>उस शाम विक्रम घर लौटते हुए मोटरसाइकिल सामान्य से कुछ धीमी चला रहा था।</p>\n<p>वह बार-बार उसी बातचीत को मन में दोहराता और फिर ख़ुद को समझाता कि इसमें सोचने जैसा कुछ है ही नहीं।</p>\n<p>वह एक अच्छे किसान परिवार का लड़का था। एक दिन पिता जिसे ज़मीन, खानदान और घर के योग्य समझेंगे, उससे उसकी शादी हो जाएगी।</p>\n<p>और किसी दूसरे की पत्नी के हाथ की चाय—</p>\n<p>वह कोई ऐसी चीज़ नहीं थी जिसे उसके जैसा आदमी दूसरी बार याद रखे।</p>\n<p>फिर भी उसने याद रखी।</p>\n<p>और इस बात पर उसे अपने आप से हल्की-सी नाराज़गी भी हुई।</p>\n<p>उसके बाद रामफल के घर जाने के कारण जैसे अपने आप बनने लगे।</p>\n<p>विक्रम ख़ुद से कहता, वह उन्हें बनाता नहीं है।</p>\n<p>कभी उसके पिता के लिए कोई संदेश।</p>\n<p>कभी किसी रिश्तेदार की सेना में भर्ती को लेकर सवाल।</p>\n<p>कभी तहसील से लौटते हुए वही लंबा रास्ता, जो संयोग से रामफल के दरवाज़े के सामने से निकलता था—उस समय जब सफ़र के लिए धूप कुछ ज़्यादा होती और चाय के लिए बिल्कुल ठीक।</p>\n<p>हर बार वही आँगन।</p>\n<p>वही पीतल की ट्रे।</p>\n<p>और हर बार चाय रखने के बाद कविता का पहले से कुछ अधिक देर तक ठहर जाना।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>उस वर्ष रामफल पच्चीस का था, मगर उसमें एक अजीब-सी बासी थकान थी जो उसकी उम्र से कहीं अधिक पुरानी लगती थी।</p>\n<p>कद लगभग कविता जितना ही। शरीर में न अनुशासन का कोई निशान था, न ताकत का। रंग कविता से कुछ गहरा था; धूप ने चेहरे और त्वचा को खुरदरा कर दिया था—हालाँकि उस धूप में उसका अधिकांश समय किसी मेहनत में नहीं बीतता था।</p>\n<p>एक दोपहर विक्रम ने उसे आँगन की दीवार से टिके देखा था। सामने खाने की थाली रखी थी और वह अधनींद में बैठा था। उसकी माँ को दो बार कहना पड़ा कि खाना खा ले।</p>\n<p>रामफल तेज़ समझ वाला आदमी भी नहीं था। बातचीत अक्सर उसके सामने से निकल जाती और वह उसे पकड़ने की कोशिश भी नहीं करता।</p>\n<p>कविता के लिए यह फ़र्क़ धीरे-धीरे साफ़ होता गया।</p>\n<p>एक ओर रामफल था।</p>\n<p>दूसरी ओर विक्रम—इतना लंबा कि आँखों में देखने के लिए कविता को सचमुच ठोड़ी ऊपर करनी पड़ती; शरीर जिसे लापरवाही ने नहीं, अनुशासन ने गढ़ा था; और सबसे बढ़कर एक ऐसा मन, जो उसकी बात सुनकर जवाब देता था। वह तर्क करती तो विक्रम तर्क से मिलता। वह सवाल करती तो उसके सामने कोई दीवार नहीं, एक दूसरा विचार खड़ा होता।</p>\n<p>रामफल ठीक से कोई काम नहीं करता था।</p>\n<p>घर उसके पिता की खेती की आमदनी और रामफल की इधर-उधर की छोटी-मोटी कमाई पर चलता था। मगर उस घर को वास्तव में कौन सँभाल रहा था, यह किसी से छिपा नहीं था।</p>\n<p>कविता—चुपचाप, जैसे ऐसे घरों में अक्सर औरतें करती हैं।</p>\n<p>विक्रम उन चुराए हुए कुछ मिनटों में जितना समझ पाया था, कविता के दिन लगभग एक ही साँचे में ढले रहते—सूरज निकलने से पहले पानी, पशुओं का काम, रसोई; ऐसा ससुर जो उससे अधिकतर तभी बोलता जब कोई काम बताना होता; और ऐसा पति जो दोपहरें या तो सोकर काटता या शराब में।</p>\n<p>कविता ने कभी सीधे शिकायत नहीं की।</p>\n<p>ज़रूरत भी नहीं थी।</p>\n<p>उसके काम करने के ढंग में ही बहुत कुछ लिखा था—हर हरकत नपी-तुली, जैसे उसने सीख लिया हो कि कुछ भी व्यर्थ नहीं करना है।</p>\n<p>न पानी।</p>\n<p>न समय।</p>\n<p>न शब्द।</p>\n<p>क्योंकि उस घर में ऐसा बहुत कम था जिसे वह सचमुच अपना कह सके।</p>\n<p>कुछ महीने बाद की एक दोपहर रामफल दिन में ही शराब पीकर भीतर सो रहा था। यह कोई असामान्य बात नहीं थी। उसका पिता खेतों पर गया हुआ था।</p>\n<p>विक्रम एक काग़ज़ लेकर पहुँचा—ऐसा काग़ज़ जो आसानी से एक सप्ताह और इंतज़ार कर सकता था।</p>\n<p>इस बार कविता उसे आँगन में नहीं, दरवाज़े पर ही मिल गई।</p>\n<p>“वो अंदर है,” उसने कहा। “सो रहा है। अंदर मत जाना।”</p>\n<p>“मैं तो बस—”</p>\n<p>“मुझे पता है तुम क्यों आए हो।”</p>\n<p>कविता रास्ते से नहीं हटी।</p>\n<p>विक्रम ने भी उसे हटने के लिए नहीं कहा।</p>\n<p>कुछ क्षण दोनों वैसे ही खड़े रहे।</p>\n<p>फिर विक्रम ने बहुत धीमे पूछा, “अगर मैं चाय पीने अंदर आऊँ… तो क्या होगा?”</p>\n<p>कविता ने उसकी आँखों में देखा।</p>\n<p>“चाय होगी।”</p>\n<p>वह रुकी।</p>\n<p>“फिर तुम चले जाओगे। जैसे हर बार चले जाते हो। और मैं प्याला धो दूँगी। जैसे हर बार धोती हूँ।”</p>\n<p>एक और ठहराव।</p>\n<p>“हाँ, अगर तुम्हें चाय नहीं पीनी तो अलग बात है।”</p>\n<p>“पीनी है।”</p>\n<p>“तो आओ।”</p>\n<p>आँगन में चाय डालते समय कविता का हाथ पूरी तरह स्थिर नहीं था।</p>\n<p>विक्रम ने कुछ नहीं कहा।</p>\n<p>चाय ख़त्म हुई। वह उठकर जाने लगा तो कविता पीछे नहीं हटी।</p>\n<p>दोनों के बीच जितनी दूरी होनी चाहिए थी, उससे बहुत कम बची थी—इतनी कि बिना छुए भी विक्रम को उसकी गर्माहट अपने सीने तक पहुँचती महसूस हो रही थी, जैसे बुझते अलाव के पास बैठने पर राख के नीचे दबी आँच चेहरे को छू जाती है।</p>\n<p>एक क्षण के लिए उसका हाथ कविता की कमर के पास तक आया—</p>\n<p>रुका—</p>\n<p>मगर छुआ नहीं।</p>\n<p>कविता ने छोटी-सी तेज़ साँस भीतर खींची, जैसे स्पर्श हो चुका हो।</p>\n<p>“विक्रम…”</p>\n<p>“जानता हूँ।”</p>\n<p>कविता की आवाज़ धीमी थी, मगर उसमें हल्का-सा रोष उतर आया।</p>\n<p>“नहीं। तुम नहीं जानते।”</p>\n<p>विक्रम चुप रहा।</p>\n<p>“तुम्हें लगता है कि जानते हो। तुम चले जाते हो, विक्रम। मैं यहीं रह जाती हूँ।”</p>\n<p>उसने उसकी आँखों में देखते हुए कहा—</p>\n<p>“तुम बस इतना जानते हो।”</p>\n<p>विक्रम चला गया।</p>\n<p>दरवाज़े से निकलकर एक बार पीछे मुड़ा।</p>\n<p>और उस क्षण उसने बिना किसी बहाने के अपने भीतर एक सच स्वीकार किया—कोई भला आदमी उसी दोपहर तय कर लेता कि वह फिर कभी इस घर में चाय पीने नहीं आएगा।</p>\n<p>उसे अपने पिता का नाम याद आया।</p>\n<p>गाँव में वर्षों से बनी परिवार की साख याद आई।</p>\n<p>उसने ख़ुद को समझाया कि ये आना-जाना अपने आप बंद हो जाएगा।</p>\n<p>नहीं हुआ।</p>\n<p>कुछ ही समय बाद उसकी छुट्टी समाप्त हो गई और वह वापस अपनी यूनिट चला गया।</p>\n<p>दो महीने बीते।</p>\n<p>घर से माँ का पत्र आया।</p>\n<p>घर-गाँव की सामान्य बातों के बीच एक बात ऐसे ही लिखी हुई थी—रामफल की पत्नी पुलिस में भर्ती हो गई है। कांस्टेबल की ट्रेनिंग करने गई है।</p>\n<p>विक्रम ने वह पंक्ति पढ़ी।</p>\n<p>फिर दोबारा पढ़ी।</p>\n<p>और एक तीसरी बार भी।</p>\n<p>उसके बाद उसने बड़ी दृढ़ता से ख़ुद को समझाया कि कविता क्या कर रही है, कहाँ गई है, किसलिए गई है—</p>\n<p>इनमें से किसी बात से अब उसे कोई फ़र्क़ नहीं पड़ता।</p>\n<p>उस रात उसने पत्र तह करके कमीज़ की जेब में रख लिया।</p>\n<p>सुबह परेड से पहले उसने उसे निकालकर चौथी बार पढ़ा।</p>"}, {"chapter": 3, "title": "अध्याय 2 — एक नई साँस", "content": "<h1>अध्याय 2 — एक नई साँस</h1>\n<p>एक दिन विक्रम के फोन पर एक ग़लत नंबर आया।</p>\n<p>या शायद वह नंबर ग़लत था ही नहीं।</p>\n<p>“हैलो?”</p>\n<p>दूसरी ओर कुछ क्षण की चुप्पी रही।</p>\n<p>“सॉरी… शायद ग़लत नंबर लग गया।”</p>\n<p>“कोई बात नहीं। किससे बात करनी थी?”</p>\n<p>“किसी से नहीं। मतलब… किसी खास से नहीं।”</p>\n<p>विक्रम एक पल चुप रहा। उस आवाज़ को पहचानने में उसे दो साँसें लगीं—उसने उसे पहले एक ही बार इस तरह सुना था: “गरम है।”</p>\n<p>फिर बोला—</p>\n<p>“कविता?”</p>\n<p>उधर की चुप्पी इस बार कुछ लंबी थी।</p>\n<p>“…हाँ। मैं हूँ।”</p>\n<p>कविता की पुलिस ट्रेनिंग का दूसरा महीना चल रहा था, और विक्रम तब श्रीनगर में तैनात था। उसे उस समय यह नहीं मालूम था कि फोन ग़लती से नहीं आया था।</p>\n<p>उस पहली बातचीत की यही साधारणता दोनों के काम आ गई। एक ग़लत नंबर पर हुई बातचीत को कोई नाम देने की ज़रूरत नहीं थी। इसलिए फोन उस जगह भी नहीं कटा जहाँ उसे कट जाना चाहिए था।</p>\n<p>और जब आख़िर में कटा, तो बात वहीं समाप्त नहीं हुई।</p>\n<p>कुछ पीछे रह गया था।</p>\n<p>अगली बार बात करने की एक छोटी-सी वजह।</p>\n<p>फिर दूसरा फोन आया।</p>\n<p>इस बार बहाना थोड़ा कम था।</p>\n<p>“थकी हुई लग रही हो,” विक्रम ने कहा।</p>\n<p>“ट्रेनिंग आदमी की आवाज़ से भी ताकत निकाल लेती है। सुबह पाँच बजे से पहले उठो, फिर तब तक दौड़ो जब तक टाँगें अपनी शिकायत करना बंद न कर दें। ऊपर से एक इंस्ट्रक्टर है जिसे ज़रूरत से थोड़ा ज़्यादा चिल्लाने का शौक है।”</p>\n<p>विक्रम हँसा।</p>\n<p>“अच्छा लगता है वहाँ?”</p>\n<p>कविता ने जवाब देने में अपेक्षा से कुछ अधिक समय लिया।</p>\n<p>“जितना सोचा था, उससे ज़्यादा।”</p>\n<p>फिर धीमे से बोली—</p>\n<p>“यहाँ मैं अपने उस रूप से मिली हूँ जिसे मेरे गाँव में किसी ने कभी देखा ही नहीं। शायद… मुझे वह औरत ज़्यादा पसंद है।”</p>\n<p>उस एक वाक्य में ट्रेनिंग से कहीं अधिक कुछ था।</p>\n<p>विक्रम ने कुरेदा नहीं।</p>\n<p>उसके बाद बातचीत बढ़ती गई।</p>\n<p>ड्रिल कैसी होती है, अनुशासन कितना कठोर है, बैरक की ज़िंदगी कैसी है—विक्रम पूछता और कविता बताती। वह उससे ऐसी बातें भी कहने लगी जो उसने वहाँ अपनी सबसे करीबी सहेली से भी नहीं कही थीं।</p>\n<p>लेकिन वे केवल ट्रेनिंग की बातें नहीं रह गईं।</p>\n<p>कविता उसे उस दुनिया के बारे में बताने लगी जहाँ एक ही बैरक में रहने वाली बहुत-सी औरतें पहली बार अपने लिए कुछ चाहना सीख रही थीं। वहाँ अकेलापन भी था और एक अजीब-सी आज़ादी भी।</p>\n<p>विक्रम सुनता।</p>\n<p>बिना बीच में टोके। बिना हर बात का कोई हल बताए।</p>\n<p>कई बार कविता बोलते-बोलते रुक जाती और दूसरी ओर से विक्रम की आवाज़ नहीं आती। फिर भी उसे मालूम रहता—वह सुन रहा है।</p>\n<p>यही बात उसे और कहने की हिम्मत देती गई।</p>\n<p>उन बातचीतों के बीच विक्रम के सामने कविता का एक ऐसा रूप खुल रहा था जिसे उसने बादशाहपुर के उस आँगन में कभी पूरा नहीं देखा था।</p>\n<p>और कविता भी पहली बार अपने भीतर उस स्त्री को पहचान रही थी, जिसे इतने वर्षों तक किसी ने ठीक से जगह नहीं दी थी।</p>\n<p>लेकिन एक सच दोनों के बीच हर समय मौजूद था।</p>\n<p>विक्रम अविवाहित था।</p>\n<p>कविता नहीं।</p>\n<p>यह बात किसी बातचीत में बार-बार कही नहीं जाती थी।</p>\n<p>कहने की ज़रूरत भी नहीं थी।</p>\n<p>वह हर फोन के पीछे मौजूद रहती थी।</p>\n<p>आगे जो भी होना था, उसकी पहली और सबसे भारी कीमत कविता को ही चुकानी थी।</p>\n<p>विक्रम यह बात समझता था।</p>\n<p>कविता भी।</p>\n<p>फिर भी फोन आते रहे।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>करनाल के पास मधुबन की हरियाणा पुलिस अकादमी उस आँगन से बिल्कुल अलग दुनिया थी, जिसे कविता पीछे छोड़ आई थी। यहाँ कंक्रीट की बैरक थी, लोहे के पलंग थे, और हवा में जूतों की पॉलिश और पीतल चमकाने वाली पॉलिश की तीखी गंध बसी रहती थी। भोर से पहले रसोई में बजने वाली चूड़ियों की खनक की जगह अब पाँच बजे की सीटी थी—सीधी, बेरहम, और किसी का इंतज़ार न करने वाली।</p>\n<p>दिन कठिन थे। शाम तक शरीर पत्थर हो जाता और कई रातें वह पलंग पर गिरते ही सो जाती। मगर यह थकान उस पुरानी थकान जैसी नहीं थी, जो घर में बिना नाम के उसकी हड्डियों में जमती रही थी। यह थकान उसकी अपनी थी—जैसे कोई किसान दिन भर अपने ही खेत में हल चलाकर लौटे: पीठ दुखती है, मगर हिसाब अपना है। इसलिए कठिन ट्रेनिंग भी उसे सज़ा जैसी नहीं लगी। बरसों से बंद किसी कोठरी की खिड़की जैसे पहली बार खुली थी, और भीतर हवा की एक पतली धार उतर आई थी।</p>\n<p>आज़ादी उसे किसी बड़ी घोषणा में नहीं मिली।</p>\n<p>वह छोटी-छोटी चीज़ों में आई।</p>\n<p>सुबह आँख खुलने पर यह देखने की ज़रूरत नहीं कि घर में उससे पहले कौन जाग चुका है।</p>\n<p>खाना खाते समय यह हिसाब नहीं कि उससे पहले किसका खाना ज़रूरी है।</p>\n<p>अपने समय के कुछ हिस्सों पर अपना अधिकार।</p>\n<p>अपने शरीर की थकान पर भी अपना अधिकार।</p>\n<p>बहुत छोटी बातें थीं।</p>\n<p>लेकिन कविता के लिए पहली बार छोटी नहीं थीं।</p>\n<p>जो गाँठ बरसों से उसके भीतर चुपचाप बँधी थी, वह धीरे-धीरे ढीली होने लगी।</p>\n<p>कुछ समय बाद उसने आँगन के सपने देखना बंद कर दिया।</p>\n<p>तभी उसे पहली बार एहसास हुआ कि वह इतने समय से सपनों में भी उसी आँगन में लौटती रही थी।</p>\n<p>कविता अपने बैच की सबसे तेज़ लड़की नहीं थी।</p>\n<p>न सबसे ताकतवर।</p>\n<p>लेकिन पहले ही सप्ताह में प्रशिक्षकों ने एक बात पहचान ली थी—उसे कोई आदेश दूसरी बार देने की ज़रूरत नहीं पड़ती थी।</p>\n<p>एक चक्कर और लगाने को कोई न कहे, तो भी वह लगा सकती थी।</p>\n<p>थककर बैठ जाने का कारण मिल जाए, तो भी वह पहले काम पूरा करती थी।</p>\n<p>बादशाहपुर के आँगन में पीतल की ट्रे थामे खड़ी कविता यहाँ हर परेड, हर थकी हुई रात के साथ थोड़ी-थोड़ी पीछे छूटती जा रही थी—जैसे पतझड़ में कोई पेड़ अपने पुराने पत्ते एक-एक करके गिराता है। मगर वह मिट नहीं रही थी। झड़ते पत्तों के नीचे, छाल की किसी दरार में, एक कोंपल जगह बना रही थी—हरी, ढीठ, और अभी इतनी नन्ही कि किसी की नज़र न पड़े। वह दूसरी कविता थी, जो अपने जीवन में पहली बार अपनी ही ओर बढ़ रही थी।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>नैना की नज़र कविता पर पहले पड़ी थी।</p>\n<p>एक शाम वह बिना पूछे कविता के पलंग के पास आ बैठी।</p>\n<p>“तुम शादीशुदा हो।”</p>\n<p>कविता ने उसकी ओर देखा।</p>\n<p>“मुझे मालूम है।”</p>\n<p>नैना की बात में कटुता नहीं थी। वह बस उन लोगों में से थी जो बात को घुमाकर कहने की मेहनत नहीं करते।</p>\n<p>“बुरा मत मानना। मैं ताना नहीं मार रही। बस… यहाँ ज़्यादातर लड़कियाँ इसलिए हैं क्योंकि उनके पिता चाहते थे कि वे भर्ती हों। तुम ऐसे दौड़ती हो जैसे यहाँ आने का फ़ैसला तुम्हारा अपना था।”</p>\n<p>“मेरा ही था।”</p>\n<p>नैना मुस्कराई।</p>\n<p>“दोनों ही अपने फ़ैसले से यहाँ हैं।”</p>\n<p>उनकी दोस्ती वहीं से शुरू हुई।</p>\n<p>इसके अलावा दोनों में समानता बहुत कम थी।</p>\n<p>नैना ऐसे परिवार से आई थी जहाँ पैसे की इतनी कमी नहीं थी कि नौकरी उसके लिए मजबूरी बनती। ज़ुबान तेज़ थी और धीमे लोगों के लिए धैर्य बहुत कम।</p>\n<p>कविता गाँव से आई थी। नई-नई शादी हुई थी। पैसे भी सोचकर खर्च करती थी और शब्द भी। ज़िंदगी ने उसे मुँह से कहने से ज़्यादा आँखों से कहना सिखाया था।</p>\n<p>नैना वे बातें बिना झिझक कह देती जिन्हें कविता वर्षों से भीतर रोकती आई थी।</p>\n<p>और कविता की स्थिरता ने नैना की बेचैनी को टिकने की एक जगह दे दी।</p>\n<p>इसी फ़र्क़ ने दोनों को एक-दूसरे के करीब ला दिया।</p>\n<p>लगभग एक वर्ष तक दोनों एक ही कमरे में रहीं।</p>\n<p>बीच-बीच में बैरक और पलंगों का फेरबदल हुआ, उन्हें अलग करने की कोशिश भी हुई; आख़िर एक प्रशिक्षक ने हार मान ली और दोनों फिर साथ ही रहने लगीं।</p>\n<p>उनकी शामों की अपनी दिनचर्या बन गई।</p>\n<p>कभी नैना दिन भर में किसी प्रशिक्षक द्वारा किए गए ‘अन्याय’ की लंबी शिकायत करती और कविता चुपचाप अपने जूतों पर तेल लगाते हुए बीच में कोई सूखी-सी बात कह देती।</p>\n<p>नैना उस बात पर ज़रूरत से ज़्यादा हँसती।</p>\n<p>हफ्ते में एक दिन, अगर ट्रेनिंग इजाज़त देती, दोनों कैंटीन में गरम समोसे की एक प्लेट बाँट लेतीं—हालाँकि उन्हें वहाँ खाने की इजाज़त नहीं थी।</p>\n<p>धीरे-धीरे नैना उन बहुत कम लोगों में शामिल हो गई जिनके सामने कविता को हर समय ख़ुद को सँभालकर रखने की ज़रूरत महसूस नहीं होती थी।</p>\n<p>पहली बार उसे ऐसी दोस्ती मिली थी जिसे निभाने के लिए उसे कुछ उठाकर नहीं ले जाना पड़ता था।</p>\n<p>न चाय की ट्रे।</p>\n<p>न किसी रिश्ते का बोझ।</p>\n<p>न अपने मन पर कोई दूसरा चेहरा।</p>\n<p>बस वह ख़ुद।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>एक रात कमरे की बत्ती बुझ चुकी थी।</p>\n<p>दोनों अपने-अपने पलंग पर लेटी थीं।</p>\n<p>उसी अँधेरे में कविता ने पहली बार रामफल के बारे में बात की।</p>\n<p>सब कुछ नहीं।</p>\n<p>बस इतना कि बाकी का अनुमान लगाया जा सके।</p>\n<p>“फोन करता है तो या पैसे चाहिए होते हैं…” कविता छत की ओर देखते हुए बोली, “या फिर बस अपनी साँस सुनाना चाहता है, ताकि मुझे याद रहे कि मैं किसी की हूँ।”</p>\n<p>नैना ने कोई सहानुभूति नहीं जताई।</p>\n<p>“तो फोन मत उठाया करो।”</p>\n<p>“इतना आसान नहीं है।”</p>\n<p>“उतना ही आसान है।”</p>\n<p>कविता उसकी ओर मुड़ी।</p>\n<p>अँधेरे में नैना का चेहरा साफ़ नहीं दिख रहा था।</p>\n<p>“तुम्हें बस पूरी ज़िंदगी यह सिखाया गया है कि आसान नहीं है।”</p>\n<p>कविता ने उस रात उससे बहस नहीं की।</p>\n<p>बहुत देर तक कुछ बोली भी नहीं।</p>\n<p>मगर वह वाक्य उसके भीतर कहीं रह गया।</p>\n<p>कुछ वाक्य सुनते ही सही नहीं लगते।</p>\n<p>फिर भी मन उन्हें फेंक नहीं पाता।</p>\n<p>यह भी वैसा ही था।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>कुछ समय बाद नैना ने कविता की एक और चुप्पी पकड़ ली।</p>\n<p>जब भी श्रीनगर के आसपास के एक खास इलाके का ज़िक्र होता, कविता के भीतर जैसे अचानक कुछ स्थिर हो जाता।</p>\n<p>उसकी सामान्य बेबाक़ी एक क्षण के लिए गायब हो जाती।</p>\n<p>एक रात नैना ने सीधे कह दिया—</p>\n<p>“कोई है।”</p>\n<p>नैना सवाल नहीं पूछ रही थी। कह रही थी।</p>\n<p>कविता ने इनकार नहीं किया।</p>\n<p>नैना ने उसकी ओर देखा, फिर कंधे उचकाए।</p>\n<p>“ठीक है। अपने राज़ अपने पास रखो।”</p>\n<p>काफी देर बाद कविता बोली—</p>\n<p>“राज़ जैसा कुछ नहीं है। हमारे गाँव का एक लड़का है। आर्मी में है। पिछली बार सुना था श्रीनगर के आसपास पोस्टेड है। बस।”</p>\n<p>“बस।”</p>\n<p>नैना ने वही शब्द दोहराया।</p>\n<p>उसके चेहरे पर साफ़ था कि उसे इस ‘बस’ पर विश्वास नहीं हुआ।</p>\n<p>मगर उसने आगे कुछ नहीं पूछा।</p>\n<p>कविता ने भी कुछ नहीं कहा।</p>\n<p>क्योंकि कुछ रिश्ते उस समय तक रिश्ते बने ही नहीं होते—फिर भी उनके बारे में बोलते हुए डर लगता है कि कहीं नाम दे देने से वे सच न हो जाएँ।</p>\n<p>उस रात कविता ने विक्रम का नाम नहीं बताया।</p>\n<p>बहुत समय तक नहीं बताया।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>उधर फोन अब नियमित होने लगे थे।</p>\n<p>अब वे केवल बातचीत का ज़रिया नहीं रहे।</p>\n<p>दिन भर की अपनी-अपनी दुनिया के बीच दोनों ने जाने-अनजाने एक-दूसरे के लिए थोड़ी-सी जगह बना ली थी।</p>\n<p>कितनी—यह दोनों जानते थे।</p>\n<p>मानना अभी किसी ने शुरू नहीं किया था।</p>\n<p>कुछ ही हफ्तों में कविता विक्रम की चुप्पियों तक को पहचानने लगी थी।</p>\n<p>कब वह सचमुच चुप है।</p>\n<p>कब मुस्करा रहा है मगर आवाज़ में आने नहीं दे रहा।</p>\n<p>कब उसका सूखा-सा मज़ाक केवल एक वाक्य में छिपा है।</p>\n<p>और उसे यह भी समझ आ गया था कि विक्रम सुनता है।</p>\n<p>फोन करने के लिए बहानों की ज़रूरत ख़त्म हो गई।</p>\n<p>तीसरे सप्ताह तक कविता ने ‘ग़लत नंबर’ का अभिनय भी छोड़ दिया।</p>\n<p>“कल आठ बजे फोन करूँगी,” कविता ने एक दिन कहा।</p>\n<p>“ठीक है।”</p>\n<p>“ठीक है नहीं। फोन उठा लेना।”</p>\n<p>विक्रम हल्का-सा मुस्कराया।</p>\n<p>“उठा लूँगा।”</p>\n<p>“देखना, इंतज़ार मत करवाना… मेजर साहब।”</p>\n<p>विक्रम तब कैप्टन था।</p>\n<p>मेजर बनने में अभी एक पद बाकी था।</p>\n<p>‘मेजर साहब’ की शुरुआत उसी आँगन के दिनों में हुई थी। किसी ने एक बार ग़लती से उसे ग़लत रैंक से पुकार दिया था और कविता को वह संबोधन पसंद आ गया।</p>\n<p>विक्रम ने कभी सुधारा नहीं।</p>\n<p>फिर वह नाम कविता का हो गया।</p>\n<p>उसमें सम्मान से ज़्यादा छेड़ थी—और उस छेड़ के भीतर वह आकर्षण, जिसे दोनों अभी खुलकर कहने से बच रहे थे।</p>\n<p>कविता जब उसे “मेजर साहब” कहती, विक्रम उसे केवल मज़ाक की तरह नहीं सुन पाता था।</p>\n<p>एक रात बात फिर रामफल पर चली गई।</p>\n<p>“आज फिर उसका फोन आया था,” कविता ने कहा। “पैसे चाहिए थे।”</p>\n<p>“कविता…”</p>\n<p>“नहीं।”</p>\n<p>उसने तुरंत रोक दिया।</p>\n<p>“मेरा नाम उस तरह मत लो जैसे तुम्हें मुझ पर तरस आ रहा हो। मैं तुम्हें तरस खाने के लिए फोन नहीं करती।”</p>\n<p>“तो क्यों करती हो?”</p>\n<p>कविता चुप रही।</p>\n<p>जब बोली तो आवाज़ पहले से धीमी थी।</p>\n<p>“क्योंकि इतने समय तक मैं तुम्हारे हाथ में चाय देती रही… और तुम्हारी आँखों से सब कुछ साफ़ था। मैं बस जानना चाहती थी कि आँगन और उस ट्रे के बिना भी तुम्हारी वह ट्रेनिंग टिकती है या नहीं।”</p>\n<p>विक्रम चुप रहा।</p>\n<p>देर तक किसी ने कुछ नहीं कहा।</p>\n<p>फिर विक्रम बोला—</p>\n<p>“नहीं टिकती।”</p>\n<p>कविता की ओर से बहुत हल्की-सी साँस सुनाई दी।</p>\n<p>“यही सुनना था।”</p>\n<p>उसके बाद बात किसी और विषय पर चली गई।</p>\n<p>लेकिन जो कहा गया था, वह वहीं रह गया।</p>\n<p>अब दोनों के बीच केवल पुराना आँगन और चाय की ट्रे नहीं थी।</p>\n<p>उससे आगे कुछ बनने लगा था।</p>\n<p>धीरे।</p>\n<p>बिना नाम के।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>उनके बीच की सीमा किसी एक रात नहीं टूटी। वह हर फोन के साथ थोड़ी-थोड़ी पीछे खिसकती गई—जैसे कटाव में नदी का किनारा खिसकता है, बिना आवाज़ किए, और किसी सुबह देखने पर पता चलता है कि पुरानी रेखा कहीं पीछे रह गई।</p>\n<p>बातें लंबी होने लगीं।</p>\n<p>कई बार कहने के लिए कुछ खास नहीं होता, फिर भी फोन नहीं कटता।</p>\n<p>किसी दिन कविता की आवाज़ सुनते ही विक्रम समझ जाता कि दिन अच्छा नहीं गया।</p>\n<p>किसी रात विक्रम सामान्य से कम बोलता तो कविता पूछती नहीं—बस फोन पर बनी रहती।</p>\n<p>और यही वे छोटे क्षण थे जिनमें दोनों एक-दूसरे के जीवन का हिस्सा बनने लगे।</p>\n<p>कुछ और हफ्तों बाद विक्रम के लिए भी इसे सामान्य बातचीत कहना कठिन हो गया।</p>\n<p>एक रात कविता की आवाज़ अचानक पहले से बहुत धीमी हो गई।</p>\n<p>“मैं तुम्हारे बारे में जितना सोचती हूँ… उतना सोचने का मुझे कोई हक नहीं है।”</p>\n<p>विक्रम ने कुछ नहीं कहा।</p>\n<p>“तुम यह बात सीधे कह सकते हो, विक्रम। मैं नहीं।”</p>\n<p>“क्यों?”</p>\n<p>कविता हल्का-सा हँसी, मगर उस हँसी में खुशी नहीं थी।</p>\n<p>“क्योंकि मैं शादीशुदा हूँ।”</p>\n<p>विक्रम के पास इसका कोई जवाब नहीं था।</p>\n<p>दोनों जानते थे कि यही वह सच था जिससे बाकी सारी बातें छोटी हो जाती थीं।</p>\n<p>कुछ देर बाद उसने कहा—</p>\n<p>“तो मत कहो।”</p>\n<p>लेकिन शब्दों में जितना निषेध था, आवाज़ में उतना नहीं।</p>\n<p>कविता समझ गई।</p>\n<p>“नहीं कहूँगी,” उसने कहा।</p>\n<p>फिर कुछ क्षण बाद—</p>\n<p>“कम-से-कम बाकी हिस्सा तो नहीं।”</p>\n<p>बाकी हिस्सा कहने की ज़रूरत नहीं पड़ी।</p>\n<p>उसके बाद जो चुप्पी आई, वह असहज नहीं थी। वह उस बात से भरी थी जिसे दोनों समझ चुके थे और अभी शब्दों में नहीं रखना चाहते थे—जैसे दो हाथ एक ही प्याला थामे हों, और दोनों जानते हों कि पहले छोड़ना किसी को नहीं है।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>महीनों तक वे मिले नहीं।</p>\n<p>फिर भी दूरी ने उस अनकहे को कम नहीं किया।</p>\n<p>कई बार तो फोन कटने के बाद उसकी मौजूदगी और अधिक महसूस होती।</p>\n<p>विक्रम रात को देर तक जागता रहता।</p>\n<p>सोचता—यह सब किस राह की ओर बढ़ रहा है?</p>\n<p>हर पोस्टिंग पर वह अपने परिवार का नाम साथ लेकर चलता था। पिता की प्रतिष्ठा, घर की मर्यादा, गाँव की निगाह—इनमें से कोई चीज़ वर्दी पहन लेने से पीछे नहीं छूटती थी।</p>\n<p>और दूसरी ओर कविता थी।</p>\n<p>एक विवाहित स्त्री।</p>\n<p>जिसकी आवाज़ अब उसके दिन का ऐसा हिस्सा बनने लगी थी जिसे वह चाहकर भी साधारण नहीं मान पा रहा था।</p>\n<p>वह कई बार तय करता—</p>\n<p>अब बस।</p>\n<p>अगला फोन नहीं।</p>\n<p>लेकिन अगली बार फोन बजता और स्क्रीन पर नंबर देखते ही पिछली रात का फ़ैसला उतना मजबूत नहीं रह जाता।</p>\n<p>कुछ सप्ताह बाद कविता ने कहा—</p>\n<p>“मैं गुरुग्राम आ रही हूँ।”</p>\n<p>विक्रम चुप रहा।</p>\n<p>“घर जाने से पहले तुमसे मिलना चाहती हूँ।”</p>\n<p>वह जवाब नहीं दे पाया।</p>\n<p>फिर कहा कि छुट्टी नहीं मिल सकती।</p>\n<p>फोन कट गया।</p>\n<p>मगर झूठ वहीं नहीं गया।</p>\n<p>लगभग पूरा दिन वह विक्रम के साथ रहा।</p>\n<p>वह जानता था कि मिलने का अर्थ केवल मिलना नहीं रह गया है।</p>\n<p>उसे अपनी नौकरी और अनुशासन का भी पता था।</p>\n<p>और उससे कहीं ज़्यादा इस बात का कि अगर गाँव तक इस रिश्ते की परछाईं भी पहुँची, तो सबसे पहले उँगली कविता पर उठेगी।</p>\n<p>उसके लिए ख़तरा था।</p>\n<p>कविता के लिए—पूरा जीवन।</p>\n<p>यही बात उसे रोकनी चाहिए थी।</p>\n<p>फिर भी वह ख़ुद को पूरी तरह रोक नहीं पा रहा था।</p>\n<p>उसे पिता याद आए।</p>\n<p>वह नाम याद आया जिसे परिवार की दो पीढ़ियों ने गाँव में बेदाग रखने की कोशिश की थी।</p>\n<p>उसने सोचा—</p>\n<p>वह नहीं जाएगा।</p>\n<p>लेकिन वह फ़ैसला उसने अपने मन से ज़्यादा अपनी समझ को सुनाकर किया था।</p>\n<p>दो दिन बाद कविता ने फिर फोन किया।</p>\n<p>“आओगे?”</p>\n<p>इस बार बीच में कोई लंबी बात नहीं हुई।</p>\n<p>विक्रम चुप रहा।</p>\n<p>और उन्हीं कुछ क्षणों में वह सारी वजहें एक बार फिर उसके भीतर से गुज़रीं जिनके कारण उसे नहीं जाना चाहिए था।</p>\n<p>फिर भी उसने इस बार ख़ुद को कोई तर्क नहीं दिया।</p>\n<p>कोई बहाना नहीं बनाया।</p>\n<p>वह चला गया।</p>"}, {"chapter": 4, "title": "अध्याय 3 — अनकहे से आगे", "content": "<h1>अध्याय 3 — अनकहे से आगे</h1>\n<p>विक्रम एक शाम पहले ही गुरुग्राम पहुँच गया था। पूरे रास्ते उसकी हथेलियाँ नम रहीं। बाइक की सीट से उसकी कमीज़ गीली हो चुकी थी, जबकि हवा ठंडी थी।</p>\n<p>उसका दिमाग लगातार कोई वाक्य बनाने की कोशिश करता—सही शब्द, सही टोन—लेकिन हर बार सोच अधूरी रह जाती थी। वह ख़ुद को समझाता रहा कि यहाँ तक आना ही उसके फ़ैसले का सबूत है।</p>\n<p>लेकिन अगर वह सचमुच इतना तय था, तो उसके साथ रात रुकने भर का सामान क्यों पड़ा था?</p>\n<p>उस रात कविता का फोन आया। सुबह आठ बजे वह मधुबन, करनाल स्थित हरियाणा पुलिस अकादमी से हरियाणा रोडवेज़ की बस पकड़ेगी और करीब ग्यारह बजे गुरुग्राम बस स्टैंड पहुँच जाएगी।</p>\n<p>विक्रम समय से पहले वहाँ मौजूद था। डीज़ल की गंध, गन्ने के रस की मशीन की खड़खड़ाहट, रोडवेज़ बसों के हॉर्न—वह इन सबके बीच एक खंभे से टिका खड़ा रहा।</p>\n<p>कविता के लिए ट्रेनिंग से एक दिन, यहाँ तक कि एक रात बाहर रह जाना बहुत असामान्य नहीं था। उसने घर पर ट्रेनिंग से जुड़े किसी काम का इतना अस्पष्ट-सा कारण बताया था कि आगे ज़्यादा सवाल पूछने की गुंजाइश न रहे।</p>\n<p>फिर भी बस में बैठी कविता पूरे रास्ते अपने फ़ैसले का जोखिम सोचती रही। कोई परिचित देख ले, गाँव का कोई आदमी उसी रास्ते पर मिल जाए, किसी तरह बात घर तक पहुँच जाए—उसके लिए इसकी कीमत विक्रम से कहीं ज़्यादा हो सकती थी।</p>\n<p>लगभग आधा रास्ता बीतने तक वह इन सबके बारे में सोचती रही।</p>\n<p>फिर उसने सोचना छोड़ दिया।</p>\n<p>फ़ैसला तो वह पहले ही कर चुकी थी।</p>\n<p>ग्यारह बजे के आसपास वह बस से उतरी। साधारण सलवार-कमीज़, कोई वर्दी नहीं, कोई ऐसा गहना नहीं जिससे वह अलग पहचानी जाए। तेज़ धूप में भी दुपट्टा आदतन अपने करीब समेटे हुए।</p>\n<p>भीड़ के बीच उसकी नीली-धूसर आँखों ने विक्रम को लगभग उसी क्षण ढूँढ़ लिया।</p>\n<p>और विक्रम ने रास्ते भर जो कुछ कहने की तैयारी की थी, वह सब वहीं ख़त्म हो गया।</p>\n<p>बाइक पर बैठते समय कविता ने सहारे के लिए उसका हाथ पकड़ा। इतने समय में पहली बार उनकी उँगलियाँ इस तरह छुई थीं—त्वचा से त्वचा, बीच में कुछ भी नहीं।</p>\n<p>किसी ने कुछ नहीं कहा।</p>\n<p>उसकी उँगलियाँ बाइक की धातु से ठंडी थीं। विक्रम की नहीं।</p>\n<p>स्पर्श एक पल से भी कम रहा, मगर वह विक्रम के भीतर ऐसे उतरा जैसे किसी ऐसे तार को छू लिया हो जिसे वह बरसों से बेजान समझता आया था—एक झटके में, पूरा।</p>\n<p>होटल स्काईलार्क सेक्टर 14 में था, बस स्टैंड से करीब एक किलोमीटर दूर। लॉबी में अलमारियों पर लगी पीतल की मूर्तियाँ रखी थीं और कोने में एक पुरानी कुर्सी पर सूखे फूलों वाला एक गमला रखा था। जगह में न तो ताज़ेपन का अहंकार था और न ही गिरावट का शर्मसार भाव—बस एक जगह जो वर्षों से अपने मेहमानों की गोपनीयता का सम्मान करती आई थी।</p>\n<p>विक्रम ने इसे सोच-समझकर चुना था। उनके बीच जो कुछ भी होने वाला था, उसके लिए वह ऐसी जगह चाहता था जहाँ चाहे कोई भी आए-जाए, पर उनकी कहानी किसी की कहानी में शामिल न हो।</p>\n<p>रजिस्टर में कविता ने ऐसा नाम लिखा जो पूरी तरह उसका नहीं था। भुगतान नकद हुआ। रिसेप्शन पर दो-चार सामान्य सवाल पूछे गए और फिर दोनों लिफ्ट में थे। धातु के डिब्बे की संकीर्ण जगह में फिनाइल की तीखी गंध थी—हजारों अजनबियों की गंध, जो इन दीवारों में महीनों तक रहती है। उसका कंधा कविता के कंधे से छू रहा था। उस गंध के बीच भी उसे अपनी कमीज़ में पसीना और सड़क की धूल महसूस होती रही। उसने कंधा हटाया नहीं।</p>\n<p>कमरे का दरवाज़ा उनके पीछे हल्की-सी आवाज़ के साथ बंद हुआ।</p>\n<p>पर्दे आधे खिंचे थे और बाहर की रोशनी कालीन पर एक सीधी पट्टी की तरह पड़ी हुई थी। खिड़की के बाहर होटल की दीवार के साथ लगे नीम और अमलतास के पेड़ों से मार्च की हल्की हवा में सूखे पत्ते गिर रहे थे। उनकी सरसराहट सड़क के सामान्य शोर के साथ कमरे तक आ रही थी। एक मौसम, जो चुपचाप ख़ुद को ख़त्म कर रहा था; नई कोंपलें अभी हफ्तों दूर थीं और किसी भी सूनी शाखा पर दिखाई नहीं देती थीं।</p>\n<p>कुछ देर दोनों केवल एक-दूसरे को देखते रहे।</p>\n<p>अब उनके बीच कोई फोन नहीं था, कोई चाय की ट्रे नहीं, कोई आँगन नहीं।</p>\n<p>“मैं इसे ख़त्म करने आया था,” विक्रम ने आख़िर कहा।</p>\n<p>शांत कमरे में उसकी अपनी आवाज़ उसे कुछ अजीब लगी।</p>\n<p>कविता ने उसकी ओर देखा। बाइक से आते हुए उसके बालों की एक लट खुलकर गर्दन के पास आ गई थी और दुपट्टा कंधे से थोड़ा खिसक चुका था।</p>\n<p>“मुझे पता है,” उसने कहा। “फिर भी मैं आ गई।”</p>\n<p>विक्रम उसके पास आया।</p>\n<p>जल्दी में नहीं, मगर अब इतना धीरे भी नहीं कि इसे सावधानी कहा जा सके। उसने कविता को अपने करीब किया और अपना माथा उसके माथे से लगा दिया।</p>\n<p>इतने पास कि दोनों की साँसें एक-दूसरे से मिल रही थीं।</p>\n<p>विक्रम के हाथों में हल्की कंपन थी जब उसने कविता को अपने करीब किया। उसकी साँस को नियंत्रण में रखना पड़ रहा था।</p>\n<p>बरसों उसने ख़ुद को वर्दी, अनुशासन और एक सीधी रेखा में बाँधकर रखा था। उस रेखा के भीतर वह कभी किसी के इतने करीब नहीं आया था कि किसी की साँस अपने चेहरे पर महसूस कर सके।</p>\n<p>और अब कविता उसके सामने थी।</p>\n<p>विक्रम ने उसका चेहरा अपनी हथेलियों में लिया। कविता ने आँखें बंद कर लीं। उनके होंठ मिले—पहले ठहरे हुए, फिर बेसब्र। विक्रम की उँगलियाँ गर्दन के पास खुली लट में उलझ गईं, और कविता ने उसकी कमीज़ का कॉलर मुट्ठी में भींच लिया, जैसे महीनों तक चाय की ट्रे थामे रही मुट्ठी को आख़िर कुछ और मिल गया हो।</p>\n<p>कविता ने बहुत धीमे कहा—</p>\n<p>“दरवाज़ा लॉक कर दो।”</p>\n<p>विक्रम ने दरवाज़ा बंद किया। लॉक की खट के बाद कमरा एकदम चुप हो गया। जब वह उसकी ओर मुड़ा, तब कविता की साँस पहले से तेज़ हो चुकी थी।</p>\n<p>कविता के हाथों में हल्की कंपन थी। उसने इस पल को न जाने कितनी बार अपने मन में देखा था, फिर भी सामने आने पर उसके हाथ उतने निश्चित नहीं थे जितना उसने सोचा था। उसका दुपट्टा कंधों से फिसलकर नीचे गिर गया।</p>\n<p>कुछ क्षण दोनों वैसे ही एक-दूसरे के बहुत करीब खड़े रहे।</p>\n<p>“विक्रम…”</p>\n<p>बस उसका नाम।</p>\n<p>उसके बाद जो कुछ उनके बीच था, उसमें जल्दबाज़ी नहीं रही। चाहत जैसे धीरे-धीरे अपना संकोच छोड़ रही थी।</p>\n<p>कुछ ही देर में कमरे के बाहर की दुनिया जैसे बहुत दूर चली गई।</p>\n<p>न सड़क का शोर सुनाई दे रहा था, न आधी खुली खिड़की से आती सूखे पत्तों की सरसराहट। कमरे की उस गहरी शांति में बस उनकी तेज़ होती साँसें थीं—कभी एक-दूसरे में उलझती हुईं, कभी कुछ पल के लिए थमती हुईं।</p>\n<p>उस ख़ामोशी के बीच कभी-कभी केवल एक नाम सुनाई देता—</p>\n<p>“विक्रम…”</p>\n<p>कविता की आवाज़ बहुत धीमी थी, लगभग साँस में घुली हुई।</p>\n<p>और हर बार अपना नाम उसकी आवाज़ में सुनकर विक्रम उसे थोड़ा और करीब महसूस करता।</p>\n<p>बहुत समय से जो एहसास दोनों के बीच अनकहा ठहरा हुआ था, उस दिन पहली बार उसे किसी शब्द की ज़रूरत नहीं रही।</p>\n<p>बहुत देर बाद कविता का सिर विक्रम की छाती पर था और उसका हाथ उसकी साँसों के साथ धीरे-धीरे उठता-गिरता रहा।</p>\n<p>काफी देर तक दोनों में से किसी ने कुछ नहीं कहा।</p>\n<p>फिर विक्रम ने धीमे स्वर में कहा, “तुम तो आग हो, कविता—पूरी की पूरी आग।”</p>\n<p>कविता हँस पड़ी। कोहनी के सहारे थोड़ा ऊपर उठकर उसने उसकी ओर देखा।</p>\n<p>“आग?”</p>\n<p>उसकी आँखों में हल्की शरारत लौट आई थी।</p>\n<p>“इतने महीनों तक चाय की ट्रे पकड़े रही और आख़िर में ये निकला मुझमें? तुम्हें तो बहुत पहले ही पता चल जाना चाहिए था।”</p>\n<p>शाम की रोशनी धीरे-धीरे सुनहरी होती गई और कुछ समय बाद वे फिर एक-दूसरे के करीब आए—इस बार पहले से अधिक सहज, बिना उस शुरुआती घबराहट के। बाद में दोनों देर तक साथ पड़े रहे और बीच-बीच में ऐसी बातों पर हँसते रहे जिनकी वजह वे किसी को समझा नहीं सकते थे—न किसी पति को, न किसी अदालत को, न बरसों बाद व्हिस्की के गिलास थामे बैठे तीन दोस्तों को।</p>\n<p>कुछ देर बाद कविता शांत हो गई।</p>\n<p>“कब से राह देख रही हूँ कि अपराध-बोध आए,” उसने कहा। “अब तक नहीं आया।”</p>\n<p>विक्रम कुछ क्षण चुप रहा।</p>\n<p>“शायद जो भीतर हमेशा से सच था, उसके लिए अपराध-बोध इतनी जल्दी नहीं आता।”</p>\n<p>कविता ने सिर उठाकर उसकी ओर देखा।</p>\n<p>वही पुरानी नज़र—जो कभी चाय के कप के उस पार से उसे देखा करती थी। फ़र्क़ इतना था कि आज उसमें कुछ अधूरा नहीं था।</p>\n<p>“इतने समय तक मुझे लगता रहा कि शायद मैं तुम्हारी निगाहों का मतलब अपने मन से बना रही हूँ। कई रातें ख़ुद को समझाया कि एक शादीशुदा औरत को वो सब चाहने का हक नहीं जो मैं चाह रही थी।”</p>\n<p>“तुमने कुछ भी अपने मन से नहीं बनाया था।”</p>\n<p>“अब जानती हूँ।”</p>\n<p>उसकी उँगली धीरे से विक्रम की कॉलरबोन पर चली।</p>\n<p>“मुझे नहीं पता इसका आगे क्या होगा, विक्रम। बस इतना पता है कि मुझे यहाँ आने का अफसोस नहीं है।”</p>\n<p>कुछ देर बाद कविता ने धीमे से पूछा—</p>\n<p>“याद है, आँगन में एक दिन मैंने तुमसे कहा था कि किशोरावस्था में सोचती थी मेरा पति कैसा होगा?”</p>\n<p>“याद है।”</p>\n<p>“मैंने कहा था कि वो अभी तक नहीं मिला।” वह कोहनी के सहारे थोड़ा उठी, ताकि उसे ठीक से देख सके। “वो पूरा सच नहीं था।”</p>\n<p>विक्रम ने कुछ नहीं कहा।</p>\n<p>“जिस दिन मैंने तुम्हें पहली बार सच में देखा—रामफल के यहाँ कभी-कभार आने वाले किसी आदमी की तरह नहीं—उसी पल मेरे भीतर से, बिना चाहे, एक आवाज़ आई: यही है। वही आदमी, जिसकी मैंने कल्पना की थी। मेरे अपने आँगन में खड़ा… बस एक साल देर से।”</p>\n<p>वह धीमे से हँसी, मगर उस हँसी में कुछ भी हल्का नहीं था।</p>\n<p>“मैं चाहती रही, विक्रम। उसी पहली दोपहर से।”</p>\n<p>उसके बाद दोपहर कब शाम में बदल गई, दोनों को ठीक से पता नहीं चला। वे बहुत देर तक बातें करते रहे—कविता के बचपन के बारे में, उसकी उस बहन के बारे में जिससे अब बहुत कम बात होती थी, विक्रम के अकादमी के दिनों के बारे में और उन दूर की पोस्टिंग्स के बारे में जहाँ कभी-कभी ठंड में दोस्ती निभाना तक मेहनत जैसा लगने लगता था।</p>\n<p>शाम को वे होटल के ही रेस्टोरेंट में नीचे खाना खाने गए। लाल मेज़पोश और उजली रोशनी में उनके चेहरे एक-दूसरे के करीब दिख रहे थे। उन्होंने दाल मखनी और तंदूरी रोटी मँगाई। रोटी का एक कौर तोड़कर कविता कटोरी में घुमाती रही, विक्रम ने चम्मच उठाकर रख दिया। दाल ठंडी होकर ऊपर से जम गई और आधे से अधिक वापस चली गई।</p>\n<p>मेज़ के नीचे एक बार उनके हाथ छुए।</p>\n<p>इस बार किसी ने तुरंत हाथ नहीं हटाया।</p>\n<p>बिल आया तो विक्रम के पर्स निकालने से पहले ही कविता भुगतान कर चुकी थी और उसने उसकी कोई दलील नहीं सुनी।</p>\n<p>रात दस बजे के बाद कविता थोड़ी दूर जाकर रामफल को फोन करने लगी। उसकी आवाज़ अचानक सपाट और व्यावहारिक हो गई थी। ट्रेनिंग की अनिश्चित दिनचर्या उसके लिए पहले भी पर्याप्त बहाना बनती रही थी; उसने बस इतना कहा कि वह अगले दिन दोपहर तक घर पहुँच जाएगी।</p>\n<p>रामफल ने ज़्यादा कुछ नहीं पूछा।</p>\n<p>फोन ख़त्म हुआ और कविता वापस कमरे में आ गई।</p>\n<p>दोनों ने उस बातचीत का फिर ज़िक्र नहीं किया।</p>\n<p>अब किसी बस को पकड़ने की जल्दी नहीं थी, न कमरे में कोई घड़ी उनके लिए समय गिन रही थी। आधी रात के बाद कब दोनों एक-दूसरे में उलझे सो गए, पता नहीं चला।</p>\n<p>सुबह शहर का शोर उनसे पहले जाग चुका था।</p>\n<p>अगले दिन कविता फिर बस में थी—रामफल के घर लौटती हुई, उस ज़िंदगी की ओर जिसे इस बात का कोई अंदाज़ा नहीं था कि गुरुग्राम के एक कमरे में क्या बदल चुका है। वापसी का रास्ता उसे आते समय से लंबा लगा, जबकि दूरी वही थी।</p>\n<p>खिड़की के बाहर नीम और अमलतास की सूनी शाखाएँ पीछे छूटती जा रही थीं—आसमान की ओर फैली खाली हथेलियों जैसी। सड़क के किनारे सूखे पत्तों के ढेर हवा के हर झोंके पर करवट बदलते, और मार्च की रोशनी धीरे-धीरे सुनहरी-धूसर होती जा रही थी। छाल की दरारों में अगर कोई कोंपल थी भी, तो इतनी नन्ही कि गुज़रती बस की नज़र उस तक नहीं पहुँच सकती थी।</p>\n<p>कविता ने माथा ठंडे शीशे से लगा लिया।</p>\n<p>उसने फिर अपने भीतर उस अपराध-बोध को ढूँढ़ने की कोशिश की जिसके आने की बात उसने विक्रम से कही थी।</p>\n<p>वह अब भी नहीं था।</p>\n<p>और शाम को उसे उसी घर में वापस जाना था। वही मेज़ लगानी थी। उसी आदमी के पास सोना था, जिसने कभी उससे ऐसा सवाल ही नहीं पूछा था जिसके जवाब में उसे अपने भीतर की कोई सचमुच महत्वपूर्ण बात छिपानी पड़े।</p>\n<p>बस अपने ठिकाने पर पहुँची तो कविता ने उस पूरे दिन को अपने भीतर समेट लिया—जैसे कोई कीमती चीज़ रुमाल में बाँधकर कपड़ों की तह के सबसे नीचे रख देता है। चेहरे पर वही सामान्य भाव लौट आए, और वह ट्रेनिंग के किसी काम से लौटती एक साधारण औरत की तरह नीचे उतर गई।</p>\n<p>लेकिन जो बदल चुका था, उसे दोनों जानते थे।</p>\n<p>अगली सुबह नहाते समय विक्रम ने आईने में अपनी पीठ पर कविता के नाखूनों के पतले अर्धचंद्राकार निशान देखे—हल्के गुलाबी, जो पानी की गर्मी में और उभर आए थे। उसने उन पर उँगली नहीं फेरी; बस देखता रहा, जब तक भाप ने शीशा धुँधला नहीं कर दिया—और उस धुँधलके में उस शाम की सुनहरी रोशनी लौट आई, और उसके ऊपर झुकी कविता।</p>\n<p>दोनों ने दोबारा मिलने की बात उस समय नहीं कही।</p>\n<p>ज़रूरत भी नहीं थी।</p>\n<p>दोनों जानते थे—</p>\n<p>यह आख़िरी बार नहीं था।</p>"}, {"chapter": 5, "title": "अध्याय 4 — चुराए हुए कुछ पल", "content": "<h1>अध्याय 4 — चुराए हुए कुछ पल</h1>\n<p>कुछ दिन बाद विक्रम उसे फिर उसी बस स्टैंड पर लेने पहुँचा। मधुबन की बस पकड़ने के बजाय कविता ने एक शाम पहले फोन करके ख़ुद कहा था कि वह उसे छोड़कर आए।</p>\n<p>“एक बार सड़क को महसूस करना चाहती हूँ,” उसने फोन पर कहा था, “अजनबियों से भरी बस में बैठकर उसे झेलने के बजाय। तुम ख़ुद छोड़कर आओ।”</p>\n<p>विक्रम ने बहस नहीं की।</p>\n<p>मुरथल के पास वे अमरीक सुखदेव ढाबे पर रुके, जहाँ तंदूर का धुआँ उठ रहा था और सड़क पर ट्रकों के हॉर्न लगातार बज रहे थे। कविता ने गर्म पराठे के साथ अचार उठाया; तीखी मिर्च से उसकी आँखों में पानी आया तो वह ख़ुद ही हँस पड़ी, और विक्रम कुछ देर उसे देखता रहा।</p>\n<p>“मुझे ये अच्छा लग रहा है,” आख़िर उसने ढाबे के शोर के बीच कहा। “ऐसी जगह होना जहाँ कोई ये नहीं देख रहा कि मैं कितनी ज़ोर से हँस रही हूँ।”</p>\n<p>“ये तुम्हें मिल सकता है,” विक्रम ने कहा। “सिर्फ आज के लिए नहीं।”</p>\n<p>कविता ने पराठे का कौर तोड़ा और नज़र थाली पर ही रखी।</p>\n<p>“मत कहो। आज नहीं। आज मुझे बस ये पराठा चाहिए, ये सड़क, और सामने बैठे तुम—ये जताते हुए कि तुमने अभी-अभी ख़ुद को ये कहते नहीं सुना।”</p>\n<p>विक्रम ने बात वहीं छोड़ दी।</p>\n<p>दोनों फिर निकल पड़े।</p>\n<p>कुछ दूर आगे सड़क के दोनों ओर सफेदे के लंबे पेड़ हरे खड़े थे—सदाबहार, पतझड़ से बेअसर—जबकि बाकी पेड़ों के पत्ते झड़ चुके थे और उनकी नंगी शाखाएँ आसमान की ओर उठी थीं। हवा अब हल्की हो चली थी। बाइक के पीछे बैठी कविता ने अचानक एक हाथ विक्रम की कमर से हटाया और खुली हवा में फैला दिया।</p>\n<p>उसने सिर थोड़ा पीछे किया और हँस पड़ी।</p>\n<p>वह हँसी किसी बात पर नहीं थी।</p>\n<p>बस उस क्षण पर थी।</p>\n<p>बरसों उसने आवाज़ धीमी और हाथ अपनी जगह पर रखे थे। आज उसकी खुली हथेली से हवा बहती जा रही थी, जैसे बरसों से मुट्ठी में भींचा कोई पानी आख़िर रास्ता पा गया हो।</p>\n<p>जब उसने हाथ वापस खींचा तो इस बार केवल सहारे के लिए विक्रम को नहीं पकड़ा, बल्कि दोनों बाँहें उसके चारों ओर लपेटकर अपना चेहरा उसकी पीठ से लगा लिया।</p>\n<p>बाकी रास्ते वह वैसे ही बैठी रही।</p>\n<p>“अगली छुट्टी में फिर यही सड़क?” उसने हल्के से पूछा। फिर उसकी दोनों बाँहें विक्रम के चारों ओर और भी मज़बूती से लपट गईं।</p>\n<p>“यही सड़क,” उसने कहा।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>उस रास्ते के बाद उन्हें फिर ऐसा मौका मिलने में कई महीने लग गए।</p>\n<p>अगली छुट्टी पर विक्रम घर आया तो कविता ने फोन पर बताया कि रामफल तीन दिनों के लिए पानीपत जा रहा है। कई महीनों में पहली बार वह उस घर में अकेली होगी।</p>\n<p>दूसरी रात विक्रम मोटरसाइकिल लेकर नहीं गया। घरों की खिड़कियों से बचता हुआ वह खेतों का लंबा रास्ता पैदल पार करता गया—अँधेरे में मेड़ों पर पाँव जमाते हुए, सूखी मिट्टी की हल्की चरमराहट के बीच, और दूर किसी कुत्ते के भौंकते ही पूरा-का-पूरा रुककर। श्रीनगर के ख़तरे वाले इलाकों में ऑपरेशनों के दौरान भी उसका दिल इतनी तेज़ नहीं धड़का था।</p>\n<p>कविता पूरे दिन उसका इंतज़ार करती रही थी।</p>\n<p>कई बार बिना किसी वजह के चेहरे पर मुस्कान आ जाती और वह होंठ दबाकर उसे लौटा देती। उसने चादर दो बार बदली और हर बार साँकल को जाकर देखा।</p>\n<p>रात को विक्रम दरवाज़े तक पहुँचा तो दस्तक देने की ज़रूरत नहीं पड़ी।</p>\n<p>कविता ने पहले ही दरवाज़ा खोल दिया।</p>\n<p>“पैदल आए हो?”</p>\n<p>“बाइक की आवाज़ से आधी गली जाग जाती।”</p>\n<p>“पूरी गली जाग जाती। अंदर आओ, इससे पहले कि किसी का कुत्ता तुम्हें यहाँ खड़ा देख ले।”</p>\n<p>कविता उसे तुरंत भीतर ले गई।</p>\n<p>घर के पिछले हिस्से का छोटा कमरा शादी के बाद धीरे-धीरे केवल उसका रह गया था।</p>\n<p>“सूरज निकलने से पहले तक,” कविता ने उसका हाथ थामते हुए कहा—दरवाज़े से भीतर आने के बाद पहली बार उसने उसे छुआ था। “तब तक पूरी रात हमारी है। यहाँ, मेरी अपनी दीवारों के बीच। मैं जानना चाहती हूँ कि ये कैसा लगता है।”</p>\n<p>उसने हथेली विक्रम के चेहरे पर रखी। “गुरुग्राम के बाद हर रात, विक्रम। इसी घर में। कई रातें वो मुझसे तीन फुट दूर सोया होता था… और मैं तुम्हें याद करती थी।”</p>\n<p>फिर वे एक-दूसरे के करीब आए।</p>\n<p>लेकिन बाद में, जब कविता उसके सीने पर सिर रखकर सो गई और नींद में भी उसका हाथ विक्रम के हाथ पर ढीला-सा टिका रहा, तो विक्रम बहुत देर तक जागता रहा।</p>\n<p>उसकी बाँह कंधे के नीचे सुन्न हो चली थी, पर उसने उसे हिलाया नहीं। कविता की साँस एक लय में चल रही थी—जैसे कुछ घंटों के लिए उसे किसी चीज़ की रखवाली नहीं करनी हो।</p>\n<p>सुबह आसमान में हल्की सफ़ेदी उतरनी शुरू हुई तो विक्रम ने ख़ुद उसे जगाया।</p>\n<p>दरवाज़े तक पहुँचकर कविता ने उसकी बाँह पकड़ ली।</p>\n<p>“शुक्रिया,” उसने कहा। आवाज़ पहले से कहीं धीमी थी। “पूरी रात रुकने के लिए। यहाँ—किसी ऐसी जगह नहीं, जिसके पैसे देने पड़ें और सुबह होते ही छोड़नी पड़े।”</p>\n<p>वह एक पल रुकी।</p>\n<p>“इस शादी की हर सुबह मैंने ऐसे आदमी के पास आँख खोली है, जो करवट बदल चुका होता है या जा चुका होता है। आज कोई रुका था।”</p>\n<p>विक्रम ने उसके माथे को चूमा और निकल गया।</p>\n<p>अगली मुलाक़ात की कोई तारीख़ तय नहीं हुई।</p>\n<p>कविता दरवाज़े पर तब तक खड़ी रही, जब तक विक्रम के कदमों की आहट पहले गली के मोड़ पर, फिर खेतों की धुंध में, फिर सुबह की पहली चिड़ियों की आवाज़ों में घुलकर खो नहीं गई।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>चार महीने बाद विक्रम 23 राष्ट्रीय राइफल्स से दस दिनों की छुट्टी लेकर लौटा।</p>\n<p>छुट्टी के दो दिन ही बीते थे कि कविता का फोन आया।</p>\n<p>“इस बार मैं रामफल के यहाँ नहीं जा रही,” उसने बिना किसी भूमिका के कहा। “घर पर कह दिया है कि आराम चाहिए। माँ के यहाँ हूँ, कोसली में। मिलना है तो यहीं मिलना होगा।”</p>\n<p>सर्दियों की सुबह थी। खेत सरसों के पीले फूलों से लदे थे और घना कोहरा नौ बजे के बाद भी ज़मीन छोड़ने को राज़ी नहीं था—जैसे रात जाते-जाते खेतों पर अपनी सफ़ेद चादर भूल गई हो। हवा में सरसों की तीखी-कड़वी गंध घुली थी, जो हर बार भीतर खिंचने पर जीभ पर आकर टिक जाती थी।</p>\n<p>कविता उसे खेतों के बीच उस जगह ले गई जहाँ सरसों का छोटा-सा जंगल इतना ऊँचा और घना था कि भीतर बैठा आदमी बाहर से दिखता ही नहीं था—पीली लहरों के बीच एक छिपा हुआ घेरा, जहाँ दुनिया की नज़र पहुँचने से पहले ही ठहर जाती थी।</p>\n<p>“बचपन में यहीं छिपकर बैठा करती थी,” उसने कहा, “जब भी कोई घंटा चाहिए होता था, जो सिर्फ मेरा हो।”</p>\n<p>कविता ने शॉल का आधा हिस्सा गीली मिट्टी पर बिछाया, आधा दोनों के कंधों पर डाल दिया, और सरककर विक्रम को भीतर अपनी जगह पर बिठा लिया। पौधों की पत्तियों से ओस उसके बालों पर टपक रही थी।</p>\n<p>“कोई ऐसी बात बताओ जो तुमने कभी किसी से नहीं कही,” उसने अचानक कहा।</p>\n<p>विक्रम कुछ देर सोचता रहा।</p>\n<p>“लगता था कश्मीर में मेरे भीतर कुछ मर जाएगा। मरा नहीं। बस जो पहले से सख़्त था, उसे और सख़्त कर दिया।”</p>\n<p>कविता कुछ देर चुप रही।</p>\n<p>“मुझे भी लगता था तुम्हारे गाँव में मेरे भीतर कुछ मर जाएगा,” आख़िर उसने कहा। “वो इंतज़ार। ट्रे पर एक पल ज़्यादा ठहरा हाथ। एक नज़र, जिसे मैंने कभी ज़ुबान तक नहीं आने दिया।”</p>\n<p>वह उसकी ओर पूरी तरह मुड़ी।</p>\n<p>“मारा नहीं। बस उसे सब्र सिखा दिया।”</p>\n<p>विक्रम ने उसका हाथ अपने हाथ में ले लिया और कविता ने अपनी ठंडी उँगलियाँ उसके जबड़े पर रख दीं।</p>\n<p>“चार महीने,” उसने धीमे से कहा। “ये सब भीतर अधूरा लिए मैं उस घर में वापस नहीं जाऊँगी।”</p>\n<p>सरसों के ऊँचे पौधों के बीच वे एक-दूसरे के करीब आए और बाद में बहुत देर तक वहीं बैठे रहे, कविता का सिर विक्रम के कंधे पर था और उनके चारों ओर पीले फूलों के बीच सर्द सुबह धीरे-धीरे खुल रही थी।</p>\n<p>दूर खेतों में लोगों की आवाज़ें सुनाई देने लगीं। कविता ने शॉल झाड़कर कंधों पर डाली; विक्रम ने उसके बालों से सरसों की एक पंखुड़ी हटाई।</p>\n<p>वे अलग-अलग दिशाओं में निकल गए।</p>\n<p>धूप चढ़ी तो पीले फूलों के बीच एक जगह दबी रह गई—गीली मिट्टी पर शॉल की सिलवटें, कुचले हुए कुछ डंठल। बाकी जंगल धीरे-धीरे अपनी पीठ सीधी करता गया, मगर वह घेरा खेत में उनका अकेला सबूत बनकर वहीं पड़ा रहा।</p>"}, {"chapter": 6, "title": "अध्याय 5 — आख़िरी बार—और उसे पता भी नहीं था", "content": "<h1>अध्याय 5 — आख़िरी बार—और उसे पता भी नहीं था</h1>\n<p>तब तक दो साल बीत चुके थे, हालाँकि दोनों ने कभी बैठकर उन दो वर्षों का हिसाब नहीं लगाया था। उनकी यादों में समय तारीखों से नहीं, कुछ छोटी-छोटी चीज़ों से दर्ज था—जैसे लंबे सफ़र में रास्ता मील के पत्थरों से नहीं, कुछ मोड़ों से याद रहता है: चाय की वह ट्रे जो हाथों में एक पल ज़्यादा ठहर जाती थी, सफेदों की कतार के बीच से गुज़रती वह सड़क, कविता के अपने कमरे की वह रात, और सरसों के खेत में चुराए कुछ घंटे। मुलाक़ातों के बीच लंबे इंतज़ार थे, और मिला हुआ समय इस तरह बचाकर रखा जाता था, जैसे सूखे के दिनों में घड़े का आख़िरी पानी।</p>\n<p>इस बार कहीं दूर जाने की बात कविता ने ही उठाई थी। बहुत समय बाद विक्रम की छुट्टियाँ और कविता की जमा छुट्टियाँ एक साथ पड़ रही थीं। वह कुछ दिन ऐसी जगह रहना चाहती थी जहाँ साथ चलते हुए उन्हें बार-बार पीछे मुड़कर न देखना पड़े।</p>\n<p>विक्रम ने गाड़ी ख़ुद चलाई। मुख्य सड़क उस साल इतनी ख़राब थी कि उसने मुरादाबाद बाइपास से होते हुए काशीपुर, बाजपुर और कालाढूंगी वाला लंबा रास्ता चुना। मैदान धीरे-धीरे पीछे छूटते गए और सड़क जंगलों के बीच चढ़ने लगी। ऊँचाई बढ़ने के साथ हवा भी बदलती गई; मैदानों की भारी गर्मी कम होती गई और चीड़ की हल्की गंध आने लगी। रास्ते में उन्होंने दो बार सड़क किनारे चाय के लिए गाड़ी रोकी।</p>\n<p>नैनीताल आख़िरी मोड़ के बाद अचानक सामने आया—जैसे पहाड़ों ने अपनी ओट एकाएक हटा ली हो। नीचे झील थी, चारों ओर चीड़ से ढकी ढलानें, और मैदानों से बिल्कुल अलग ठंडी हवा, जिसमें कहीं दूर जलती लकड़ी के धुएँ की हल्की गंध घुली थी।</p>\n<p>उन्होंने मॉल रोड के पास द पवेलियन में कमरा लिया। होटल साधारण था, मगर झील इतनी पास थी कि सुबह कमरे तक पानी और पक्षियों की आवाज़ पहुँचती थी।</p>\n<p>दो दिन उनके पास कोई योजना नहीं थी। झील के किनारे चलते रहे, छोटे रेस्तराँ में खाते रहे, ठंडी हवा में गरम मोमोज बाँटकर खाए और शाम को कमरे की छोटी बालकनी में एक ही कंबल में बैठे रहे। ठंड कम हो जाने के बाद भी कविता के हाथ विक्रम की जैकेट के भीतर ही रहते।</p>\n<p>दूसरी शाम कविता ने धीमे से, लगभग सँभलकर, विक्रम से नीचे के छोटे बार से ड्रिंक्स मँगवाने को कहा—ग्रीन एप्पल वोडका, दो बड़े गिलास उसके लिए और दो विक्रम के लिए। मेन्यू में बस यही एक चीज़ थी जो उसे चेतावनी कम और फल ज़्यादा लगी थी। कमरे के लिए नहीं, उसने कहा, बालकनी के लिए—जहाँ किसी अजनबी की छत के बजाय झील उन्हें देख सके।</p>\n<p>विक्रम ने उसे देखा।</p>\n<p>“तुम तो पीती नहीं हो।”</p>\n<p>“नहीं पीती,” उसने माना। “कभी नहीं पी। न किसी शादी में, न अकेले, न जिज्ञासा में, न दुख में… हालाँकि दुख ने कई बार कहा।”</p>\n<p>वह विक्रम की बजाय झील की ओर देख रही थी। ढलती रोशनी में पानी सीसे-सा धूसर हो चला था—ठीक उसकी अपनी आँखों के उस रंग जैसा, जो कभी शीशे की तरह साफ़ रहता है और कभी बादल की तरह भारी।</p>\n<p>“अपने घर में सारी ज़िंदगी देखा है कि ये आदमियों के साथ क्या करती है। बहुत छोटी उम्र में ख़ुद से कह दिया था कि मेरे भीतर जो कुछ बचाने लायक बचा है, उसके पास इसे फटकने नहीं दूँगी।”</p>\n<p>एक पल के लिए उसके चेहरे पर कोई पुरानी, दबी हुई कड़वाहट उभरी।</p>\n<p>“फिर कहीं रास्ते में मैं ख़ुद से एक दूसरा सवाल पूछने लगी। अगर रामफल हर शाम उस पैसे से बेसुध हो सकता है, जो उतना ही मेरा भी था, तो मैंने पूरी शादी में अपने हिस्से की एक शाम तक ख़ुद से क्यों छीन रखी है? आज रात मैंने तय कर लिया है कि इस सवाल को जवाब की ज़रूरत नहीं।”</p>\n<p>फिर वह उसकी ओर मुड़ी।</p>\n<p>“आज मुझे तुमसे कुछ कहना है, और होश में रहकर शायद कह नहीं पाऊँगी। इसलिए ये।”</p>\n<p>विक्रम ने आगे कुछ नहीं पूछा। वह नीचे गया और दो चक्करों में चार गिलास लेकर लौट आया। वोडका का हल्का हरा रंग ढलती रोशनी को वैसे ही पकड़ रहा था, जैसे झील पकड़ रही थी—सुनहरा, धीरे-धीरे धूसर होता हुआ।</p>\n<p>कविता ने पहला घूँट बहुत धीरे लिया, जैसे कोई अनजान पानी में उतरने से पहले एक पैर से उसे परखता है। हल्की खाँसी आई, जिसे उसने हँसी में छिपाने की कोशिश की; आँखें एक पल को भर आईं। दूसरा घूँट पहले से सहज था, तीसरा उससे भी।</p>\n<p>विक्रम का हाथ अपने गिलास की ओर बढ़ा और बीच में ही रुक गया। वह बिना कुछ कहे उसे देखता रहा।</p>\n<p>पहला गिलास ख़त्म होने और दूसरे का आधा रह जाने तक उसके कंधे ढीले पड़ चुके थे। उसने अपनी ठंडी उँगलियाँ एक पल अपने तपते गाल पर रखीं, जैसे जाँच रही हो कि यह गर्माहट सचमुच उसकी है।</p>\n<p>“बस,” उसने कहा—धीमे, थोड़े लड़खड़ाते स्वर में—और गिलास मेज़ पर रख दिया।</p>\n<p>उस रात दोनों फिर एक-दूसरे के करीब आए। बाहर पहाड़ों की ठंड खिड़की से लगी थी और कमरे के भीतर उनके पास कुछ समय के लिए केवल एक-दूसरे की गर्माहट थी। बाद में कविता बहुत देर तक विक्रम के सीने पर सिर रखे चुप रही, उसकी उँगलियाँ अनजाने में उसकी त्वचा पर छोटे-छोटे निशान बनाती रहीं।</p>\n<p>“अब ठीक से कह सकती हूँ,” आख़िर उसने कहा। उसकी आवाज़ उससे छोटी थी, जितनी विक्रम सुनने का आदी था। “यह कहना मेरे लिए मुश्किल है, विक्रम। मैं चाहती हूँ तुम पूरी बात सुनो—सिर्फ वह हिस्सा नहीं जो सुनने में आसान है।”</p>\n<p>“सुन रहा हूँ।”</p>\n<p>“मैं तुम्हें छोड़ नहीं रही। यह बात सबसे पहले साफ़ रहे। ज़िंदगी हम जैसे दो लोगों को जिस भी रूप में साथ रहने देगी, उस रूप में मैं हमेशा तुम्हारे साथ रहूँगी।”</p>\n<p>वह एक पल चुप रही।</p>\n<p>“लेकिन अब तुम्हें आगे बढ़ना होगा। सच में। तुम्हारी शादी का वक्त आ गया है—और यह मैं तुम्हें दूर करने के लिए नहीं, तुम्हारी फ़िक्र में कह रही हूँ।”</p>\n<p>“जब तक तुम सच में इससे आगे नहीं निकल जाते, मैं यहीं हूँ। यह भी जान लो। मेरे लिए भी आसान नहीं है यह सोचना कि किसी दिन तुम्हारे पास कोई खुशी या कोई परेशानी होगी, और तुम मुझे सबसे पहले फोन नहीं करोगे। लेकिन मैं तुम्हारे साथ यह करती नहीं रह सकती। यह तुम्हारे साथ ठीक नहीं है, विक्रम।”</p>\n<p>“कविता—”</p>\n<p>“हम दोनों पहले से जानते हैं कि इसका कोई भविष्य नहीं। हम दो साल में सत्रह बार मिले हैं। मैंने हर मुलाक़ात गिनी है, विक्रम—उन्हें भी, जिन्हें हम दोनों ने किसी कैलेंडर पर नहीं लिखा। बस कभी इन शब्दों में कहा नहीं।”</p>\n<p>उसने सिर उठाकर उसे ठीक से देखा। कम रोशनी में उसकी आँखें चमक रही थीं—उनमें कुछ था जो न पूरी तरह आँसू थे, न उनकी ग़ैरमौजूदगी।</p>\n<p>“एक बात और, फिर चुप हो जाऊँगी। बाकी सब बदल जाए तो बदल जाए—मैं हमेशा तुम्हारी दोस्त रहूँगी। इस हिस्से पर कोई सौदा नहीं होगा, चाहे यह बातचीत हम दोनों से कुछ भी ले ले।”</p>\n<p>विक्रम बहुत देर चुप रहा। सीने में कसाव-सा उठा था, जिसका पहाड़ की ठंड से कोई लेना-देना नहीं था। उसका जबड़ा कसा, उसने मुँह खोला—और बिना कुछ कहे बंद कर लिया।</p>\n<p>“तुम सही हो,” आख़िर विक्रम ने कहा। आवाज़ जितनी चाही थी, उससे ज़्यादा खुरदरी निकली। “मैं भी जानता था। गुरुग्राम से ही… बस कभी इसे सामने रखकर सोचने की हिम्मत नहीं की।”</p>\n<p>“जान लेने से कहना आसान नहीं हो जाता,” कविता ने धीमे से कहा।</p>\n<p>“नहीं,” विक्रम ने माना। “नहीं होता।”</p>\n<p>उसने कविता को और करीब खींच लिया।</p>\n<p>“कहने के लिए शुक्रिया,” उसने उसके बालों में कहा। “मैं कभी नहीं कह पाता।”</p>\n<p>कविता उसके सीने से लगी हल्का-सा मुस्कराई; उसकी पलकों के कोने गीले थे।</p>\n<p>“किसी को तो कहना था। मैं चाहती थी कि यह बात मैं प्यार से कहूँ, इससे पहले कि ज़िंदगी इसे बेरहमी से कहे।”</p>\n<p>उसके बाद विक्रम बहुत देर तक उसे थामे रहा। खिड़की के बाहर झील पर कोहरा उतरता रहा—पहले दूर की रोशनियाँ मिटीं, फिर किनारा, फिर पानी; आख़िर में शीशे पर बस उन दोनों की परछाइयाँ बची रहीं।</p>\n<p>अगली सुबह झील पर हल्का कोहरा अब भी ठहरा हुआ था और दोनों होटल की छोटी मेज़ पर पराठे और दही के साथ नाश्ता कर रहे थे, जब कविता ने बिना पूछे विक्रम का फोन उठा लिया।</p>\n<p>उसने उसमें एक नंबर सेव किया और फोन वापस उसकी ओर सरका दिया।</p>\n<p>“मेरे साथ ट्रेनिंग की थी,” उसने कहा। “नैना। गुरुग्राम की है, अब घर के पास ही पोस्टेड है। तेज़ ज़ुबान वाली, थोड़ी अकेली भी।”</p>\n<p>कविता एक पल विक्रम की आँखों में कुछ खोजती रही।</p>\n<p>“तुम्हें कोई ऐसी चाहिए, जिसे तुमसे प्यार करने की कीमत हर बार अपनी बाकी पूरी ज़िंदगी से तौलनी न पड़े।”</p>\n<p>“कविता—”</p>\n<p>“इसे जितना है, उससे बड़ा मत बनाओ,” कविता ने कहा, और इस बार उसकी नज़र दही की कटोरी पर चली गई। “मैं बस तुम्हारे सामने एक दरवाज़ा रख रही हूँ।”</p>\n<p>विक्रम ने फोन में सेव हुआ नाम देखा, फिर कविता को।</p>\n<p>“तो अब मेरी होने वाली पत्नी भी तुम ही ढूँढ़ोगी? कोई ऐसी चीज़ बची भी है, कविता, जिसे सँभालने का ज़िम्मा तुम ख़ुद पर न ले लो?”</p>\n<p>कविता हँस पड़ी।</p>\n<p>“किसी को तो करना पड़ेगा। तुम्हें अपने भरोसे छोड़ दूँ, तो तुम्हारे फ़ैसले कभी अच्छे नहीं निकलते।”</p>\n<p>उस सुबह विक्रम को अंदाज़ा नहीं था कि वह दरवाज़ा असल में कितना बड़ा था।</p>"}, {"chapter": 7, "title": "अंतराल — फाइल का पहला पन्ना", "content": "<h1>अंतराल — फाइल का पहला पन्ना</h1>\n<p><i>बरसों बाद, जिस दिन विक्रम का नाम पहली बार किसी खास मेज़ से गुज़रा, एक फाइल चुपचाप खोली गई। उसमें पन्ने गिने-चुने थे, पर सारे बहुत ध्यान से लिखे हुए।</i></p>\n<p>पहला पन्ना एक नाम से शुरू होता था: <i>कविता।</i></p>\n<p>मोटे तौर पर दो साल—हालाँकि फाइल की भाषा बहुत सधी हुई थी, जैसे लिखने वाले को पता था कि कौन-से शब्द छोड़ देने हैं। रिश्ता बिना किसी शोर के ख़त्म हुआ था: कोई शिकायत नहीं, कोई गवाह नहीं, कोई ऐसी बात नहीं जो किसी असरदार आदमी के कानों तक पहुँचती।</p>\n<p>पन्ने के आख़िर में एक पंक्ति बाकी सब से अलग थी। आख़िरी मुलाक़ात की सुबह वही औरत विक्रम को किसी बिल्कुल दूसरी लड़की का फोन नंबर थमा गई थी।</p>\n<p>उस पंक्ति के नीचे दो बार रेखा खिंची थी।</p>\n<p>फाइल अपडेट रखने का ज़िम्मा जिस अफसर के पास था, वह देर तक उस रेखा को देखता रहा। फिर उसने हाशिये पर बस तीन शब्द लिखे, फाइल बंद की और उसे वापस दराज़ में सरका दिया।</p>\n<p><i>दिलचस्प। नज़र रखो।</i></p>"}, {"chapter": 8, "title": "अध्याय 6 — सूनी शामें", "content": "<h1>अध्याय 6 — सूनी शामें</h1>\n<p>नैना का नंबर विक्रम के फोन में कई महीनों तक वैसे ही पड़ा रहा।</p>\n<p>कविता पूछती तो विक्रम कोई सोची-समझी वजह गिना देता। सच यह था कि जब भी उसका अँगूठा उस नंबर तक पहुँचता, वह स्क्रीन बंद कर देता।</p>\n<p>उधर कविता से उसकी बातचीत भी धीरे-धीरे कम होने लगी थी।</p>\n<p>उनके बीच कोई झगड़ा नहीं हुआ था। कभी विक्रम फोन करता तो घंटी बजती रहती और कविता उठाती ही नहीं; कभी उठाती भी तो कुछ देर बाद ड्यूटी या किसी दूसरे काम का कहकर फोन रख देती।</p>\n<p>विक्रम को उस समय यह नहीं मालूम था कि कविता की कुछ शामों में अब कोई और भी शामिल होने लगा था।</p>\n<p>उसका नाम कमल था।</p>\n<p>कविता की ही पोस्टिंग पर तैनात एक कांस्टेबल।</p>\n<p>शुरुआत वैसे ही हुई, जैसे कविता के साथ ऐसी चीज़ें अक्सर शुरू होती थीं—चाय से। एक ठंडी रात कविता चाय का एक अतिरिक्त फ्लास्क लेकर बाहर की पोस्ट तक चली गई, जहाँ कमल की ड्यूटी थी। दूर से कमल कई घंटों से अकेला खड़ा दिख रहा था, साँस की भाप उसके सामने उठती हुई; किसी ने उससे यह तक नहीं पूछा होगा कि उसे चाय चाहिए या नहीं।</p>\n<p>कमल ने दोनों हाथों से कप लिया।</p>\n<p>“इतनी दूर आने की ज़रूरत नहीं थी।”</p>\n<p>कविता ने कंधे उचकाए। “कोई और आने वाला भी नहीं था।”</p>\n<p>वह लौटने लगी तो कमल बोला, “एक मिनट रुक जाओ। कोई बात करने वाला न हो, तो ये ड्यूटी बहुत लंबी लगती है।”</p>\n<p>कविता रुक गई।</p>\n<p>उस पहली रात उनकी बातचीत में ऐसा कुछ नहीं था जिसे बाद में याद करके कोई शुरुआत कहा जा सके। वे बस कुछ देर ठंड से कसे, तारों से चमकते आसमान के नीचे खड़े बातें करते रहे और फिर कविता बैरक की ओर लौट चली। कमल भी कविता के साथ हो लिया।</p>\n<p>सीधा रास्ता छोटा था, मगर दोनों पुराने बरगद की तरफ से घूमकर गए।</p>\n<p>पाँच मिनट ज़्यादा लगे।</p>\n<p>अगली बार भी वे उसी रास्ते से लौटे।</p>\n<p>फिर धीरे-धीरे वही उनका रास्ता बन गया।</p>\n<p>ड्यूटी साथ पड़ती तो कमल कविता को वापस छोड़ने आता और रास्ते भर छोटी-छोटी बातें पूछता रहता। उसके सवालों में कोई जल्दबाज़ी नहीं होती थी।</p>\n<p>बहुत पहले आँगन में चाय के प्याले के उस पार से विक्रम भी कविता से इसी तरह बातें किया करता था—तब, जब दोनों के बीच जो बन रहा था, उसका कोई नाम नहीं था।</p>\n<p>एक शाम कमल ने चलते-चलते कहा, “तुम कभी-कभी एकदम चुप हो जाती हो। जैसे कुछ ऐसा साथ लेकर चल रही हो जिसे कहीं रख नहीं सकती।”</p>\n<p>“इस वर्दी में हर कोई कुछ न कुछ लेकर चलता है।”</p>\n<p>“तुम्हारा अलग है।”</p>\n<p>कमल ने इसके आगे कुछ नहीं पूछा।</p>\n<p>इसी वजह से वह बात कविता के भीतर कुछ देर और ठहरी रही।</p>\n<p>कविता ने ख़ुद को समझाया कि इसमें कुछ नहीं है। साथ ड्यूटी करने वाले दो लोग हैं, बातें कर लेते हैं, कभी लंबा रास्ता चुन लेते हैं। उसने इस पर ज़्यादा विचार नहीं किया कि उसकी शामें कब से कमल की ड्यूटी के हिसाब से अपने आप बदलने लगी थीं—लगभग उसी तरह, जैसे कभी वे विक्रम की छुट्टियों के आसपास बदलती थीं।</p>\n<p>पहली नज़र में कमल में विक्रम की हल्की-सी झलक थी। वह भी लंबा था, कंधे चौड़े थे, हालाँकि उसका रंग विक्रम जितना साफ़ नहीं था और खुले इलाकों की पोस्टिंग की धूप उसके चेहरे पर दिखती थी। विक्रम के चेहरे पर जहाँ फौज की स्थिरता थी, वहाँ कमल के नैन-नक्श तीखे थे, और अपने बालों तथा पहनावे पर वह बाकी कांस्टेबलों से कुछ ज़्यादा ध्यान देता था।</p>\n<p>लेकिन कविता को उसकी ओर खींचने वाली बात उसका चेहरा नहीं था।</p>\n<p>कमल के साथ रहना आसान था।</p>\n<p>वह हँसता था, दूसरों को हँसाता था और महिलाओं से बात करते समय उसके व्यवहार में एक सहज सम्मान था, जिसे दिखाने के लिए उसे अलग से कोई कोशिश नहीं करनी पड़ती थी। मेस में किसी ने ठीक से खाना नहीं खाया हो तो वह बिना कुछ कहे अपनी प्लेट उसकी तरफ सरका देता। सामने वाला बोल रहा हो तो उसकी नज़र इधर-उधर नहीं भटकती थी—पूरी, बिना जल्दी के, जैसे उस पल उसे कहीं और होने की कोई चाह ही न हो।</p>\n<p>और सबसे बड़ी बात—वह वहाँ था। हर दिन।</p>\n<p>विक्रम की आवाज़ कविता ने दो वर्षों में बहुत सुनी थी, मगर उसकी मौजूदगी हमेशा चुराए हुए दिनों और घंटों में मिली थी।</p>\n<p>कमल के साथ ऐसा नहीं था।</p>\n<p>कभी बाज़ार के पास किसी कैफे में एक शाम निकल जाती, कभी दोनों की ड्यूटी जल्दी ख़त्म होती तो बातें लंबी हो जातीं।</p>\n<p>करीब तीन हफ्तों बाद की एक शाम कमल की किसी मामूली बात पर कविता खुलकर हँस पड़ी। अपनी आवाज़ सुनकर उसे ख़ुद हैरानी हुई। कमल उसे देख रहा था।</p>\n<p>“यही वाली,” कमल ने कहा।</p>\n<p>“क्या?”</p>\n<p>“तुम्हारी असली हँसी। इसे ऐसे बचाकर रखती हो जैसे खर्च हो जाएगी।”</p>\n<p>कविता कुछ नहीं बोली।</p>\n<p>कमल मुस्कराया। “अच्छा लगता है कि मेरे सामने इसे बचाना नहीं पड़ता।”</p>\n<p>उसके बाद दोनों कुछ देर चुप चलते रहे, मगर वह पहले वाली सहज ख़ामोशी नहीं थी। कविता जेब में हाथ डाले, नज़र सामने रखकर चलती रही; दोनों के बीच का फ़ासला आज एक कदम कम था।</p>\n<p>विक्रम ने उसे दो वर्षों में ऐसा प्रेम दिया था जो गहरा था, तीखा था और लगभग असंभव भी। कमल उसे कुछ और दे रहा था—साथ होने की साधारण-सी सुविधा। और कविता को अब जाकर समझ आया कि वह इसके लिए भी उतनी ही प्यासी थी।</p>\n<p>एक सप्ताहांत वे पोस्टिंग से करीब दो घंटे दूर एक छोटे-से रिज़ॉर्ट तक गए; घरवालों के लिए वजह एक ट्रेनिंग थी, जिसके बारे में किसी ने ज़्यादा सवाल नहीं किए। शाम को दोनों रिज़ॉर्ट के पीछे बने बरामदे में अकेले बैठे थे। नीचे दूर कस्बे की रोशनियाँ दिखाई दे रही थीं, जब कमल ने आख़िर वह बात कह दी जिसके आसपास वे कई हफ्तों से घूम रहे थे।</p>\n<p>“मुझे तुम अच्छी लगती हो, कविता। सिर्फ इतनी नहीं कि साथ ड्यूटी करना अच्छा लगता है। उससे ज़्यादा। काफी समय से। और अब ये नाटक करते-करते थक गया हूँ कि हम बरगद वाले उस लंबे रास्ते से यूँ ही लौटते हैं।”</p>\n<p>कमल का हाथ कविता के हाथ पर आकर ठहरा। कविता ने उसे हटाया नहीं; वह कस्बे की रोशनियों को देखती रही।</p>\n<p>फिर वह कमल की ओर वैसे ही बढ़ी, जैसे बरसों से किनारे अटका कोई सूखा लट्ठा आख़िर तब बहता है, जब नदी की धारा पूरी ताकत से उस तक पहुँचती है—दिशा चुनते हुए नहीं, बस टिके रहने की कोशिश छोड़ते हुए।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>विक्रम को बस इतना दिखाई दे रहा था कि कविता अब पहले की तरह उसके पास नहीं थी। कारण वह अपने हिसाब से खोज लेता—शायद रामफल को कुछ शक हुआ होगा, शायद कविता सावधान हो रही होगी।</p>\n<p>विक्रम भी उन दिनों कश्मीर घाटी की एक ऊँची पोस्ट पर था, जहाँ सर्दियाँ आदमी को बाहर से कम और भीतर से ज़्यादा थकाती थीं। लगातार दो ऑपरेशनों के बाद उसकी चुप्पी और गहरी हो गई थी—किसी जमी हुई झील की तरह, जिसकी सतह पर कुछ नहीं हिलता और तल में बहुत कुछ दबा रहता है। कुछ बातें ऐसी थीं जो वह अपने साथियों तक से नहीं कहता था, और कविता से कहने की तो कभी आदत ही नहीं बनी। कविता विक्रम के जीवन में थी, पर उसकी फौजी ज़िंदगी का एक बड़ा हिस्सा हमेशा कविता की पहुँच से बाहर रहा था—किसी ऊँचे दर्रे के उस पार के इलाके जैसा, जहाँ कोई पहुँच ही नहीं सकता।</p>\n<p>उस सर्दी की ठंड भी अलग थी—मैदानों की सूखी, चटखती ठंड नहीं, बल्कि नम और भारी, जो जूतों के रास्ते हड्डियों में उतरकर बैठ जाती और भीतर लौट आने के बहुत देर बाद तक वहीं रहती। कभी-कभार की साफ़ सुबहों में आसपास के पहाड़ इतनी घनी धुंध में लिपटे दिखते, जैसे साँस रोके बैठे हों।</p>\n<p>पोस्ट के नीचे एक नदी बहती थी—ठिठुरती सर्दी में भी तेज़, भरी हुई, अपनी ही धुन में। उसकी गहरी, अनथक गूँज धुंध को चीरती ऊपर चढ़ती रहती, दिन-रात, जैसे घाटी की छाती के भीतर कोई पुराना, ज़िद्दी दिल धड़क रहा हो। कुछ रातों में वह इतनी ज़ोर से गरजती कि पानी कम और नीचे करवट बदलती कोई जीती-जागती चीज़ ज़्यादा लगती—ऐसी चीज़, जो कभी सोती नहीं। पहले कुछ हफ्तों के बाद वहाँ के जवान उसे सुनना भूल जाते, जैसे आदमी हर उस आवाज़ को भूल जाता है जो कभी बदलती नहीं—अपनी ही साँस की तरह। विक्रम भी भूल गया था। नदी उन्हें तभी याद आती, जब किसी सुबह वह गूँज बेवजह थम जाती—और हर बार वह सन्नाटा उन्हें उस शोर से कहीं ज़्यादा बेचैन कर जाता।</p>\n<p>कुछ शामों विक्रम घेरे के किनारे खड़ा होता, मुँह से निकलती भाप सर्द हवा में घुलती जाती, और वह सोचता कि उसकी ज़िंदगी में जो कुछ भी गर्म था, वह असल में कितनी दूर था—घर, गाँव, धूप ओढ़े सरसों के पीले खेत, और कविता की आवाज़, जो अब फोन पर भी ढलान उतरती किसी गूँज की तरह दूर होती जा रही थी। सब कुछ एक ऐसी दूरी के उस पार था, जिसे किलोमीटर नाप ही नहीं सकते थे।</p>\n<p>ऐसी ही रातों में—जब कमरे के पीछे जेनरेटर घरघराता रहता और खिड़की के शीशे पर ठंड अपनी हथेली टिकाए धीरज से भीतर आने का इंतज़ार करती—नैना का नंबर बार-बार विक्रम की नज़र में आने लगा। कविता ने वह नंबर उसे आगे बढ़ने के लिए दिया था, मगर विक्रम महीनों तक उसे बिना छुए पड़ा रहने देता—बर्फ़ में दबे किसी बीज की तरह, जिसे अभी मौसम का भरोसा नहीं था।</p>\n<p>जब वह नंबर पर लौटा, तो उसके पीछे कोई योजना नहीं थी। कविता ने जिस लड़की को तेज़ और आसानी से प्रभावित न होने वाली बताया था, वह उस रात ध्यान बँटाने का एक छोटा, बेनुकसान-सा ज़रिया लगी—जैसे कुएँ में पत्थर डालकर यह सुनना कि पानी कितना नीचे है।</p>\n<p>एक रात उसने ज़्यादा सोचे बिना एक फॉरवर्डेड मैसेज भेज दिया और उसके पीछे लिख दिया—</p>\n<p>“सॉरी, ग़लत नंबर।”</p>\n<p>भेजने से पहले उसका अंगूठा कुछ देर स्क्रीन पर रुका ज़रूर, लेकिन मैसेज चला गया।</p>\n<p>जवाब उसकी उम्मीद से जल्दी आया, और उसके सीने की गाँठ ढीली हो गई।</p>\n<p>“कोई बात नहीं। किसे भेजना था?”</p>\n<p>“किसी खास को नहीं।”</p>\n<p>बस इतनी-सी बातचीत हुई और फिर नैना चुप हो गई। उस रात विक्रम देर तक जागता रहा, वही तीन लाइनें मन में दोहराता रहा—लगभग यकीन के साथ कि जो ठीक से शुरू भी नहीं हुआ था, उसे वह पहले ही बिगाड़ चुका है।</p>\n<p>उसके बाद विक्रम ने ख़ुद को समझा लिया कि बात वहीं ख़त्म हो चुकी है। मगर चार-पाँच दिन बाद, एक और लंबी शाम में, उसकी उँगलियाँ अपने-आप वही नंबर खोल बैठीं। इस बार भी उसने ज़्यादा सोचे बिना एक फॉरवर्डेड मैसेज भेजा और नीचे वही दो शब्द जोड़ दिए—</p>\n<p>“सॉरी, फिर ग़लत नंबर।”</p>\n<p>इस बार कोई जवाब नहीं आया। स्क्रीन पर “डिलीवर्ड” के नीचे पहली रात सन्नाटा पड़ा रहा, दूसरी रात भी। विक्रम ने फोन उल्टा करके तकिये के नीचे दबा दिया—जैसे जो चीज़ आँख से हट जाए, वह मन से भी हट जाती हो।</p>\n<p>तीसरे दिन, बिना किसी आहट के, फोन पर नैना का मैसेज चमका—और खोलने से पहले ही वह पसलियों के ठीक नीचे कहीं आकर लगा।</p>\n<p>“फिर वही ग़लत नंबर वाले हो, या इस हफ्ते किसी और का फोन परेशान कर रहा है?”</p>\n<p>विक्रम अपने फोन को देखकर किसी बेवकूफ़ की तरह मुस्करा दिया। कमरा, जो एक मिनट पहले खाली लग रहा था, अचानक उतना खाली नहीं रहा।</p>\n<p>“आदमी वही है। कन्फ्यूजन भी शायद वही है।”</p>\n<p>“या तो तुम्हें नंबर टाइप करना नहीं आता, या ये सब जानबूझकर कर रहे हो। कौन-सी बात है?”</p>\n<p>“अगर कहूँ कि जानबूझकर?”</p>\n<p>“तो ये भी बताओ, मेरा नंबर मिला कहाँ से?”</p>\n<p>यह सवाल आते ही विक्रम की मुस्कान ठहर गई। उसने कविता का नाम टाइप किया और मिटा दिया। नाम बताना आसान था, मगर जिस कहानी से यह नंबर आया था, उसे खोलने का हक अकेले उसका नहीं था।</p>\n<p>“एक कॉमन फ्रेंड से। नाम नहीं बताऊँगा।”</p>\n<p>“इतनी मिस्ट्री मुझे पसंद नहीं।”</p>\n<p>“बोरिंग है,” विक्रम ने लिखा।</p>\n<p>“लगता तो है,” नैना ने जवाब दिया।</p>\n<p>“फिर सही है। बोरिंग मिस्ट्री के लिए नींद ख़राब नहीं की जा सकती!”</p>\n<p>“ये मैं डिसाइड करूँगी,” नैना ने लिखा।</p>\n<p>उस शाम तीन-चार मैसेज और हुए, हर एक पिछले से थोड़ा कम सावधान—जैसे कोई मुट्ठी धीरे-धीरे खुलती है, जब उसे चोट की उम्मीद नहीं रहती। फिर अगले दिनों में कभी दो मैसेज हुए, कभी दस, कभी बीच में एक-दो दिन कुछ नहीं हुआ। किसी ने इसे नियमित बनाने की कोशिश नहीं की, फिर भी दोनों के बीच एक छोटी-सी जगह अपने आप बनती चली गई।</p>\n<p>एक दिन नैना ने पूछ लिया—</p>\n<p>“वैसे करते क्या हो?”</p>\n<p>“आर्मी।”</p>\n<p>कुछ देर जवाब नहीं आया। विक्रम स्क्रीन को घूरता रहा, और पोस्ट के नीचे नदी की गूँज अचानक फिर सुनाई देने लगी। फिर स्क्रीन चमकी।</p>\n<p>“ज़ाहिर है। तभी इतनी मिस्ट्री है। तुम फौजी लोगों को तो बातें छिपाने की ट्रेनिंग ऐसे दी जाती है, जैसे उसमें भी मेडल मिलते हों।”</p>\n<p>“सिर्फ ज़रूरी बातें छिपाता हूँ। बाकी पूछकर देख लो।”</p>\n<p>“देखते हैं।”</p>\n<p>विक्रम को नैना का यही अंदाज़ अच्छा लगने लगा था। वह उसकी बातों से आसानी से प्रभावित नहीं होती थी—कभी सवाल करती, कभी उसकी बात काट देती, तो कभी अचानक जवाब देना बंद कर देती। उसके सामने विक्रम को कुछ साबित नहीं करना पड़ता था।</p>\n<p>नैना के साथ न कोई वादा था, न कोई उम्मीद—बस बातचीत थी, और धीरे-धीरे विक्रम को उसके जवाब का इंतज़ार रहने लगा।</p>\n<p>जिस नंबर को उसने महीनों तक अपने फोन में यूँ ही पड़ा रहने दिया था, अब उसी नंबर से आने वाले मैसेज और कॉल उसकी शामों का हिस्सा बनने लगे थे।</p>\n<p>कुछ दिनों बाद विक्रम को लगा कि अब वह केवल नैना के मैसेज नहीं पढ़ना चाहता, उसकी आवाज़ भी सुनना चाहता है। इसके लिए किसी बहाने की ज़रूरत नहीं पड़ी और जल्द ही उनकी बातचीत मैसेज से फोन तक पहुँच गई।</p>\n<p>शुरुआती कॉल्स कभी कुछ मिनट चलतीं, कभी काफी देर तक। इसी दौरान विक्रम को कभी-कभी लगता कि कुछ शामों में नैना के बोलने का ढंग और मिज़ाज थोड़ा बदला हुआ है, मगर उसने इसे सामान्य बात समझकर ज़्यादा ध्यान नहीं दिया।</p>\n<p>असल में उन शुरुआती कॉल्स में एक-दो बार फोन नैना ने नहीं, किसी और ने उठाया था। ख़राब लाइन और आवाज़ की मिलती-जुलती लय के कारण विक्रम फ़र्क़ नहीं पकड़ पाया और फिलहाल विक्रम के लिए यह जानने की कोई वजह भी नहीं थी।</p>"}, {"chapter": 9, "title": "अध्याय 7 — आवाज़ की आदत", "content": "<h1>अध्याय 7 — आवाज़ की आदत</h1>\n<p>आठ बजने से कुछ पहले ही विक्रम के पाँव अपने-आप मेस के बाहर वाले संकरे कॉरिडोर की ओर मुड़ने लगे थे। ऐसा कोई दिन नहीं था जब दोनों ने तय किया हो कि अब रोज़ बात करेंगे, न आठ बजे का समय कभी आपस में निश्चित किया गया था; बस धीरे-धीरे उनकी शामें इस तरह बदलती गईं कि आठ से नौ के बीच किसी एक का फोन आना लगभग तय हो गया।</p>\n<p>हर रात बात हो पाना संभव नहीं था। दोनों की ड्यूटी थी और कई बार चाहकर भी समय नहीं मिलता, लेकिन जिन शामों में फोन नहीं आता, उनमें अब कुछ अधूरा-सा रहने लगा था—जैसे कोई वाक्य अपने आख़िरी शब्द के बिना रह गया हो।</p>\n<p>मेस के बाहर का संकरा कॉरिडोर ही वह इकलौती जगह थी जहाँ सिग्नल पकड़ता था, इसलिए विक्रम वहीं खड़ा होकर बात करता। कंक्रीट के फर्श से उठती ठंड जूतों की सिलाई तक चढ़ आती, और दीवार के उस पार किसी का रेडियो रोज़ वही पुराने फिल्मी गाने खरखराती आवाज़ में बजाता रहता—घिसी हुई रीलों जैसे, जो टूटकर भी चलना नहीं छोड़तीं। पहले यह सब उसकी शाम का हिस्सा भर था; अब आठ बजते ही फर्श की ठंड कहीं पीछे छूट जाती, और घड़ी पर टिकी उसकी नज़र वैसी ही हो जाती जैसी कभी भोर की पेट्रोलिंग से पहले क्षितिज पर टिकती थी—चौकन्नी, इंतज़ार में, एक पतली लकीर के उजले होने की राह देखती हुई।</p>\n<p>नैना की तरफ भी बहुत अलग हाल नहीं था। सोमवार उसके लिए हमेशा भारी होते—थाने का एक सीनियर अफसर अपनी सबसे ओछी हिदायतें हफ्ते की शुरुआत के लिए ऐसे बचाकर रखता, जैसे कोई छोटी-छोटी क्रूरताएँ जमा करता हो। ड्यूटी स्टेशन से कुछ दूर गुरुग्राम में उसका अपना क्वार्टर था, और वह शाम की ड्यूटी इस तरह निपटाने लगी थी कि आठ बजे से पहले वहाँ पहुँच जाए। अक्सर जब विक्रम का फोन आता, वह बिस्तर पर पैर मोड़कर बैठी होती, पीठ ठंडी दीवार से टिकी, और पास रखे चाय के कप से भाप की एक पतली लकीर उठकर बल्ब की रोशनी में घुलती रहती। बगल के क्वार्टर से छौंक की महक दीवार पार करके चली आती, और सामने वही उपन्यास औंधा पड़ा रहता, जिसके तीन-चार पन्नों से आगे वह कई रातों से नहीं बढ़ पाई थी—फोन ख़त्म होने के बाद पढ़ने बैठती और कुछ ही देर में नींद उसे पन्ने से उठाकर ले जाती।</p>\n<p>इन बातचीतों में दोनों एक-दूसरे के बारे में कोई बड़ी बातें नहीं खोज रहे थे, फिर भी छोटी-छोटी आदतें अपने आप सामने आने लगी थीं। नैना ने जल्दी समझ लिया था कि किसी गंभीर सवाल का जवाब देने से पहले विक्रम एक पल चुप रहता है, जैसे बोलने से पहले शब्दों को भीतर ही तौल रहा हो; और विक्रम ने यह जान लिया था कि नैना की बातों में जितनी तेज़ी थी, उसके पीछे उतनी ही बारीकी से सामने वाले को देखने की आदत भी थी।</p>\n<p>विक्रम नैना के मज़ाक पर ज़्यादातर लोगों से आधा पल देर से हँसता था—जैसे कोई लकड़ी के पुल पर पहला कदम रखने से पहले एक पाँव से तख़्ते को आज़माता है, कि यह सचमुच मज़ाक ही है और इस पर पूरा वज़न रखा जा सकता है। नैना को यह देरी खलती नहीं थी; उल्टे वह उसी का इंतज़ार करने लगी थी। उस आधे पल में उसे दिखता कि उसकी बात विक्रम के भीतर कहीं तक उतरी है, शिष्टाचार में सुनकर किनारे नहीं रख दी गई।</p>\n<p>एक रात नैना ने कोई मज़ाक किया और विक्रम को हँसने में हमेशा की तरह एक पल ज़्यादा लग गया।</p>\n<p>“तुम थोड़े स्लो हो,” नैना ने कहा।</p>\n<p>“स्लो नहीं, सावधान हूँ।”</p>\n<p>“सावधान आदमी कई बार बहुत बोरिंग भी होते हैं।”</p>\n<p>विक्रम हँसा। “कोशिश करूँगा तुम्हारे लिए थोड़ा कम सावधान रहने की।”</p>\n<p>“ज़्यादा मेहनत मत करना,” नैना ने कहा।</p>\n<p>बात वहीं निकल गई, लेकिन ऐसी ही छोटी-छोटी बातों के बीच दोनों एक-दूसरे के लिए जगह बनाते जा रहे थे।</p>\n<p>उनकी बातचीत शुरू हुए करीब चार हफ्ते हुए थे, जब नैना ने आख़िर वह बात बता दी जिसे विक्रम शुरुआती कॉल्स में केवल उसके बदलते मिज़ाज की तरह महसूस करता रहा था। कुछ शामों में जिस आवाज़ से वह बात करता रहा था, वह नैना की नहीं, उसकी छोटी बहन सुनैना की थी, जो कभी-कभी रात रुकने गाँव से उसके क्वार्टर आ जाती थी। सुनैना कुछ ही हफ्तों में यूके जाने वाली थी—वहाँ दो साल की पढ़ाई के लिए—इसलिए इन दिनों उसके चक्कर बहन के पास बढ़ गए थे। दोनों बहनों ने मज़ाक में एक-दो बार फोन सुनैना के हाथ में दे दिया था, और नैना ने बाद में इसे ठीक करने की ज़रूरत नहीं समझी।</p>\n<p>विक्रम कुछ क्षण चुप रहा।</p>\n<p>“तो मैं इतने दिनों से दो लोगों से बात कर रहा था?” विक्रम ने पूछा।</p>\n<p>नैना हँस पड़ी। “इतने दिनों से नहीं। बस कुछ बार।”</p>\n<p>बाद में तीनों की बाकायदा बात कराई गई। सुनैना ने माफ़ी भी माँगी, हालाँकि उसकी आवाज़ में पछतावे से ज़्यादा हँसी थी। उसका अंदाज़ विक्रम को पहली ही बातचीत में भा गया—तेज़, बेबाक, और ऐसी लड़की जिसे इस बात से ज़्यादा फ़र्क़ नहीं पड़ता था कि सामने वाला उसके बारे में क्या सोचता है; ऐसी, जो जहाँ जाए, अपना मौसम अपने साथ लेकर चलती हो।</p>\n<p>दूसरा महीना आते-आते फोन केवल शाम की एक अच्छी आदत नहीं रहा; अब पूरा दिन आठ बजे की ओर ऐसे झुकने लगा था, जैसे नई बनी इमारत की दीवारें धीरे-धीरे अपनी नींव पर बैठती जाती हैं—सुबह की परेड, दिन की ड्यूटी, सब उसी एक घंटे की ओर ढलते हुए। विक्रम भी कई बार साथी अफसरों के साथ चल रही बेकार की हँसी-मज़ाक बीच में छोड़कर निकल आता—जब आठ बजे का वक्त अपना वही धैर्य भरा सवाल लेकर उसके सामने आ खड़ा होता।</p>\n<p>दोनों में से किसी ने कभी नहीं कहा कि वह इंतज़ार करता है। पर जब भी घंटी बजती, पहली घंटी पूरी होने से पहले ही उठा ली जाती, और कोई यह कभी नहीं पूछता था कि इतनी जल्दी कैसे।</p>\n<p>सुनैना के जाने से एक रात पहले तीनों फिर स्पीकर पर थे। वह बहन के क्वार्टर पर आख़िरी रात बिताने आई थी, और सुनैना के आधे खुले सूटकेस की आवाज़ें बातचीत के बीच लगातार आती रहीं—कभी जिप बंद करने की कोशिश, कभी कोई चीज़ फिर बाहर निकालने की खड़खड़ाहट।</p>\n<p>बातों के बीच नैना अचानक कुछ शांत हो गई।</p>\n<p>“मैं ख़ुद को समझा रही हूँ कि दो साल बहुत लंबे नहीं होते… लेकिन अभी ये बात सच जैसी नहीं लग रही।”</p>\n<p>वह वाक्य नैना की आम तेज़ रफ्तार से धीमा निकला था। विक्रम ने उसकी बातों में इतना लंबा ठहराव पहले कभी नहीं सुना था।</p>\n<p>सुनैना अपनी बहन को अच्छी तरह पहचानती थी।</p>\n<p>“मेरी बहन का ध्यान रखना,” उसने विक्रम से कहा। “ये दिखाती ऐसे है जैसे इसे किसी की ज़रूरत ही नहीं पड़ती।”</p>\n<p>“रखूँगा,” विक्रम ने कहा।</p>\n<p>सुनैना के यूके चले जाने के बाद नैना की दिनचर्या लगभग वही रही। वह पहले की तरह बात करती, विक्रम को छेड़ती, उसकी बातों पर हँसती भी—मगर क्वार्टर में सुनैना की निशानियाँ बाकी थीं। एक रात नैना ने यूँ ही बताया कि सुनैना का दुपट्टा अब भी खूँटी पर टँगा है और उसने उसे हटाया नहीं; बाथरूम में दो टूथब्रश रखे हैं, जिनमें से एक को वह रोज़ देखती है और रोज़ वहीं रहने देती है। यह बताते हुए वह हँसी थी—मगर हँसी बीच में ही कहीं रुक गई, और फोन पर कुछ क्षण केवल लाइन की हल्की सरसराहट रही।</p>\n<p>विक्रम सैकड़ों किलोमीटर दूर, ठंडे कॉरिडोर में फोन कान से लगाए, उस ठहराव को सुनता रहा।</p>\n<p>वह उस जगह को भर नहीं सकता था।</p>\n<p>कुछ जगहें धूप के उस टुकड़े जैसी होती हैं जो दीवार पर किसी एक ही खिड़की से गिरता है; कोई दूसरा चिराग़ उसकी जगह नहीं ले सकता। बस इतना किया जा सकता था कि जब तक वह टुकड़ा खाली रहे, उस कमरे में कोई जागता रहे—आवाज़ के दूसरी तरफ।</p>\n<p>और उन दिनों विक्रम ने वही किया।</p>\n<p>रात के आठ बजे फोन अब भी बजता रहा।</p>"}, {"chapter": 10, "title": "अध्याय 8 — गुलमोहर के नीचे", "content": "<h1>अध्याय 8 — गुलमोहर के नीचे</h1>\n<p>फोन पर बनी यह आदत जितनी आसान थी, मिलने की बात उतनी ही भारी निकली। तीन महीने हो चुके थे, और हर बार जब बातचीत उस मोड़ के पास पहुँचती, कोई एक उसे मोड़ देता—छुट्टी का हिसाब, ड्यूटी का रोस्टर, किसी पुराने किस्से की ओर मुड़ती हँसी। दोनों जानते थे कि अब तक वे एक-दूसरे के लिए सिर्फ एक आवाज़ थे; मिलने के बाद उस आवाज़ के साथ एक चेहरा जुड़ जाता, और चेहरे के साथ वे उम्मीदें, जिनसे फिर अनजान बने रहना आसान नहीं रहता।</p>\n<p>आख़िर एक दिन विक्रम ने बातों-बातों में बताया कि उसकी छुट्टी आने वाली है और वह गुरुग्राम में होगा। उसने मिलने के लिए नहीं पूछा, बस इतना कहकर बात वहीं छोड़ दी और फ़ैसला नैना पर रहने दिया।</p>\n<p>नैना ने लेज़र वैली पार्क, सेक्टर 29 का नाम लिया। दिन का समय, खुली जगह और आसपास सामान्य लोग—एक ऐसी जगह जहाँ दो लोगों का मिलना सिर्फ दो लोगों का मिलना भी माना जा सकता था। जैसे दोनों में से कोई भी एक पल के लिए भी सचमुच ऐसा मानता हो।</p>\n<p>तय दिन विक्रम पहले पहुँच गया।</p>\n<p>हफ्ते के बीच की दोपहर थी और पार्क में ज़्यादा भीड़ नहीं थी। हवा में कटी हुई घास की हल्की गंध थी, प्रवेश द्वार के पास किसी ठेले से चाट-मसालों की खुशबू भीतर तक चली आ रही थी। पक्के रास्ते पर इक्का-दुक्का लोग दौड़ रहे थे, एक बुज़ुर्ग दंपती कुछ दूरी पर बेंच पर बैठा था और कहीं नज़रों से ओझल बच्चों के खेलने की आवाज़ बीच-बीच में सुनाई दे रही थी।</p>\n<p>नैना ने जिस जगह का ज़िक्र किया था, उसे ढूँढ़ने में विक्रम को कोई मुश्किल नहीं हुई। पार्क के दूर वाले हिस्से में एक पुराना गुलमोहर था और उसकी चौड़ी शाखाओं के नीचे सीमेंट की एक बेंच। तना मोटा था, छाल उम्र के साथ खुरदरी और धूसर हो चुकी थी और शाखाएँ आसपास के करीने से लगे पेड़ों की तरह सधी हुई नहीं, बल्कि अपनी मर्ज़ी से दूर-दूर तक फैली थीं।</p>\n<p>अभी उस पर फूल नहीं आए थे। शाखाओं पर नई कोंपलों की हल्की हरी नोकें ही दिख रही थीं—छोटी, कसी हुई, अपने खुलने का वक्त तौलती हुई। कुछ हफ्तों बाद यही पेड़ लाल-नारंगी फूलों से इस तरह भर जाएगा कि दूर से देखने पर लगेगा जैसे पूरा पेड़ आग पकड़ चुका हो। फिर भी वह बाकी पेड़ों के बीच अलग दिखाई देता था—बहुत पुराना, थोड़ा बेतरतीब, और इतना विशाल कि पास से गुज़रते हुए नज़र अपने आप उस पर चली जाए।</p>\n<p>अगर कोई पेड़ याद रख सकता, तो यह रखता। यह इस ज़मीन पर तब से खड़ा था, जब पार्क का कोई नाम नहीं था—जब सेक्टर 29 बस खुली ज़मीन थी, जो किसी शहर के आकर उसे अपना लेने का इंतज़ार कर रही थी। इन चुपचाप बीते दशकों में उसने अंत कम और शुरुआतें ज़्यादा देखी थीं, जैसे पुरानी और धीरज वाली चीज़ें अक्सर देखती हैं।</p>\n<p>इन दोनों के पैदा होने से पहले भी जवान जोड़े उसकी छाँव में बैठे थे—आधे-अधूरे यकीन वाले वादे फुसफुसाते, ऐसी चोर निगाहें डालते जिनके बारे में उन्हें लगता था कि कोई नहीं देख रहा। पहली स्वीकारोक्तियाँ, शब्दों से ज़्यादा कह जाने वाली पहली चुप्पियाँ, और वह खास सिहरन, जब दो अजनबी किसी वाक्य के बीच अचानक समझ जाते हैं कि अब वे अजनबी नहीं रहे—सब कुछ उसके तने की परतों में चुपचाप तह होता गया, और हर कहानी अपने वक्त में यही मानती रही कि बस वही मायने रखती है।</p>\n<p>उसे इसका कोई पता नहीं था, और पता होने की ज़रूरत भी नहीं थी, कि आज वह एक और कहानी थामने जा रहा है।</p>\n<p>विक्रम बेंच के पास खड़ा इंतज़ार करता रहा और बहुत समय बाद ख़ुद को लेकर असामान्य रूप से सचेत था। उसने एक बार अपनी शर्ट ठीक की, फिर बेवजह दोबारा; कभी घड़ी देखता, कभी पिछले महीनों की बातचीत याद करता। उसे ख़ुद पर हल्की झुँझलाहट भी हुई जब उसने महसूस किया कि उसके हाथ पूरी तरह स्थिर नहीं थे। जो आदमी घात वाले इलाकों में बिना इस काँपन के उतर चुका हो, उसके लिए पार्क की एक बेंच पर किसी लड़की का इंतज़ार करना तो मामूली बात होनी चाहिए थी।</p>\n<p>फिर उसकी नज़र सामने वाले रास्ते पर पड़ी।</p>\n<p>नैना आ रही थी।</p>\n<p>विक्रम का दिल एक बार पसलियों से ज़ोर से टकराया—एक सख़्त, अकेली दस्तक, जैसी किसी असली मुठभेड़ से पहले भी उसे बरसों से महसूस नहीं हुई थी, पार्क की बेंच की ओर आती किसी लड़की के लिए तो बिल्कुल नहीं। उसने नैना को पहले कभी देखा नहीं था, फिर भी पहचानने में एक पल नहीं लगा। महीनों से जिस आवाज़ को वह लगभग हर रात कॉरिडोर की ठंड में खड़ा सुनता आया था, उसे आज पहली बार एक चेहरा मिला था—जैसे बरसों रेडियो पर सुनी किसी आवाज़ का मालिक अचानक सामने आकर खड़ा हो जाए, और पहली ही नज़र में लगे कि आवाज़ ने उसके साथ पूरा इंसाफ़ नहीं किया था। कुछ क्षणों तक विक्रम की धड़कन अपनी सामान्य रफ्तार पर लौटने को तैयार ही नहीं हुई।</p>\n<p>नैना लंबी थी। कंधे सीधे, कदम लंबे, सधे हुए और बेझिझक। वह जिस तरह उसकी ओर चली आ रही थी, उसमें न किसी को प्रभावित करने की कोशिश थी, न आसपास की निगाहों को लेकर कोई संकोच—बस वही बेपरवाह तेज़ी, जो विक्रम महीनों से उसकी आवाज़ में सुनता आया था, आज उसकी चाल में दिखाई दे रही थी।</p>\n<p>दोपहर की रोशनी नैना के साफ़, गोरे रंग पर पड़ रही थी। चेहरे की बनावट तीखी और स्पष्ट थी, आँखें गहरी काली। ड्यूटी के दौरान बँधे रहने वाले उसके लंबे, घने काले बाल आज खुले थे, और चलते हुए कभी कंधों के पीछे चले जाते, कभी हवा के साथ चेहरे के पास लौट आते। उसने साधारण जींस और कुर्ती पहन रखी थी; कपड़ों में दिखावे जैसा कुछ नहीं था, फिर भी वह भीड़ में अलग से पहचान ली जाती थी।</p>\n<p>कुर्ती इतनी फिट थी कि बिना कुछ जताए अपनी बात कह दे। विक्रम की नज़र एक पल ज़्यादा ठहर गई—बस एक पल, मगर इतना कि जब उसकी नज़र दोबारा ऊपर उठी, नैना की गहरी काली आँखें पहले से उसी पर टिकी थीं।</p>\n<p>एक क्षण के लिए दोनों की नज़रें वहीं बँधी रहीं।</p>\n<p>विक्रम समझ गया कि वह पकड़ा गया है, और उसने नज़र हटाई नहीं।</p>\n<p>नैना भी विक्रम को देखते हुए अपनी तरफ से यही हिसाब लगा रही थी, और उसने इसे छिपाने की कोई कोशिश नहीं की—हालाँकि दूर से विक्रम को पहचानते ही नैना के कदमों की लय एक पल को टूटी थी, जबकि पूरी सुबह वह ख़ुद को समझाती आई थी कि यह एक मामूली-सी मुलाक़ात होगी। विक्रम उसकी कल्पना से लंबा था; साफ़ रंग, मजबूत चेहरा, और फौजी ट्रेनिंग से तराशी हुई देह। उसकी नज़र में एक ठहराव था, बाँह पर हल्का-सा सफ़ेद निशान, और बाल छुट्टी से पहले कटवाने की ज़रूरत से कुछ आगे निकल चुके थे। फोन पर वह जितना खुलकर बात करता था, सामने उससे कहीं ज़्यादा शांत और स्थिर दिखाई दे रहा था।</p>\n<p>नैना उसके पास आकर रुकी।</p>\n<p>“घूर रहे हो।”</p>\n<p>पकड़े जाने पर विक्रम के चेहरे पर हल्की मुस्कान आई।</p>\n<p>“एक बार देखने का हक तो है। इतने महीनों से सिर्फ आवाज़ सुनी है।”</p>\n<p>“सिर्फ एक बार?” नैना ने उसे देखते हुए कहा। “काफी उदार हो।”</p>\n<p>वह बेंच पर बैठ गई और विक्रम भी उसके पास आकर बैठ गया। दोनों के बीच थोड़ी-सी दूरी थी—इतनी कि पहली मुलाक़ात की झिझक अभी साफ़ दिखाई दे सके।</p>\n<p>फोन पर जो सहजता दोनों को बिना कोशिश मिल जाती थी, सामने बैठकर उसके लौटने में कुछ मिनट लगे। अब तक वे बिना सोचे एक-दूसरे से कुछ भी कह देते थे; अब हर वाक्य के साथ यह भी दिख रहा था कि सामने वाला कब मुस्करा रहा है, कब नज़रें हटा रहा है, और किस बात पर उसके चेहरे का रंग बदल जाता है।</p>\n<p>कुछ देर बाद नैना ने ख़ुद ही उस असहजता को तोड़ दिया।</p>\n<p>“ये थोड़ा अजीब है। फोन पर इतनी बातें करती हूँ और अब समझ नहीं आ रहा कि कहाँ देखूँ।”</p>\n<p>विक्रम ने ऊपर गुलमोहर की ओर देखा।</p>\n<p>“पेड़ को देख लो। पेड़ों को देखना आसान होता है।”</p>\n<p>नैना हँस पड़ी।</p>\n<p>वही हँसी जिसे विक्रम महीनों से फोन पर सुनता आया था। बस इस बार वह किसी स्पीकर से नहीं आ रही थी; उसके ठीक सामने बैठी थी।</p>\n<p>उस हँसी के बाद जैसे शुरुआती झिझक भी टूट गई।</p>\n<p>बातें फिर उसी लय में लौटने लगीं जिसे दोनों पहले से जानते थे। नैना ने अपने एक मामले के बारे में बताया जिसने पिछले कुछ दिनों से उसे परेशान कर रखा था, विक्रम ने अपनी पिछली सर्दियों की पोस्टिंग के कुछ किस्से सुनाए। एक बात से दूसरी निकलती गई और जिस मुलाक़ात की शुरुआत में दोनों यह तय नहीं कर पा रहे थे कि नज़र कहाँ रखें, उसमें कब लगभग दो घंटे बीत गए, इसका किसी को ध्यान नहीं रहा।</p>\n<p>बीच में नैना उसे कुछ देर देखती रही।</p>\n<p>“तुम सामने से अलग हो।”</p>\n<p>“अच्छा या बुरा?”</p>\n<p>“अभी फ़ैसला नहीं किया।” उसके होंठों पर हल्की मुस्कान आई। “फोन पर ज़्यादा बोलते हो। यहाँ ज़्यादा देखते हो।”</p>\n<p>“मैं हिसाब लगा रहा हूँ।”</p>\n<p>“किस बात का?”</p>\n<p>“आवाज़ और इंसान एक जैसे हैं या नहीं।”</p>\n<p>नैना ने भौंह उठाई। “और?”</p>\n<p>विक्रम ने इस बार जवाब देने से पहले नज़र नहीं हटाई।</p>\n<p>“इंसान बेहतर है।”</p>\n<p>नैना के चेहरे पर एक भाव कौंधा—छोटा-सा, बेपर्दा, और पूरी तरह दिखने से पहले ही गायब। उसने नज़र रास्ते की ओर कर ली और एक पल में ख़ुद को सँभालकर लौटी, वही तीखापन फिर अपनी जगह—जैसे किसी रोशन खिड़की पर फिर से पर्दा खींच दिया गया हो।</p>\n<p>“तुम्हें ऐसी बातें इतनी सीधे नहीं कहनी चाहिए।”</p>\n<p>“क्यों?”</p>\n<p>“क्योंकि मुझे उन लोगों की आदत है जो सीधी बात तक पहुँचने से पहले उसके चार चक्कर लगाते हैं।”</p>\n<p>“मुझे चक्कर लगाने का धैर्य नहीं है।”</p>\n<p>इस बार नैना की मुस्कान कुछ देर उसके चेहरे पर रही।</p>\n<p>बातचीत फिर आगे बढ़ी, मगर अब दोनों के बीच शुरुआती सावधानी उतनी नहीं थी। नैना ने जूते की नोक से पास पड़ा सूखा पत्ता एक तरफ सरका दिया, और विक्रम ने बेंच के किनारे टिका अपना हाथ अनजाने में उसकी ओर कुछ इंच खिसका लिया—दोनों में से किसी ने इस पर ध्यान नहीं दिया।</p>\n<p>कुछ देर की चुप्पी के बाद नैना ने कहा, “आज तुमने सीधी बात का नियम बना रखा है, तो सुनो। पूरे रास्ते मैं इस मुलाक़ात का इंतज़ार करती रही, और ख़ुद से भी यह बात मानने में मुझे वक्त लगा।”</p>\n<p>विक्रम ने उसकी ओर देखा।</p>\n<p>“मैं भी।”</p>\n<p>इस बार किसी ने बात को मज़ाक में नहीं उड़ाया।</p>\n<p>वे वहीं बैठे रहे। आसपास पार्क की सामान्य आवाज़ें चलती रहीं—कहीं बच्चे, किसी ठेले वाले की पुकार—और ढलती दोपहर की रोशनी रास्ते पर धीरे-धीरे ऐसे फैलती रही, जैसे कोई शहद सँभालकर उड़ेल रहा हो। उनके बीच की दूरी अब भी बनी हुई थी और दोनों में से किसी ने दूसरे को छुआ तक नहीं था; फिर भी महीनों से फोन के दोनों सिरों के बीच जो फ़ासला था, वह उस बेंच पर बैठे-बैठे घुल चुका था—गुलमोहर की छाया के साथ-साथ, जो अपनी जगह धीरे-धीरे खिसकती हुई उनके पैरों तक आ पहुँची थी।</p>\n<p>कुछ देर बाद नैना ने घड़ी देखी।</p>\n<p>“मुझे निकलना चाहिए। सुबह जल्दी ड्यूटी है।”</p>\n<p>उसने कहा ज़रूर, मगर उठी नहीं।</p>\n<p>विक्रम ने भी उसे जाने की याद नहीं दिलाई।</p>\n<p>कुछ क्षण बाद नैना ने सामने रास्ते की ओर देखते हुए कहा, “मैं दोबारा मिलना चाहती हूँ। फोन पर नहीं।”</p>\n<p>विक्रम चुपचाप उसकी ओर देखता रहा।</p>\n<p>“मुझे नहीं पता अभी ये क्या है,” नैना ने कहा, “लेकिन जितना है… उससे थोड़ा और चाहती हूँ।”</p>\n<p>“मैं भी।”</p>\n<p>नैना ने पहली बार उस जवाब के बाद नज़र नहीं हटाई।</p>\n<p>फिर ऊपर फैली गुलमोहर की शाखाओं की ओर देखते हुए बोली, “अगली बार भी यही गुलमोहर?”</p>\n<p>विक्रम के चेहरे पर हल्की मुस्कान आई।</p>\n<p>“यही गुलमोहर।”</p>\n<p>नैना पहले चली गई। विक्रम वहीं खड़ा उसे तब तक जाते देखता रहा, जब तक वह पार्क के गेट के पास भीड़ में घुलकर दिखना बंद नहीं हो गई—और उसके बाद भी कुछ देर रास्ते की ओर देखता रहा, जैसे वहाँ अब भी कुछ बाकी हो।</p>\n<p>उसने नैना को उस दिन भी नहीं बताया कि उसका नंबर उसे कहाँ से मिला था। लंबे समय तक नहीं बताया। नैना उसे संयोग समझती रही। किस्मत। वह सब, जो इंसान किसी ऐसी शुरुआत के बारे में मानना चाहता है, जिसके बारे में उसे अभी पता ही न हो कि वह आगे चलकर कितनी मायने रखेगी।</p>\n<p>उसके जाने के बाद पार्क का वह कोना फिर पहले जैसा शांत हो गया।</p>\n<p>गुलमोहर कुछ नहीं बोला—बोल भी कैसे सकता था। हवा चली तो उसकी शाखाओं पर नई कोंपलों की नोकें एक साथ हिलीं, जैसे किसी ने सिर हिलाकर हामी भरी हो; मगर वह आगे का हाल नहीं जानता था। उसकी छाँव में शुरू हुई ज़्यादातर कहानियाँ चुपचाप मुरझा जाती थीं, जैसे ज़्यादातर शुरुआतें मुरझा जाती हैं। कुछ हफ्तों बाद यही पेड़ लाल-नारंगी फूलों से दहक उठेगा, और राह चलते लोग रुककर कहेंगे कि जैसे इसमें आग लग गई है—पर किसी को पता नहीं चलेगा कि उसकी जड़ों के पास बैठी वह एक दोपहर आगे चलकर बाकी सब कहानियों से कहीं ज़्यादा माँगने वाली थी।</p>"}, {"chapter": 11, "title": "अध्याय 9 — आदत पड़ जाएगी", "content": "<h1>अध्याय 9 — आदत पड़ जाएगी</h1>\n<p>पार्क की उस पहली मुलाक़ात के बाद के हफ्तों में उनका रिश्ता एक ऐसी जगह आकर ठहर गया था, जिसका नाम दोनों में से कोई तय नहीं करना चाहता था। रात के आठ बजे का फोन अब भी बजता था, मगर कटने से पहले कोई एक पूछ लेता, “अगली बार कब?”—और दूसरा तारीख़ की जगह बस “देखते हैं” कह देता, जैसे उस “अगली बार” को पक्का कर देने में भी कोई जोखिम हो। फिलहाल वे एक-दूसरे को जान रहे थे—फोन पर सुनी हुई आवाज़ के पीछे मौजूद उस असली इंसान को, जिसकी आदतें, फ़ैसले और अपनी ज़िंदगी को लेकर कुछ ऐसी ज़िदें थीं जिन्हें समझने में समय लगना था—वैसे ही, जैसे कोई हाथ किसी नए साज़ को धीरे-धीरे पहचानता है, उस पर सधने का हक कमाने से पहले।</p>\n<p>अगली मुलाक़ात में विक्रम उसे बाइक पर जयपुर रोड के पास हाईवे मूड्स नाम के एक छोटे-से रिसॉर्ट में ले गया। उस दिन उनके बीच पहली मुलाक़ात जैसी घबराहट नहीं थी। खाली लॉन में चाय के सामने बैठे दोनों काफी सहज थे, फिर भी अभी इतनी सावधानी बाकी थी कि दोनों के हाथ मेज़ पर सामने ही रहते—जैसे ताश के खिलाड़ी दिखा रहे हों कि उनके पास कोई छिपा पत्ता नहीं है।</p>\n<p>बातों-बातों में नैना ने विक्रम की बजाय सामने फैले खेतों की ओर देखते हुए कहा—जैसे इस बात को बाहर आने के लिए कोई और जगह चाहिए हो— “मैं हमेशा से फोर्स में आना चाहती थी। मैं यहाँ किसी संयोग से नहीं पहुँची। मैंने इसे चुना है… और चुनती रहूँगी।”</p>\n<p>विक्रम को नैना की बात पर ज़रा भी हैरानी नहीं हुई।</p>\n<p>“तुम्हें देखकर लगता भी नहीं कि तुमने वर्दी बस नौकरी की तरह पहनी है,” विक्रम ने कहा। “जैसे यह हमेशा से तुम्हारी ज़िंदगी का हिस्सा होनी थी।”</p>\n<p>नैना ने चाय का कप मेज़ पर रखा—धीरे, बिना आवाज़ किए, जैसे किसी बात को सँभालकर रख रही हो। कुछ ही हफ्तों से जानने वाला आदमी उसे इतनी आसानी से समझ लेगा, इसकी उसे उम्मीद नहीं थी।</p>\n<p>फिर विक्रम ने अपने घर के बारे में बताया—उस पिता के बारे में, जिनके लिए आदमी की कीमत उसकी ज़मीन और उसके अनुशासन से तय होती थी; उस माँ के बारे में, जो हर दिन बेटे की सलामती की प्रार्थना करती थी, लेकिन उससे कभी यह नहीं कहती थी कि वह कोई सुरक्षित ज़िंदगी चुन ले। उसने अपने खेतों और आम-जामुन के उन पेड़ों का भी ज़िक्र किया जिन्हें उसके दादा ने लगाया था और जो उनके जाने के बहुत बाद भी हर साल फल देते थे।</p>\n<p>नैना कुछ देर सुनती रही, फिर बोली, “तुम अपने घर की बात ऐसे करते हो जैसे घर में रहकर भी तुम्हें उसकी याद आती हो।”</p>\n<p>विक्रम हल्का-सा मुस्कराया।</p>\n<p>“शायद ट्रेनिंग के लिए पहली बार घर छोड़ने के बाद से ही आती रही है।”</p>\n<p>“ये बात मैं तुम्हारी सोच से ज़्यादा अच्छी तरह समझती हूँ,” नैना ने कहा।</p>\n<p>वह अपने कप के किनारे पर उँगली फिराती रही, जैसे आगे की बात के लिए सही शब्द ढूँढ़ रही हो।</p>\n<p>“मेरे लिए फोर्स भी कुछ ऐसी ही है। आगे मेरी ज़िंदगी में चाहे जो आए, मैं इसका हिस्सा रहूँगी। किसी भी कीमत पर। मैंने ख़ुद को कभी इसके बाहर खड़ा हुआ सोचा ही नहीं।”</p>\n<p>विक्रम ने उस बात को हल्के में नहीं लिया। नैना उसे अपनी पसंद नहीं बता रही थी; वह अपनी ज़िंदगी की उन चीज़ों में से एक बता रही थी जिन पर आगे कभी समझौता नहीं होना था।</p>\n<p>अगली बार विक्रम उसे एम्बियंस मॉल में फिल्म दिखाने ले गया। फिल्म में दोनों की कोई खास दिलचस्पी नहीं थी; वह बस दो घंटे साथ बैठने का एक बहाना थी। अँधेरे हॉल में स्क्रीन की बदलती रोशनी कभी उनके चेहरों पर नीली गिरती, कभी सुनहरी; दोनों के कंधे कभी-कभी हल्के से छू जाते, और हर बार छूने के बाद कोई एक ज़रा-सा हट जाता—फिर कुछ देर में वही दूरी अपने-आप घट जाती।</p>\n<p>फिल्म के बाद कॉफी पीते हुए नैना ने कहानी और किरदारों की ऐसी धज्जियाँ उड़ाईं कि विक्रम फिल्म के दौरान जितना नहीं हँसा था, उससे ज़्यादा वहाँ हँसता रहा।</p>\n<p>“तुम बहुत सख़्त आलोचक हो,” विक्रम ने कहा।</p>\n<p>“सख़्त नहीं, ईमानदार हूँ। दोनों में फ़र्क़ होता है,” नैना ने कहा। “काम की राय चाहिए तो ईमानदार वाली ही बेहतर होती है, सिर्फ अच्छी लगने वाली नहीं।”</p>\n<p>एक और बार उन्होंने कहीं जाने का तय ही नहीं किया। बाइक शहर से बाहर निकलती चली गई—खेतों, ईंट-भट्ठों और सूनी पुलियाओं को पीछे छोड़ती—और फिर उसी रास्ते वापस लौट आई। रास्ते में न जाने कहाँ से बहस शुरू हो गई कि जब फर्ज और अपनी खुशी आमने-सामने खड़े हों, तो पहले किसे चुना जाना चाहिए। हवा उनके कई शब्द रास्ते में ही उड़ा ले जा रही थी; जो पहुँचते, आधे-अधूरे पहुँचते, और दोनों बाकी हिस्सा अंदाज़े से भरते रहे—फिर भी बहस चलती रही।</p>\n<p>कुछ देर बाद नैना को अचानक समझ आया कि विक्रम असल में उससे असहमत था ही नहीं।</p>\n<p>“तुम मेरी बात से सहमत हो। सिर्फ ये देखने के लिए बहस कर रहे हो कि मैं अपनी बात के बचाव में क्या कहती हूँ।”</p>\n<p>विक्रम बिना किसी शर्मिंदगी के हँसा। “गुनाह कबूल।”</p>\n<p>“बहुत परेशान करने वाली आदत है।”</p>\n<p>“आदत पड़ जाएगी।”</p>\n<p>नैना कुछ क्षण चुप रही। जब उसने दोबारा कहा तो स्वर में पहले वाली छेड़छाड़ थोड़ी कम थी।</p>\n<p>“तुम्हें भी मेरी आदतें पड़ेंगी, विक्रम। और पहले ही बता दूँ—एक बार मेरी ठीक से आदत पड़ गई, तो फिर इतनी आसानी से पीछा नहीं छुड़ा पाओगे। मैं उन आदतों में से नहीं हूँ जो वक्त के साथ अपने-आप छूट जाती हैं।”</p>\n<p>विक्रम ने जवाब नहीं दिया। उसने बाइक की चाबी उँगली में घुमाई और देर तक सड़क के पार खेतों को देखता रहा।</p>\n<p>नैना ने अनजाने में अपनी बात के भीतर यह मान लिया था कि उनके पास एक-दूसरे की आदत पड़ने जितना समय होगा—और वह भी हमेशा के लिए। विक्रम ने उस अनकहे हिस्से को वैसे ही महसूस किया, जैसे कोई किसी की रुकी हुई साँस महसूस करता है। नैना ने अपनी बात वापस नहीं ली, और विक्रम ने भी उसे वहीं रहने दिया।</p>\n<p>एक शाम दोनों बिना पहले से तय किए फिर उसी पार्क में पहुँच गए।</p>\n<p>वही बेंच। वही पुराना गुलमोहर।</p>\n<p>उस शाम सेक्टर 29 पर हल्की धुंध उतर आई थी। स्ट्रीट लाइटों की रोशनी धुंध में फैलकर मुलायम-सी हो गई थी, और आम दिनों में जॉगर्स और टहलने वालों से भरे रहने वाले रास्ते लगभग खाली थे। गुलमोहर की कोंपलें कुछ और खुल चुकी थीं; सबसे ऊँची शाखाओं के सिरों पर एक-दो कलियों की हल्की सूजन दिखाई देने लगी थी, जैसे कोई कहने वाली बात होंठों तक आकर ठहर गई हो।</p>\n<p>नैना ने शॉल अपने चारों ओर थोड़ा और कस लिया और इस बार विक्रम के पहले से ज़्यादा करीब बैठ गई। दोनों की बाँहें कंधे से कोहनी तक एक-दूसरे से लगी हुई थीं।</p>\n<p>“आज हवा में ठंडक है,” नैना ने कहा।</p>\n<p>“किसी गर्म जगह चलने को कह सकती थीं,” विक्रम ने कहा।</p>\n<p>“कह सकती थी। लेकिन मुझे ये बेंच पसंद है।”</p>\n<p>नैना ने ऊपर गुलमोहर की शाखाओं की ओर देखा। धुंध में लटकी स्ट्रीट लाइट उसके चेहरे पर पीली-सी परछाईं डाल रही थी।</p>\n<p>“मुझे लगता है मैंने तय कर लिया है कि अब ये हमारी बेंच है। इतनी कम मुलाक़ातों में ऐसा कहना अजीब है?”</p>\n<p>“नहीं,” विक्रम ने सहजता से कहा। “शायद मैंने तो पहले दिन ही तय कर लिया था। बस कहा नहीं था।”</p>\n<p>नैना ने जवाब शब्दों में नहीं दिया।</p>\n<p>उसने धीरे से अपना सिर विक्रम के कंधे पर रख दिया।</p>\n<p>दोनों काफी देर वैसे ही बैठे रहे। बातें बहुत कम हुईं। सामने धुंध खाली रास्तों पर ऐसे सरकती रही, जैसे कोई सफ़ेद चादर खिसकाकर पूरे पार्क को धीरे-धीरे सुला रहा हो; और उनके बीच पहली बार चुप्पी ऐसी थी जिसे किसी बात से भरने की ज़रूरत नहीं थी।</p>\n<p>वह बेंच अब पार्क की बाकी बेंचों जैसी नहीं रही थी। वहाँ उनकी पहली मुलाक़ात हुई थी, फिर वे लौटकर वहीं आए थे—और आज नैना ने बैठने से पहले उस पर से सूखे पत्ते हाथ से झाड़े थे, उसी सहज अधिकार से, जिससे कोई अपनी ही कुर्सी झाड़ता है।</p>\n<p>उस छुट्टी के ख़त्म होने के बाद अगली लंबी छुट्टी तक करीब दो महीने निकल गए। इस बीच एक दिन के लिए भी मिलना संभव नहीं हुआ। उनकी शामें फिर फोन पर लौट आईं और रात के आठ बजे के आसपास आने वाली आवाज़ ही दोनों के बीच की दूरी को थामे रही।</p>\n<p>मगर अब उन फोन कॉल्स में एक फ़र्क़ था।</p>\n<p>वे एक-दूसरे को सिर्फ आवाज़ से नहीं जानते थे। अब हर शब्द के पीछे एक चेहरा था, हर हँसी के साथ उसका भाव और हर चुप्पी के साथ वह इंसान, जिसे दोनों सामने बैठकर देख चुके थे। रिश्ता अब ऊपर से कम दिखता था और भीतर ज़्यादा बढ़ता था—ठीक उस गुलमोहर की तरह, जिसके नीचे वे बैठे थे: ऊपर अभी कोंपलों की नोकें भर थीं, पर नीचे ज़मीन में जड़ें हर रात थोड़ा और गहरे उतर रही थीं, इससे बहुत पहले कि किसी को पेड़ का आने वाला रंग दिखाई दे।</p>\n<p>दोनों जानते थे कि अगली छुट्टी जब भी आएगी, बहुत कुछ बदल देगी। अब तक उन्होंने एक-दूसरे को छोटे-छोटे हिस्सों में जाना था—कुछ फोन कॉल्स, कुछ मुलाक़ातें, साथ बिताई कुछ दोपहरें। अगली बार दूरी के पीछे छिपने की गुंजाइश नहीं होगी।</p>\n<p>जो कुछ उनके बीच बन रहा था, उसे पहली बार रोज़मर्रा की ज़िंदगी में एक-दूसरे के सामने रहकर परखा जाना था।</p>"}, {"chapter": 12, "title": "अध्याय 10 — साठ दिन", "content": "<h1>अध्याय 10 — साठ दिन</h1>\n<p>आख़िर विक्रम की छुट्टी मंज़ूर हो गई—पूरे साठ दिन की।</p>\n<p>कई वर्षों में उसे एक साथ इतनी लंबी छुट्टी नहीं मिली थी। आम तौर पर ऐसी छुट्टी का मतलब होता था कि पोस्टिंग में कोई बदलाव आने वाला है और ऊपर बैठे लोग उससे पहले उसके हिस्से का काम समेट रहे हैं। वजह जो भी थी, विक्रम ने ज़्यादा सवाल नहीं किए। उसने छुट्टी ऐसे स्वीकार की जैसे अचानक मिली कोई अच्छी चीज़—इससे पहले कि देने वाला अपना इरादा बदल दे।</p>\n<p>उस शाम फोन पर उसने नैना को बताया।</p>\n<p>कुछ क्षण दूसरी ओर चुप्पी रही।</p>\n<p>“साठ दिन?” नैना ने दोहराया, जैसे उस संख्या को ठीक से समझ रही हो। “मुझे नहीं लगता ट्रेनिंग के अलावा मेरी ज़िंदगी में कभी लगातार साठ दिन किसी एक चीज़ के रहे हैं।”</p>\n<p>“ड्यूटी तो तुम्हारी रहेगी। छुट्टी सिर्फ मेरी है।”</p>\n<p>“मेरे पास शामें हैं। संडे हैं। और मेरा इरादा दोनों का ज़रूरत से ज़्यादा इस्तेमाल करने का है।”</p>\n<p>वह एक पल रुकी, फिर अपनी आवाज़ को लापरवाह बनाने की नाकाम कोशिश के साथ बोली, “अच्छा लग रहा है कि छुट्टी इतनी लंबी है, विक्रम। एक महीने पहले शायद मैं ये बात नहीं कहती।”</p>\n<p>उस रात अपने कमरे तक लौटते हुए नैना का वही वाक्य—“अच्छा लग रहा है कि छुट्टी इतनी लंबी है”—देर तक विक्रम के साथ चलता रहा, जैसे बूट के तले में दबा कोई कंकड़, जो हर कदम पर अपनी याद दिलाए। चारों ओर ठंडी, चुप पहाड़ियाँ अपनी रोज़ की बेपरवाही से खड़ी थीं, चोटियों पर बर्फ़ की धुँधली लकीरें ओढ़े—जैसे उन्होंने अभी-अभी कुछ ऐसा देखा ही न हो, जिस पर ध्यान दिया जाए।</p>\n<p>छुट्टी के पहले ही हफ्ते में, बिना कोई योजना बनाए, दोनों की एक छोटी-सी दिनचर्या बनने लगी। नैना की ड्यूटी ख़त्म होने से कुछ पहले विक्रम उसे फोन कर देता। ज़रूरी नहीं था कि हर बार मिलने का कार्यक्रम बने; कई शामें सिर्फ बीस-पच्चीस मिनट की बातचीत में निकल जातीं—नैना थाने की कोई घटना सुनाती, विक्रम दिन भर की कोई मामूली बात। लेकिन कई बार वही फोन अचानक मिलने की वजह बन जाता और एक घंटे के भीतर तय हो जाता कि कहाँ जाना है। पहले से कुछ तय करना दोनों टालते थे—जैसे प्लान को जल्दी नाम दे देने से उसे नज़र लग जाएगी।</p>\n<p>पहली शाम जब विक्रम उसे बाकायदा कहीं बाहर ले गया, जगह थी लीजर वैली रोड के पास रिन्यूएबल एनर्जी पार्क में बना छोटा-सा कैफे—रूट्स। खुले में पेड़ों के बीच रखी मेज़ें, लकड़ी का सादा-सा माहौल और शाम ढलते ही टहनियों से लटकी छोटी रोशनियाँ, जो एक-एक करके जुगनुओं की तरह जल उठती थीं, उस जगह को शहर के बीच होते हुए भी उससे थोड़ा अलग कर देती थीं। मेज़-कुर्सियाँ पेड़ों के बीच ऐसे बिखरी थीं, जैसे वे भी वहीं उग आई हों। आसपास की मेज़ों की बातचीत के बीच की खाली जगहें पंछियों की आवाज़ भर देती थी, और रसोई से किसी तली जाती चीज़ की महक बाहर तक आ रही थी।</p>\n<p>विक्रम बीस मिनट पहले पहुँच गया था और उनमें से काफी समय उसने सिर्फ यह तय करने में लगा दिया कि बैठना कहाँ है। दरवाज़े के पास वाली मेज़ उसे ज़रूरत से ज़्यादा खुली लगी; पेड़ों के बहुत भीतर वाली ऐसी, जैसे वह जानबूझकर नैना को किसी की नज़र से छिपा रहा हो। आख़िर उसने बीच की एक मेज़ चुन ली।</p>\n<p>नैना बारह मिनट देर से पहुँची और बिना किसी अपराधबोध के सामने वाली कुर्सी पर बैठ गई।</p>\n<p>उसके बैठते ही विक्रम एक पल को आधा खड़ा हो गया—मेस की पुरानी आदत—और अगले ही पल उसे ख़ुद इस पर झेंप आई।</p>\n<p>“फोन कर सकती थीं,” विक्रम ने कहा।</p>\n<p>“कर सकती थी। फिर सोचा, बारह मिनट इंतज़ार करके तुम बच जाओगे।”</p>\n<p>नैना ने आसपास नज़र दौड़ाई। पेड़ों के बीच छोटी रोशनियाँ जलने लगी थीं, और उसके कंधे ढीले पड़ गए—जैसे किसी जगह पहुँचकर समझ आ जाए कि यहाँ कोई दिखावा नहीं करना पड़ेगा।</p>\n<p>“जगह अच्छी चुनी है,” नैना ने कहा। “तुमसे इतनी उम्मीद नहीं थी।”</p>\n<p>“उम्मीद कम रखो तो आदमी आसानी से अच्छा लगने लगता है।”</p>\n<p>नैना ने मेन्यू उठाया, कुछ सेकंड देखा और वापस रख दिया।</p>\n<p>“मेरे लिए तुम ऑर्डर करो।”</p>\n<p>विक्रम ने उसे देखा।</p>\n<p>“टेस्ट है?”</p>\n<p>“बिल्कुल। देखना है पार्क में मेरी बातें सच में सुन रहे थे, या बाकी आदमियों की तरह बस सिर हिला रहे थे—जो समझते हैं कि सिर हिलाना ही पर्सनैलिटी है।”</p>\n<p>“अभी बैठे पाँच मिनट भी नहीं हुए और परीक्षा शुरू हो गई?”</p>\n<p>“तैयारी के लिए दो महीने मिले थे। मुझे कोई हमदर्दी नहीं है।”</p>\n<p>विक्रम ने चिली मशरूम मँगाया, फिर शाही पनीर, वेज रायता और दोनों के लिए नान। वह सिर्फ एक चीज़ भूल गया—नैना को साथ में अलग से हरी मिर्च चाहिए थी।</p>\n<p>नैना ने पूरी गंभीरता से फ़ैसला सुनाया, “शुरुआत स्वीकार करने लायक है। इससे ज़्यादा खुश मत होना।”</p>\n<p>खाना धीरे-धीरे आता रहा और उसके साथ उनकी बातचीत भी ढीली होती गई। अब हर वाक्य बोलने से पहले सोचने की ज़रूरत नहीं पड़ रही थी। दोनों एक-दूसरे को छेड़ सकते थे, बात काट सकते थे और बिना वजह हँस सकते थे—और किसी ने ध्यान नहीं दिया कि यह छूट कब मिल गई थी।</p>\n<p>उनसे दो मेज़ दूर साफ़ तौर पर किसी अरेंज मैरिज की पहली मुलाक़ात चल रही थी—और बुरी तरह बिगड़ रही थी। लड़का बार-बार फोन देख रहा था और लड़की से ज़्यादा उसकी माँ बोल रही थी।</p>\n<p>नैना कुछ देर उन्हें देखती रही, फिर धीमे से बोली, “देखना, ग्यारह सेकंड में फिर फोन देखेगा। दो बार टाइम कर चुकी हूँ।”</p>\n<p>ठीक ग्यारह सेकंड बाद लड़के ने फोन उठा लिया।</p>\n<p>विक्रम को हँसी रोकने के लिए नैपकिन मुँह पर रखना पड़ा।</p>\n<p>“तुम ख़तरनाक हो,” विक्रम ने कहा।</p>\n<p>“ऑब्ज़र्वेंट हूँ,” नैना ने कहा। “फ़र्क़ होता है। हमारी नौकरी में इसी फ़र्क़ से प्रमोशन मिलता है।”</p>\n<p>खाते-खाते विक्रम ने हमेशा की तरह खाने को छोटे और लगभग बराबर टुकड़ों में काटना शुरू कर दिया। नैना करीब एक मिनट तक उसे देखती रही।</p>\n<p>“तुम खाना भी ऐसे खाते हो जैसे कोई इंस्पेक्शन चल रहा हो।”</p>\n<p>“पुरानी आदत है।”</p>\n<p>“तुम्हारी हर चीज़ पुरानी आदत है। बैठने का तरीका, नैपकिन रखने का तरीका… मुझे पूरा यकीन है कि सोते हुए कोई कमांड दे दे तो तुम नींद में भी सावधान खड़े हो जाओगे।”</p>\n<p>“मैंने तय किया है कि तुम्हारी कुछ नई आदतें बनानी हैं,” नैना ने कहा। “ये छुट्टी ख़त्म होने से पहले।”</p>\n<p>“धमकी लग रही है।”</p>\n<p>“लक्ष्य है। साथ चलने की कोशिश करना।”</p>\n<p>खाना ख़त्म होने पर नैना ने बिना विक्रम से पूछे आइसक्रीम मँगवा ली। अपने लिए दो स्कूप। विक्रम ने लेने से मना कर दिया तो नैना ने उसे ऐसे देखा जैसे उसने कोई बेहद चिंताजनक बात कह दी हो।</p>\n<p>“तुम्हें आइसक्रीम पसंद नहीं है?”</p>\n<p>“आइसक्रीम में ऐसा क्या खास है, ये मुझे कभी समझ नहीं आया। ठंडी होती है, दो मिनट में ख़त्म हो जाती है… और आख़िर है तो चीनी ही, बस सज-धजकर आती है।”</p>\n<p>नैना कुछ क्षण उसे देखती रही।</p>\n<p>“पिछले कई महीनों में किसी भी इंसान के मुँह से सुना हुआ ये सबसे बेरस वाक्य है।”</p>\n<p>विक्रम हँस पड़ा।</p>\n<p>“इसे भी ठीक करूँगी,” नैना ने चम्मच उठाते हुए कहा। “नैपकिन के ठीक नीचे लिस्ट में डाल रही हूँ।”</p>\n<p>“मैं तैयार रहूँगा।”</p>\n<p>“रहना भी चाहिए। जो लड़ाई मैं ख़ुद चुनती हूँ, आसानी से हारती नहीं।”</p>\n<p>उसके बाद भी दोनों काफी देर तक बैठे रहे, जबकि कैफे के कर्मचारियों के चेहरे धीरे-धीरे बता रहे थे कि अब उन्हें उठ जाना चाहिए। बातें भी किसी खास विषय पर नहीं थीं। नैना ने <i>हमशकल्स</i> की ऐसी आलोचना की जैसे फिल्म ने निजी तौर पर उसका अपमान किया हो; फिर अपने एक सीनियर अफसर की नकल उतारी, जो महिला कॉन्स्टेबलों से ऐसे बात करता था जैसे उन्हें हर बात दो बार समझानी पड़े। विक्रम ने अपनी एक पुरानी ठंडी पोस्टिंग का किस्सा सुनाया, जहाँ जवानों ने पूरी गंभीरता से बहस की थी कि चाय स्टील के कप में जल्दी ठंडी होती है या प्लास्टिक में।</p>\n<p>नैना उस बात पर ज़रूरत से ज़्यादा हँसी।</p>\n<p>और विक्रम को वह हँसी अपनी कमाई हुई लगी—वैसे ही, जैसे किसी को वह पहली आग लगती है, जो उसने बिना किसी की मदद के जलाई हो: कुछ तिनके, एक फूँक, और फिर लौ का वह पहला काँपता हुआ भरोसा।</p>\n<p>बिल आया तो दोनों के बीच उसे चुकाने को लेकर छोटी-सी लड़ाई हुई। नैना हमेशा की तरह तेज़ निकली; विक्रम के बटुए तक हाथ पहुँचने से पहले ही उसने पैसे निकालकर वेटर को दे दिए।</p>\n<p>बाहर निकलने के बाद भी दोनों में से कोई तुरंत शाम ख़त्म करने की जल्दी में नहीं था।</p>\n<p>“साठ दिन,” नैना ने पार्किंग की ओर चलते हुए फिर कहा। “मैं इनका बिल्कुल समझदारी से इस्तेमाल नहीं करने वाली।”</p>\n<p>“मुझे भी यही उम्मीद है।”</p>\n<p>चलते-चलते नैना का हाथ विक्रम के हाथ तक आया और उसकी उँगलियाँ विक्रम की उँगलियों में समा गईं—बिना रुके, बिना किसी झिझक के, जैसे वह रास्ता उसे पहले से मालूम हो।</p>\n<p>नैना ने कुछ नहीं कहा, न विक्रम ने।</p>\n<p>जैसे हाथ पकड़ना कोई फ़ैसला नहीं था। बस चलते-चलते वही सबसे सहज जगह थी जहाँ दोनों के हाथों को होना चाहिए था।</p>\n<p>विक्रम चलता रहा।</p>\n<p>पिछले दो घंटों में कोई बड़ी बात नहीं हुई थी—न किसी ने प्रेम कहा था, न कोई वादा किया था। फिर भी कुछ बदल चुका था। अब उनके बीच सिर्फ मिलने की इच्छा नहीं थी; रोज़मर्रा की छोटी-छोटी चीज़ों में भी एक-दूसरे के लिए जगह बनने लगी थी—हरी मिर्च, आइसक्रीम की लिस्ट, नैपकिन का मोड़।</p>\n<p>छुट्टी का अधिकांश हिस्सा अभी बाकी था।</p>\n<p>पार्किंग में बाइक की चाबी निकालते हुए विक्रम ने बिना चाहे उँगलियों पर गिनना शुरू कर दिया कि साठ में से कितने दिन बाकी हैं—और गिनते-गिनते उसकी उँगलियाँ कुछ ज़्यादा ही जल्दी ख़त्म हो गईं।</p>"}, {"chapter": 13, "title": "अध्याय 11 — वर्दी के भीतर", "content": "<h1>अध्याय 11 — वर्दी के भीतर</h1>\n<p>नैना के साथ बिताई हर शाम हँसी और हल्की बातों से भरी नहीं होती थी। कुछ दिन वह ड्यूटी से ऐसी थकान लेकर लौटती थी जिसे कुछ घंटे की नींद दूर नहीं कर सकती थी।</p>\n<p>विक्रम की छुट्टी को करीब दो हफ्ते हुए थे। गुरुवार की उस शाम नैना ने रोज़ के समय का इंतज़ार किए बिना सीधे ड्यूटी से उसे फोन किया। उसकी आवाज़ सपाट और बहुत संभली हुई थी—इतनी संभली हुई कि विक्रम समझ गया, वह अपने भीतर कुछ रोककर बैठी है।</p>\n<p>“मिल सकते हो?” नैना ने पूछा, फिर जवाब का इंतज़ार किए बिना कहा, “कहीं बंद जगह पर नहीं। थोड़ी खुली हवा चाहिए।”</p>\n<p>विक्रम को जगह पूछने की ज़रूरत नहीं पड़ी।</p>\n<p>वही पार्क। वही बेंच। वही गुलमोहर, जिसकी शाखाओं पर हल्की हरी कोंपलें अभी-अभी फूटी थीं—फूल आने में अभी देर थी।</p>\n<p>विक्रम पहुँचा तो नैना पहले से वहाँ बैठी थी। वह अब भी वर्दी में थी, जबकि उससे मिलने से पहले वह हमेशा कपड़े बदलती थी। उसके लिए यह एक छोटी-सी सीमा थी—ड्यूटी पर मौजूद पुलिसवाली और विक्रम के साथ रहने वाली नैना के बीच। मगर आज उसमें वह सीमा निभाने की भी ताकत नहीं बची थी।</p>\n<p>कैप सिर पर थोड़ा पीछे खिसका हुआ था। दिन भर की धूल, धूप और भागदौड़ से बालों की कुछ लटें माथे पर चिपकी थीं। वह बेंच पर बिल्कुल सीधी बैठी थी, जैसे शरीर को ढीला छोड़ दिया तो भीतर सँभालकर रखा सब कुछ भी बिखर जाएगा।</p>\n<p>विक्रम उसके पास आकर बैठ गया।</p>\n<p>“मुश्किल दिन था?”</p>\n<p>नैना ने हल्का-सा सिर हिलाया।</p>\n<p>“एक केस आया था,” नैना ने सामने देखते हुए कहा। “लड़का-लड़की की कुछ महीने पहले शादी हुई है। इंटर-कास्ट लव मैरिज। दोनों के घरवाले ख़िलाफ़ थे। आज शाम दोनों प्रोटेक्शन माँगने आए थे।”</p>\n<p>उसकी आवाज़ थोड़ी कस गई।</p>\n<p>“सुबह लड़की का अपना पिता परिवार के तीन लोगों को लेकर उनके घर पहुँच गया। पूरी गली के सामने दोनों को धमकी देकर गया है।”</p>\n<p>विक्रम ने धीरे से उसके सिर की कैप उतारकर दोनों के बीच बेंच पर रख दी—जैसे सिपाही का दर्जा उतारकर कुछ देर के लिए एक तरफ रख दिया हो। बाल खुलकर चेहरे के आसपास आ गए। विक्रम ने माथे पर चिपकी एक लट दो उँगलियों से पीछे कर दी।</p>\n<p>“लड़की क्या कह रही थी?”</p>\n<p>नैना कुछ क्षण चुप रही।</p>\n<p>“कह रही थी, बचपन में उसके पिता से ज़्यादा प्यार उसे किसी ने नहीं किया। हर मेले में उसे कंधे पर बैठाकर ले जाते थे। स्कूल से पास हुई तो रो पड़े थे। उसने बचपन में जो माँगा, किसी न किसी तरह लाकर दिया।”</p>\n<p>नैना की नज़र अब भी सामने थी।</p>\n<p>“और आज वही आदमी उसके किराए के घर के बाहर तीन लोगों के साथ खड़ा होकर बिल्कुल शांत आवाज़ में कह रहा था कि बेटी को इस तरह घर की इज़्ज़त मिटाते देखने से अच्छा है कि वह उसे मरा हुआ देख ले।”</p>\n<p>विक्रम ने कहा, “फिर वह वही आदमी नहीं रहा।”</p>\n<p>नैना ने पहली बार उसकी ओर देखा।</p>\n<p>उसके चेहरे पर सिर्फ उस केस की परेशानी नहीं थी। बात कहीं और भी जाकर लगी थी।</p>\n<p>“मैं यही नहीं समझ पा रही, विक्रम। इतना प्यार इतनी नफ़रत कैसे बन जाता है? धीरे-धीरे कम हो जाए, दूर हो जाए… वह समझ में आता है। लेकिन एक फ़ैसला पसंद न आया और वही प्यार एकदम उलट गया?”</p>\n<p>विक्रम कुछ नहीं बोला।</p>\n<p>“उस लड़की ने मुझसे बार-बार पूछा कि क्या उसके पिता अब भी उससे प्यार करते होंगे। कहीं भीतर, इन सबके नीचे। मेरे पास उसके लिए कोई ईमानदार जवाब नहीं था।”</p>\n<p>“तुमने उसे क्या कहा?” विक्रम ने पूछा।</p>\n<p>“जो हम कह सकते थे। शिकायत दर्ज होगी। धमकी रिकॉर्ड में जाएगी। पते पर नज़र रखेंगे।”</p>\n<p>नैना ने जबड़ा भींच लिया।</p>\n<p>“सब सच है। लेकिन उसके सवाल का जवाब इनमें से कुछ भी नहीं है। मेरे सवाल का भी नहीं।”</p>\n<p>विक्रम समझ गया कि नैना यहाँ किसी समाधान के लिए नहीं आई थी। पुलिस की तरफ से जो किया जा सकता था, वह उसे उससे बेहतर मालूम था। जिस बात ने उसे भीतर से परेशान किया था, उसका जवाब किसी प्रक्रिया या नियम में था ही नहीं।</p>\n<p>विक्रम ने बस अपना हाथ नैना के कंधों के चारों ओर रख दिया।</p>\n<p>कुछ क्षण बाद नैना उसकी ओर झुक गई और सिर उसके कंधे पर टिका दिया। कैप वहीं पड़ी रही—बेंच पर रखा थाने का एक छोटा-सा हिस्सा, जिसे आज की शाम किसी ने नहीं उठाया।</p>\n<p>“और भी है तो बताओ,” विक्रम ने धीमे से कहा। “मैं सुन रहा हूँ। जितना कहना है, कहो।”</p>\n<p>और भी था।</p>\n<p>करीब आधे घंटे तक नैना बोलती रही। कई बार एक ही बात दोबारा लौटकर आती, जैसे भँवर में पानी नीचे उतरने से पहले एक ही जगह घूमता रहता है—लड़की के पिता की वह असामान्य रूप से शांत आवाज़; अपनी पत्नी के पास असहाय खड़ा उसका पति; बिना चीखे, बिना गाली दिए दी गई वे धमकियाँ, जो इसी वजह से और ज़्यादा डरावनी लग रही थीं।</p>\n<p>विक्रम ने बीच में उसे नहीं रोका।</p>\n<p>उसने ऐसा पहले देखा था—अपने भीतर भी। पहली पोस्टिंग में एक आतंकी हमले के दौरान वह एक छोटी-सी बच्ची को बचा नहीं पाया था, और उस रात की वही दो-तीन बातें वह कई दिनों तक मन में दोहराता रहा था, जब तक एक पुराने हवलदार ने उससे नहीं कहा था कि अब उन्हें छोड़ दे। मगर विक्रम ने नैना को वह किस्सा नहीं सुनाया। इस समय नैना को उसकी अपनी कहानी की ज़रूरत नहीं थी।</p>\n<p>उसे बस अच्छा लगा कि नैना इस बोझ को अकेले लेकर घर जाने के बजाय उसके पास आई थी।</p>\n<p>बोलते-बोलते नैना उसके और करीब आ गई। सिर कंधे से खिसककर उसकी छाती पर टिक गया और एक हाथ ने उसकी कमीज़ को हल्के से पकड़ लिया। विक्रम ने उसे वहीं रहने दिया, बाँह उसके चारों ओर थोड़ी और सहजता से आ गई।</p>\n<p>कुछ देर बाद नैना ने पैर बेंच पर समेट लिए और करवट लेकर लेट गई। उसका सिर अब विक्रम की गोद में था। विक्रम का एक हाथ उसे सँभाले हुए था और दूसरे हाथ की उँगलियाँ धीरे-धीरे उसके बालों में चल रही थीं।</p>\n<p>नैना कुछ पल के लिए चुप हुई तो विक्रम ने नीचे देखते हुए कहा, “रुकने की ज़रूरत नहीं है। जो कहना है, पूरा कहो। जितना समय लगे।”</p>\n<p>नैना ने वहीं लेटे-लेटे फिर बोलना शुरू किया।</p>\n<p>“उसकी बातें सुनते हुए मैं अपने बाबा के बारे में सोच रही थी। उन्होंने कभी मुझ पर आवाज़ तक ऊँची नहीं की। ऐसी धमकी देने की तो मैं कल्पना भी नहीं कर सकती।”</p>\n<p>वह कुछ क्षण रुकी।</p>\n<p>“लेकिन सच ये भी है कि मैंने उन्हें कभी ऐसी वजह दी ही नहीं। मुझे नहीं पता, विक्रम… अगर कभी मैंने उस लड़की जैसा कोई फ़ैसला लिया तो वे क्या करेंगे। मैंने कभी उन्हें उस जगह तक पहुँचाकर देखा ही नहीं।”</p>\n<p>विक्रम की उँगलियाँ उसी धीमी गति से उसके बालों में चलती रहीं।</p>\n<p>जब नैना के पास कहने को कुछ नहीं बचा और वह चुप हो गई, विक्रम ने उसके चेहरे पर हाथ रखा और अंगूठे से गाल को हल्के से छुआ।</p>\n<p>नैना ने उसकी ओर देखा।</p>\n<p>“तुमने जवाब में कुछ कहा ही नहीं।”</p>\n<p>“मुझे लगा तुम्हें मेरे जवाब की ज़रूरत नहीं थी,” विक्रम ने कहा। “तुम्हें बस ये सब कहना था… और किसी को बीच में रोके बिना पूरा सुनना था।”</p>\n<p>नैना कुछ देर उसकी आँखों में देखती रही। फिर आँखें बंद कर लीं और वैसे ही उसकी गोद में पड़ी रही।</p>\n<p>काफी देर बाद नैना ने कहा, “थैंक यू।”</p>\n<p>विक्रम की उँगलियाँ अब भी उसके बालों में थीं।</p>\n<p>“किसलिए?”</p>\n<p>“इसे ठीक करने की कोशिश न करने के लिए। हर कोई तुरंत कोई समाधान देने लगता है। बाबा भी। मेरे साथ वाले भी। फिर ऐसा लगने लगता है जैसे असली समस्या वो चीज़ नहीं जो हुई है… समस्या ये है कि मैं उससे परेशान क्यों हूँ।”</p>\n<p>“जो हुआ है, उसमें सचमुच कुछ ग़लत है,” विक्रम ने कहा। “सिर्फ तुम्हें अच्छा महसूस कराने के लिए मैं उसे छोटा नहीं बनाऊँगा।”</p>\n<p>नैना ने आँखें खोलीं। चेहरे पर थकी हुई-सी छोटी मुस्कान आई।</p>\n<p>“इसीलिए घर जाने के बजाय तुम्हें फोन किया। घर जाती तो कहते ज़्यादा मत सोचो। तुमने मुझे सोचने दिया… और जब तक मैं सोचती रही, मेरे साथ बैठे रहे।”</p>\n<p>इसके बाद उनके बीच जो चुप्पी आई, उसमें पहले जैसा बोझ नहीं था—जैसे दिन भर तना रहा कोई तार आख़िर ढील पा गया हो।</p>\n<p>कुछ देर बाद विक्रम ने ऊपर गुलमोहर की कोंपलों भरी शाखाओं की ओर देखते हुए कहा, “एक बात बताऊँ? उसके बाद इंडियन आर्मी के काग़ज़ी हिसाब-किताब पर तुम्हारा भरोसा थोड़ा कम हो सकता है।”</p>\n<p>नैना के मुँह से, विक्रम की कमीज़ में दबा हुआ-सा, स्वर निकला, जिसमें हँसी की शुरुआत थी।</p>\n<p>“बताओ।”</p>\n<p>“पहाड़ों में एक तय ऊँचाई से ऊपर पोस्टेड यूनिट्स को ठंड के लिए एक्स्ट्रा रम राशन मिलता है। मेरी पहली पहाड़ी पोस्टिंग में यूनिट ने पूरा हिसाब लगाकर उसके लिए आवेदन कर दिया। सब खुश। कुछ महीने बाद ऑडिट वाले आए और उन्होंने बेस कैंप की ऊँचाई अपने हिसाब से नापी।”</p>\n<p>विक्रम एक क्षण रुका।</p>\n<p>“हम तय सीमा से बीस मीटर नीचे निकले।”</p>\n<p>नैना ने आँखें खोलीं।</p>\n<p>“फिर?”</p>\n<p>“फिर बाकायदा चर्चा हुई कि बीस मीटर ऊँचा प्लेटफॉर्म बनाया जा सकता है या नहीं।”</p>\n<p>नैना ने सिर उठाकर उसे देखा।</p>\n<p>“रम के लिए?”</p>\n<p>“बहुत गंभीरता से।”</p>\n<p>अब उसके चेहरे पर अविश्वास के साथ मुस्कान फैलने लगी थी।</p>\n<p>“आख़िर किसी ने याद दिलाया कि फ्लैग पोल पहले से एक ऊँची जगह पर लगा है और उससे कुछ मीटर पूरे हो जाते हैं। बाकी के लिए लकड़ी का प्लेटफॉर्म बनाते तो किसी दिन ब्रिगेडियर को समझाना पड़ता कि यूनिट ने ये इमारत किस महान सैन्य उद्देश्य से खड़ी की है। इसलिए मामला छोड़ दिया।”</p>\n<p>नैना हँस पड़ी।</p>\n<p>इस बार खुलकर।</p>\n<p>नैना का सिर फिर विक्रम की गोद में लुढ़क गया और उसने एक हाथ से अपना चेहरा ढक लिया—हँसी अब भी रुकने का नाम नहीं ले रही थी।</p>\n<p>“ये सच है?”</p>\n<p>“एक-एक शब्द।”</p>\n<p>विक्रम भी मुस्करा रहा था।</p>\n<p>“हमारे यहाँ कहते थे कि हर लड़ाई दो अलग स्केल वाले नक्शों के जोड़ पर लड़ी जाती है। उस पोस्टिंग में पता चला, रम की लड़ाई भी दो अलग ऊँचाइयों के जोड़ पर लड़ी जा सकती है।”</p>\n<p>नैना की हँसी धीरे-धीरे थमी। उसने आँखों के किनारे पोंछे और सिर हिलाया।</p>\n<p>“मुझे नहीं पता तुम बीस मीटर और लकड़ी के प्लेटफॉर्म को इस हफ्ते की सबसे मज़ेदार बात कैसे बना सकते हो।”</p>\n<p>नैना अब भी उसी वर्दी में थी, जिसमें पूरे दिन का बोझ लेकर आई थी। केस वही था, सवाल वहीं थे; विक्रम ने उनमें से किसी का जवाब नहीं दिया था।</p>\n<p>विक्रम ने बस इतना किया था कि जब तक नैना के भीतर वह सब था, उसे अकेले ढोने नहीं दिया।</p>\n<p>शाम और गहरी हो चुकी थी। बेंच के ऊपर पुराना गुलमोहर चुपचाप फैला था और नैना अब भी विक्रम की गोद में सिर रखे लेटी थी।</p>\n<p>इस बार दोनों को उस चुप्पी से बाहर आने की कोई जल्दी नहीं थी।</p>\n<p>गुलमोहर उन दोनों से कहीं पुराना था। अपने धीमे, जड़ों वाले ढंग से उसने सीख लिया था कि एक साधारण शाम और वज़न वाली शाम में क्या फ़र्क़ होता है।</p>\n<p>उसने इन दोनों को अजनबी बनकर आते देखा था, महीनों पहले—दो आवाज़ें, जिन्हें आख़िर शरीर मिले थे, उसकी तब लगभग नंगी शाखाओं के नीचे झिझकते हुए, सँभल-सँभलकर बैठते हुए। तब से हर मुलाक़ात की छोटी-छोटी गर्माहट उसकी जड़ों में जमा होती आई थी: एक हाथ, जो दूसरे हाथ तक पहुँचा; एक हँसी, जो ज़रूरत से ज़्यादा ज़ोर से निकल गई; एक चुप्पी, जिसमें शब्दों से ज़्यादा था।</p>\n<p>और आज यह—एक लड़की, वर्दी में ही, दिन भर का सारा बोझ लिए एक आदमी की गोद में सिर रखे लेटी थी।</p>\n<p>उसने बेंच के ऊपर ख़ुद को वैसे ही थामे रखा, जैसे इससे पहले की हर ऐसी कहानी के ऊपर थामा था—चुपचाप, धीरज से, जो कुछ देखता उसे अपने भीतर वैसे ही समेटता, जैसे जड़ें पानी समेटती हैं। उसे नहीं पता था कि यह कहानी कैसे ख़त्म होगी।</p>\n<p>बस इतना चाहता था—बहुत शिद्दत से—कि इस बार, इन दोनों के लिए, उसकी शाखाओं की ये कोंपलें पूरे फूल बन सकें।</p>\n<p>उसे अभी पता नहीं था कि वह इनसे कितना माँगने वाला है।</p>"}, {"chapter": 14, "title": "अध्याय 12 — एक बोझ, दो कंधे", "content": "<h1>अध्याय 12 — एक बोझ, दो कंधे</h1>\n<p>छुट्टी के करीब तीन हफ्ते गुज़र चुके थे और इन दिनों में विक्रम और नैना के बीच मिलने-जुलने की वह शुरुआती औपचारिकता लगभग ख़त्म हो गई थी, जिसमें हर मुलाक़ात के लिए कोई जगह, कोई वक्त और कोई बहाना पहले से तय करना पड़ता है। अब कभी शाम अपने-आप उन्हें एक जगह ले आती, कभी एक फोन आधे घंटे की बातचीत बन जाता और कभी मिलने निकले तो पता ही नहीं चलता कि दो घंटे कहाँ चले गए।</p>\n<p>इसीलिए जब विक्रम अचानक बदल गया, नैना को समझने में ज़्यादा वक्त नहीं लगा।</p>\n<p>बदलाव की वजह एक फोन था।</p>\n<p>कश्मीर से।</p>\n<p>उस शाम स्क्रीन पर कैप्टन रुद्र प्रताप सिंह का नाम देखकर विक्रम ने सहजता से फोन उठाया था। रुद्र उसके ही ट्रूप, 23 राष्ट्रीय राइफल्स, में था—कमांडो ट्रेनिंग के दिनों का साथी। विक्रम छुट्टी पर घर आ गया था और रुद्र पीछे कश्मीर में ही रह गया था; मगर फौज की कुछ दोस्तियाँ ऐसी होती हैं जिनमें न दूरी फ़ासला बनती है, न महीनों की ख़ामोशी—अगली बार बात होती है तो आदमी वहीं से शुरू करता है जहाँ पिछली बार छोड़ा था।</p>\n<p>लेकिन उस रात रुद्र ने कुछ शुरू नहीं किया।</p>\n<p>दूसरी तरफ से बस कुछ वाक्य आए—छोटे, सीधे, बिना किसी भूमिका के। विक्रम चुप रह गया। लाइन पर हल्की सरसराहट थी, जिसमें रुद्र की भारी चुप्पी दबी थी।</p>\n<p>वे चंद वाक्य उसके भीतर कहीं उतरते रहे, बिना किसी आवाज़ के—जैसे गहरे कुएँ में फेंका पत्थर, जिसके तल से टकराने की आवाज़ बहुत देर बाद आती है।</p>\n<p>फोन कटने के बाद विक्रम वहीं बैठा रहा। न जाने कितनी देर।</p>\n<p>हाथ में फोन की स्क्रीन धीरे-धीरे बुझ गई, और कमरे का अँधेरा उसके और उस एक नाम के बीच आकर बैठ गया।</p>\n<p>उस रात उसने खाना नहीं खाया। भूख सचमुच नहीं थी, इसलिए ख़ुद से कोई बहाना भी नहीं बनाना पड़ा।</p>\n<p>नैना को फोन करने का ख़याल आया ज़रूर, मगर विक्रम ने फोन नहीं किया।</p>\n<p>अगली शाम उससे मिला तो जैसे अपने साथ आधा ही पहुँचा था। सामने नैना बैठी थी, बीच में खाना रखा था, आसपास लोगों की आवाज़ें थीं; वह हर बात सुन भी रहा था और उसका जवाब भी दे रहा था, फिर भी उसका एक हिस्सा लगातार कहीं और अटका हुआ था।</p>\n<p>नैना ने पहली शाम कुछ नहीं कहा।</p>\n<p>दूसरी शाम नैना ने काँटा प्लेट में रख दिया।</p>\n<p>“क्या हुआ है?” नैना ने पूछा।</p>\n<p>“कुछ नहीं।”</p>\n<p>नैना ने पहले उसकी तरफ देखा, फिर लगभग अछूती पड़ी प्लेट की तरफ।</p>\n<p>“ये ‘कुछ नहीं’ खाना भी नहीं खाता क्या?”</p>\n<p>विक्रम ने नज़र उठाई।</p>\n<p>“भूख नहीं है।”</p>\n<p>“तुम्हें भूख नहीं है?”</p>\n<p>नैना के लहजे में चिंता थी, मगर अब उसके नीचे हल्की नाराज़गी भी उतर आई थी।</p>\n<p>“कल से देख रही हूँ। तीन निवाले खाते हो, बाकी प्लेट में घुमाते रहते हो। बात करो तो आधा जवाब देते हो। सामने बैठे हो, मगर दिमाग कहीं और है।”</p>\n<p>विक्रम फिर चुप रहा।</p>\n<p>नैना कुछ देर उसका चेहरा पढ़ती रही।</p>\n<p>“तुम्हारी परेशानी से मुझे शिकायत नहीं है, विक्रम। शिकायत ये है कि जैसे ही परेशानी तुम्हारी होती है, तुम मुझे बाहर खड़ा कर देते हो।”</p>\n<p>“ऐसी कोई बात नहीं है।”</p>\n<p>“है।”</p>\n<p>इस बार नैना ने विक्रम को बात टालने का मौका नहीं दिया।</p>\n<p>“मैंने तुम्हें अपने बारे में ऐसी बातें बताई हैं जो शायद किसी और से कभी नहीं कही। उस दिन मैं वर्दी समेत तुम्हारे पास चली आई थी क्योंकि मुझे पता था कि तुम सुनोगे। लेकिन तुम्हारी बारी आती है तो तुम इतने आराम से अपने भीतर दरवाज़ा बंद कर लेते हो जैसे मुझे मालूम ही नहीं पड़ेगा।”</p>\n<p>एक नाम विक्रम के होंठों तक आया।</p>\n<p>बस नाम कह देना था।</p>\n<p>फिर बाकी सब अपने-आप निकल आता—रुद्र का फोन, रिज लाइन, वे छह किलोमीटर, वह आदमी जिसके होने की उसे ऐसी आदत थी कि कभी उसके न होने की कल्पना ही नहीं की।</p>\n<p>मगर विक्रम फिर पीछे हट गया।</p>\n<p>“पुरानी बात है। तुमसे मिलने से पहले की।”</p>\n<p>नैना के चेहरे पर जो आया, वह गुस्सा कम और चोट ज़्यादा थी।</p>\n<p>“मैंने ये नहीं पूछा कि बात तुमसे मिलने से पहले की है या बाद की।”</p>\n<p>वह कुछ पल रुकी।</p>\n<p>“मैं बस चाहती हूँ कि जब तुम किसी मुश्किल जगह पर हो तो मुझे दरवाज़े के बाहर मत छोड़ो।”</p>\n<p>उसके बाद उस शाम में कुछ खास बचा नहीं।</p>\n<p>नैना चली गई।</p>\n<p>विक्रम दो ठंडी प्लेटों के सामने बैठा रहा और पहली बार ख़ुद से यह सवाल ठीक तरह से पूछा कि आख़िर वह नैना को बता क्यों नहीं पा रहा।</p>\n<p>अगले दिन न उसका फोन गया, न नैना का आया।</p>\n<p>वह ख़ामोशी ज़रूरी थी।</p>\n<p>उसी में विक्रम को अपने डर की असली शक्ल दिखाई दी।</p>\n<p>वह नैना पर भरोसा नहीं करता—बात ऐसी बिल्कुल नहीं थी। डर बस इतना था कि जो दुःख वह अकेले उठा रहा है, उसे बाँटते ही नैना के हिस्से में भी हर रोज़ थोड़ा-सा खौफ आ जाएगा और एक दिन वह उससे थक जाएगी।</p>\n<p>एक दोस्त को वह खो चुका था; नैना को खो देने का वहम भी उस वक्त उसे बर्दाश्त नहीं था।</p>\n<p>वह दिन भी निकल गया।</p>\n<p>उस पूरे दिन उसने ठीक से खाना भी नहीं खाया, और उसे ख़ुद इसका एहसास तब हुआ जब शाम ढले वह बिना फोन किए नैना के दरवाज़े पर जा खड़ा हुआ।</p>\n<p>दरवाज़ा खुला।</p>\n<p>नैना ने उसे देखा। चेहरे पर पिछली नाराज़गी की परछाईं अभी बाकी थी, मगर दो ही पल में नैना की नज़र विक्रम के धँसे हुए चेहरे पर टिक गई।</p>\n<p>“आख़िरी बार खाना कब खाया था?”</p>\n<p>“याद नहीं।”</p>\n<p>“विक्रम।”</p>\n<p>“शायद… दो दिन।”</p>\n<p>बस इतना सुनना था।</p>\n<p>नैना ने न डाँटा, न कोई सवाल किया। पलटी और रसोई में चली गई।</p>\n<p>विक्रम कमरे में अकेला बैठा रहा। बाहर सड़क का शोर रात उतरने के साथ धीमा हो चुका था। नीचे कहीं किसी ठेले वाले ने घंटी बजाई—दो बार—फिर आवाज़ दूर चली गई। कुछ देर में रसोई से जीरे और गर्म होती दाल की खुशबू कमरे में फैलने लगी।</p>\n<p>नैना लौटी तो हाथ में एक प्लेट थी।</p>\n<p>दाल। चावल।</p>\n<p>जो घर में था।</p>\n<p>नैना ने प्लेट विक्रम के सामने रखी।</p>\n<p>“खाओ।”</p>\n<p>“पहले मेरी बात सुनो।”</p>\n<p>“सुनूँगी।”</p>\n<p>“नैना—”</p>\n<p>“विक्रम, दो दिन से भूखे हो। पहले पहला निवाला खाओ, फिर जितना बोलना है बोलते रहना। इस बात पर बहस नहीं होगी।”</p>\n<p>नैना ने जिस अंदाज़ में कहा, उसमें बहस की गुंजाइश सचमुच नहीं थी।</p>\n<p>विक्रम ने चम्मच उठा लिया।</p>\n<p>पहले कुछ कौर सिर्फ नैना की खातिर उतरे। फिर जैसे पेट को याद आया कि उससे दो दिनों से उसकी राय पूछी ही नहीं गई थी। भूख लौट आई और खाने की रफ्तार अपने-आप बढ़ गई।</p>\n<p>नैना सामने बैठी रही।</p>\n<p>न कोई सवाल।</p>\n<p>न जल्दी।</p>\n<p>जब प्लेट का अच्छा-खासा हिस्सा ख़त्म हो गया, नैना ने बहुत सहजता से कहा—</p>\n<p>“अब बताओ।”</p>\n<p>विक्रम ने चम्मच प्लेट में रख दिया।</p>\n<p>कुछ क्षण नैना की तरफ देखा।</p>\n<p>फिर कहा—</p>\n<p>“रेड्डी शहीद हो गया।”</p>\n<p>इतने दिनों से भीतर अटके हुए सच को बाहर आने के लिए बस इतने ही शब्द चाहिए थे।</p>\n<p>वेंकटेश श्रीनिवास रेड्डी—सिर्फ तेईस साल का, आंध्र प्रदेश के अनंतपुर जिले के छोटे-से गाँव लेपाक्षी का रेड्डी; 23 राष्ट्रीय राइफल्स में विक्रम के साथ रहे सबसे अच्छे कमांडो में से एक; वह आदमी जो अपनी खैर बताने से पहले अपने साथियों की कुशलता पूछता था—अब नहीं था।</p>\n<p>रुद्र ने जैसा बताया था, विक्रम वही दोहराता गया। एम्बुश था। रिज लाइन थी। फ़ैसला लेने के लिए एक पल से भी कम वक्त मिला था और नतीजा किसी भी तरफ जा सकता था।</p>\n<p>मगर गया सिर्फ एक तरफ।</p>\n<p>इसके बाद बात किसी तरतीब में नहीं निकली।</p>\n<p>कभी रुद्र का फोन आया, कभी वह रिज लाइन; फिर अचानक विक्रम छह किलोमीटर पीछे चला गया—उस दिन तक, जब रेड्डी ने बिना पूछे उसका पैक अपने कंधे पर उठा लिया था।</p>\n<p>“छह किलोमीटर चला था मेरा सामान लेकर,” विक्रम ने कहा। “ढलान पर पैर फिसला और फ्रैक्चर हो गया। मैं उसी के सहारे घिसटता रहा, और अपना बोझ ढोते हुए उसने मेरा भी उठा लिया। मैंने माँगा भी नहीं था।”</p>\n<p>नैना सुनती रही।</p>\n<p>“बाद में मैंने पूछा, क्यों उठाया था? बोला—‘साहब, आप पैर से कम और बैग से ज़्यादा परेशान दिख रहे थे। सोचा, एक की तकलीफ़ तो कम कर दूँ।’”</p>\n<p>विक्रम के होंठों पर बहुत हल्की मुस्कान आई।</p>\n<p>बस एक पल।</p>\n<p>फिर चली गई।</p>\n<p>“ऐसा था वो।”</p>\n<p>उसके बाद कुछ देर कमरे में ख़ामोशी रही।</p>\n<p>नैना ने उसे तोड़ा नहीं।</p>\n<p>“उस रात मुझे क्यों नहीं बताया?” नैना ने आख़िर पूछा।</p>\n<p>विक्रम ने इस बार जवाब से बचने की कोशिश नहीं की।</p>\n<p>“डर गया था।”</p>\n<p>“मुझसे?”</p>\n<p>विक्रम ने सिर हिलाया।</p>\n<p>“तुम्हारे डर से।”</p>\n<p>नैना की भौंहें हल्की-सी सिकुड़ीं।</p>\n<p>“अगर मैं तुम्हें रेड्डी के बारे में बता देता, तो अगली बार जब भी मैं कहीं जाता… तुम सिर्फ मेरी पोस्टिंग के बारे में नहीं सोचतीं। तुम्हें पता होता कि वहाँ क्या हो सकता है। किसी का नाम होता तुम्हारे पास। चेहरा होता।”</p>\n<p>वह थोड़ी देर चुप रहा।</p>\n<p>“मुझे लगा फिर हर बार फोन देर से आएगा तो तुम डरोगी। हर ऑपरेशन की ख़बर पर डरोगी। और शायद एक दिन…”</p>\n<p>“एक दिन?”</p>\n<p>विक्रम ने उसकी आँखों में देखा।</p>\n<p>“शायद एक दिन तुम्हें लगे कि मुझसे प्यार करना इस डर के लायक नहीं है।”</p>\n<p>नैना बहुत देर तक कुछ नहीं बोली।</p>\n<p>फिर उठकर उसके पास आ बैठी।</p>\n<p>“मेरी एक बात ध्यान से सुनो।”</p>\n<p>विक्रम उसकी तरफ मुड़ा।</p>\n<p>“मैं कितना डर सह सकती हूँ, कितना दुःख उठा सकती हूँ और किस बात के बाद भाग जाऊँगी—ये सारे फ़ैसले तुम मेरी तरफ से मत लिया करो।”</p>\n<p>नैना के लहजे में तल्ख़ी नहीं थी। इसीलिए बात और भीतर गई।</p>\n<p>“तुम्हें लगता है मुझे बाहर रखोगे तो बचा लोगे। लेकिन फिर होता क्या है? तुम अकेले अंदर बैठे रहते हो और मैं बाहर खड़ी सोचती रहती हूँ कि आख़िर हुआ क्या है। इसे हिफ़ाज़त मत समझो, विक्रम। ये सिर्फ दो लोगों का अलग-अलग अकेला होना है।”</p>\n<p>विक्रम ने नज़रें झुका लीं।</p>\n<p>नैना ने उसकी खाली होती प्लेट की ओर देखा।</p>\n<p>“और ये दो दिन भूखे रहने वाला तमाशा दोबारा मत करना। इससे मुझे एक बात की जगह दो बातों का डर लगेगा—एक तुम्हारी पोस्टिंग का, दूसरा तुम्हारी अक्ल का।”</p>\n<p>विक्रम के चेहरे पर इस बार मुस्कान कुछ देर ठहरी।</p>\n<p>नैना का स्वर भी थोड़ा नरम पड़ गया।</p>\n<p>“रेड्डी की बात सुनकर मुझे डर लगा है। बहुत साफ़ बात है—लगा है। आगे तुम ऐसी जगह रहोगे जहाँ मैं तुम तक नहीं पहुँच सकती, तो शायद ये सब याद भी आए।”</p>\n<p>नैना ने विक्रम का हाथ अपने हाथ में ले लिया।</p>\n<p>“लेकिन मुझे सच के साथ डरना मंज़ूर है। झूठी तसल्ली के साथ जीना नहीं।”</p>\n<p>विक्रम कुछ कहता, उससे पहले नैना ने आगे कहा—</p>\n<p>“और तुमने दोस्त खोया है। अभी तुम्हारा दुःख तुम्हारा है। मेरे डर का बोझ भी अपने सिर पर रखकर मत बैठो। मुझे मेरे हिस्से का ख़ुद उठाने दो।”</p>\n<p>इसी एक बात ने विक्रम के भीतर बची हुई आख़िरी गिरह भी खोल दी—जैसे भीतर का वह दरवाज़ा, जिसे वह सिर्फ अंदर से बंद करना जानता था, पहली बार किसी और के सामने खुल गया।</p>\n<p>वह नैना की ओर झुक गया।</p>\n<p>नैना ने उसे बाँहों में ले लिया।</p>\n<p>कुछ दिन पहले गुलमोहर के नीचे वह ख़ुद इसी तरह उसके पास आई थी—थकी हुई, परेशान, अपने भीतर जमा एक सवाल लेकर। तब विक्रम ने उसे कोई जवाब नहीं दिया था; बस अपने पास जगह दी थी।</p>\n<p>आज वही जगह नैना की बाँहों में विक्रम के लिए थी।</p>\n<p>विक्रम ने सिर नैना के कंधे पर रख दिया।</p>\n<p>दो रातों की अधूरी नींद, भूख और भीतर दबाए रखा दुःख जैसे एक साथ शरीर पर उतर आए। नैना का हाथ उसकी गर्दन के पीछे था। कुछ देर बाद विक्रम और करीब खिसक आया, सिर उसकी छाती से लग गया और नैना की उँगलियाँ बिना कुछ कहे उसके बालों में चलने लगीं।</p>\n<p>“आज मेरे सामने ख़ुद को सँभालने की ज़रूरत नहीं है,” नैना ने बहुत धीमे कहा।</p>\n<p>विक्रम ने आँखें बंद कर लीं।</p>\n<p>पहली बार विक्रम को किसी ने यह इजाज़त दी थी।</p>\n<p>या इजाज़त हमेशा थी और उसने कभी ख़ुद को दी ही नहीं थी।</p>\n<p>कुछ देर बाद वह नैना की गोद में सिर रखे लेटा था।</p>\n<p>नैना ने उसके चेहरे पर हाथ रखा। अंगूठा थकी हुई आँखों के नीचे से बहुत हल्के से गुज़रा।</p>\n<p>फिर नैना ने पूछा—</p>\n<p>“रेड्डी कैसा था?”</p>\n<p>विक्रम ने उसकी तरफ देखा।</p>\n<p>“मतलब?”</p>\n<p>“कैसे मरा, ये बता चुके हो। मैं पूछ रही हूँ—था कैसा?”</p>\n<p>विक्रम जवाब देने ही वाला था, फिर रुक गया।</p>\n<p>इतने बरसों की दोस्ती में से किसी आदमी को निकालकर दो-चार वाक्यों में कैसे बताया जाए?</p>\n<p>कुछ देर बाद उसके चेहरे पर फीकी-सी मुस्कान आई।</p>\n<p>“पागल कम था, बहादुर ज़्यादा था।”</p>\n<p>विक्रम की आँखों के सामने वह पूरा आदमी खड़ा हो गया—चौड़े कंधे, तगड़ा बदन, पूरा कमांडो।</p>\n<p>“स्वभाव से नम्र, बोलचाल में शालीन—और एक्शन में सबसे आगे,” विक्रम ने कहा। “ऑपरेशन में न कभी डरा, न कभी पीछे हटा। जिस दरवाज़े पर सब एक पल को रुकते, पहला कदम उसी का होता था।”</p>\n<p>नैना भी हल्का मुस्कराई, जैसे इन वाक्यों से रेड्डी की पहली झलक उसे मिल गई हो।</p>\n<p>“अच्छा। आगे बताओ।”</p>\n<p>और न जाने क्यों सबसे पहले विक्रम को वह गेट याद आया।</p>\n<p>कमांडो ट्रेनिंग के बाद दोनों लगभग एक साथ 23 राष्ट्रीय राइफल्स में पोस्ट हुए थे—एक ऐसा संयोग, जिसकी कीमत आदमी को बाद में समझ आती है। पहली शाम दोनों अपने किट बैग लेकर, जिनसे अब भी रेल के सफ़र की गंध आ रही थी, उस गेट तक पहुँचे थे। गेट की मेहराब के ऊपर एक खोपड़ी बनी थी, उसके जबड़े के आर-पार लंबी खुखरी धँसी हुई और दाँत ऐसे निकले हुए जैसे वह आने वालों पर हँस रही हो।</p>\n<p>“हम दोनों नीचे खड़े उसे देख रहे थे,” विक्रम ने कहा। “रेड्डी ने धीरे से पूछा—‘साहब, ये हमारा स्वागत कर रही है या पहले ही दिन हमारी औकात बता रही है?’”</p>\n<p>नैना हँस दी—रेड्डी के उस सवाल पर, जो उसने सीधे खोपड़ी से पूछ लिया था।</p>\n<p>“फिर?” नैना ने पूछा।</p>\n<p>“संतरी ने हमारी शक्ल देख ली। नीचे लगी प्लेट दिखाई।”</p>\n<p>पीतल की उस छोटी-सी प्लेट के अक्षर बरसों से वहाँ ठहरती निगाहों ने घिसकर चिकने कर दिए थे। विक्रम को आज भी वे शब्द याद थे—</p>\n<p><b>थोड़ा मुस्कराओ। स्वागत है—तुम हेड हंटर्स में हो।</b></p>\n<p>“रेड्डी वहीं हँस पड़ा था—बिना किसी घबराहट के, खुलकर।”</p>\n<p>विक्रम भी मुस्कराया।</p>\n<p>महीनों बाद, कुछ ऑपरेशनों के बाद, विक्रम को समझ आया था कि वह खोपड़ी किसी पर हँस नहीं रही थी। वह अपनी उस हालत में भी मुस्कराने का रास्ता ढूँढ़ चुकी थी—और हर गुज़रते आदमी से चुपचाप पूछती थी: जो अब भी पूरा है, जीता-जागता है, वह इतना भी क्यों नहीं कर सकता?</p>\n<p>रेड्डी यह विक्रम से हमेशा बेहतर कर पाता था। आख़िरी दिन तक, ज़्यादातर दिनों, वह कर भी लेता था।</p>\n<p>फिर यादें खुलती चली गईं—बिना किसी सिलसिले के, जैसे बरसों से बंद संदूक में रखी चीज़ें एक-एक करके हाथ लगती जाएँ।</p>\n<p>कभी कोई बर्फीली पोस्ट याद आती जहाँ ट्रूप की दाल बनते ही रेड्डी तड़के पर अपना हक जमा लेता था। उस छोटे-से भगोने के सामने उसका रौब ऐसा होता जैसे पूरी यूनिट की इज़्ज़त उसी तड़के पर टिकी हो; रैंक का फ़र्क़ जितनी इजाज़त देता था, वह इस रस्म को उससे कहीं ज़्यादा गंभीरता से निभाता था।</p>\n<p>कभी किसी पेट्रोलिंग के बाद मिली पूड़ियाँ याद आतीं।</p>\n<p>कभी उसकी बेसिर-पैर की बातें, जिन पर सबसे पहले और सबसे ज़्यादा वही ख़ुद हँसता था।</p>\n<p>कभी वह जमा देने वाली रात जब आग के पास बैठने की बारी रेड्डी की थी, मगर वह बिना कुछ कहे उठ गया और विक्रम को अपनी जगह की आँच दे गया।</p>\n<p>“अगले दिन मैंने कहा, बड़ी मेहरबानी की कल।”</p>\n<p>“क्या बोला?”</p>\n<p>“बोला—‘कौन-सी मेहरबानी, साहब? आप ऐसे काँप रहे थे कि आपको देखकर मुझे ठंड लगने लगी थी।’”</p>\n<p>नैना की हँसी इस बार थोड़ी देर रही—रेड्डी के उस जवाब पर, जिसमें उसने अपनी मेहरबानी को ठंड का बहाना बना दिया था।</p>\n<p>विक्रम भी हँसा।</p>\n<p>और वही सबसे तकलीफ़देह था—किसी मर चुके आदमी की कोई बात याद करके अचानक हँस पड़ना और अगले ही पल याद आ जाना कि अब वह आदमी ख़ुद कभी नहीं हँसेगा।</p>\n<p>विक्रम की मुस्कान धीरे-धीरे बुझ गई।</p>\n<p>“माँ-बाप का इकलौता बेटा था।”</p>\n<p>नैना का हाथ उसके बालों में चलता रहा।</p>\n<p>“और उसकी शादी होने वाली थी।”</p>\n<p>हाथ एक पल को थमा।</p>\n<p>“कब?”</p>\n<p>“जल्दी। छुट्टी पर जाने वाला था।”</p>\n<p>कुछ क्षण बाद नैना ने पूछा—</p>\n<p>“लड़की?”</p>\n<p>“सुजाता।”</p>\n<p>नाम कहते ही विक्रम की आवाज़ का रंग बदल गया।</p>\n<p>“उसी के गाँव की थी। बचपन से साथ पढ़े थे। दोनों घर भी एक-दूसरे को जानते थे।”</p>\n<p>“तुमने उसे देखा था?”</p>\n<p>“फोटो में।”</p>\n<p>विक्रम की आँखें कहीं और चली गईं, जैसे वह तस्वीर इतने महीनों बाद भी उसके सामने रखी हो।</p>\n<p>“लंबे बाल थे। मोटी-सी चोटी बनाती थी… और मुस्कराती थी तो आँखों से पता चलता था कि सच में हँस रही है।”</p>\n<p>नैना चुप रही।</p>\n<p>विक्रम भी कुछ देर चुप रहा, फिर ख़ुद ही आगे बोला—</p>\n<p>“रेड्डी उसके बारे में बड़ी छोटी-छोटी बातें बताता था। कहता था, मेरी माँ का मूड मुझसे ज़्यादा उसे समझ आता है। घर में किसी को कुछ चाहिए हो तो पूछने से पहले पकड़ लेती है। दो साल से अपनी दादी वाला सांभर बनाना सीख रही थी क्योंकि ‘रेड्डी साहब’ को वही पसंद था।”</p>\n<p>“रेड्डी साहब?”</p>\n<p>“ख़ुद को यही कहता था—सुजाता की बात करते वक्त।”</p>\n<p>नैना के चेहरे पर हल्की मुस्कान आई।</p>\n<p>“बहुत प्यार करता था?”</p>\n<p>विक्रम ने बिना सोचे कहा—</p>\n<p>“बेइंतहा।”</p>\n<p>इस बार कमरे में जो ख़ामोशी उतरी, वह पहले जैसी नहीं थी।</p>\n<p>छुट्टी पर आने से कुछ ही दिन पहले रेड्डी ने विक्रम से कहा था कि वह शादी के लिए छुट्टी पर जाने वाला है। फिर हँसी-मज़ाक में बोला था—‘देखते हैं साहब, पहले घोड़ी कौन चढ़ता है।’</p>\n<p>उस वक्त बात इतनी मामूली थी कि दोनों हँसकर आगे बढ़ गए थे।</p>\n<p>अब वही मज़ाक याद आया तो विक्रम की आँखें बंद हो गईं।</p>\n<p>“अब कोई शादी नहीं होगी।”</p>\n<p>नैना की उँगलियाँ उसके बालों में और धीमी हो गईं।</p>\n<p>“पता नहीं सुजाता को ख़बर मिल गई होगी या…”</p>\n<p>वाक्य बीच में रह गया।</p>\n<p>विक्रम ने उस लड़की को कभी देखा नहीं था, सिर्फ एक तस्वीर में; फिर भी उस रात वह बार-बार उसके बारे में सोच रहा था। लेपाक्षी में कहीं एक लड़की, जिसने आने वाले महीनों को शादी के हिसाब से बाँट रखा होगा—क्या लेना है, क्या पहनना है, कौन आएगा, छुट्टी कब मिलेगी—और फिर एक ख़बर ने उन सारी छोटी-बड़ी तैयारियों को एक ही पल में बेमानी कर दिया होगा।</p>\n<p>विक्रम ने गहरी साँस ली।</p>\n<p>“और उसके माँ-बाप…”</p>\n<p>अब आवाज़ में थकान थी।</p>\n<p>“इकलौता बेटा था, नैना। सेना मेडल मिला था उसे। उसकी फोटो शायद हर रिश्तेदार को दिखाई होगी उन्होंने। कितने गर्व से बताते होंगे कि हमारा बेटा वहाँ पोस्टेड है…”</p>\n<p>उसकी आवाज़ फिर अटक गई।</p>\n<p>नैना का हाथ उसके गाल पर आ गया।</p>\n<p>“और अब वही बेटा एक ऐसी रिज पर रह गया, जिसे उसके माँ-बाप ने कभी देखा तक नहीं,” विक्रम ने कहा।</p>\n<p>कुछ पल विक्रम बिल्कुल शांत पड़ा रहा।</p>\n<p>फिर बहुत धीमे बोला—</p>\n<p>“अजीब है न… ख़बर सुनते ही आदमी शब्द समझ जाता है। ‘नहीं रहा’ का मतलब भी जानता है। फिर भी अंदर कहीं बहुत देर तक लगता रहता है कि नहीं… ऐसा कैसे हो सकता है।”</p>\n<p>नैना ने कोई तसल्ली नहीं दी।</p>\n<p>रेड्डी वापस नहीं आने वाला था और उस सच के सामने कोई तसल्ली काफी भी नहीं थी।</p>\n<p>वह बस विक्रम के साथ बैठी रही।</p>\n<p>कभी उसके बालों में हाथ फेरती, कभी माथे पर; और विक्रम जब किसी याद पर रुक जाता तो उसे आगे बोलने के लिए नहीं कहती। कुछ देर बाद वह ख़ुद दूसरी याद से शुरू हो जाता।</p>\n<p>उस रात रेड्डी की मौत की कहानी धीरे-धीरे रेड्डी के जीने की कहानी बन गई।</p>\n<p>कभी दोनों हँसे।</p>\n<p>कभी बहुत देर चुप रहे।</p>\n<p>कभी विक्रम की आवाज़ भर्रा गई और इस बार उसने उसे छिपाने के लिए चेहरा दूसरी तरफ नहीं किया।</p>\n<p>दुःख कम नहीं हुआ था।</p>\n<p>सुबह होने तक भी रेड्डी मरा ही रहने वाला था। लेपाक्षी में उसके माँ-बाप के घर का एक कमरा खाली ही रहने वाला था। सुजाता की शादी नहीं होने वाली थी।</p>\n<p>नैना इनमें से कुछ बदल नहीं सकती थी।</p>\n<p>उसने कोशिश भी नहीं की।</p>\n<p>बस जिस दुःख को विक्रम इतने दिनों से अपने भीतर बंद करके बैठा था, अब उसमें वह अकेला नहीं था।</p>\n<p>नैना की गोद में सिर रखे, उसकी उँगलियों की धीमी हरकत महसूस करते हुए विक्रम को उस रात एक बहुत साधारण-सी बात समझ आई—जिसे वह अपनी पूरी फौजी ज़िंदगी में नहीं समझ पाया था।</p>\n<p>हर बोझ अकेले उठा लेना मज़बूती नहीं होती।</p>\n<p>कुछ बोझ ऐसे भी होते हैं जिन्हें कोई आपसे छीन नहीं सकता, न आधा कर सकता है; लेकिन अगर कोई अपना बिना कुछ कहे आपके साथ उस वज़न के नीचे कंधा लगा दे—जैसे किसी भारी बल्ली के नीचे दूसरा कंधा आ जाए—तो रास्ता थोड़ा कम तन्हा ज़रूर हो जाता है।</p>\n<p>उस रात नैना ने रेड्डी के जाने का दुःख कम नहीं किया।</p>\n<p>उसने बस विक्रम को उसमें अकेला नहीं रहने दिया।</p>\n<p>जैसे कभी रेड्डी ने छह किलोमीटर विक्रम का पैक उठाया था—बिना माँगे, बिना जताए।</p>\n<p>मगर उस राहत के नीचे कहीं एक छोटा, ठंडा ख़याल उभरा, जिसे वह फिर नीचे नहीं रख पाया—दुःख को एक बार पूरा भीतर आने दो, तो वह शायद ही कभी एक बार आकर रुकता है।</p>\n<p>विक्रम ने यह कहा नहीं।</p>\n<p>बस नैना को थोड़ा और कसकर पकड़ लिया—जैसे इतना भर कर देने से वह ख़याल कभी सच न हो पाए।</p>"}, {"chapter": 15, "title": "अध्याय 13 — एक दोस्त की शादी", "content": "<h1>अध्याय 13 — एक दोस्त की शादी</h1>\n<p>रेड्डी के जाने के बाद के दिनों में नैना ने विक्रम के भीतर आई ख़ामोशी को धीरे-धीरे उतरते देखा था। दुःख कहीं गया नहीं था, बस अब हर वक्त उसके चेहरे पर बैठा नहीं रहता था। वह फिर हँसने लगा था, खाने की मेज़ पर बहस करने लगा था और कभी-कभी नैना की किसी बेवकूफ़ी पर उसी पुराने अंदाज़ में सिर हिलाकर मुस्करा भी देता था।</p>\n<p>इसीलिए नैना ने उस शाम को थोड़ा पहले से सँभालकर रखना चाहा।</p>\n<p>उसने तीन दिन पहले एक रेस्तराँ में टेबल बुक कर दी।</p>\n<p>यह उसके मिज़ाज के बिल्कुल उलट था। वह उन लोगों में नहीं थी जो शाम को पहले से सजाकर रखते हैं—कहाँ जाना है, कितने बजे पहुँचना है, कौन-सी टेबल चाहिए। मगर इस बार उसने विक्रम को कुछ बताए बिना तय किया था कि उसे एक ऐसी शाम देगी जिसमें किसी ख़तरे का ज़िक्र न हो, किसी बात का हिसाब न लगाना पड़े और दोनों को कुछ देर के लिए किसी चीज़ से जूझना न पड़े।</p>\n<p>बस एक अच्छी शाम।</p>\n<p>बिना किसी वजह के।</p>\n<p>रेस्तराँ गुरुग्राम की नई ऊँची इमारतों में से एक की ऊपरी मंज़िल पर था। शीशे की बड़ी-बड़ी खिड़कियों के उस पार आधा बन चुका शहर रात में दूर तक फैला दिखाई देता था; कहीं रोशन इमारतें थीं, कहीं अधूरे ढाँचे और उनके बीच खड़ी क्रेनें, जिन पर लगी छोटी बत्तियाँ अँधेरे में टिमटिमा रही थीं—जैसे अजीब-से, धीरज वाले पंछी, जो रात भर शहर के बनने का इंतज़ार कर रहे हों।</p>\n<p>अंदर सफ़ेद मेज़पोश, धीमी रोशनी और इतनी नपी-तुली ख़ामोशी थी कि सामने वाले को सुनने के लिए आवाज़ ऊँची करने की ज़रूरत नहीं पड़ती थी। रसोई का दरवाज़ा खुलता तो मक्खन और भुनते मसालों की खुशबू कुछ पल के लिए हवा में घुल जाती।</p>\n<p>जगह नैना ने चुनी थी और यही बात विक्रम को सबसे ज़्यादा हैरान कर रही थी।</p>\n<p>“क्या देख रहे हो?”</p>\n<p>“सोच रहा हूँ तुम्हें अचानक इतनी शरीफ जगह कैसे पसंद आ गई।”</p>\n<p>“मुझे शरीफ जगह पसंद नहीं आई। मुझे ऊपर से शहर देखना पसंद है।”</p>\n<p>उसने शीशे के पार इशारा किया।</p>\n<p>“देखो इसे। दो साल पहले इसमें से आधा था ही नहीं। मुझे अच्छा लगता है कि शहर आदमी की आँखों के सामने बदलता रहता है।”</p>\n<p>विक्रम ने बाहर देखा।</p>\n<p>नैना ने धीरे से कहा—</p>\n<p>“शायद इसलिए कि फिर लगता है कोई चीज़ हमेशा वैसी रहने के लिए मजबूर नहीं है जैसी कभी थी।”</p>\n<p>विक्रम की नज़र बाहर से लौटकर उसके चेहरे पर आ गई।</p>\n<p>वह बात शहर के बारे में कह रही थी।</p>\n<p>विक्रम ने उसे शहर के बारे में ही रहने दिया।</p>\n<p>शाम बढ़ती गई तो विक्रम को एक और बात महसूस हुई। यह पहली बार था जब वे किसी ऐसी जगह बैठे थे जहाँ उन्हें देखकर किसी को उनके रिश्ते का अंदाज़ा लगाने की ज़रूरत नहीं पड़ती। सामने से देखने पर वे ठीक वही लग रहे थे जो अब थे—दो लोग जिन्हें एक-दूसरे की मौजूदगी पसंद थी और जिन्हें फिलहाल इस बात की कोई जल्दी नहीं थी कि दुनिया उस रिश्ते को क्या नाम देती है।</p>\n<p>नैना ने उसे तीसरी बार आसपास देखते पकड़ लिया।</p>\n<p>“किसे ढूँढ़ रहे हो?”</p>\n<p>“किसी को नहीं।”</p>\n<p>“फिर बार-बार दरवाज़ा क्यों देख रहे हो?”</p>\n<p>विक्रम हल्का-सा मुस्कराया।</p>\n<p>“पुरानी आदत।”</p>\n<p>“आज छुट्टी दे दो अपनी पुरानी आदतों को। यहाँ न कोई हमें जानता है, न किसी को फ़र्क़ पड़ता है।”</p>\n<p>इतना कहकर नैना ने बिना पूछे विक्रम की प्लेट से नान का एक टुकड़ा उठा लिया।</p>\n<p>“और आज एक शाम मुझे ऐसी चाहिए जिसमें तुम हर जगह से बाहर निकलने का रास्ता नापते न रहो।”</p>\n<p>विक्रम ने उसकी तरफ देखा।</p>\n<p>“तुम मेरी प्लेट से खाना चुराना कब बंद करोगी?”</p>\n<p>“जिस दिन तुम अपनी प्लेट में मेरे लिए ख़ुद रख दिया करोगे।”</p>\n<p>“मतलब कभी नहीं।”</p>\n<p>“तो फिर शिकायत मत करना।”</p>\n<p>रेस्तराँ से निकले तो रात काफी हो चुकी थी। आसपास की ऊँची इमारतों में कहीं-कहीं ही रोशनी बची थी और सड़क पर दिन वाला शोर नहीं था। चलते हुए नैना ने बिना कुछ कहे अपना हाथ उसके हाथ में डाल दिया।</p>\n<p>विक्रम ने भी कुछ नहीं कहा।</p>\n<p>कुछ रिश्तों में एक वक्त के बाद हाथ पकड़ना कोई घटना नहीं रह जाता।</p>\n<p>बस चलते समय हाथ वहीं चला जाता है जहाँ उसकी आदत पड़ चुकी होती है।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>शादी का न्योता नैना की ट्रेनिंग बैच की एक दोस्त का था। शादी गुरुग्राम में ही थी और इतनी बड़ी कि एक अतिरिक्त मेहमान पर किसी की नज़र टिकने वाली नहीं थी।</p>\n<p>नैना ने ख़ुद कहा था—</p>\n<p>“मेरे साथ चलोगे?”</p>\n<p>“किस हैसियत से?”</p>\n<p>“प्लस वन।”</p>\n<p>विक्रम ने उसे देखा।</p>\n<p>“इतना आधुनिक?”</p>\n<p>“ज़्यादा खुश मत हो। मेरे घर का कोई आदमी वहाँ नहीं होगा। मेरी तरफ से बस ट्रेनिंग वाले कुछ लोग होंगे। इसलिए तुम्हें ले जा रही हूँ।”</p>\n<p>“मतलब सुरक्षित इलाका है।”</p>\n<p>“बिल्कुल। तुम्हें मेरे साथ किसी शादी में देखने का इससे आसान ट्रायल नहीं मिल सकता।”</p>\n<p>शादी वाले दिन विक्रम ने अपना इकलौता ढंग का कुर्ता निकाला।</p>\n<p>वेन्यू पर पहुँचकर विक्रम ने नैना को प्रवेश द्वार के पास खड़ा देखा तो उसके कदम अपने-आप एक पल के लिए धीमे पड़ गए।</p>\n<p>नैना ने गहरे हरे रंग का लहँगा पहन रखा था—उसी हरे का, जो उस गुलमोहर की नई कोंपलों में उतर रहा था—जिसके घेर और ब्लाउज़ पर सुनहरी कढ़ाई रोशनी पड़ते ही चमक उठती थी। ड्यूटी पर हमेशा बँधे या क्लिप में समेटे रहने वाले उसके बाल आज खुले थे—घने, लंबे, कमर से नीचे तक उतरते हुए और सिरों पर हल्के घुँघराले; चलते समय वे उसकी पीठ पर लहराते तो आसपास की झालरों की रोशनी उनमें अटक जाती।</p>\n<p>आँखों में गहरा काजल था, होंठों पर हल्का सुर्ख रंग।</p>\n<p>विक्रम उसे देखता रह गया।</p>\n<p>खूबसूरत वह पहले भी थी। बात यह थी कि उसने नैना को हमेशा किसी हरकत के बीच देखा था—कभी तेज़-तेज़ बोलते, कभी बहस करते, कभी हँसते, कभी वर्दी में कहीं पहुँचने की जल्दी में। उसे यूँ सामने खड़े होकर देखने का मौका ही कम मिला था, जहाँ कुछ पल के लिए वह सिर्फ नैना थी और विक्रम के पास उसे देखने के अलावा कोई दूसरा काम नहीं था।</p>\n<p>“तुम…”</p>\n<p>नैना ने तुरंत हाथ उठा दिया।</p>\n<p>“आगे मत बोलना।”</p>\n<p>“क्यों?”</p>\n<p>“सोमवार को जिन लोगों के साथ मुझे ड्यूटी करनी है, उनके सामने मुझे शर्मिंदा मत करो।”</p>\n<p>विक्रम हँस पड़ा—ड्यूटी की उस चिंता पर, जो इस क्षण भी नैना का पीछा नहीं छोड़ रही थी।</p>\n<p>नैना ने उसकी बाँह पकड़ी और भीतर खींच लिया।</p>\n<p>“चलो।”</p>\n<p>उसकी चूड़ियाँ खनकीं और वह आगे बढ़ गई।</p>\n<p>शाम सचमुच उतनी ही आसान निकली जितनी नैना ने कही थी। ट्रेनिंग बैच के कुछ पुराने साथी थे—अपनापन था, जिज्ञासा भी, मगर किसी ने विक्रम को कटघरे में खड़ा करके सवाल-जवाब शुरू नहीं किए। उल्टा ज़्यादातर मज़ा नैना को छेड़ने में लिया जा रहा था।</p>\n<p>“हमने तो उम्मीद छोड़ दी थी,” उसकी एक साथी ने हँसते हुए कहा। “तीन साल से जो रिश्ता आया, मैडम ने मना किया। और आज ख़ुद एक लड़के को साथ लेकर पहुँची हैं।”</p>\n<p>नैना ने बिना झिझके जवाब दिया—</p>\n<p>“उन सबको मैंने मना किया था। इसे नहीं किया। फ़र्क़ है।”</p>\n<p>सामने वाली ने विक्रम को ऊपर से नीचे तक देखा, मगर उस नज़र में जाँच कम, मज़ाक ज़्यादा था।</p>\n<p>“आर्मी?” उसने विक्रम से पूछा।</p>\n<p>“हाँ। पैरा एसएफ़।”</p>\n<p>पास खड़ी दो और सहेलियों की भौंहें एक साथ ऊपर चढ़ गईं।</p>\n<p>“वाओ,” एक ने आँखें फैलाकर कहा। “पैरा एसएफ़?”</p>\n<p>“वैसे देखकर लगता भी है,” दूसरी ने विक्रम की सीधी पीठ और चौड़े कंधों पर नज़र फिराते हुए धीमे से कहा।</p>\n<p>नैना ने भौंह उठाकर दोनों को घूरा, पर उसके होंठों के कोने पर छिपी मुस्कान को कोई रोक नहीं पाया।</p>\n<p>“तभी,” सामने वाली ने जैसे अपनी कोई शंका पक्की करते हुए कहा, फिर नैना की तरफ देखकर मुस्कराई, “अब समझ आया मैडम ने तीन साल में किसी को भाव क्यों नहीं दिया।”</p>\n<p>“ज़्यादा मत सोच,” नैना ने तुरंत टोका। “बस ये बाकी लोगों से थोड़ा कम परेशान करता है।”</p>\n<p>“अच्छा?”</p>\n<p>“अभी तक तो।”</p>\n<p>विक्रम दोनों की बातें सुनकर मुस्कराता रहा।</p>\n<p>“मेरे सामने ही मेरी खूबियाँ गिनाई जा रही हैं?”</p>\n<p>नैना ने उसकी तरफ देखा। “खूबियाँ कहाँ गिनाईं? मैंने तो सिर्फ इतना कहा है कि अभी तक झेला जा सकता है।”</p>\n<p>“बहुत मेहरबानी।”</p>\n<p>“वेलकम।”</p>\n<p>उसकी सहेली हँस पड़ी—दोनों की इस नोक-झोंक पर। “ठीक है, अब समझ आया तुम दोनों की बन कैसे रही है।”</p>\n<p>खाने-पीने और हँसी-मज़ाक के बीच कब डीजे शुरू हो गया, पता ही नहीं चला। मंडप से कुछ दूर बड़े-बड़े स्पीकर लगे थे और पहली तेज़ बीट के साथ ही नैना के साथियों ने उसे पकड़ लिया।</p>\n<p><b>गजबण पानी नै चाली</b> बजते ही कई लोग एक साथ खुले हिस्से की ओर निकल गए।</p>\n<p>नैना ने पलटकर विक्रम की बाँह खींची।</p>\n<p>“चलो।”</p>\n<p>“मैं नहीं नाचता।”</p>\n<p>“तुमसे किसने कहा अच्छा नाचना है?”</p>\n<p>“दोनों बातें लगभग एक ही हैं।”</p>\n<p>“पहले देखो। फिर जितना हो सके उतना कर लेना।”</p>\n<p>विक्रम किनारे खड़ा रहा तो नैना वापस आई और इस बार उसका हाथ नहीं, कुर्ते की बाँह पकड़कर उसे भीड़ में खींच लाई।</p>\n<p>“बस कंधे हिलाओ। कोई तुम्हारा कोर्ट मार्शल नहीं करेगा।”</p>\n<p>उसने कोशिश की।</p>\n<p>बहुत ख़राब कोशिश।</p>\n<p>नैना ने मुँह फेरकर हँसी रोकने की कोशिश की, फिर कोशिश छोड़कर खुलकर हँस पड़ी।</p>\n<p>“इतना बुरा?”</p>\n<p>“तुम गोली चला लेना। नाचने का काम मैं कर लूँगी।”</p>\n<p>नैना उससे कुछ कदम दूर थी। आसपास बाकी लोग भी उसी खुले, बेफ़िक्र अंदाज़ में नाच रहे थे—हाथ हवा में, कंधे ताल पर, कोई किसी का स्टेप देखकर हँस रहा था, कोई अपनी ही धुन में था। छूने की ज़रूरत नहीं थी। नैना और विक्रम के बीच भी कुछ कदम का फ़ासला बना रहा, मगर कभी-कभी एक नज़र उस दूरी को इतनी आसानी से पार कर जाती कि पास आने की ज़रूरत ही नहीं पड़ती।</p>\n<p>विक्रम कोई स्टेप बिगाड़ता तो नैना भौंह उठाकर उसे देखती।</p>\n<p>वह जानबूझकर वही ग़लती दोबारा करता।</p>\n<p>और फिर वह हँसती।</p>\n<p>जब डीजे ने <b>बावन गज का घाघरा</b> लगा दिया तो आसपास ऐसा शोर उठा जैसे पूरी मंडली उसी गाने का इंतज़ार कर रही हो। नैना की सहेलियाँ उसे फिर बीच में खींच ले गईं।</p>\n<p>विक्रम इस बार किनारे नहीं गया।</p>\n<p>वहीं खड़ा उसे देखता रहा।</p>\n<p>दूर मंडप में हवन की आग धीमी पड़ चुकी थी, पर हवा में उसकी आँच अब भी बाकी थी।</p>\n<p>खुले बाल हर बार घूमने पर उसके साथ घूमते, चूड़ियाँ रोशनी पकड़तीं, कभी स्टेप बिगड़ जाता तो वह ख़ुद पर ही हँस पड़ती। उसके चेहरे पर उस समय न ड्यूटी थी, न किसी केस का बोझ, न घर-परिवार की कोई फ़िक्र और न यह हिसाब कि कल क्या होगा।</p>\n<p>सिर्फ खुशी थी।</p>\n<p>बिल्कुल बेफ़िक्र।</p>\n<p>विक्रम ने उसे गुस्से में देखा था, थका हुआ देखा था, परेशान देखा था; गुलमोहर के नीचे अपनी गोद में सिर रखे, भीतर से टूटते हुए भी देखा था।</p>\n<p>मगर नैना को यूँ सिर्फ खुश होते हुए उसने पहली बार देखा था।</p>\n<p>और न जाने क्यों वही रूप उसे सबसे ज़्यादा भीतर तक छू गया।</p>\n<p>वह उसके चेहरे का हर झुकाव याद करता रहा—वह खास ढंग, जिससे वह अपने ही बिगड़े स्टेप पर हँसती थी—जैसे उसका कोई हिस्सा पहले से जानता हो कि किसी ठंडी रात, यहाँ से बहुत दूर, उसे यह रूप फिर बुलाना पड़ेगा।</p>\n<p>वह उसे देखता रहा।</p>\n<p>नैना घूमते हुए अचानक उसकी तरफ हुई और दोनों की नज़र मिली।</p>\n<p>नैना के कदम की ताल एक पल को बिगड़ गई।</p>\n<p>विक्रम की आँखों में इस बार वह रोज़ वाली ठहरी हुई नरमी नहीं थी। कुछ ज़्यादा खुला हुआ था—कुछ ऐसा, जिसे उसने ख़ुद भी अभी कोई नाम नहीं दिया था।</p>\n<p>नैना ने कुछ नहीं पूछा।</p>\n<p>बस उस नज़र को अपने भीतर कहीं रख लिया और अगले ही पल फिर संगीत में लौट गई।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>शादी ख़त्म होने से पहले ही दोनों निकल आए।</p>\n<p>पार्किंग तक आते-आते पीछे बजता संगीत धीमा होकर दूर की आवाज़ बन चुका था। मंडप की झालरों से बची कुछ रोशनियाँ पार्किंग तक चली आई थीं और नैना के खुले बालों में अब भी झालरों की सुनहरी रोशनी की हल्की चमक अटकी हुई थी।</p>\n<p>“आने के लिए थैंक यू,” नैना ने चलते हुए कहा। “मुझे पता है शादी में जाना किसी का पसंदीदा शौक नहीं होता।”</p>\n<p>“ये वाली बुरी नहीं थी,” विक्रम ने कहा।</p>\n<p>“मेरे लोग अच्छे हैं।”</p>\n<p>“उम्मीद से ज़्यादा,” विक्रम ने कहा।</p>\n<p>नैना ने उसे कोहनी मारी।</p>\n<p>“मेरे दोस्तों के बारे में तुम्हारी उम्मीद इतनी ख़राब क्यों थी?”</p>\n<p>“पुलिस वालों की शादी थी,” विक्रम ने कहा।</p>\n<p>“तुम आर्मी वाले हो।”</p>\n<p>“इसीलिए अनुभव से बोल रहा हूँ,” विक्रम ने कहा।</p>\n<p>नैना हँस दी—फौज और पुलिस की उस पुरानी खींचतान पर।</p>\n<p>फिर कुछ नरम होकर बोली—</p>\n<p>“अच्छा लगा कि तुमने मेरे इस हिस्से को भी देखा। बिना छह मौसियों और चार चाचाओं के तुम्हारी नीयत पूछे।”</p>\n<p>“वो भी होगा?”</p>\n<p>“अगर बात वहाँ तक पहुँची तो बहुत होगा।”</p>\n<p>वाक्य हल्का था।</p>\n<p>दोनों ने उसे हल्का ही रहने दिया।</p>\n<p>विक्रम उसे घर छोड़ने गया। रास्ते भर शहर लगभग शांत रहा, मगर विक्रम की अपनी ख़ामोशी अब पहले जैसी नहीं थी।</p>\n<p>उस दोपहर आया एक फोन उसके भीतर तब से रखा था।</p>\n<p>विक्रम ने तय किया था कि शादी से पहले नहीं बताएगा।</p>\n<p>कम-से-कम यह शाम नैना से नहीं छीनेगा।</p>\n<p>उसकी बिल्डिंग के नीचे पहुँचकर दोनों एकमात्र जलती स्ट्रीट लाइट के पास रुके तो विक्रम ने आख़िर कहा—</p>\n<p>“ऊपर जाने से पहले एक बात बतानी है।”</p>\n<p>नैना की मुस्कान उसी क्षण हल्की पड़ गई।</p>\n<p>“क्या हुआ?”</p>\n<p>“आज दोपहर कॉल आया था।”</p>\n<p>वह रुक गया।</p>\n<p>“मुझे जल्दी वापस रिपोर्ट करना है। साठ दिन पूरे नहीं होंगे।”</p>\n<p>नैना ने कुछ नहीं कहा।</p>\n<p>विक्रम उसके चेहरे पर आते-जाते भाव देखता रहा।</p>\n<p>“कब?”</p>\n<p>“कल सुबह।”</p>\n<p>बस इतना।</p>\n<p>नैना ने न पूछा कहाँ, न क्यों, न यह कि कोई ख़तरा है या नहीं।</p>\n<p>नैना एक कदम आगे बढ़ी और अपनी बाँहें विक्रम के चारों ओर डाल दीं।</p>\n<p>इस बार आधा-अधूरा नहीं।</p>\n<p>पूरा।</p>\n<p>उसका गाल विक्रम की छाती से लगा था और विक्रम की बाँहें उसकी पीठ के चारों ओर थीं। कुछ देर दोनों वैसे ही खड़े रहे—एक साधारण विदाई के लिए ज़रूरत से थोड़ी ज़्यादा देर, मगर यह साधारण विदाई थी भी कहाँ।</p>\n<p>“जाओ,” नैना ने आख़िर उसकी कमीज़ में मुँह छिपाए हुए कहा। “जो करना है, करो।”</p>\n<p>फिर उसकी पकड़ थोड़ी और कस गई।</p>\n<p>“बस पूरे वापस आना। मुझे और कुछ नहीं चाहिए।”</p>\n<p>विक्रम ने ठुड्डी उसके सिर पर रख दी। उसके बालों में परफ्यूम के साथ शादी की अगरबत्ती और धुएँ की बहुत हल्की-सी मिली-जुली खुशबू अब भी थी।</p>\n<p>“वापस आऊँगा।”</p>\n<p>“मुझे पता है।”</p>\n<p>नैना उससे थोड़ा अलग हुई।</p>\n<p>आँखों में नमी थी, मगर आवाज़ स्थिर।</p>\n<p>“मैं अपने ही घर के नीचे रोकर इसे और मुश्किल नहीं बनाऊँगी। बस सावधान रहना। और जैसे ही मौका मिले, फोन करना।”</p>\n<p>विक्रम ने सिर हिलाया।</p>\n<p>फिर माथे को चूमा।</p>\n<p>बहुत हल्के से।</p>\n<p>उस स्पर्श में चाहत से ज़्यादा भरोसा था—जैसे वह विदा नहीं ले रहा, लौटने की बात वहीं छोड़कर जा रहा हो।</p>\n<p>नैना ने उसे जाने दिया।</p>\n<p>विक्रम गाड़ी में बैठा तो वह वहीं खड़ी रही, दोनों बाँहें अपने चारों ओर समेटे हुए। गाड़ी दूर निकल गई, तब वह मुड़ी और अकेली सीढ़ियाँ चढ़ने लगी।</p>\n<p>कुछ देर पहले तक वही रात रोशनी, संगीत और हँसी से भरी हुई थी।</p>\n<p>अब उसी रात में उसकी ग़ैरमौजूदगी की ठंड उतरने लगी थी।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>कुछ हफ्तों बाद नैना घर गई तो विक्रम का ज़िक्र पहली बार उसकी माँ के सामने ठीक से आया।</p>\n<p>नैना ने उस दिन बताने की कोई तैयारी नहीं की थी। फोन रसोई की मेज़ पर खुला छूट गया था और स्क्रीन पर शादी की एक तस्वीर थी—हरे और सुनहरे रंग की रोशनी के बीच नैना के साथ खड़ा विक्रम।</p>\n<p>माँ प्लेटें समेटते हुए रुकीं।</p>\n<p>तस्वीर देखी।</p>\n<p>फिर नैना की तरफ।</p>\n<p>“कौन है?”</p>\n<p>एक सवाल के बाद छिपाने जैसा कुछ खास बचा नहीं।</p>\n<p>नैना ने बाकी तस्वीरें भी दिखा दीं। एक छोटा-सा वीडियो भी, जिसमें दोनों शादी में नाचने की नाकाम कोशिश के बीच हँस रहे थे।</p>\n<p>माँ ने वीडियो दो बार देखा।</p>\n<p>फिर फोन मेज़ पर रख दिया।</p>\n<p>“लड़का ठीक लगता है।”</p>\n<p>नैना ने इससे ज़्यादा की उम्मीद नहीं की थी, फिर भी उसके चेहरे पर हल्की मुस्कान आ गई।</p>\n<p>माँ ने वह मुस्कान देख ली।</p>\n<p>“मैंने सिर्फ इतना कहा है कि ठीक लगता है। ये नहीं कहा कि मुझे सब मंज़ूर है।”</p>\n<p>मुस्कान थोड़ी कम हुई।</p>\n<p>“मैंने मंज़ूरी माँगी भी नहीं।”</p>\n<p>“नहीं माँगी। लेकिन तस्वीरें दिखाईं, वीडियो दिखाया। कहीं न कहीं चाहती तो थी कि मैं उसे पसंद करूँ।”</p>\n<p>उनकी आवाज़ में डाँट नहीं थी। चिंता थी—उस तरह की, जिसमें माँ सामने खड़ी बेटी से ज़्यादा उन रास्तों को देख रही होती है जिनसे बेटी अभी गुज़री ही नहीं।</p>\n<p>“नैना, तू इक्कीस साल की है। इस उम्र में अपने दिल की बात बहुत साफ़ लगती है। हो सकता है तू बिल्कुल सही हो। लेकिन मैंने तेरी उम्र की लड़कियों को किसी आदमी में इतनी दूर तक जाते देखा है कि बाद में उन्हें फ़र्क़ ही नहीं समझ आता—सामने वाला सच में कैसा है और वे उसे कैसा देखना चाहती हैं।”</p>\n<p>“विक्रम सिर्फ अच्छा चेहरा नहीं है, माँ।”</p>\n<p>“मैंने ऐसा कहा भी नहीं।”</p>\n<p>माँ ने कुछ पल रुककर शब्द चुने।</p>\n<p>“मैं बस कह रही हूँ कि तू अभी उसके बहुत करीब है। और जब दिल बहुत करीब चला जाए न, तो आँखें कभी-कभी थोड़ा कम देखती हैं।”</p>\n<p>नैना ने जवाब नहीं दिया।</p>\n<p>“तेरे पापा ने अभी उसका नाम तक नहीं सुना। सुनेंगे तो पहला सवाल क्या होगा, तू जानती है। कौन है? कहाँ का है? जात क्या है? परिवार कैसा है? अपनी बिरादरी में लोग क्या कहेंगे कि लड़की अपनी मर्ज़ी से किसी आर्मी वाले के साथ घूम रही है, जिससे घरवालों ने मिलवाया तक नहीं।”</p>\n<p>नैना की नज़र मेज़ पर पड़े फोन पर चली गई।</p>\n<p>“मुझे पता है।”</p>\n<p>“तो फिर आगे की बात भी समझती है।”</p>\n<p>माँ की आवाज़ इस बार और नरम हो गई।</p>\n<p>“बाकी सब सँभालने से पहले अपने दिल को सँभालकर रखना, बेटा।”</p>\n<p>नैना चुप रही।</p>\n<p>माँ ने उसके चेहरे को देखा और वहीं समझ गईं कि यह चेतावनी कुछ देर से आई है।</p>\n<p>“अगर तू इस लड़के में बहुत दूर चली गई और बात वहाँ तक नहीं पहुँची जहाँ तू चाहती है—चाहे वजह उसका घर हो, हमारा घर हो या बीच में खड़ी कोई और दीवार—चोट तुझे लगेगी। मुझे नहीं। उसे भी शायद नहीं। सबसे ज़्यादा तुझे।”</p>\n<p>नैना की साँस एक पल को अटक गई।</p>\n<p>मगर उसी के साथ उसका वह ज़िद्दी हिस्सा भी जागा जो हर डर के सामने पहले सवाल करता था—क्यों?</p>\n<p>“मैं आपकी बात समझ रही हूँ, माँ।”</p>\n<p>वह रुकी।</p>\n<p>फिर पहली बार ख़ुद से भी बिना बचते हुए बोली—</p>\n<p>“लेकिन मैं ये झूठ नहीं बोलूँगी कि अभी बहुत शुरुआत है। शायद मैं काफी आगे जा चुकी हूँ।”</p>\n<p>माँ ने लंबी साँस छोड़ी।</p>\n<p>उसमें नाराज़गी कम थी, फ़िक्र ज़्यादा।</p>\n<p>“फिर मैं सिर्फ इतना कह सकती हूँ कि दिल जहाँ जाना चाहता है, जाए… मगर आँखें खुली रखना। माँ आख़िर इससे ज़्यादा कर भी क्या सकती है।”</p>\n<p>नैना ने कोई जवाब नहीं दिया।</p>\n<p>क्योंकि कुछ जवाब उस वक्त उसके पास थे भी नहीं।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>कई हजार मील दूर बैठी सुनैना ने वही तस्वीरें और वही वीडियो कुछ दिन बाद अपने फोन पर देखे। नैना ने ख़ुद भेजे थे।</p>\n<p>सुनैना की राय माँ से कहीं लंबी थी, हालाँकि उस समय उसका ज़्यादातर हिस्सा उसने अपने मन में ही रख लिया।</p>\n<p>नैना ने उस शाम विक्रम को फोन किया।</p>\n<p>“मैंने माँ को तुम्हारे बारे में बता दिया।”</p>\n<p>“सब?”</p>\n<p>“सब मतलब जितना अभी बताने लायक है। लड़का है। आर्मी में है। नाम विक्रम है। चेहरा भी दिखा दिया।”</p>\n<p>“फ़ैसला?”</p>\n<p>“उम्मीद से बेहतर। उन्हें तुम शरीफ लगे।”</p>\n<p>“ये बड़ी उपलब्धि है?”</p>\n<p>“मेरी माँ के हिसाब से बहुत बड़ी।”</p>\n<p>विक्रम हँसा—‘शरीफ’ को उपलब्धि की तरह सुनकर।</p>\n<p>नैना की आवाज़ फिर थोड़ी गंभीर हुई।</p>\n<p>“लेकिन उन्हें लगता है मैं तुम्हारे बहुत करीब हूँ, इसलिए शायद साफ़ नहीं देख रही। और उन्होंने मुझे याद दिलाया कि अगर ये कभी… आगे गया, तो रास्ते में कितनी चीज़ें खड़ी हो सकती हैं।”</p>\n<p>“जैसे?”</p>\n<p>“परिवार। जात। लोग। बाबा। बाकी दुनिया।”</p>\n<p>कुछ पल ख़ामोशी रही।</p>\n<p>फिर नैना ने कहा—</p>\n<p>“उन्होंने पूछा, तुमसे कब मिलेंगी।”</p>\n<p>विक्रम ने जवाब देने में देर नहीं की।</p>\n<p>“मैं मिलना चाहूँगा।”</p>\n<p>नैना चुप रही।</p>\n<p>विक्रम ने नैना के स्वर में छिपी झिझक पहचान ली।</p>\n<p>“जब तुम सच में तैयार हो। सिर्फ इसलिए नहीं कि माँ के सामने बहादुर बनने के लिए कह दिया।”</p>\n<p>“मैं बहादुर हूँ।”</p>\n<p>“मुझे पता है।”</p>\n<p>“नहीं। तुम्हें ये भी पता होना चाहिए कि कभी-कभी बहादुर रहने के लिए मुझे मेहनत करनी पड़ती है।”</p>\n<p>विक्रम मुस्कराया—उस ईमानदारी पर, जो अपनी कमज़ोरी भी नहीं छिपाती।</p>\n<p>“वो भी पता है।”</p>\n<p>फोन कटने के बाद नैना के चेहरे पर मुस्कान थी।</p>\n<p>मगर माँ का एक शब्द उसके भीतर कहीं अटका रह गया था—</p>\n<p><b>रुकावटें।</b></p>\n<p>उसने चाहा कि उस पर ज़्यादा न सोचे।</p>\n<p>फिर भी जाने-अनजाने वह गिनने लगी कि अगर यह रिश्ता सचमुच उस मंज़िल की तरफ बढ़ा, जिसकी कल्पना अब दोनों ने कभी-कभी चुपचाप करनी शुरू कर दी थी—</p>\n<p>तो उनके बीच कितनी दीवारें खड़ी हो सकती थीं।</p>\n<p>जैसे विक्रम ने कभी उँगलियों पर दिन गिने थे, वैसे ही नैना की उँगलियाँ अब दीवारें गिनने लगी थीं।</p>"}, {"chapter": 16, "title": "अध्याय 14 — खोपड़ी फिर से हँसी", "content": "<h1>अध्याय 14 — खोपड़ी फिर से हँसी</h1>\n<p>दोपहर के उस कॉल का ज़िक्र उसने नैना से आधा ही किया था।</p>\n<p>फोन पर रुद्र का नाम आया तो विक्रम बरामदे में खड़ा था।</p>\n<p>“सुल्तान गंजा,” रुद्र ने कहा। “हिज़्बुल का एरिया कमांडर। रेड्डी को उसकी टोली ने मारा।”</p>\n<p>विक्रम कुछ नहीं बोला।</p>\n<p>“रामबन-बनिहाल, गाँव सुम्बड़ा। इंटेलिजेंस रिपोर्टें हैं कि उसे वहीं-कहीं देखा गया है। गाँव में हमारे सोर्स हैं। चार-पाँच उसके साथ हैं। सीओ शर्मा साहब कह चुके हैं, इसने हमारे बच्चों को बहुत तंग किया है।”</p>\n<p>“सर, आप?”</p>\n<p>“मैं नहीं जा पाऊँगा। शर्मा साहब ने मुझे दूसरी ड्यूटी पर भेज दिया। कमान तुम्हारी। आ सकते हो?”</p>\n<p>विक्रम ने रेलिंग पर हाथ रखा।</p>\n<p>“आ रहा हूँ। कल यूनिट में हूँगा।” फिर धीरे से, “छोड़ेंगे नहीं, सर। रेड्डी का बदला लिए बिना न उसे शांति मिलेगी, न हमें।”</p>\n<p>रात को, गली की बत्ती के नीचे, उसने नैना को विदा किया था। उसने बहुत कुछ नहीं कहा, बस इतना कि कल सुबह जाना है। जो असली बात थी, वह भीतर ही रह गई, जैसे कोई चिट्ठी जो लिखी तो गई हो, पर डाक में न डाली गई हो।</p>\n<p>वह बात यह थी: प्यार के लिए वक्त बाद में भी मिल जाएगा। उसके आगे पूरी ज़िंदगी पड़ी है। गुलमोहर इंतज़ार कर सकता है, बदला नहीं।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>यूनिट में पहुँचकर उसने पहली बात यही तय की कि इंतज़ार यूनिट में नहीं होगा।</p>\n<p>ब्रीफिंग हॉल में नक़्शा दीवार पर था और तीस-पैंतीस जवान सामने। विक्रम यूनिट की घातक टुकड़ी, यानी विशेष टीम, का कमांडर था, और ये सभी जवान उसकी अपनी टीम के थे। वे उसे जानते थे। उसकी काबिलियत पर उन्हें पहले से भरोसा था, और उसके आने की ख़बर मिलते ही यूनिट में जोश फैल गया था। जो कल तक थके दिखते थे, आज सीधे बैठे थे। हॉल में दबी हुई फुसफुसाहट थी: “राठौड़ साहब आ गए हैं, अब तो हो ही जाएगा।”</p>\n<p>यह भरोसा बेवजह नहीं था। 23 राष्ट्रीय राइफल्स में घातक टुकड़ी का कमांडर विक्रम जब भी अपनी पार्टी को लेकर निकला, बिना शिकार किए कभी यूनिट नहीं लौटा। चाहे पाँच दिन लगे हों या दस, एक महीना या दो महीने, वह टीम को जंगलों में ही रखता, ख़ाक छानता, जब तक कोई आतंकी न मार लेता। उसके साथ गई पार्टी खाली हाथ नहीं लौटती थी। यही उसकी साख थी, और यूनिट का हर जवान यह जानता था।</p>\n<p>“सुम्बड़ा!” विक्रम ने नक़्शे पर उँगली ठोकी। “बारह घंटे पैदल। तीस-पैंतीस जवान चाहिए, और हम पूरे हैं!”</p>\n<p>एक सूबेदार खड़ा हुआ। “सर, सोर्स की ख़बर का इंतज़ार करें?”</p>\n<p>“नहीं! हम पहले जाएँगे। गाँव से एक घंटे की दूरी पर छिपेंगे। एक दिन लगे या चार, बर्फ़ में, बिना आग, बिना आवाज़!”</p>\n<p>उसने जवानों को एक-एक करके देखा।</p>\n<p>“कोई शक? कोई शंका? जिसे हो, यहीं रुक जाए!”</p>\n<p>एक पल की ख़ामोशी रही। फिर पूरा हॉल एक साथ गरजा:</p>\n<p>“नो सर!”</p>\n<p>“आवाज़ नहीं आई!”</p>\n<p>“नो सर!!”</p>\n<p>हॉल में जोश चरम पर था। सभी जवान बदला चाहते थे। रेड्डी उनका भी साथी था, और हर मुट्ठी भिंची हुई थी, हर आँख में एक ही बात थी: जब तक सुल्तान गंजा नहीं मिलता, कोई पीछे नहीं हटेगा।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>रात का मार्च बारह घंटे चला।</p>\n<p>न कोई सड़क थी, न सड़क का किनारा, न कोई गाड़ी। रात के अँधेरे में सीधे जंगल के रास्तों से, बिना एक शब्द बोले, कतार चुपचाप आगे बढ़ती रही। विक्रम सबसे आगे था। उसका हाथ उठता तो पूरी कतार रुक जाती, गिरता तो चल पड़ती।</p>\n<p>उत्तर की रात थी, और उत्तर की रात अपनी ठंड को ढोल बजाकर नहीं, चुपके से उतारती है। हवा चीड़ की सुइयों में सीटी-सी बजाती हुई घाटी में दौड़ती, और कभी सूखे पत्तों की सरसराहट बनकर पाँवों के नीचे बिछ जाती। साँसें सफ़ेद धुएँ की तरह मुँह से निकलकर रात में खो जाती थीं। मूँछों और भौंहों पर पाला जमने लगा था। ऊपर आसमान में तारे इतने पास थे कि लगता था हाथ उठाओ तो उँगलियों से छू जाएँगे, और उतने ही ठंडे।</p>\n<p>जंगल जहाँ बर्फ़ से ढका था, वहाँ उसने कतार नाले के पत्थरों पर उतार दी। इशारे से, बिना बोले: बर्फ़ में पाँव के निशान रह जाते हैं, गीले पत्थर निशान नहीं रखते। नाला अपने ऊपर जमी बर्फ़ की परत के नीचे धीमे-धीमे बुदबुदा रहा था, जैसे पहाड़ अपनी नींद में कुछ कह रहा हो। पाँव फिसलते रहे, पर निशान कहीं नहीं छूटा।</p>\n<p>तीसरे घंटे में एक जवान लड़खड़ा गया। विक्रम ने बिना कुछ कहे उसका पैक अपने कंधे पर उठा लिया और आगे चल दिया। उस कंधे पर बोझ रेड्डी का भी था, पर यह किसी को पता नहीं था।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>गाँव से एक घंटा पहले, पौ फटने से पहले, उसने कतार रोक दी।</p>\n<p>“यहीं।”</p>\n<p>जवान बर्फ़ में गड्ढे खोदकर उतर गए और ऊपर सफ़ेद चादरें खींच लीं। चट्टानों के पीछे दो निगरानी चौकियाँ बनीं। रेडियो पर सिर्फ सुनना था, बोलना नहीं।</p>\n<p>न आग थी, न धुआँ। राशन सूखा था, पानी बर्फ़ पिघलाकर।</p>\n<p>दिन निकलता तो धूप बर्फ़ पर पड़कर आँखों में चुभती, और रात उतरती तो हवाएँ तेज़ हो जातीं, इतनी तेज़ कि सफ़ेद चादरों को फाड़ ले जाना चाहतीं। शरीर काँपते थे। दाँत बजते थे, जबड़े भींचकर उन्हें चुप कराना पड़ता। पलकों पर पाला जम जाता, और बर्फ़ गिरती तो जवान धीरे-धीरे सफ़ेद टीलों में बदल जाते, जिन्हें पास से गुज़रने वाला भी पहचान न पाता। दूसरे दिन से ठंड हड्डियों में उतरने लगी, उँगलियाँ सुन्न होने लगीं, कुछ के पैर सूजने लगे।</p>\n<p>विक्रम हर रात रेंगकर हर जवान के पास गया। मोज़े छूकर देखता कि गीले हैं या सूखे। जिसके गीले निकलते, उसे अपना सूखा जोड़ा दे देता। बस इतना कहता, “पैर सूखे रखो।”</p>\n<p>अपनी निगरानी की पाली उसने किसी को नहीं दी। दूरबीन से रात-रात भर गाँव देखता रहा: किस घर का दरवाज़ा कब खुलता है, कुत्ते कब भौंकते हैं।</p>\n<p>“साहब, तीन रात से पलक नहीं झपकाई,” सूबेदार रणजीत सिंह ने कहा।</p>\n<p>“वह मिलेगा, तब।”</p>\n<p>तीसरे दिन की शाम सोर्स ने छत पर तय रंग का कपड़ा टाँगा: सुल्तान गंजा गाँव में है, ठिकाना पक्का नहीं। चौथी रात के आख़िरी पहर में कपड़ा दो जगह टँगा। ऊपर वाला पक्का घर, वही कमरा।</p>\n<p>विक्रम ने नक़्शा खोला। उसकी उँगली गाँव पर नहीं, पीछे के नाले पर थी।</p>\n<p>“नाला। भागेगा तो यहीं से। यहाँ मैं, तीन रोक-दल मेरे साथ। खोज-दल रणजीत के साथ। उत्तर में ढलान है, वह दक्षिण में आएगा।”</p>\n<p>आधे घंटे में तीस-पैंतीस जवान चार दिशाओं में बँट गए। दो-दो रोक-दल पूरब और उत्तर में, एक पश्चिम में, ऊपर निगरानी चौकी, पीछे रिज़र्व। गाँव ऐसे बँध गया जैसे उस पर किसी ने मुट्ठी कस ली हो।</p>\n<p>नाले के किनारे बैठकर विक्रम ने रेडियो पर कहा, “सब चौकियाँ पुष्टि करें।”</p>\n<p>एक-एक कर आवाज़ें आईं।</p>\n<p>“खोज-दल आगे बढ़े।”</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>अगले तीन मिनट में सब हो गया।</p>\n<p>दरवाज़ा खुलते ही अंदर से गोलियाँ चलीं। खिड़की से तीन आकृतियाँ पिछवाड़े कूदीं और नाले की तरफ दौड़ीं, ठीक उसी रास्ते पर जिसे विक्रम ने उनके लिए खुला छोड़ा था। रोक-दल से टकराते ही दो वहीं गिर गए। तीसरा ढलान पर लुढ़कता रहा।</p>\n<p>फिर सुल्तान गंजा आया। उसके आगे एक बुज़ुर्ग औरत थी, जिसे उसने बाँह से खींचकर ढाल बना रखा था।</p>\n<p>“कोई गोली नहीं,” विक्रम ने रेडियो पर कहा। उसकी आवाज़ बिल्कुल सामान्य थी।</p>\n<p>वह औरत को घसीटता हुआ एक-एक कदम पीछे हटा। विक्रम उसके ठीक ऊपर की चट्टान पर था। औरत की चुन्नी हवा में उड़ी, उसका सिर ज़रा झुका, और सुल्तान गंजा का कंधा ओट से बाहर आ गया।</p>\n<p>एक गोली चली।</p>\n<p>वह सुल्तान गंजा का जान लेने वाला निशाना नहीं था। गोली उसके कंधे में लगी, ठीक वहाँ जहाँ विक्रम ने चाही थी। हथियार उसके हाथ से छूट गया और वह औरत को छोड़कर घुटनों के बल बर्फ़ पर गिरा, घायल, पर ज़िंदा। औरत काँपती हुई दूर जा बैठी। जवानों ने उसे थाम लिया।</p>\n<p>जवान सुल्तान गंजा को क़ाबू में लेकर बर्फ़ पर लिटा चुके थे। कंधे से खून बर्फ़ को गहरा लाल करता जा रहा था।</p>\n<p>विक्रम नीचे उतरकर उसके पास खड़ा हुआ। उसने कुछ नहीं कहा।</p>\n<p>चार आतंकी मारे गए थे। पाँचवाँ घायल पड़ा था। गाँव का कोई घर नहीं जला। विक्रम के किसी जवान की जान नहीं गई, बस एक के हाथ में मामूली घाव था।</p>\n<p>रणजीत सिंह उसके पास आया। “साहब, आपको कैसे पता था कि वह यहीं से भागेगा?”</p>\n<p>“उसकी जगह खड़े होकर सोचा था।”</p>\n<p>“और अगर न भागता?”</p>\n<p>“तब तीन रास्ते और थे।”</p>\n<p>रणजीत सिंह ने उसे सलाम किया, नियम से नहीं, भीतर से।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>अब एक सवाल बचा था।</p>\n<p>बर्फ़ रात भर गिरकर घुटनों तक हो चुकी थी, और यूनिट तक बारह घंटे का पहाड़ी रास्ता था। पाँच लोगों को उठाकर इतनी दूर ले जाने का मतलब था अपने ही जवानों को ख़तरे में डालना, और घायल सुल्तान गंजा को ज़िंदा ले जाने का मतलब था उसे बचाने के लिए जवानों की जान जोखिम में डालना।</p>\n<p>विक्रम ने रिले के ज़रिए यूनिट को संदेश भेजा। पहाड़ों में सीधी आवाज़ नहीं पहुँचती थी, इसलिए संदेश रिज की एक चौकी से होकर गया। थोड़ी देर बाद शर्मा साहब की भारी आवाज़ लौटी।</p>\n<p>“सर, चार ढेर। सुल्तान गंजा घायल, ज़िंदा। खून बहुत बह चुका है।”</p>\n<p>कुछ पल लाइन पर सिर्फ हवा रही।</p>\n<p>“बारह घंटे की बर्फ़ में वह नहीं पहुँचेगा,” शर्मा साहब ने कहा। “खोपड़ियाँ ले आओ। पहचान के लिए काफी है।”</p>\n<p>“यस, सर।”</p>\n<p>विक्रम ने गाँव वालों को घरों की तरफ भिजवाया। किसी को यह नहीं देखना चाहिए था।</p>\n<p>रणजीत सिंह उसके पास आया। “साहब, पहले मार दीजिए। खोपड़ियाँ हम उतार लेंगे।”</p>\n<p>“नहीं,” विक्रम ने कहा। “ज़िंदा ही काटूँगा।”</p>\n<p>उसने अपनी खुखरी निकाली और सुल्तान गंजा के पास घुटनों के बल बैठ गया।</p>\n<p>सुल्तान गंजा की आँखें खुली थीं, और उनमें डर था। वही आतंकी जो गाँव का गढ़ चलाता था, अब बर्फ़ पर पड़ा काँप रहा था।</p>\n<p>“वेंकटेश श्रीनिवास रेड्डी,” विक्रम ने कहा। “तेईस साल का था।”</p>\n<p>“ग़लती हो गई,” सुल्तान गंजा ने काँपती आवाज़ में कहा।</p>\n<p>“फिर सज़ा तो भुगतनी पड़ेगी, सुल्तान,” विक्रम ने कहा। “तूने बहुत ग़लत किया। यह गर्दन नहीं, रेड्डी की मौत का बदला है।”</p>\n<p>विक्रम के चेहरे पर न उत्तेजना थी, न उल्लास, बस वही ठंडी एकाग्रता जो पूरे ऑपरेशन में थी। उसने ज़िंदा सुल्तान गंजा की गर्दन पर खुखरी चलाई, एक ही बार में।</p>\n<p>कुछ पल वह वहीं घुटनों पर रहा।</p>\n<p>“बदला पूरा हुआ,” उसने धीमे से कहा। इतना धीमे कि पास का हवलदार भी न सुन पाया।</p>\n<p>रणजीत सिंह और तीन जवानों ने बाकी चार मारे गए आतंकियों के साथ वही किया जो आदेश था, चुपचाप। बर्फ़ पर कोई नारा नहीं था, सिर्फ हवा।</p>\n<p>पाँचों खोपड़ियाँ बोरों में बाँधी गईं। बाकी शरीर बर्फ़ के नीचे एक आड़ में रखकर पुलिस को उठाने की सूचना भेज दी गई। विक्रम ने खुखरी साफ़ की, म्यान में रखी, और हाथ तब तक बर्फ़ में धोता रहा जब तक उँगलियाँ सुन्न नहीं हो गईं।</p>\n<p>वापसी का बारह घंटे का रास्ता उसी रात शुरू हुआ।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>यूनिट के गेट पर वे अगली सुबह पहुँचे, पाँच बोरे जवानों के कंधों पर।</p>\n<p>शर्मा साहब ख़ुद गेट तक आए। उन्होंने बोरों पर नज़र डाली, फिर विक्रम के कंधे पर हाथ रखा।</p>\n<p>“वेल डन, विक्रम।”</p>\n<p>शर्मा साहब हर ऑपरेशन के बाद यही कहते थे।</p>\n<p>विक्रम ने सिर हिलाया।</p>\n<p>वह मेहराब के नीचे से गुज़रा। ऊपर वही खोपड़ी थी, जबड़े में धँसी खुखरी, निकले हुए दाँत। पहली शाम जब वह और रेड्डी यहाँ किट बैग लिए खड़े थे, तब लगा था कि वह उन पर हँस रही है। महीनों बाद उसे समझ आया था कि वह किसी पर नहीं हँस रही।</p>\n<p>आज उसने ऊपर देखा, और पहली बार लगा कि वह सचमुच हँस रही है। इस बार उसमें न ताना था, न सवाल। वह किसी लंबी लड़ाई के बाद की थकी हुई, हल्की हँसी थी, जैसे कोई बहुत दिनों का बोझ उतार दे।</p>\n<p>“अब आराम कर, दोस्त रेड्डी,” उसने मन में कहा। “तेरा हिसाब चुका दिया।”</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>उसी शाम शर्मा साहब ने उसे बुलाया। “विक्रम, एक हफ्ते की छुट्टी जाओ। फिर 9 पैरा एसएफ़, अपनी यूनिट में रिपोर्ट करो।”</p>\n<p>वह नैना के पास पहुँचा तो शाम ढल रही थी। आसमान के किनारे पर हल्का सिंदूरी रंग बचा था, और गुलमोहर की डालियों पर कोंपलें वैसी ही थीं जैसी वह छोड़ गया था, जैसे समय ने उन्हें उसकी वापसी तक रोक रखा हो।</p>\n<p>नैना ने दरवाज़ा खोला। उसने पहले उसके चेहरे को देखा, फिर हाथों को, जैसे गिन रही हो कि वह पूरा लौटा है या नहीं। फिर उसकी आँखों में वह चीज़ उतर आई जो शब्दों से पहले पहुँचती है।</p>\n<p>“तुम पूरे लौट आए।”</p>\n<p>“वादा किया था।”</p>\n<p>उसने चाय का कप उसके हाथ में थमाया और सामने बैठ गई। उसने कुछ पूछा नहीं। वह जानती थी कि कुछ बातें पूछने से नहीं, इंतज़ार से खुलती हैं।</p>\n<p>“उस दिन तुमने पूछा था मैं क्यों जा रहा हूँ,” विक्रम ने कहा। “मैंने पूरा नहीं बताया था।”</p>\n<p>“हाँ।”</p>\n<p>“रेड्डी…” उसकी आवाज़ पहली बार काँपी। “वह मेरा भाई था, नैना। उसके क़ातिल ज़िंदा थे। जब तक सैनिक अपने साथी का बदला नहीं लेता, उसे शांति नहीं मिलती। उस बोझ के साथ तुम्हारे पास बैठ नहीं सकता था।”</p>\n<p>नैना कुछ नहीं बोली।</p>\n<p>उसके सामने जो इंसान बैठा था, उसने बारह घंटे की बर्फ़ पर अपने दोस्त की याद ढोई थी, और वही अब चाय के कप को दोनों हाथों से ऐसे थामे था जैसे उसे टूटने का डर हो। दुनिया के लिए वह जितना कठोर था, उसके सामने उतना ही कोमल। नैना को डर नहीं लगा। उसे गर्व हुआ, चुपचाप, भीतर तक। उसने जिससे प्यार किया था, वह ऐसा था कि अपने साथी के लिए पहाड़ चढ़ जाए, और लौटकर भी उसके सामने बैठे तो सिर झुकाकर सच बोले।</p>\n<p>सैनिकों को सिखाया जाता है कि वह टूट नहीं सकता। पर जो महसूस नहीं कर सकता, वह जीना भूल जाता है।</p>\n<p>नैना ने मन ही मन सोचा: विक्रम की यही भावुकता उसे उसके सबसे करीब ला रही थी, और यही उसकी सबसे बड़ी ताकत भी थी, कमज़ोरी नहीं।</p>\n<p>“मुझे तुम पर नाज़ है,” उसने कहा।</p>\n<p>विक्रम ने नज़र उठाई।</p>\n<p>“तुम मुझे बता सकते थे। मैं रोकती नहीं।”</p>\n<p>“जानता हूँ। इसीलिए नहीं बताया। अगर तुम रोक लेतीं, तो शायद मैं रुक जाता।”</p>\n<p>नैना की आँखें भर आईं, पर होंठ मुस्कराए। उसने उसकी मुट्ठी अपनी दोनों हथेलियों में ले ली। “और प्यार?”</p>\n<p>“प्यार के लिए वक्त बाद में भी मिल जाता है,” विक्रम ने कहा। “उसके लिए पूरी ज़िंदगी है। बदले के लिए नहीं है। इसलिए उसे पहले करना था।”</p>\n<p>“तो तुमने मुझे बाद के लिए रख छोड़ा,” नैना ने धीरे से कहा, “क्योंकि मैं तुम्हारी पूरी ज़िंदगी थी।”</p>\n<p>विक्रम ने कुछ नहीं कहा। उसकी चुप्पी ही जवाब थी।</p>\n<p>कुछ देर बाद उसने कहा, “अब मुझे अपनी यूनिट, 9 पैरा एसएफ़, में रिपोर्ट करना है। नॉर्थ-ईस्ट में।”</p>\n<p>“कितनी दूर?”</p>\n<p>“बहुत।”</p>\n<p>नैना हँस दी, इस बात पर कि इतनी बड़ी दूरी भी उसने कितने कम शब्दों में कह दी। “फिर जाओ। पर इस बार बता कर जाना।”</p>\n<p>“बता कर जाऊँगा।”</p>\n<p>उसने उसके माथे को चूमा।</p>\n<p>बाहर शाम रात में ढल रही थी, और नैना उसका हाथ थामे रही।</p>"}, {"chapter": 17, "title": "अध्याय 15 — पंद्रह सौ किलोमीटर", "content": "<h1>अध्याय 15 — पंद्रह सौ किलोमीटर</h1>\n<p>मंगलवार का दिन था जब विक्रम के फोन पर सुनैना का नाम आया।</p>\n<p>वह उस वक्त मणिपुर में, अपनी यूनिट में था और लंदन से सुनैना का उस अजीब वक्त पर फोन आना ही काफी था यह समझने के लिए कि बात मामूली नहीं है। फोन उठाते ही उसकी आवाज़ में वह खिंचाव सुनाई दिया जिसे वह छिपाना चाह रही थी, मगर पूरी तरह छिपा नहीं पा रही थी।</p>\n<p>“नैना मेदांता में है… गुरुग्राम में।”</p>\n<p>विक्रम सीधा होकर बैठ गया।</p>\n<p>“क्या हुआ?”</p>\n<p>“डॉक्टर कह रहे हैं अब जान का कोई ख़तरा नहीं है, लेकिन तीन दिन से अस्पताल में है। माँ-पापा को भी ठीक से नहीं बता रही कि हालत कितनी बिगड़ी थी। मैं यहाँ से पहुँच नहीं सकती और…”</p>\n<p>सुनैना कुछ पल चुप रही।</p>\n<p>“मुझे समझ नहीं आया तुम्हारे अलावा किसे फोन करूँ।”</p>\n<p>उसके बाद विक्रम ने ज़्यादा सवाल नहीं किए।</p>\n<p>कुछ बातें फोन पर पूरी सुन लेने के लिए नहीं होतीं। उनका मतलब पहली दो पंक्तियों में ही समझ आ जाता है।</p>\n<p>अगले कुछ घंटों में उसने इमरजेंसी क्लॉज़ के तहत छुट्टी मंज़ूर करवाई—एक ऐसा रास्ता जिसे सर्विस के इतने वर्षों में उसे पहले कभी इस्तेमाल करने की ज़रूरत नहीं पड़ी थी। उसी शाम एयरफोर्स का एक ट्रांसपोर्ट विमान दिल्ली जा रहा था। अपनी यूनिट के एक परिचित के ज़रिए उसने उसमें जगह निकलवा ली।</p>\n<p>सुबह तक वह दिल्ली में था।</p>\n<p>और वहाँ से सीधे गुरुग्राम।</p>\n<p>पूरी दूरी उसके लिए शहरों और किलोमीटरों में बँटी ही नहीं। मणिपुर से दिल्ली, दिल्ली से गुरुग्राम—सब एक ही बेचैनी का लंबा रास्ता बन गया था, जिसके दूसरे छोर पर बस नैना थी।</p>\n<p>विमान जब उत्तर प्रदेश के ऊपर से गुज़र रहा था, नीचे अँधेरे में खेतों की धुँधली चौखटें पीछे छूट रही थीं। बीच-बीच में किसी गाँव की इक्का-दुक्का बत्ती टिमटिमा जाती, जैसे अँधेरे ने साँस लेते-लेते पलक झपकाई हो। विक्रम काफी देर तक उन्हें देखता रहा।</p>\n<p>रेड्डी के जाने के बाद पहली बार उसके भीतर एक ख़याल उठा, और उठते ही उसने उसे दबाने की कोशिश की।</p>\n<p>क्या किसी अपने को खो देने का डर सिर्फ किसी पहाड़ी मोर्चे, किसी गोली या किसी ऑपरेशन के साथ ही आता है?</p>\n<p>कभी-कभी एक मामूली-सा बुखार भी इंसान को वहाँ पहुँचा सकता है जहाँ से कोई वापस नहीं आता।</p>\n<p>एक साधारण अस्पताल का कमरा।</p>\n<p>एक बिस्तर।</p>\n<p>और ख़बर आने में हुई थोड़ी-सी देर।</p>\n<p>उसने ख़याल को आगे नहीं बढ़ने दिया।</p>\n<p>नज़र वापस खिड़की के बाहर कर ली और तब तक वहीं देखता रहा जब तक विमान उतरने नहीं लगा।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>मेदांता के वार्ड के शीशे वाले दरवाज़े से नैना पहली बार दिखाई दी तो विक्रम के कदम एक पल को धीमे पड़ गए।</p>\n<p>उसने नैना को कई रूपों में देखा था—वर्दी में, गुस्से में, हँसते हुए, थककर उसकी गोद में सिर रखे हुए, शादी में खुले बालों और हरे लहँगे में बेफ़िक्र नाचते हुए।</p>\n<p>अस्पताल के उस बिस्तर पर वह उन सबसे अलग लग रही थी।</p>\n<p>छोटी-सी, जैसे वर्दी उतारकर तह करके तकिए के पास रख दी गई हो।</p>\n<p>एक हाथ के पीछे आईवी लगी थी और चेहरे पर बीमारी की वह सफ़ेदी उतर आई थी जो इंसान की सारी अकड़ कुछ दिनों के लिए चुप करा देती है।</p>\n<p>वार्ड में एंटीसेप्टिक और दोबारा गर्म की गई चाय की मिली-जुली गंध थी। दूर गलियारे में किसी ट्रॉली का एक पहिया हर चक्कर पर चरमराता था और मशीनों की धीमी आवाज़ के बीच वही आवाज़ बार-बार अलग सुनाई देती।</p>\n<p>नैना की नज़र दरवाज़े की तरफ गई।</p>\n<p>फिर वहीं ठहर गई।</p>\n<p>उसकी आँखें फैल गईं।</p>\n<p>“विक्रम?”</p>\n<p>नैना ने नाम ऐसे लिया जैसे सामने खड़ा इंसान जवाब दे दे तो ही यकीन होगा कि बुखार कोई वहम नहीं दिखा रहा।</p>\n<p>अगले ही पल उसके कंधे ढीले पड़ गए, जैसे बहुत देर से रोकी हुई साँस आख़िर छूट गई हो।</p>\n<p>“तुम यहाँ क्या कर रहे हो?”</p>\n<p>विक्रम उसके पास आ गया।</p>\n<p>“तुम्हें देखने आया हूँ।”</p>\n<p>“मुझे दिख रहा है।” उसकी आवाज़ कमज़ोर थी, मगर पुरानी नैना उसमें लौटने लगी थी। “मेरा मतलब है—तुम मणिपुर में थे।”</p>\n<p>“था।”</p>\n<p>“वो ढाई हजार किलोमीटर है, विक्रम। तुम—”</p>\n<p>“इतना नहीं है।”</p>\n<p>नैना ने उसे घूरा।</p>\n<p>“क्या?”</p>\n<p>“हवाई दूरी करीब पंद्रह सौ किलोमीटर है। सड़क से ज़्यादा पड़ेगा, लेकिन मणिपुर से कोई गाड़ी चलाकर थोड़े आएगा।”</p>\n<p>कुछ क्षण वह उसे देखती रही।</p>\n<p>फिर तीन दिन की बीमारी, हाथ में लगी आईवी और चेहरे की सारी थकान के बावजूद हँस पड़ी—उसकी उस पक्की गिनती पर, जो अस्पताल के बिस्तर के पास भी नहीं छूटी थी।</p>\n<p>“तुम पंद्रह सौ किलोमीटर उड़कर मेरे अस्पताल के बिस्तर के पास पहुँचे हो और तुम्हें सबसे पहले मेरी दूरी ठीक करनी है?”</p>\n<p>विक्रम के चेहरे पर भी आख़िर मुस्कान आ गई।</p>\n<p>“ग़लत आँकड़ा सुनकर चुप कैसे रहूँ?”</p>\n<p>“बिल्कुल। बहुत ज़रूरी है।”</p>\n<p>“स्टैंडर्ड बनाए रखने पड़ते हैं।”</p>\n<p>उसने गंभीर चेहरा बनाकर नैना को देखा।</p>\n<p>“खासकर तब, जब तुम यहाँ बुखार लेकर पूरे वार्ड की नर्सों को अपना फैन बनाने में लगी हो।”</p>\n<p>“मैंने सिर्फ एक नर्स को इंप्रेस किया है।”</p>\n<p>“एक दिन में?”</p>\n<p>“तीन दिन में। और वो भी इसलिए कि उसे लगा मैं बहुत बहादुर हूँ। असल में मैं बस इस ड्रिप से परेशान थी।”</p>\n<p>“तुम सुधरोगी नहीं।”</p>\n<p>“बीमार हूँ, मरी नहीं हूँ।”</p>\n<p>विक्रम की मुस्कान वहीं ठहर गई।</p>\n<p>नैना ने ख़ुद भी महसूस किया कि उसने क्या कह दिया है।</p>\n<p>एक छोटा-सा सन्नाटा आया।</p>\n<p>फिर उसने हाथ आगे बढ़ाया।</p>\n<p>विक्रम ने बिना कुछ कहे उसका हाथ अपने दोनों हाथों में ले लिया।</p>\n<p>“थैंक यू,” नैना ने धीमे से कहा।</p>\n<p>“किसलिए?”</p>\n<p>“पंद्रह सौ किलोमीटर के लिए।”</p>\n<p>इस बार विक्रम ने मज़ाक नहीं किया।</p>\n<p>कुर्सी खींचकर बिस्तर के बिल्कुल पास बैठ गया।</p>\n<p>“अब सच-सच बताओ। हालत कितनी ख़राब हुई थी?”</p>\n<p>नैना की आँखें कुछ पल उसके चेहरे पर रहीं।</p>\n<p>तीन दिनों से वह हर किसी को वही हिस्सा बता रही थी जिससे सामने वाला ज़्यादा परेशान न हो। विक्रम ने सवाल कुछ इस तरह पूछा था कि आधा सच बोलने की गुंजाइश कम बची थी।</p>\n<p>“पहली रात बुखार बहुत ऊपर चला गया था,” उसने आख़िर कहा। “डॉक्टरों को भी शुरू में समझ नहीं आ रहा था कि वजह क्या है। कुछ घंटे…”</p>\n<p>वह रुक गई।</p>\n<p>विक्रम का अंगूठा उसके हाथ की पीठ पर बहुत धीरे चलता रहा।</p>\n<p>“कुछ घंटे मैं बहुत डर गई थी।”</p>\n<p>विक्रम ने बीच में कुछ नहीं कहा।</p>\n<p>“किसी को बताया नहीं। माँ-बाबा को बताती तो वे घबरा जाते। सुनैना इतनी दूर थी। और मैं यहाँ…”</p>\n<p>नैना ने नज़रें नीचे कर लीं।</p>\n<p>“अकेली थी।”</p>\n<p>उसकी उँगलियों की पकड़ ज़रा ढीली पड़ गई।</p>\n<p>“और पता है उस वक्त मैं किसके बारे में सोच रही थी?”</p>\n<p>विक्रम जानता था, फिर भी पूछा—</p>\n<p>“किसके?”</p>\n<p>“तुम्हारे।”</p>\n<p>नैना ने उसकी उँगलियाँ थोड़ा कसकर पकड़ लीं।</p>\n<p>“मैं सोच रही थी, अगर तीन दिन की बीमारी में, एक अस्पताल के बिस्तर पर पड़े-पड़े मुझे इतना डर लग सकता है… तो जब तुम कहीं ऐसी जगह होते हो जहाँ मैं तुम्हें फोन तक नहीं कर सकती, तब तुम्हारे लिए इंतज़ार करने वाले पर क्या गुज़रती होगी।”</p>\n<p>उसकी आवाज़ धीमी हो गई।</p>\n<p>“क्या तुम्हें हर बार ऐसा ही लगता है?”</p>\n<p>“हाँ।”</p>\n<p>“हर बार?”</p>\n<p>“हर बार।”</p>\n<p>नैना काफी देर चुप रही।</p>\n<p>“मुझे पहले समझ नहीं आया था।”</p>\n<p>“क्या?”</p>\n<p>“इंतज़ार की कीमत।”</p>\n<p>विक्रम ने उसकी तरफ देखा।</p>\n<p>“जब तुम कहीं जाते थे और मैं फोन पर कह देती थी—‘सावधान रहना’—मुझे लगता था मैंने अपनी फ़िक्र कह दी। अब समझ आया कि उसके बाद बचता क्या है। बस इंतज़ार। और उस इंतज़ार में इंसान के पास करने को कुछ भी नहीं होता।”</p>\n<p>“तुम्हें इसके लिए माफ़ी माँगने की ज़रूरत नहीं है।”</p>\n<p>“थोड़ी-सी है।”</p>\n<p>“नहीं,” विक्रम ने कहा।</p>\n<p>“है,” नैना ने कहा। “क्योंकि अब पता चला है कि किसी की ख़बर का इंतज़ार करना भी अपने आप में कितना थका देता है।”</p>\n<p>कुछ देर दोनों वैसे ही बैठे रहे।</p>\n<p>फिर नैना ने बिस्तर पर अपने पास की पतली-सी जगह थपथपाई।</p>\n<p>“यहाँ आओ।”</p>\n<p>विक्रम ने कुर्सी की तरफ देखा।</p>\n<p>“मैं यहीं ठीक हूँ।”</p>\n<p>“मैं नहीं हूँ। वो कुर्सी देखकर मेरी कमर दुख रही है और मुझे तुम इतनी दूर भी नहीं चाहिए।”</p>\n<p>विक्रम उठकर बिस्तर के किनारे बैठ गया। आईवी की लाइन का ध्यान रखते हुए नैना धीरे से खिसकी और कुछ ही देर में उसका सिर विक्रम की गोद में था।</p>\n<p>यह मुद्रा दोनों के लिए नई नहीं थी।</p>\n<p>गुलमोहर के नीचे वह पहले भी ऐसे ही लेटी थी।</p>\n<p>तब डालियों पर हल्की हरी कोंपलें थीं। आज सिर्फ अस्पताल की ट्यूबलाइट थी।</p>\n<p>मगर उस दिन की थकान मन की थी।</p>\n<p>आज उसका शरीर भी थका हुआ था।</p>\n<p>विक्रम ने एक हाथ उसके सिर के नीचे रखा और दूसरे की उँगलियाँ धीरे-धीरे उसके बालों में फेरने लगा।</p>\n<p>उसी स्पर्श ने वह कर दिया जो तीन दिन की बीमारी, डॉक्टरों के सवाल और अकेले बिताई रातें नहीं कर पाई थीं।</p>\n<p>नैना रो पड़ी।</p>\n<p>पहले बिल्कुल चुपचाप, जैसे बाँध की दीवार पर पहली रिसन।</p>\n<p>फिर साँसें टूटने लगीं और कंधे हल्के-हल्के काँपने लगे।</p>\n<p>विक्रम ने उसे चुप कराने की कोशिश नहीं की।</p>\n<p>न यह कहा कि सब ठीक है।</p>\n<p>न यह कि रो मत।</p>\n<p>बस उसकी उँगलियाँ उसी धीमी रफ्तार से उसके बालों में चलती रहीं।</p>\n<p>काफी देर बाद नैना ने कहा—</p>\n<p>“सॉरी।”</p>\n<p>“किस बात का?”</p>\n<p>“पता नहीं। अब रो रही हूँ जब सबसे बुरा वक्त निकल चुका है।”</p>\n<p>“शायद इसीलिए।”</p>\n<p>नैना ने आँखें खोलीं।</p>\n<p>विक्रम ने उसके माथे से बाल हटाए।</p>\n<p>“तीन दिन अकेले ख़ुद को संभालती रही। अब अकेली नहीं हो, तो मत संभालो।”</p>\n<p>नैना की आँखों से फिर दो आँसू निकले, मगर इस बार उनमें पहले वाली घबराहट नहीं थी।</p>\n<p>कुछ देर बाद विक्रम ने बहुत धीमे कहा—</p>\n<p>“जब भी तुम्हें मेरी ज़रूरत होगी, मैं आऊँगा।”</p>\n<p>नैना स्थिर हो गई।</p>\n<p>“जहाँ भी हुआ। जितना भी दूर हुआ। जो करना पड़ा।”</p>\n<p>विक्रम ने नीचे नैना की तरफ देखा।</p>\n<p>“ये बात सिर्फ सुनना मत, नैना। यकीन करना।”</p>\n<p>नैना ने उसकी गोद में सिर थोड़ा मोड़ा ताकि उसका चेहरा देख सके।</p>\n<p>“करती हूँ।”</p>\n<p>फिर कुछ पल बाद बोली—</p>\n<p>“शायद आज से पहले पूरी तरह नहीं करती थी। आज करती हूँ।”</p>\n<p>विक्रम की उँगलियाँ फिर उसके बालों में चलने लगीं।</p>\n<p>नैना ने आँखें बंद कर लीं।</p>\n<p>कुछ देर बाद उसके आँसू थम गए और साँसें बराबर होने लगीं। कमरे में कुछ भी बदला नहीं था—वही अस्पताल की गंध, वही मशीनों की आवाज़, वही आईवी, वही चरमराती ट्रॉली।</p>\n<p>मगर उसके भीतर तीन दिनों से जमा खौफ अब उतना तन्हा नहीं था।</p>\n<p>विक्रम अगले दो दिन वहीं रहा।</p>\n<p>उसने एक बार भी यह नहीं कहा कि अब उसे लौट जाना चाहिए। रात में उसी गद्देदार विज़िटर चेयर पर अधूरी नींद लेता, सुबह फिर उसके पास बैठा मिलता। बुखार पूरी तरह उतर गया और डॉक्टरों ने आख़िर नैना को घर जाने की इजाज़त दे दी, तब जाकर उसने वापसी के बारे में सोचा।</p>\n<p>उसने नैना को उस रात यह नहीं बताया कि उत्तर प्रदेश के ऊपर उड़ते हुए उसके मन में क्या ख़याल आया था।</p>\n<p>रेड्डी के जाने के बाद उसने नैना से वादा किया था कि वह अपने दुःख के दरवाज़े उसके लिए बंद नहीं करेगा।</p>\n<p>मगर डर और दुःख हमेशा एक ही चीज़ नहीं होते।</p>\n<p>कुछ खौफ ऐसे होते हैं जिन्हें इंसान जानता है कि किसी दिन बाँटना पड़ेगा—</p>\n<p>जैसे बीज जानता है कि उसे मिट्टी के भीतर अपनी बारी का इंतज़ार करना है—</p>\n<p>बस आज नहीं।</p>"}, {"chapter": 18, "title": "अध्याय 16 — सोहना किला", "content": "<h1>अध्याय 16 — सोहना किला</h1>\n<p>अस्पताल से छुट्टी मिले नैना को एक हफ्ता हो चुका था। एंटीबायोटिक्स का कोर्स लगभग पूरा था, बुखार लौटकर नहीं आया था और डॉक्टर भी उसे पूरी तरह ठीक मान चुके थे। तीन दिन की निगरानी ज़रूरत से कुछ ज़्यादा चली थी, मगर अस्पताल वाले भी उस इंसान की मौजूदगी को देखकर थोड़े ज़्यादा एहतियाती हो गए थे, जो मणिपुर से पंद्रह सौ किलोमीटर का सफ़र तय करके सिर्फ उसके बिस्तर के पास बैठने चला आया था।</p>\n<p>अब विक्रम की छुट्टी में दो दिन बचे थे।</p>\n<p>उस शाम नैना का फोन आया तो उसकी आवाज़ में एक ऐसी बेचैनी थी जिसे दोनों पहचानते थे, मगर कोई उसका नाम नहीं लेना चाहता था।</p>\n<p>“मुझे कहीं ले चलो।”</p>\n<p>“कहाँ?”</p>\n<p>“कहीं भी। मुझे फ़र्क़ नहीं पड़ता। बस एक दिन और चाहिए जो अस्पताल का कमरा न हो… और ऐसी विदाई भी नहीं, जो आने से पहले ही हमारे बीच बैठ जाए।”</p>\n<p>विक्रम कुछ पल चुप रहा।</p>\n<p>“सोहना किला?”</p>\n<p>“क्यों?”</p>\n<p>“कई महीने पहले तुमने कहा था कभी जाना है।”</p>\n<p>नैना को याद करने में एक पल लगा।</p>\n<p>“तुम्हें वो भी याद है?”</p>\n<p>“तुम बोलती बहुत हो। कुछ न कुछ याद रह ही जाता है।”</p>\n<p>“अच्छा।”</p>\n<p>उसकी आवाज़ में मुस्कान लौट आई।</p>\n<p>“तो कल सोहना किला। और कल हम किसी दूसरी चीज़ के बारे में नहीं सोचेंगे।”</p>\n<p>“कोशिश करेंगे।”</p>\n<p>“नहीं। करेंगे।”</p>\n<p>विक्रम हँस दिया।</p>\n<p>नैना की यही आदत थी—जिन चीज़ों पर उसका कोई बस नहीं होता, उनके बारे में भी फ़ैसला ऐसे सुनाती थी जैसे दुनिया को मानना ही पड़ेगा।</p>\n<p>उस रात उसने दोबारा फोन करके बस इतना कहा—</p>\n<p>“वीकडे है, भीड़ नहीं होगी। तुम, मैं और कुछ सौ साल पुरानी किसी और की महत्वाकांक्षाएँ।”</p>\n<p>“बहुत रोमांटिक योजना है।”</p>\n<p>“मुझे पता था तुम्हें पसंद आएगी।”</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>सुबह वे निकले तो आसमान का रंग फीका धूसर था, जैसे किसी पुराने अख़बार का पन्ना ऊपर तान दिया गया हो।</p>\n<p>किला लगभग वैसा ही खाली मिला जैसा नैना चाहती थी। झाड़ियों और सूखी घास के बीच पुरानी बलुआ पत्थर की दीवारें खड़ी थीं; टिकट देने वाला एक ऊबा हुआ केयरटेकर था, जिसने दो टिकट काटे और फिर अपने काम में लग गया।</p>\n<p>बाकी वहाँ कोई नहीं था।</p>\n<p>बाहरी दीवार के कई हिस्से बरसों पहले ढह चुके थे। कहीं-कहीं इतनी बड़ी दरार थी कि बिना किसी दरवाज़े से गुज़रे सीधे भीतर जाया जा सकता था—जैसे किसी वक्त किले ने तय कर लिया हो कि अब दुनिया से ख़ुद को बचाने की मशक्कत बेकार है, जिसे आना है आए।</p>\n<p>टूटी दीवार की एक दरार में कहीं से एक नन्हीं हरी कोंपल फूट आई थी—पत्थरों की उस पुरानी थकान के बीच अकेली जीती-जागती चीज़।</p>\n<p>दोनों बिना किसी तय रास्ते के घूमते रहे।</p>\n<p>सदियों के कदमों से घिस चुकी सँकरी पत्थर की सीढ़ियाँ चढ़ीं, छोटे-छोटे आँगनों में निकले, कभी किसी टूटी मेहराब के नीचे रुक गए।</p>\n<p>एक बड़े से हॉल में पहुँचकर नैना ठहर गई। छत बहुत पहले गिर चुकी थी और ऊपर पूरा आसमान दिखाई दे रहा था।</p>\n<p>“कभी कोई यहाँ पूरी ज़िंदगी रहा होगा।”</p>\n<p>विक्रम ने उसकी तरफ देखा।</p>\n<p>“शादी हुई होगी यहीं। बच्चे हुए होंगे। पैसे की चिंता की होगी, ससुराल वालों से परेशान हुआ होगा… कोई औरत बैठकर सोचती होगी कि उसका पति उससे उतनी मोहब्बत करता भी है या नहीं जितनी वह चाहती है।”</p>\n<p>उसने चारों तरफ देखा।</p>\n<p>“और अब?”</p>\n<p>टूटी दीवारें।</p>\n<p>उगी हुई घास।</p>\n<p>खुला आसमान।</p>\n<p>“अब बस ये बचा है। और सदियों बाद हम दोनों यहाँ खड़े उनकी ज़िंदगी के बारे में अंदाज़ा लगा रहे हैं।”</p>\n<p>विक्रम ने सिर हिलाया।</p>\n<p>“मंगलवार की सुबह के लिए काफी भारी ख़याल है।”</p>\n<p>“मुझे उल्टा सुकून देता है।”</p>\n<p>नैना उसकी तरफ मुड़ी।</p>\n<p>“जो चीज़ आज हमें बहुत बड़ी लगती है न… शायद थोड़ी दूरी से उतनी बड़ी नहीं रहती।”</p>\n<p>विक्रम कुछ कहता, उससे पहले बारिश की पहली बूँद उसके हाथ की पीठ पर गिरी।</p>\n<p>उसने ऊपर देखा।</p>\n<p>दूसरी बूँद का इंतज़ार नहीं करना पड़ा।</p>\n<p>एकाएक पानी टूट पड़ा।</p>\n<p>कुछ ही पलों में धूल कीचड़ बनने लगी। नैना चौंककर हँसी और विक्रम की बाँह पकड़कर पास की एक मेहराब की तरफ भागी।</p>\n<p>“इधर!”</p>\n<p>दोनों दौड़े, मगर छत के नीचे पहुँचते-पहुँचते भीग चुके थे।</p>\n<p>कमरा छोटा था और किले के उन गिने-चुने हिस्सों में से था जिसकी छत अब भी पूरी बची थी। पत्थर की सँकरी दीवारें, ऊपर एक छोटी खिड़की और बाहर गिरती बारिश की लगातार आवाज़; हवा में भीगी मिट्टी और पुराने पत्थर की गंध भर गई थी।</p>\n<p>नैना ने अपने दुपट्टे का सिरा निचोड़ा।</p>\n<p>“ये योजना में नहीं था।”</p>\n<p>“योजना तुम्हारी थी।”</p>\n<p>“बारिश मेरी नहीं थी।”</p>\n<p>उसने बाहर देखा। पानी कम होने के बजाय और तेज़ पड़ रहा था।</p>\n<p>फिर विक्रम की तरफ मुड़ी।</p>\n<p>“लगता है कुछ देर यहीं फँसे हैं।”</p>\n<p>बैठने को पत्थर के फर्श के अलावा कुछ नहीं था।</p>\n<p>दोनों दीवार से पीठ लगाकर बैठ गए। कंधे आपस में छू रहे थे और सामने खुले दरवाज़े के पार बारिश एक मोटे पर्दे की तरह गिर रही थी।</p>\n<p>“मैंने आज की कल्पना ऐसी नहीं की थी,” विक्रम ने कहा।</p>\n<p>“मैं शिकायत नहीं कर रही।”</p>\n<p>नैना ने सिर पीछे पत्थर से टिका दिया।</p>\n<p>कुछ देर बारिश सुनती रही।</p>\n<p>“पता है मुझे इसमें क्या अच्छा लग रहा है?”</p>\n<p>“भीगे कपड़े?”</p>\n<p>“चुप रहो।”</p>\n<p>वह मुस्कराई, फिर आवाज़ अपने-आप थोड़ी धीमी हो गई।</p>\n<p>“मुझे रुकना नहीं आता, विक्रम। मेरी पूरी ज़िंदगी में कुछ न कुछ मुझसे माँगता रहता है—घर, नौकरी, ड्यूटी, लोग… हमेशा अगली चीज़।”</p>\n<p>उसने चेहरा उसकी तरफ किया।</p>\n<p>“तुम शायद मेरी ज़िंदगी की इकलौती चीज़ हो जो मुझसे कुछ माँगती नहीं।”</p>\n<p>विक्रम की नज़र उस पर ठहर गई।</p>\n<p>नैना ने आगे कहा—</p>\n<p>“तुम्हारे साथ मैं बस रह सकती हूँ। मुझे हर वक्त कुछ साबित नहीं करना पड़ता, किसी की उम्मीद पूरी नहीं करनी पड़ती।”</p>\n<p>एक हल्की-सी मुस्कान उसके होंठों पर आई।</p>\n<p>“अभी तक ठीक से समझ नहीं पाई कि इसे क्या नाम दूँ।”</p>\n<p>“आज नाम देना ज़रूरी भी नहीं है।”</p>\n<p>“शायद नहीं।”</p>\n<p>कुछ क्षण बीते।</p>\n<p>फिर नैना पूरी तरह उसकी तरफ मुड़ गई।</p>\n<p>इस बार उसकी आँखों में वह पुरानी हिचक नहीं थी। महीनों से अपने भीतर हर बात को पहले परखने, फिर स्वीकार करने और आख़िर में बोलने वाली नैना जैसे उस दिन पहली बार अपनी ही सावधानी से थक चुकी थी।</p>\n<p>“एक बात पर नाम की ज़रूरत नहीं है।”</p>\n<p>“किस पर?”</p>\n<p>“इस पर कि मैं तुम्हें चाहती हूँ।”</p>\n<p>विक्रम चुप रहा।</p>\n<p>नैना की आँखें उसकी आँखों से नहीं हटीं।</p>\n<p>“और अब मैं ये भी नहीं सोच रही कि मुझे पक्का यकीन है या नहीं। कई हफ्तों से है। बस मानने में देर कर रही थी।”</p>\n<p>बाहर बारिश पत्थरों पर लगातार गिरती रही।</p>\n<p>विक्रम ने हाथ उठाकर उसके गाल से चिपकी भीगी लट हटाई।</p>\n<p>नैना ने उसका हाथ जाने नहीं दिया।</p>\n<p>नैना ने उसकी कलाई पकड़कर हथेली अपने गाल पर रख ली और एक पल के लिए आँखें बंद कर लीं।</p>\n<p>विक्रम झुका।</p>\n<p>नैना भी उसकी ओर बढ़ी।</p>\n<p>दोनों के बीच बची थोड़ी-सी दूरी ख़त्म हुई और उसके होंठ नैना के होंठों से आ मिले। पहले स्पर्श में एक पल की नरमी थी, फिर नैना की उँगलियाँ उसकी कमीज़ पर कस गईं और वह ख़ुद उसके और करीब आ गई।</p>\n<p>बारिश तो बस चिंगारी थी। आग उस चीज़ ने पकड़ी, जो दोनों के भीतर हफ्तों से सूखी और तैयार पड़ी थी—और एक बार पकड़ ली, तो उसे बुझाने की न कोई सूरत बची, न दोनों में से किसी के भीतर ऐसी कोई चाह।</p>\n<p>कुछ पलों के लिए दोनों भूल गए कि वे पत्थर के ठंडे फर्श पर हैं, एक ऐसे पुराने किले में, जिसने अपने चार सौ सालों में ऐसा न जाने कितनी बार देखा होगा।</p>\n<p>विक्रम का हाथ उसके कंधे के पास ठहरा तो वह और करीब आ गई। भीगे कपड़ों की ठंड के बावजूद दोनों की साँसें गर्म और तेज़ थीं। नैना की धड़कन उसकी हथेली के नीचे इतनी साफ़ महसूस हो रही थी कि उसे अपनी धड़कन से अलग करना मुश्किल था।</p>\n<p>विक्रम थोड़ा पीछे हुआ।</p>\n<p>“नैना…”</p>\n<p>“मत पूछना।”</p>\n<p>“क्या?”</p>\n<p>“फिर से ये मत पूछना कि मैं पक्की हूँ या नहीं।”</p>\n<p>उसने अपना माथा उसके माथे से लगा दिया।</p>\n<p>“बता चुकी हूँ।”</p>\n<p>विक्रम फिर उसकी ओर झुका। उसके होंठ दोबारा नैना के होंठों को छू गए—इस बार पहले से धीमे, ठहरे हुए। नैना का हाथ उसके भीगे बालों में चला गया और उसने उसे अपने और करीब खींच लिया।</p>\n<p>कुछ पल बाद विक्रम के होंठ उसके होंठों से अलग हुए और धीरे-धीरे उसके गाल को छूते हुए गर्दन तक उतर आए। नैना ने सिर पीछे पत्थर से टिका दिया; उसकी साँस एक पल को अटककर फिर और तेज़ लौट आई।</p>\n<p>विक्रम के हाथ उसकी कमर और पीठ पर ठहरे, भीगे कपड़े के ऊपर से उसकी देह की गर्माहट महसूस करते हुए। नैना उससे दूर नहीं हुई। उल्टा उसकी उँगलियाँ विक्रम की कमीज़ के बटनों तक पहुँच गईं।</p>\n<p>नैना की उँगलियों से पहला बटन खुला।</p>\n<p>फिर दूसरा।</p>\n<p>विक्रम ने धीरे से उसकी दोनों कलाइयाँ थाम लीं। वह उसे रोक नहीं रहा था, बस उनकी बढ़ती हुई रफ्तार को एक पल थाम रहा था।</p>\n<p>उसने नैना की एक कलाई अपने करीब की और होंठ बहुत हल्के से उसकी कलाई की भीतरी तरफ रख दिए।</p>\n<p>“धीरे,” विक्रम ने वहीं ठहरी आवाज़ में कहा। “हमें किसी बात की जल्दी नहीं है।”</p>\n<p>नैना ने उसकी तरफ देखा।</p>\n<p>“धीरे,” नैना ने दोहराया। उसकी आवाज़ कुछ काँपी।</p>\n<p>फिर नैना ने विक्रम को अपनी ओर खींच लिया।</p>\n<p>“बस रुकना मत।”</p>\n<p>विक्रम नहीं रुका।</p>\n<p>मगर जल्दबाज़ी भी नहीं की।</p>\n<p>उसके होंठ नैना के कंधे तक गए जहाँ भीगा कुर्ता थोड़ा खिसक आया था। उँगलियाँ उसकी कमर और पीठ पर धीरे-धीरे चलती रहीं, जैसे किसी अनजानी जगह को जीतना नहीं, पहचानना चाहती हों। नैना ने उसे वैसे पकड़ा हुआ था जैसे बहुत दिनों से ख़ुद को इस अधिकार से रोकती आई हो।</p>\n<p>एक जगह उसके होंठ गर्दन पर ठहरे तो नैना का पूरा शरीर एक पल के लिए सिहर गया।</p>\n<p>फिर दोनों वहीं ठहर गए।</p>\n<p>साँसें तेज़ थीं।</p>\n<p>विक्रम की कमीज़ आधी खुल चुकी थी। नैना का दुपट्टा जाने कब पत्थर के फर्श पर गिर गया था। उनके बीच की महीनों पुरानी सावधानी लगभग पूरी तरह पिघल चुकी थी।</p>\n<p>फिर भी एक आख़िरी सीमा थी।</p>\n<p>किसी ने उसका नाम नहीं लिया।</p>\n<p>दोनों जानते थे।</p>\n<p>और दोनों वहीं रुक गए।</p>\n<p>कुछ देर उनके माथे एक-दूसरे से लगे रहे।</p>\n<p>फिर नैना ने बहुत सीधे, बिना किसी शर्म या बनावट के कहा—</p>\n<p>“मैं तुम्हें चाहती हूँ, विक्रम।”</p>\n<p>विक्रम की आँखें उसके चेहरे पर टिक गईं।</p>\n<p>“मुझे पता है।”</p>\n<p>“नहीं।”</p>\n<p>उसने हल्का-सा सिर हिलाया।</p>\n<p>“ठीक से जानो।”</p>\n<p>उसकी आवाज़ अब धीमी थी, मगर उसमें कोई हिचक नहीं थी।</p>\n<p>“मैं तुम्हारे साथ वो सब चाहती हूँ जो अभी हमारे बीच बाकी है। आज नहीं… इस पुराने किले के पत्थर पर नहीं।”</p>\n<p>उसके होंठों पर हल्की मुस्कान आई।</p>\n<p>“लेकिन किसी दिन। जल्दी।”</p>\n<p>विक्रम ने उसके चेहरे को दोनों हाथों में लिया।</p>\n<p>“मैं भी चाहता हूँ।”</p>\n<p>उसने अपना माथा उसके माथे पर टिकाए रखा।</p>\n<p>“जब सही वक्त होगा।”</p>\n<p>नैना ने आँखें बंद करके सिर हिला दिया।</p>\n<p>उसके बाद वे काफी देर वहीं बैठे रहे—एक-दूसरे में सिमटे हुए। नैना का गाल विक्रम की खुली कमीज़ के पास उसकी छाती से लगा था और विक्रम का हाथ उसके लंबे भीगे बालों पर धीरे-धीरे चलता रहा।</p>\n<p>चाहत ख़त्म नहीं हुई थी।</p>\n<p>बस उसकी जल्दबाज़ी उतर गई थी।</p>\n<p>मोहब्बत का एक हिस्सा यही भी था—किसी को इतना चाहना कि उसके और करीब जाने की तमन्ना हो, और फिर भी उस एक कदम के लिए सही वक्त का इंतज़ार कर सकना।</p>\n<p>बाहर बारिश भी धीरे-धीरे हल्की पड़ गई।</p>\n<p>जब दोनों कमरे से निकले तो किला वही था, मगर बारिश ने उसका रंग बदल दिया था। धूल बैठ चुकी थी, पत्थर चमक रहे थे, जगह-जगह पानी जमा था और हवा में गीली मिट्टी के साथ कहीं से नई घास की महक आ रही थी। दीवार की दरार वाली कोंपल पर बारिश की बूँदें टिकी थीं, हर बूँद में आसमान का एक नन्हा टुकड़ा।</p>\n<p>कार तक लौटते हुए दोनों बहुत कम बोले।</p>\n<p>कहने को बचा भी कम था।</p>\n<p>वापसी में नैना पहले की तरह अपनी तरफ सिमटकर नहीं बैठी। वह विक्रम के करीब थी, उसका हाथ पूरे रास्ते विक्रम के घुटने पर टिका रहा।</p>\n<p>न विक्रम ने हटाया।</p>\n<p>न नैना ने।</p>\n<p>शहर करीब आने लगा तो बाहर की दुनिया धीरे-धीरे फिर लौटने लगी—ट्रैफिक, रोशनी, लोग, रास्ते।</p>\n<p>मगर उनके बीच कुछ पीछे नहीं लौटा।</p>\n<p>अब दोनों जानते थे कि मोहब्बत सिर्फ फ़िक्र और इंतज़ार तक नहीं रह गई थी। उसमें स्पर्श भी था, नज़दीकी भी, और उस चाहत से अब कोई नज़र नहीं चुरा रहा था।</p>\n<p>दो दिन बाद विक्रम की छुट्टी ख़त्म होनी थी, और अगली कब मिलेगी, इसका कोई भरोसा नहीं था। दोनों ने रास्ते में इसका ज़िक्र नहीं किया।</p>\n<p>आने वाली दूरी उनके साथ ही शहर लौटी, इस बार पहले से कुछ ज़्यादा भारी। क्योंकि अब उनके बीच सिर्फ मिलने की आदत नहीं थी, एक अधूरी नज़दीकी भी थी, जिसे दोनों पूरा करना चाहते थे।</p>\n<p>और पीछे किले की दरार में वह कोंपल अब भी बूँद थामे खड़ी थी, बिना किसी के देखे।</p>"}, {"chapter": 19, "title": "अध्याय 17 — तुम्हें चुना है", "content": "<h1>अध्याय 17 — तुम्हें चुना है</h1>\n<p>छुट्टी लगभग अचानक मिली थी।</p>\n<p>पूरे पाँच दिन।</p>\n<p>बीच में न कोई ड्यूटी, न वापस रिपोर्ट करने की कोई मजबूरी। दोनों को एक साथ एहसास हुआ कि जब से यह रिश्ता शुरू हुआ था, पहली बार उनके पास इतने दिन थे जिन्हें बीच से कोई और आकर नहीं बाँट रहा था।</p>\n<p>नैना ने फोन पर फ़ैसला सुना दिया—</p>\n<p>“हिमाचल।”</p>\n<p>उसकी आवाज़ ऐसी थी जैसे आधा रास्ता वह पहले ही तय कर चुकी हो।</p>\n<p>“लेकिन कोई ऐसा हिल स्टेशन नहीं जहाँ हर तरफ हनीमून वाले सेल्फी लेते मिलें। छोटी-सी जगह। मेरे दिमाग में एक है।”</p>\n<p>“गाड़ी ले आऊँगा। छह घंटे का रास्ता है।”</p>\n<p>“नहीं। बाइक।”</p>\n<p>“नैना—”</p>\n<p>“बाइक।”</p>\n<p>उस लहजे का मतलब विक्रम अब अच्छी तरह समझता था।</p>\n<p>“पूरी ज़िंदगी लोग मुझे कहीं न कहीं गाड़ी में बैठाकर पहुँचाते रहे हैं। इस बार सिर्फ पहुँचना नहीं है। रास्ता भी महसूस करना है।”</p>\n<p>विक्रम ने बहस नहीं की।</p>\n<p>इतने महीनों में वह एक बात सीख चुका था—नैना जिस फ़ैसले पर अपने भीतर पहुँच चुकी हो, वहाँ तर्क सिर्फ समय बर्बाद करता है।</p>\n<p>वे सूरज निकलने से पहले गुरुग्राम से निकल गए।</p>\n<p>शहर अभी आधी नींद में था। सड़कें खाली थीं और शुरुआती कुछ घंटों में नैना की बाँहें उसकी कमर के चारों तरफ ढीली-सी टिकी रहीं। पहाड़ शुरू हुए, सड़कें मुड़ने लगीं तो उसकी पकड़ अपने-आप कसती गई। कभी किसी मोड़ पर दूर कुछ देखने के लिए वह आगे झुकती और उसका माथा हल्के से विक्रम के कंधे को छू जाता।</p>\n<p>बातें बहुत कम हुईं।</p>\n<p>ज़रूरत भी नहीं थी।</p>\n<p>दो लोगों के बीच जब ख़ामोशी असहज न रहे, तो लंबे रास्ते अक्सर छोटे लगने लगते हैं।</p>\n<p>करीब दो घंटे बाद वे सड़क किनारे एक पुराने ढाबे पर रुके। एक औरत तंदूर सँभाल रही थी, उसका बेटा ऑर्डर ले रहा था और छाँव में बिछी चारपाई पर एक बूढ़ा ऊँघ रहा था, जो उनके बैठने पर बस आँखें खोलकर सिर हिलाता और फिर अपनी नींद में लौट जाता।</p>\n<p>विक्रम ने नैना से पूछे बिना खाना मँगवा दिया।</p>\n<p>अब वह जानता था उसे क्या पसंद है।</p>\n<p>गाढ़ी दाल आई, तंदूर से उतरती गर्म रोटियाँ आईं और कुछ देर दोनों चुपचाप खाते रहे।</p>\n<p>नैना ने रोटी का टुकड़ा तोड़ते हुए कहा—</p>\n<p>“मेरी नानी एक बात कहती थीं।”</p>\n<p>“क्या?”</p>\n<p>“इंसान को समझना हो तो उसे ऐसी जगह खाना खाते देखो जहाँ दिखावा करने को कुछ न हो। फिर पता चलता है कि उसे जो मिला है उसकी कद्र है, या उसे सिर्फ वही चीज़ें अच्छी लगती हैं जिनसे दूसरे प्रभावित हों।”</p>\n<p>विक्रम ने पानी पिया।</p>\n<p>“आज क्या पता चला?”</p>\n<p>नैना कुछ क्षण उसे देखती रही।</p>\n<p>“तुम पानी भरने वाले उस बच्चे को भी थैंक यू बोलते हो जिससे कोई उम्मीद भी नहीं करता कि उसे थैंक यू कहा जाएगा।”</p>\n<p>विक्रम ने सहजता से कंधे उचकाए।</p>\n<p>“उसने पानी भरा।”</p>\n<p>“मुझे पता है। बात वही है।”</p>\n<p>नैना के चेहरे पर एक पुरानी याद की नरमी उतर आई।</p>\n<p>“नानी ने कहा था, कभी जीवनसाथी चुनना तो देखना कि वह उन लोगों से कैसे पेश आता है जिनसे उसे कुछ हासिल नहीं करना। ऐसा इंसान ढूँढ़ना जिसके दिल में सफाई हो।”</p>\n<p>वह हल्का-सा हँसी।</p>\n<p>“तब मुझे समझ नहीं आया था कि उनका मतलब क्या है।”</p>\n<p>“और अब?”</p>\n<p>“अभी तुम्हें देखते हुए थोड़ा समझ आया।”</p>\n<p>विक्रम कुछ नहीं बोला।</p>\n<p>उसे अपनी दादी याद आईं—इतनी जल्दी चली गई थीं कि उनकी साफ़ तस्वीर भी अब याद में नहीं बची थी। जाने क्यों वर्षों बाद पहली बार उसके मन में आया कि काश वह कुछ और साल जीवित रहतीं। किसी ऐसे ही ढाबे की मेज़ पर उसके सामने बैठतीं और नैना को देखकर अपनी कोई राय बनातीं।</p>\n<p>“उम्मीद है मैं उनका टेस्ट पास कर लेता।”</p>\n<p>“कर लेते।”</p>\n<p>“इतना भरोसा?”</p>\n<p>“लोगों को पहचानने में मैं अच्छी हूँ।”</p>\n<p>“ये दावा थोड़ा संदिग्ध है।”</p>\n<p>नैना ने आख़िरी निवाला खाया और उठ खड़ी हुई।</p>\n<p>“चलो। अभी चार घंटे और हैं।”</p>\n<p>विक्रम ने उसके पर्स तक हाथ पहुँचने से पहले पैसे दे दिए।</p>\n<p>इस छोटी-सी जीत पर उसने कुछ नहीं कहा।</p>\n<p>मुस्कराकर बाइक की तरफ चल पड़ा।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>आख़िरी कुछ घंटों ने शरीर से छह घंटे की बाइक यात्रा की पूरी कीमत वसूल ली।</p>\n<p>जब वे शोजा पहुँचे, दोनों की कमर और कंधे रास्ते की शिकायत कर रहे थे और हवा चेहरे पर अपनी खुरदरी छाप छोड़ चुकी थी।</p>\n<p>शोजा सेराज घाटी का एक छोटा-सा गाँव था, जिसका नाम विक्रम ने नैना से पहले कभी नहीं सुना था। आख़िरी हिस्सा ऐसी सँकरी सड़क से होकर आया था जिसे सड़क कहना भी कुछ उदारता थी।</p>\n<p>शाम उतरने लगी थी।</p>\n<p>पहाड़ की ढलान पर लकड़ी और पत्थर के घर एक-दूसरे के ऊपर चढ़े दिखाई देते थे। आख़िरी छतों के बाद देवदार और चीड़ का जंगल ऊपर उठता चला गया था और उससे भी आगे उन चोटियों तक पहुँचता था जहाँ अब भी बर्फ़ ठहरी हुई थी।</p>\n<p>गेस्टहाउस की छोटी बालकनी में खड़ी नैना देर तक सामने देखती रही।</p>\n<p>“बहुत खूबसूरत है।”</p>\n<p>“फोटो देखकर चुना था न?”</p>\n<p>“हाँ। इसीलिए भरोसा नहीं था। तस्वीरें बहुत झूठ बोलती हैं।”</p>\n<p>“इसने नहीं बोला।”</p>\n<p>नैना ने अपनी कमर पर हाथ रखा।</p>\n<p>“और छह घंटे बाइक पर बैठने ने भी कोई झूठ नहीं बोला। मेरा पूरा शरीर मुझसे नाराज़ है।”</p>\n<p>“कल आराम करेंगे।”</p>\n<p>“किसने कहा?”</p>\n<p>विक्रम ने उसे देखा।</p>\n<p>उसकी आँखों की चमक देखकर ही उसे शक हो गया।</p>\n<p>रात को खाने के दौरान नैना ने अगली सुबह का कार्यक्रम सुना दिया।</p>\n<p>“रिज तक जाएँगे। चार घंटे ऊपर, दो घंटे वापस।”</p>\n<p>“तुम्हारे हिसाब से छुट्टी का मतलब क्या होता है?”</p>\n<p>“अपनी मर्ज़ी से थकना।”</p>\n<p>“आज छह घंटे बाइक पर अपनी मर्ज़ी से नहीं बैठी थीं?”</p>\n<p>“बैठी थी। कल अपनी मर्ज़ी से पहाड़ चढ़ूँगी।”</p>\n<p>विक्रम ने सिर हिलाया।</p>\n<p>“पूरी सर्विस पहाड़ इसलिए चढ़ता रहा हूँ क्योंकि किसी ने ऑर्डर दिया। छुट्टी में भी यही करना है?”</p>\n<p>“फ़र्क़ यही है। कल कोई ऑर्डर नहीं देगा।”</p>\n<p>उस रात सोने से पहले वे छोटी खिड़की के पास कुछ देर खड़े रहे। बाहर का आसमान इतना साफ़ था कि शहरों में भुला दिए गए तारे भी दिखाई दे रहे थे।</p>\n<p>नैना ने बिना उसकी तरफ देखे कहा—</p>\n<p>“मैं नहीं चाहती कि कभी हम इस ट्रिप को याद करके कहें—वो हमारी आख़िरी अच्छी याद थी।”</p>\n<p>विक्रम ने उसकी तरफ देखा।</p>\n<p>“मैं चाहती हूँ ये पहली हो। ऐसी बहुत सारी यात्राओं में से पहली।”</p>\n<p>विक्रम ने जवाब देने में देर नहीं की।</p>\n<p>“मैं भी।”</p>\n<p>खिड़की के काँच पर दोनों की साँस की धुंध एक ही जगह मिल गई।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>अगली सुबह पूरी रोशनी फैलने से पहले वे निकल पड़े।</p>\n<p>आसमान में रात का गहरा नीला रंग अब भी बचा था और हवा इतनी ठंडी थी कि शुरुआती हर साँस सीने में चुभती थी। घास पर जमी ओस ने कुछ ही देर में उनकी पैंट के निचले हिस्से भिगो दिए।</p>\n<p>पहाड़ों के पीछे से रोशनी इतनी धीरे उठ रही थी जैसे कोई परदे के किनारे उठाकर दुनिया को जगा रहा हो।</p>\n<p>रास्ता पहले देवदार के बीच से ऊपर चढ़ता था। गिरी हुई सूइयों की मोटी तह उनके कदमों की आवाज़ तक सोख लेती। रोशनी बढ़ी तो पेड़ छँटने लगे; फिर झाड़ियाँ और खुली चट्टानें आईं और हवा में पहाड़ की वह साफ़, तीखी ठंड उतर आई जो त्वचा को छूकर भीतर तक पहुँचती है।</p>\n<p>नैना की चाल ने विक्रम को हैरान किया।</p>\n<p>न तेज़, न सुस्त।</p>\n<p>बस लगातार।</p>\n<p>वर्षों पहले किसी और पहाड़ी इलाके में उसके पिता ने उसे यही चाल सिखाई थी।</p>\n<p>एक जगह दोनों समतल चट्टान पर बैठकर पराँठे खाने लगे। नीचे पूरी घाटी फैली थी और जिस गाँव से चले थे वह अब कुछ छोटी छतों और उठते धुएँ जितना रह गया था।</p>\n<p>नैना नीचे देखती रही।</p>\n<p>“ऊपर से सब कितना छोटा लगता है।”</p>\n<p>“नीचे जाकर फिर बड़ा हो जाएगा।”</p>\n<p>“पता है।”</p>\n<p>उसने पराँठे का टुकड़ा तोड़ा।</p>\n<p>“शायद इसीलिए कभी-कभी ऊपर आना चाहिए।”</p>\n<p>रिज पर पहुँचकर दृश्य अचानक उनके सामने खुला।</p>\n<p>एक के पीछे एक सफ़ेद चोटियाँ दूर धुँधले क्षितिज तक चली गई थीं। हवा दर्रे की चट्टानों के बीच से गुज़रती हुई एक लगातार धीमी गूँज पैदा कर रही थी, जो उन दोनों से कहीं पुरानी लगती थी। जैसे पहाड़ ख़ुद साँस ले रहे हों, और दो लोग उसकी हर साँस के बीच बैठे हों। इसके अलावा वहाँ लगभग कोई आवाज़ नहीं थी।</p>\n<p>दोनों करीब एक घंटे वहीं बैठे रहे।</p>\n<p>थर्मस की आख़िरी चाय अब गुनगुनी रह गई थी। नैना पहले विक्रम के कंधे से लगी, फिर थोड़ा और नीचे खिसककर उसकी छाती से टिक गई। दोनों सामने पहाड़ देख रहे थे।</p>\n<p>विक्रम ने अचानक गहरी साँस ली।</p>\n<p>हवा में चीड़ की हल्की-सी राल जैसी महक थी।</p>\n<p>उसके भीतर कहीं कोई बहुत पुराना दरवाज़ा खुला।</p>\n<p>“डोडा।”</p>\n<p>नैना ने सिर थोड़ा उठाया।</p>\n<p>“क्या?”</p>\n<p>“कश्मीर में डोडा डिस्ट्रिक्ट। मेरे ज़्यादातर ऑपरेशन्स वहीं हुए थे।”</p>\n<p>उसने फिर वही हवा भीतर खींची।</p>\n<p>“वहाँ के चीड़ की महक बिल्कुल ऐसी थी। महीनों से उस पोस्टिंग के बारे में सोचा तक नहीं था। अभी एकदम सब याद आ गया।”</p>\n<p>नैना ने ख़ुद हवा सूँघी।</p>\n<p>“मुझे तो कुछ अलग नहीं लग रहा।”</p>\n<p>“अभी नहीं लगेगा।”</p>\n<p>“फिर?”</p>\n<p>विक्रम की उँगलियाँ उसके बालों में धीरे-धीरे चल रही थीं।</p>\n<p>“कभी लगेगा। शायद यहाँ नहीं। शायद सालों बाद किसी बिल्कुल दूसरी जगह। यही महक अचानक दोबारा मिलेगी और उसी पल पहचान जाओगी।”</p>\n<p>नैना ने ऊपर उसकी तरफ देखा।</p>\n<p>“और क्या पहचानूँगी?”</p>\n<p>“कि ये मुझसे होकर कभी तुम्हारे पास पहले भी आई थी।”</p>\n<p>नैना के चेहरे पर हल्की मुस्कान आई।</p>\n<p>“महक से भी वादे करते हो?”</p>\n<p>“हर वादे को जगह थोड़े चाहिए। कभी-कभी एक खुशबू और थोड़ा वक्त काफी होता है।”</p>\n<p>नैना फिर उसकी छाती से लग गई।</p>\n<p>“तो इंतज़ार करूँगी।”</p>\n<p>एक पल रुकी।</p>\n<p>“जितना वक्त लगे।”</p>\n<p>कुछ देर दोनों चुप रहे।</p>\n<p>फिर नैना ने कहा—</p>\n<p>“मुझे कुछ सच बताओ।”</p>\n<p>“मैं झूठ बहुत बोलता हूँ?”</p>\n<p>“मज़ाक में बताई हुई कोई कहानी नहीं। ऐसी बात जो तुमने सचमुच कभी किसी से नहीं कही।”</p>\n<p>विक्रम काफी देर सामने पहाड़ों को देखता रहा।</p>\n<p>विक्रम का हाथ अब भी नैना के बालों में था।</p>\n<p>“मुझे लगता था मोहब्बत दूसरे लोगों के साथ होती है।”</p>\n<p>नैना स्थिर हो गई।</p>\n<p>“मेरे साथ नहीं। मुझे हमेशा लगा ज़िंदगी में कभी कोई रिश्ता होगा तो बस… तय हो जाएगा। घर वाले देखेंगे, बात होगी, शादी हो जाएगी और फिर इंसान धीरे-धीरे उसी ज़िंदगी में ढल जाएगा।”</p>\n<p>“और दूसरी वाली?”</p>\n<p>“कौन-सी?”</p>\n<p>“जिसमें इंसान ढलता नहीं। गिरता है।”</p>\n<p>विक्रम मुस्कराया।</p>\n<p>“उस पर यकीन नहीं था।”</p>\n<p>“अब?”</p>\n<p>इस बार उसने नीचे नैना की तरफ देखा।</p>\n<p>“अब लगता है तुमसे मिलने से पहले मैं बहुत-सी चीज़ों के बारे में ग़लत था।”</p>\n<p>नैना की नज़र पल भर को ठहरी।</p>\n<p>फिर वह सामने पहाड़ों पर लौट गई।</p>\n<p>“मुझे लगता था मुझसे ठीक तरह मोहब्बत करना मुश्किल है।”</p>\n<p>विक्रम का हाथ उसके बालों में रुक गया।</p>\n<p>“क्यों?”</p>\n<p>“माँ कहा करती थीं—थोड़ी नरम हुआ कर, नैना। हर बात में इतनी तेज़ मत रहा कर। अच्छे-भले लड़के डरकर भाग जाएँगे।”</p>\n<p>उसकी आवाज़ में शिकायत नहीं थी; बस कोई पुरानी बात थी जो बहुत दिनों बाद बाहर आई थी।</p>\n<p>“सालों तक लगा शायद सही कहती हैं। कि जिसे मेरे साथ रहना होगा, उसके लिए मुझे अपना कुछ हिस्सा कम करना पड़ेगा।”</p>\n<p>वह पलटकर उसे देखने लगी।</p>\n<p>“तुमने कभी नहीं कहा।”</p>\n<p>“क्या?”</p>\n<p>“कि मैं थोड़ी कम हो जाऊँ।”</p>\n<p>विक्रम ने बिना सोचे जवाब दिया—</p>\n<p>“मुझे तुम कम चाहिए ही नहीं थीं।”</p>\n<p>नैना की आँखें उससे नहीं हटीं।</p>\n<p>“जैसी हो, वैसी ही चाहिए थीं।”</p>\n<p>कई क्षण वह कुछ नहीं बोली।</p>\n<p>फिर बहुत धीरे कहा—</p>\n<p>“मेरे लिए शायद आज तक किसी ने इससे ज़्यादा सच्ची बात नहीं कही।”</p>\n<p>उसने सिर वापस उसकी छाती पर रख दिया।</p>\n<p>“और पता है सबसे अजीब क्या है?”</p>\n<p>“क्या?”</p>\n<p>“मैं हर हफ्ते इंतज़ार करती हूँ कि तुम अपना मन बदलोगे।”</p>\n<p>विक्रम की बाँह उसके चारों तरफ थोड़ी और सिमट आई।</p>\n<p>“और जब नहीं बदलते… तो हर हफ्ते थोड़ा और यकीन हो जाता है।”</p>\n<p>उसके बाद ख़ामोशी आई।</p>\n<p>मगर वह खाली ख़ामोशी नहीं थी।</p>\n<p>कई बार दो लोगों के बीच कुछ बातें कह दिए जाने के बाद उन्हें तुरंत किसी और बात से ढक देना उनकी कीमत कम कर देता है।</p>\n<p>इसलिए दोनों वहीं बैठे रहे।</p>\n<p>नैना उसकी छाती से लगी रही और विक्रम की उँगलियाँ उसके बालों में चलती रहीं।</p>\n<p>सामने पहाड़ थे।</p>\n<p>और उनके बीच पहली बार मोहब्बत सिर्फ महसूस की हुई चीज़ नहीं रही थी।</p>\n<p>फिर नैना ने अपनी हथेली उसकी हथेली में रख दी और विक्रम ने उँगलियाँ बंद कर लीं।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>दोपहर ढलने से पहले वे नीचे लौट आए।</p>\n<p>पैर थके हुए थे, मगर वह अच्छी थकान थी जो किसी दिन को पूरा जी लेने के बाद शरीर में रहती है।</p>\n<p>आख़िरी रास्ते में नैना बहुत शांत हो गई।</p>\n<p>विक्रम ने महसूस किया, मगर पूछा नहीं।</p>\n<p>अब वह उसकी हर ख़ामोशी को तुरंत सवाल से खोलने की कोशिश नहीं करता था।</p>\n<p>रात के खाने पर, उसी नीची मेज़ के सामने, नैना ने ख़ुद बात शुरू की।</p>\n<p>“मैं सोहना वाली बात के बारे में सोच रही थी।”</p>\n<p>विक्रम समझ गया।</p>\n<p>“मुझे याद है।”</p>\n<p>“वो उस वक्त की बात नहीं थी।”</p>\n<p>उसने कप मेज़ पर रख दिया।</p>\n<p>“मतलब… मैं सिर्फ बहाव में नहीं कह रही थी। उसके बाद कई बार सोचा है। ठीक से।”</p>\n<p>उसने विक्रम की आँखों में देखा।</p>\n<p>“मैं तैयार हूँ।”</p>\n<p>विक्रम कुछ कहने लगा।</p>\n<p>“पहले मुझे पूरा बोलने दो। वरना हिम्मत चली जाएगी।”</p>\n<p>वह चुप हो गया।</p>\n<p>नैना ने साँस ली।</p>\n<p>“मैं जानती हूँ मेरे लिए इसका क्या मतलब है। सिर्फ शरीर वाली बात नहीं। मेरे घर में इन चीज़ों को हल्के में नहीं लिया जाता। मैं भी नहीं लेती।”</p>\n<p>उसकी आवाज़ बिल्कुल स्थिर थी।</p>\n<p>“अगर मैं तुम्हारे साथ उस सीमा के आगे जाती हूँ, तो अगले दिन उठकर ये नहीं कह सकती कि बस हो गया, भूल जाओ। मैं ऐसी नहीं हूँ। मेरे लिए उसके बाद कुछ बदल जाएगा।”</p>\n<p>विक्रम सुनता रहा।</p>\n<p>“इसलिए मैं चाहती हूँ कि तुम्हें साफ़ पता हो—मैं ये तुम्हें इसलिए नहीं दे रही कि हम यहाँ अकेले हैं, या क्योंकि मौका है।”</p>\n<p>एक पल को उसकी आवाज़ धीमी हुई।</p>\n<p>“मैंने तुम्हें चुना है।”</p>\n<p>विक्रम ने कप उठाया, फिर बिना पिए रख दिया।</p>\n<p>“आगे जो भी हो… मेरे लिए ये मामूली नहीं होगा।”</p>\n<p>“मेरे लिए भी नहीं।”</p>\n<p>“मुझे पता है।”</p>\n<p>उसके चेहरे पर हल्की-सी नरमी आई।</p>\n<p>“इसीलिए तुम्हें कह पा रही हूँ।”</p>\n<p>उसके बाद दोनों तुरंत कमरे की तरफ नहीं भागे।</p>\n<p>शाम अपनी रफ्तार से चलती रही।</p>\n<p>विक्रम ने पिछले दिन गेस्टहाउस के पास एक छोटी-सी दुकान देखी थी जहाँ मंदिर के लिए गेंदे के फूल बिकते थे। नैना बर्तन धोने गई तो वह बाहर निकला और थोड़े-से फूल ले आया।</p>\n<p>न कोई गुलदस्ता।</p>\n<p>न कोई बड़ी तैयारी।</p>\n<p>बस कुछ गेंदे के फूल—पीले, मंदिर के, जिनमें देवता से पहले किसी की हथेली की गर्माहट थी।</p>\n<p>कमरे की मेज़ पर रख दिए।</p>\n<p>नैना अंदर आई तो उसकी नज़र तुरंत उन पर गई।</p>\n<p>फिर विक्रम पर।</p>\n<p>“ये क्यों?”</p>\n<p>“बस।”</p>\n<p>“बस?”</p>\n<p>“कमरा सिर्फ कमरा न लगे।”</p>\n<p>नैना ने फूलों को देखा और फिर उसे।</p>\n<p>“तुम्हारे साथ तो पहले ही नहीं लग रहा।”</p>\n<p>उस एक वाक्य के बाद विक्रम के पास कहने को कुछ नहीं बचा।</p>\n<p>दोनों बिस्तर के किनारे काफी देर बैठे रहे।</p>\n<p>हाथ एक-दूसरे में थे, मगर बात उन चीज़ों की होती रही जिनका उस रात से कोई सीधा रिश्ता नहीं था—नैना का बचपन, उसके पिता का लंबी ड्राइव पर बेसुरा गाना, पहाड़ों में रात को कहीं से आती वह अजीब-सी आवाज़ जिसे दोनों पहचान नहीं पा रहे थे।</p>\n<p>विक्रम समझ रहा था।</p>\n<p>नैना वहाँ पहुँच चुकी थी जहाँ वह पहुँचना चाहती थी; अब बस अपने डर को पीछे आने का थोड़ा वक्त दे रही थी।</p>\n<p>कुछ देर बाद नैना ने कहा—</p>\n<p>“माँ ने एक बात कही थी कभी।”</p>\n<p>विक्रम ने हल्के से छेड़ा—</p>\n<p>“आज उनकी बहुत याद आ रही है।”</p>\n<p>“चुप रहो।”</p>\n<p>वह मुस्कराई।</p>\n<p>“उन्होंने कहा था, पहली बार उस इंसान के साथ होना जिसके सामने तुम इतनी महफ़ूज़ महसूस करो कि बेवकूफ़ भी हो सको।”</p>\n<p>उसने विक्रम की उँगलियों को देखा।</p>\n<p>“तब समझ नहीं आया था।”</p>\n<p>“अब?”</p>\n<p>“अब आता है।”</p>\n<p>विक्रम ने उसके चेहरे पर आई एक लट पीछे की।</p>\n<p>वही छोटा-सा स्पर्श जो सोहना में भी हुआ था।</p>\n<p>फ़र्क़ इतना था कि इस बार नैना ने सिर्फ उसकी हथेली नहीं थामी; अपना पूरा चेहरा उसमें रख दिया।</p>\n<p>“महफ़ूज़ महसूस करती हो?” विक्रम ने पूछा।</p>\n<p>“बहुत।”</p>\n<p>उसने उसकी तरफ देखा।</p>\n<p>“इसीलिए यहाँ हूँ। वरना शायद कहीं बैठकर बहादुर होने का नाटक कर रही होती।”</p>\n<p>विक्रम ने कुछ क्षण उसे देखा।</p>\n<p>“अभी भी ज़रूरी नहीं है।”</p>\n<p>नैना की आँखें नरम हो गईं।</p>\n<p>“क्या?”</p>\n<p>“आज। या कभी भी। सिर्फ इसलिए नहीं कि हमने बात कर ली है।”</p>\n<p>“मैं चाहती हूँ।”</p>\n<p>वह रुकी।</p>\n<p>“पहले कभी नहीं हुआ मेरे साथ। तुम्हें पता है।”</p>\n<p>“पता है।”</p>\n<p>“तो मुझे शीशे की तरह मत छूना कि टूट जाऊँगी।”</p>\n<p>नैना ने उसकी उँगलियाँ कसकर पकड़ लीं।</p>\n<p>“और इतनी जल्दी भी मत करना जैसे तुम्हें डर हो कि मैं फ़ैसला बदल दूँगी।”</p>\n<p>फिर बहुत साफ़ कहा—</p>\n<p>“नहीं बदलूँगी।”</p>\n<p>उसके बाद उनके बीच शब्द धीरे-धीरे कम होने लगे।</p>\n<p>विक्रम उसके करीब आया तो नैना पीछे नहीं हटी। उसके होंठ बहुत हल्के से नैना के होंठों से मिले और कुछ पल वहीं ठहरे रहे—जैसे दोनों आख़िरी बार एक-दूसरे को वक्त दे रहे हों कि चाहें तो रुक जाएँ।</p>\n<p>कोई नहीं रुका।</p>\n<p>नैना की उँगलियाँ उसके कंधों पर आ गईं।</p>\n<p>विक्रम के हाथ उसके चेहरे से होते हुए उसकी पीठ तक पहुँचे, मगर हर स्पर्श में वही ठहराव था—चाहत को कम करने वाला नहीं, उसे भरोसे के भीतर रखने वाला।</p>\n<p>नैना उसकी आँखों में बार-बार देखती रही।</p>\n<p>जैसे हर अगले पल से पहले सिर्फ इतना जान लेना चाहती हो कि सामने अब भी वही इंसान है जिस पर उसने भरोसा किया था।</p>\n<p>और हर बार उसे वही मिला।</p>\n<p>न कोई जीत का भाव।</p>\n<p>न कोई जल्दबाज़ी।</p>\n<p>सिर्फ वह नरमी जिसमें वह जितनी घबराई हुई थी, उतनी ही रह सकती थी; जितनी तैयार थी, उतनी ही आगे बढ़ सकती थी।</p>\n<p>कुछ देर बाद उनके बीच की आख़िरी दूरी भी नहीं रही।</p>\n<p>कमरे में पहाड़ की ठंडी हवा थी और मेज़ पर रखे गेंदे के फूलों की हल्की-सी महक।</p>\n<p>“ठंड लग रही है?” विक्रम ने धीमे से पूछा।</p>\n<p>“थोड़ी।”</p>\n<p>वह एक पल रुकी।</p>\n<p>“कमरे से नहीं।”</p>\n<p>विक्रम ने चादर उठा दी। नैना उसके भीतर आ गई और अगले ही पल अपनी ही घबराहट पर हल्का-सा हँस पड़ी।</p>\n<p>विक्रम भी मुस्कराया।</p>\n<p>उसकी यही हँसी उस रात की सबसे ज़रूरी चीज़ थी।</p>\n<p>क्योंकि उसके बाद डर उतना बड़ा नहीं रहा।</p>\n<p>नैना ने ख़ुद उसे अपने और करीब खींच लिया।</p>\n<p>इस बार नैना के होंठ विक्रम के होंठों को पहले से ज़्यादा यकीन के साथ छू रहे थे। उँगलियाँ विक्रम की पीठ पर ठहर गईं और उनके बीच बची हुई आख़िरी सावधानियाँ भी धीरे-धीरे उतरने लगीं।</p>\n<p>किसी पल नैना को तकलीफ़ हुई तो उसने तुरंत बता दिया।</p>\n<p>विक्रम वहीं रुक गया।</p>\n<p>अपना माथा उसके माथे से लगाए तब तक ठहरा रहा जब तक उसके चेहरे का तनाव ढीला नहीं पड़ा।</p>\n<p>नैना ने उसकी आँखों में देखा।</p>\n<p>फिर ख़ुद उसे वापस अपने करीब खींच लिया।</p>\n<p>“रुको मत।”</p>\n<p>उसकी आवाज़ विक्रम के कान के पास बहुत धीमी थी।</p>\n<p>“डरकर इतना संभालो भी मत मुझे।”</p>\n<p>उसकी बाँहें उसके चारों तरफ कस गईं।</p>\n<p>“बस मेरे करीब रहो।”</p>\n<p>और विक्रम रहा।</p>\n<p>उसके बाद जो कुछ उनके बीच था, उसमें जल्दबाज़ी नहीं थी, मगर अब झिझक भी नहीं बची थी। दोनों एक-दूसरे की साँसों, स्पर्श और हर छोटी प्रतिक्रिया से अपनी रफ्तार समझते रहे।</p>\n<p>और जब आख़िर उनके बीच कोई दूरी नहीं रही, नैना ने अपना चेहरा उसके कंधे में छिपा लिया।</p>\n<p>उसके होंठों से विक्रम का नाम निकला।</p>\n<p>एक बार।</p>\n<p>फिर दोबारा।</p>\n<p>फिर जैसे उस पल उसके पास कहने के लिए वही एक शब्द बचा हो—</p>\n<p>“विक्रम…”</p>\n<p>और उन्हीं साँसों के बीच एक बार एक और शब्द निकला।</p>\n<p>बहुत धीमे।</p>\n<p>लगभग अपने-आप।</p>\n<p>“मोहब्बत…”</p>\n<p>नैना ने उसे वापस नहीं लिया।</p>\n<p>विक्रम ने भी उससे कोई जवाब नहीं माँगा।</p>\n<p>उस पल ज़रूरत नहीं थी।</p>\n<p>काफी देर बाद भी दोनों अलग नहीं हुए।</p>\n<p>नैना की उँगलियाँ उसकी पीठ पर धीरे-धीरे चल रही थीं, जैसे वह सिर्फ यह महसूस कर लेना चाहती हो कि वह सचमुच वहीं है।</p>\n<p>“ठीक हो?” विक्रम ने पूछा।</p>\n<p>नैना ने तुरंत जवाब नहीं दिया।</p>\n<p>अपने शरीर को, अपने मन को, उस पूरे पल को जैसे भीतर से जाँचकर फिर बोली—</p>\n<p>“थोड़ी तकलीफ़ है।”</p>\n<p>कुछ पल बाद उसके होंठों पर मुस्कान आई।</p>\n<p>“अलग लग रहा है।”</p>\n<p>और फिर—</p>\n<p>“लेकिन अच्छा।”</p>\n<p>विक्रम की बाँह उसके गिर्द और गहरी हो गई।</p>\n<p>नैना ने आँखें बंद कर लीं।</p>\n<p>“ऐसा नहीं लगा कि हमने कोई पल चुरा लिया।”</p>\n<p>उसकी आवाज़ उसकी छाती के पास से आ रही थी।</p>\n<p>“ऐसा लगा जैसे गुलमोहर के नीचे उस बेंच से जिस जगह की तरफ चलना शुरू किया था… आज वहाँ पहुँच गए।”</p>\n<p>विक्रम के होंठ उसके माथे से बहुत हल्के से छुए और वहीं एक पल ठहरे रहे।</p>\n<p>नैना उसके और करीब सिमट गई।</p>\n<p>कमरे में फिर ख़ामोशी उतर आई।</p>\n<p>मेज़ पर रखे गेंदे के फूलों की हल्की मीठी महक उनके आसपास बनी रही।</p>\n<p>कुछ देर बाद नैना ने कहा—</p>\n<p>“जो मैंने पहले कहा था… वो सच था।”</p>\n<p>“क्या?”</p>\n<p>“कि मैंने तुम्हें चुना है।”</p>\n<p>उसने अपना गाल उसकी छाती पर और आराम से रख लिया।</p>\n<p>“मुझे इसका अफसोस नहीं है।”</p>\n<p>एक लंबी साँस।</p>\n<p>“मुझे नहीं लगता कभी होगा।”</p>\n<p>विक्रम का हाथ उसके बालों में ठहर गया।</p>\n<p>“मुझे भी नहीं।”</p>\n<p>फिर बहुत धीमे बोला—</p>\n<p>“और आज की रात तुम्हारे लिए क्या मायने रखती है, ये मैं कभी हल्के में नहीं लूँगा।”</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>सुबह नैना पहले जाग गई।</p>\n<p>विक्रम की आँख खुली तो वह उसके पास बैठी एक गीले कपड़े से उसके कंधे पर पड़े अपने नाखूनों के हल्के निशान साफ़ कर रही थी।</p>\n<p>“ये करने की ज़रूरत नहीं है।”</p>\n<p>उसकी आवाज़ अभी नींद से भारी थी।</p>\n<p>“मुझे करनी है।”</p>\n<p>नैना ने बिना रुके कपड़ा उसके कंधे से हंसली और फिर छाती तक फेर दिया।</p>\n<p>“रात तुमने मेरा ख़याल रखा था।”</p>\n<p>उसने ऊपर उसकी तरफ देखा।</p>\n<p>“सुबह मेरी बारी है।”</p>\n<p>काम ख़त्म करके वह उठने लगी तो विक्रम ने उसकी कलाई पकड़ ली।</p>\n<p>“पाँच मिनट और।”</p>\n<p>नैना हँस पड़ी।</p>\n<p>“पाँच मिनट?”</p>\n<p>विक्रम ने उसे वापस अपनी तरफ खींच लिया।</p>\n<p>इस बार नैना उसकी बाँहों में पिछली रात की तरह सँभलकर नहीं आई। उसकी उँगलियाँ विक्रम की उँगलियों में फँसीं और अगले ही पल उनके बीच की जगह पूरी तरह ख़त्म हो गई।</p>\n<p>“विक्रम…”</p>\n<p>वह उसके गाल के पास मुस्कराई।</p>\n<p>अब उसे समझ आ चुका था कि वे पाँच मिनट सिर्फ पाँच मिनट नहीं थे।</p>\n<p>“क्या चाहिए?”</p>\n<p>विक्रम ने जवाब नहीं दिया।</p>\n<p>सिर्फ उसे देखा।</p>\n<p>चेहरे पर वह धीमी-सी मुस्कान थी जिसे अब नैना पढ़ना सीख चुकी थी।</p>\n<p>नैना को दूसरी बार पूछने की ज़रूरत नहीं पड़ी।</p>\n<p>रात की झिझक सुबह तक नहीं बची थी।</p>\n<p>अब दोनों एक-दूसरे को थोड़ा और जानते थे—सिर्फ मन से नहीं, स्पर्श से भी। कौन-सा स्पर्श साँस रोक देता है, कहाँ हाथ ठहरता है तो दूसरा अपने-आप और करीब आ जाता है; रात ने उन्हें एक-दूसरे की वह भाषा भी सिखा दी थी जिसमें शब्द बहुत कम पड़ते थे।</p>\n<p>इस बार नैना ने भी ख़ुद को उतना नहीं रोका।</p>\n<p>उसकी बाँहें विक्रम के चारों तरफ कस गईं, उँगलियाँ उसकी पीठ पर और मज़बूती से ठहरीं और साँसों में पिछली रात वाली घबराहट की जगह एक खुली हुई चाहत थी।</p>\n<p>कुछ देर बाद वह उसका नाम लेने लगी।</p>\n<p>बस नाम।</p>\n<p>“विक्रम…”</p>\n<p>फिर वही।</p>\n<p>और फिर।</p>\n<p>जैसे उस सुबह बाकी सारे शब्द ग़ैरज़रूरी हो गए हों।</p>\n<p>इस बार उनके बीच की नज़दीकी पिछली रात से ज़्यादा तेज़ थी, ज़्यादा बेझिझक—इसलिए नहीं कि रात की नरमी कम हो गई थी, बल्कि इसलिए कि अब दोनों को मालूम था सामने वाला कहाँ खड़ा है।</p>\n<p>और दोनों वहीं होना चाहते थे।</p>\n<p>बहुत देर बाद नैना ने अपना चेहरा उसके कंधे में छिपाकर हँसते हुए कहा—</p>\n<p>“मुझे नहीं पता था तुम्हारे साथ सुबह ऐसी भी हो सकती है।”</p>\n<p>विक्रम की साँस अभी पूरी तरह सामान्य नहीं हुई थी।</p>\n<p>“मुझे भी करीब बीस मिनट पहले तक नहीं पता था।”</p>\n<p>नैना खुलकर हँस पड़ी।</p>\n<p>फिर वापस उसकी बाँहों में सिमट गई।</p>\n<p>कुछ देर दोनों चादर के नीचे वैसे ही उलझे पड़े रहे।</p>\n<p>बाहर सुबह पूरी तरह आ चुकी थी, पर भीतर किसी ने परदा नहीं हटाया।</p>\n<p>मेज़ पर गेंदे के फूल अब भी महक रहे थे, और घाटी की धूप खिड़की तक आकर रुक गई थी, जैसे उसे भी भीतर आने की जल्दी नहीं थी।</p>\n<p>कल तक विक्रम को लगता था कि कोई ज़िंदगी में आता है तो साथ चलता है। आज उसे पता चला कि कोई भीतर भी रह सकता है।</p>"}, {"chapter": 20, "title": "अध्याय 18 — मैं इंतज़ार कर रही हूँ", "content": "<h1>अध्याय 18 — मैं इंतज़ार कर रही हूँ</h1>\n<p>ड्यूटी पर लौटने से एक शाम पहले नैना ने तय कर लिया कि वह विक्रम को स्टेशन छोड़ने जाएगी।</p>\n<p>विक्रम ने एक से ज़्यादा बार कहा कि इसकी ज़रूरत नहीं है।</p>\n<p>नैना ने हर बार एक ही जवाब दिया—</p>\n<p>“तुम जा रहे हो और मैं घर बैठी रहूँ? नहीं।”</p>\n<p>“नैना—”</p>\n<p>“फ़ैसला कर चुकी हूँ। इस एक बात पर बहस मत करना।”</p>\n<p>स्टेशन पहुँचकर दोनों प्लेटफॉर्म पर खड़े रहे। ट्रेन आने में अभी बीस मिनट थे।</p>\n<p>उनके चारों तरफ रेलवे स्टेशन अपनी रोज़ की रफ्तार में चल रहा था—कुली सामान लेकर निकल रहे थे, दुकानदार आवाज़ लगा रहे थे, कोई परिवार बच्चों को सँभालते हुए डिब्बे का नंबर ढूँढ़ रहा था, कोई देर हो जाने के डर से भागता हुआ सामने से गुज़र रहा था।</p>\n<p>उस पूरी भागदौड़ के बीच वे दोनों थे जो जैसे अपनी जगह से हिलना नहीं चाहते थे।</p>\n<p>प्लेटफॉर्म की पीली बत्तियों के नीचे दो परछाइयाँ एक-दूसरे में इतनी मिली थीं कि भीड़ उनके आसपास से बहती हुई गुज़र रही थी।</p>\n<p>नैना काफी देर चुप रही।</p>\n<p>फिर बोली—</p>\n<p>“मुझे नहीं पता तुम्हारे बिना कैसे रहूँगी।”</p>\n<p>विक्रम ने उसकी तरफ देखा।</p>\n<p>“रह लोगी। इससे मुश्किल चीज़ें सँभाली हैं तुमने।”</p>\n<p>“सँभाल लेना और किसी चीज़ को चाहना एक बात नहीं होती।”</p>\n<p>नैना ने हाथ बढ़ाकर विक्रम का कॉलर ठीक किया।</p>\n<p>कॉलर पहले से ठीक था।</p>\n<p>नैना के हाथों को उस वक्त कुछ करना ज़रूरी था, वरना उनकी हल्की-सी थरथराहट साफ़ दिखाई देती।</p>\n<p>“मैं कहीं नहीं जा रही, विक्रम।”</p>\n<p>नैना की उँगलियाँ कॉलर पर एक पल और ठहरी रहीं।</p>\n<p>“अब से तुम्हारी अगली छुट्टी तक जो भी हो… मैं इंतज़ार करूँगी।”</p>\n<p>विक्रम की आँखें उसके चेहरे पर टिक गईं।</p>\n<p>“जो भी हो,” विक्रम ने बहुत धीमे कहा, “बस एक बात याद रखना।”</p>\n<p>“क्या?”</p>\n<p>“मैं वापस आऊँगा।”</p>\n<p>नैना ने जवाब नहीं दिया।</p>\n<p>विक्रम को देखती रही।</p>\n<p>जैसे उस वाक्य को सुन नहीं, अपने भीतर कहीं रख रही हो।</p>\n<p>कुछ देर बाद ट्रेन प्लेटफॉर्म पर घुसी। पहियों और पटरियों की तेज़ आवाज़, ब्रेक की चीख, कुलियों की पुकार और यात्रियों की अचानक बढ़ी हलचल ने उनके आसपास की दुनिया फिर से उनके बीच ला खड़ी की।</p>\n<p>विक्रम ने कुछ और कहने के बजाय नैना को अपनी बाँहों में भर लिया।</p>\n<p>नैना का चेहरा उसके कंधे में छिप गया।</p>\n<p>नैना की मुट्ठियाँ विक्रम की कमीज़ की पीठ पर कस गईं—जैसे कुछ पल और पकड़कर रखने से जाने का वक्त भी कुछ पल पीछे खिसक जाएगा।</p>\n<p>“ज़िंदा लौटना।”</p>\n<p>नैना की आवाज़ विक्रम के कंधे में दबकर निकली।</p>\n<p>“बस इतना माँग रही हूँ।”</p>\n<p>विक्रम की बाँहें उसके चारों तरफ और गहरी हो गईं।</p>\n<p>“ज़िंदा लौटना, विक्रम।”</p>\n<p>“आऊँगा।”</p>\n<p>विक्रम को ट्रेन में चढ़ना पड़ा।</p>\n<p>विक्रम ने खिड़की के पास जगह ढूँढ़ ली। नैना वहीं प्लेटफॉर्म पर खड़ी रही।</p>\n<p>ट्रेन धीरे-धीरे चलने लगी तो नैना का एक हाथ उठा।</p>\n<p>वह ठीक से हाथ भी नहीं हिला रही थी।</p>\n<p>उठाए रही।</p>\n<p>जब तक उनके बीच की दूरी इतनी नहीं बढ़ गई कि उस इशारे का कोई मतलब ही नहीं बचा।</p>\n<p>फिर ट्रेन दूर होती गई।</p>\n<p>पहले डिब्बे छोटे हुए।</p>\n<p>फिर सिर्फ आवाज़ बची।</p>\n<p>और कुछ देर बाद वह भी नहीं।</p>\n<p>पटरियाँ देर तक काँपती रहीं, जैसे उन्हें भी कुछ याद रह गया हो।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>म्यांमार बॉर्डर पर पहुँचने के तीसरे दिन विक्रम को वह जगह दिखाई गई, जो नक़्शे पर सिर्फ एक पेंसिल का गोला थी।</p>\n<p>कर्नल ने गोले पर उँगली रखी।</p>\n<p>“चालीस के आसपास। हथियारों का डिपो। और वह इंसान जो हर महीने किसी न किसी गाँव को जलाता है।”</p>\n<p>एक पल।</p>\n<p>“यह काम 9 पैरा एसएफ़ को सौंपा गया है। तैयारी में कितना वक्त चाहिए?”</p>\n<p>“सात दिन।”</p>\n<p>“सात?”</p>\n<p>“सात दिन देखे बिना अंदर नहीं जाऊँगा, सर।”</p>\n<p>कर्नल ने उसे देखा, फिर सिर हिला दिया।</p>\n<p>“वक्त तुम्हारा।”</p>\n<p>“पहले मैं अकेला नहीं, चार जवानों के साथ जाऊँगा। रेकी। बाकी टीम बाद में।”</p>\n<p>“ठीक।”</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>उसी रात विक्रम चार जवान लेकर निकल गया—उनमें हवलदार थापा भी था।</p>\n<p>कोई सड़क नहीं। कोई गाड़ी नहीं। रेडियो साथ था, मगर बंद। रात भर पैदल जंगल के रास्ते, और दिन में किसी खाई या झाड़ी में छिपकर।</p>\n<p>जंगल रात में जागता था। झींगुरों की न थमने वाली झनकार, पत्तों के नीचे सरसराते कीड़े-पतंगे, दूर कहीं किसी उल्लू की भारी पुकार। एक बार झाड़ियों में कोई बड़ा जानवर खड़-खड़ करता हुआ गुज़रा, और पाँचों पत्थर बन गए। अँधेरे में उसकी आँखें दो पल चमकीं, फिर वह भी चला गया।</p>\n<p>तीसरे दिन पाँचों सरहद पार कर चुके थे।</p>\n<p>कैंप ढलान के नीचे था, घने बाँस के पीछे, जहाँ एक छोटी नदी बगल से गुज़रती थी। नदी की आवाज़ इतनी लगातार थी कि दूर से कोई कुछ और सुन ही नहीं सकता था। और कैंप के पीछे एक जेनरेटर घरघराता रहता था, जिसकी धीमी गूँज रात भर पूरे जंगल में फैली रहती।</p>\n<p>नदी रात में किसी पुरानी, अनथक साँस की तरह बहती थी—पत्थरों से टकराती, मोड़ों पर गहराती, और अपनी ही आवाज़ में हर दूसरी आवाज़ को डुबोती हुई।</p>\n<p>विक्रम सब गिनता गया।</p>\n<p>पहरेदार कहाँ खड़े होते हैं। कब बदलते हैं। किस झोंपड़ी में रोशनी देर तक रहती है। कौन-सी झोंपड़ी में कभी कोई नहीं जाता।</p>\n<p>चौथे दिन उसे ऐसी चीज़ दिखी जो किसी रिपोर्ट में नहीं थी।</p>\n<p>रात के दो बजे जेनरेटर बंद हो जाता था। डीज़ल बचाने के लिए। ठीक दो बजे।</p>\n<p>उसके बाद करीब बीस मिनट पूरे कैंप में अँधेरा रहता, और पहरेदार जागने की जगह बीड़ी सुलगाने बैठ जाते।</p>\n<p>हवलदार थापा ने उसकी तरफ देखा, और विक्रम ने बस एक उँगली उठाई।</p>\n<p>यही बीस मिनट।</p>\n<p>पाँचवें दिन बारिश आई, और पूरा जंगल एक साथ बोल पड़ा—पत्तों पर बूँदों की थाप, मेंढकों की गूँजती टर्र-टर्र, नदी का और भारी होता स्वर। बारिश की आड़ में उसने ख़ुद नदी का किनारा नापा—कहाँ पानी घुटनों तक है, कहाँ कमर तक, कहाँ पत्थर चिकने हैं।</p>\n<p>छठे दिन वह सबसे पास तक गया।</p>\n<p>पूरा दिन ठंडी, गँदली खाई में पड़ा रहा। एक जोंक कलाई तक चढ़ आई। उसने हटाई नहीं। दोपहर में पत्तों पर एक पतला हरा साँप सरकता आया और उसकी बाँह के ऊपर से गुज़र गया, ठंडा और बेआवाज़। विक्रम ने पलक तक नहीं झपकाई। थोड़ी दूर एक पहरेदार बैठा था, इतना पास कि उसकी साँस सुनाई देती थी। एक बार उसके बूट की नोक विक्रम के हाथ से बस दो इंच दूर रही।</p>\n<p>विक्रम की साँस रुकी रही।</p>\n<p>उस पल उसे ट्रेन की खिड़की की याद आई। प्लेटफॉर्म पर उठा एक हाथ, जो हिल नहीं रहा था, बस उठा रहा।</p>\n<p><i>जो भी हो, मैं वापस आऊँगा।</i></p>\n<p>पहरेदार उठा। आगे बढ़ गया।</p>\n<p>उस रात विक्रम ने पूरा नक़्शा एक पत्थर पर कोयले से खींच दिया।</p>\n<p>पाँच झोंपड़ियाँ। दो पहरेदार-चौकियाँ। एक डिपो। और बीच की सबसे बड़ी झोंपड़ी, जहाँ वह इंसान सोता था।</p>\n<p>पाँच निशाने।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>अगले पंद्रह दिन—</p>\n<p>कुछ नहीं।</p>\n<p>विक्रम के आख़िरी फोन के अगले दिन नैना ने विक्रम का नंबर मिलाया।</p>\n<p>नैना को हमेशा की तरह घंटी सुनाई देने की उम्मीद थी।</p>\n<p>मगर दूसरी तरफ न घंटी थी, न कोई आवाज़।</p>\n<p>एक ऐसी चुप्पी जो कुछ नहीं बताती।</p>\n<p>अगले दिन उसने फिर फोन किया।</p>\n<p>फिर उसके अगले दिन।</p>\n<p>हर बार वही खालीपन।</p>\n<p>अगर सिर्फ नेटवर्क नहीं था तो वह इंतज़ार कर सकती थी।</p>\n<p>अगर कोई ऑपरेशन था तो भी।</p>\n<p>मुश्किल सिर्फ इतनी थी कि उसे पता ही नहीं था कि वह किस बात का इंतज़ार कर रही है।</p>\n<p>पाँचवें दिन तक खाना सामने रखा रहता और आधा भी ख़त्म नहीं होता।</p>\n<p>आठवें दिन तक नींद कुछ घंटों की चीज़ नहीं रही थी। वह छोटे-छोटे टुकड़ों में आती—और हर थोड़ी देर बाद नैना इस यकीन के साथ जाग जाती कि उसका फोन बजा है।</p>\n<p>फोन नहीं बजा होता।</p>\n<p>विक्रम की आख़िरी बात बार-बार भीतर लौटती—</p>\n<p><b>जो भी हो, याद रखना। मैं वापस आऊँगा।</b></p>\n<p>जिस वक्त उसने कहा था, वह एक भरोसा था।</p>\n<p>दिन गुज़रते गए तो वही शब्द नैना के सीने में कहीं अटक गए।</p>\n<p>बारहवीं शाम उसने रसोई में दो बार गैस जलाई और दोनों बार बिना कुछ पकाए बंद कर दी।</p>\n<p>फ्लैट में अजीब-सी ख़ामोशी थी।</p>\n<p>दो हफ्तों से उस जगह से वह एक आवाज़ गायब थी जिसकी नैना को आदत हो चुकी थी।</p>\n<p>बाहर सड़क की आवाज़ उस ऊँचाई तक नहीं आ रही थी। पंखा बंद था। कमरे में सिर्फ रसोई की घड़ी की लगातार टिक-टिक थी और अपनी ही साँसें, जो उस रात उसे ज़रूरत से ज़्यादा सुनाई दे रही थीं।</p>\n<p>नैना अपनी छोटी-सी मेज़ के सामने बैठ गई।</p>\n<p>सामने एक खाली काग़ज़ रखा था।</p>\n<p>टेबल लैम्प की रोशनी सिर्फ उस काग़ज़ तक सीमित थी; बाकी कमरा लगभग अँधेरे में था।</p>\n<p>रोशनी का वह गोल घेरा उस रात पूरी दुनिया था, और उसके बाहर अँधेरे में विक्रम कहीं था, जिसे वह देख नहीं सकती थी।</p>\n<p>कुछ देर वह यूँ ही बैठी रही।</p>\n<p>फिर जाने किस ख़याल से उसकी नज़र उस छोटी ब्लेड पर गई जिससे वह पेंसिलें छीलती थी।</p>\n<p>उसने उसे उठा लिया।</p>\n<p>अँगूठे के पोर पर बहुत हल्का-सा दबाया।</p>\n<p>फिर कलम उठाई।</p>\n<p>और काग़ज़ पर तीन पंक्तियाँ लिखीं—</p>\n<p><i>I am waiting.</i></p>\n<p><i>You promised me you will come back.</i></p>\n<p><i>Come back alive, Vikram.</i></p>\n<p>मैं इंतज़ार कर रही हूँ।</p>\n<p>तुमने वादा किया है कि लौटोगे।</p>\n<p>ज़िंदा लौटना, विक्रम।</p>\n<p>तीसरी पंक्ति तक पहुँचते-पहुँचते खून इतना हल्का पड़ चुका था कि आगे उससे कुछ लिखा नहीं जा सकता था।</p>\n<p>नैना ने दोबारा अँगूठा नहीं काटा।</p>\n<p>बस ब्लेड एक तरफ रख दी।</p>\n<p>लिफाफे के ऊपर विक्रम का नाम और उसकी यूनिट का पता साधारण स्याही से लिखा—साफ़, सीधी लिखावट में; इतनी सँभली हुई कि बाहर से देखने वाला अंदाज़ा भी नहीं लगा सकता था कि अंदर रखे काग़ज़ तक पहुँचते-पहुँचते वही हाथ कितना काँपा था।</p>\n<p>उसी रात उसने खत पोस्ट कर दिया।</p>\n<p>लाल डिब्बे में लिफाफा गिरने की हल्की-सी आवाज़ आई, और नैना को लगा जैसे उसने अपना कुछ हिस्सा भी साथ गिरा दिया हो।</p>\n<p>उसे यह तक नहीं मालूम था कि वह विक्रम तक पहुँचेगा भी या नहीं।</p>\n<p>फिर भी भेज दिया।</p>\n<p>उस वक्त पहुँचने से ज़्यादा ज़रूरी यह था कि वे तीन पंक्तियाँ अब सिर्फ उसके भीतर न रहें।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>सातवीं शाम सूरज ढलते ही विक्रम ने पहली बार रेडियो चालू किया।</p>\n<p>दो वाक्य, फुसफुसाहट से भी धीमी आवाज़ में।</p>\n<p>“निर्देशांक भेज रहा हूँ। टीम को वहीं उतारिए।”</p>\n<p>और रेडियो फिर बंद।</p>\n<p>घना जंगल था। हेलिकॉप्टर के उतरने की जगह ही नहीं थी। इसलिए वह कैंप से कई किलोमीटर दूर, पेड़ों की चोटियों के ठीक ऊपर, हवा में ठहर गया—बिना रोशनी, बस उसके पंखों की धीमी थरथराहट।</p>\n<p>रस्सियाँ नीचे गिरीं।</p>\n<p>और 9 पैरा एसएफ़ के बारह कमांडो एक-एक करके उन पर फिसलते हुए अँधेरे जंगल में उतर गए। आख़िरी के ज़मीन छूते ही रस्सियाँ ऊपर खिंच गईं, और हेलिकॉप्टर उतनी ही चुपचाप दूर होता गया।</p>\n<p>नीचे जंगल ने उन्हें निगल लिया—नम मिट्टी, सड़े पत्तों की गंध, और ऊपर कहीं बंदरों की अचानक जागी बेचैन चीख, जो कुछ पल में फिर थम गई।</p>\n<p>इसके बाद फिर वही पैदल रास्ता। दो घंटे, नदी के मोड़ तक।</p>\n<p>विक्रम वहाँ पहले से इंतज़ार कर रहा था।</p>\n<p>किसी ने कुछ नहीं कहा।</p>\n<p>उसने नदी किनारे के एक चपटे पत्थर की तरफ इशारा किया। कोयले की लकीरें टॉर्च की ढकी हुई हल्की रोशनी में उभर आईं।</p>\n<p>उसकी उँगली एक-एक निशाने पर रुकी। हर निशाने के साथ एक टुकड़ी का इशारा।</p>\n<p>पहली टुकड़ी, दोनों चौकियाँ। दूसरी, डिपो। तीसरी, झोंपड़ियाँ। और बीच की सबसे बड़ी झोंपड़ी—</p>\n<p>उसने अपनी छाती पर हाथ रखा।</p>\n<p>“दो बजे जेनरेटर बंद होगा।”</p>\n<p>फुसफुसाहट से भी धीमी आवाज़।</p>\n<p>“उसके पहले कोई गोली नहीं। जब तक मैं इशारा न दूँ, कोई नहीं।”</p>\n<p>“जी, सर।”</p>\n<p>“सिर्फ निशाने। एक भी गोली फ़ालतू नहीं।”</p>\n<p>फिर कुछ पल रुककर—</p>\n<p>“एक भी इंसान पीछे नहीं छूटेगा।”</p>\n<p>इस बार कोई जवाब नहीं आया।</p>\n<p>ज़रूरत भी नहीं थी।</p>\n<p>नदी पार करना सबसे लंबा काम था। पानी बर्फ़-सा ठंडा था और चारों तरफ सिर्फ उसकी आवाज़। हर कदम पर पैर जमाना पड़ता। विक्रम सबसे आगे चला, एक हाथ में रस्सी का सिरा।</p>\n<p>सब अपनी-अपनी जगह पहुँच गए।</p>\n<p>फिर इंतज़ार।</p>\n<p>इंतज़ार में जंगल की आवाज़ें और साफ़ सुनाई देने लगीं—झींगुरों की झनकार, नदी की गूँज, और कहीं दूर किसी जानवर की कराहती-सी पुकार।</p>\n<p>दो बजकर एक मिनट पर जेनरेटर की गूँज अचानक थम गई।</p>\n<p>पूरा कैंप एक साँस में अँधेरे में डूब गया।</p>\n<p>और जो आवाज़ें अब तक उसकी घरघराहट के नीचे दबी थीं, एक साथ ऊपर आ गईं—झींगुर, नदी, पत्तों की सरसराहट। जैसे पूरा जंगल कैंप के अँधेरे में उतर आया हो।</p>\n<p>पहरेदार की बीड़ी की लाल नोक हवा में चमकी।</p>\n<p>विक्रम पहले ही उसके पीछे था।</p>\n<p>एक हाथ, एक पल, और बीड़ी ज़मीन पर गिरकर बुझ गई। पहरेदार बिना आवाज़ के नीचे बैठ गया।</p>\n<p>उसने हाथ उठाया।</p>\n<p>एक इशारा।</p>\n<p>और सब कुछ एक साथ हुआ—</p>\n<p>दोनों चौकियों पर एक ही पल में दो चिंगारियाँ चमकीं। डिपो की तरफ से बस एक धीमी, दबी आवाज़ आई। झोंपड़ियों के दरवाज़ों पर एक-एक जवान पहुँचकर रुक गया।</p>\n<p>कैंप में किसी को सँभलने का वक्त ही नहीं मिला।</p>\n<p>विक्रम बीच की झोंपड़ी के दरवाज़े पर था।</p>\n<p>भीतर से किसी ने उठते हुए कुछ कहा।</p>\n<p>दरवाज़ा खुला।</p>\n<p>कुछ पल बाद वह इंसान जो हर महीने किसी गाँव को जलाता था, फर्श पर था।</p>\n<p>बाहर कहीं हवलदार थापा की चीख आई। एक गोली उसकी जाँघ को चीरती निकली थी।</p>\n<p>विक्रम बिना रुके उसके पास पहुँचा और उसे कंधे पर लाद लिया।</p>\n<p>“सर, मुझे छोड़िए—”</p>\n<p>“चुप।”</p>\n<p>बस इतना।</p>\n<p>दो मिनट बाद डिपो में विस्फोट हुआ।</p>\n<p>आधा जंगल पल भर के लिए दिन जैसा रोशन हो गया। पेड़ों पर सोए पक्षी चीखते हुए एक साथ उड़े, और फड़फड़ाते पंखों का शोर कुछ पल तक नदी की आवाज़ से भी ऊँचा रहा। फिर आग की लाल लपटें और धुएँ का काला पर्दा।</p>\n<p>“निकलो!”</p>\n<p>टीम पीछे हटी। एक-एक करके, गिनती के साथ।</p>\n<p>विक्रम ने थापा को कंधे पर लिए नदी में उतरकर आख़िरी बार गिनती पूरी की।</p>\n<p>सब थे।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>भोर से ठीक पहले वे सरहद के इस तरफ लौट आए। पूरब में आसमान राख-सा हल्का पड़ रहा था, और जंगल पहली चिड़ियों की पुकार से धीरे-धीरे जाग रहा था—जैसे रात भर कुछ हुआ ही न हो।</p>\n<p>थापा को मेडिकल टेंट तक पहुँचाया गया। डॉक्टर ने उसकी जाँघ की चोट देखी और कहा कि वह बच जाएगा।</p>\n<p>कर्नल पास आए।</p>\n<p>“पूरा कैंप ख़त्म। डिपो भी। कोई नहीं खोया।”</p>\n<p>एक पल रुके।</p>\n<p>फिर बोले—</p>\n<p>“सात दिन सही कहे थे तुमने।”</p>\n<p>विक्रम ने कुछ नहीं कहा।</p>\n<p>उसने अपने हाथ देखे। हथेली पर कोयले की काली लकीरें अब भी बची थीं।</p>\n<p>उसकी जेब में फोन चुप पड़ा था। यहाँ सिग्नल नहीं आता था।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>पंद्रहवें दिन फोन आया।</p>\n<p>स्क्रीन पर विक्रम का नाम देखते ही नैना एक पल उसे देखती रह गई।</p>\n<p>पंद्रह दिन बाद उस नाम से कमरे की रोशनी जैसे थोड़ी बढ़ गई।</p>\n<p>फिर फोन उठाया।</p>\n<p>विक्रम ने नैना को कुछ पूछने का मौका नहीं दिया।</p>\n<p>“मैं ठीक हूँ।”</p>\n<p>नैना की साँस वहीं अटक गई।</p>\n<p>“एक खरोंच तक नहीं है। बिल्कुल ठीक हूँ।”</p>\n<p>नैना ने पंद्रह दिन से जो कुछ भीतर कसकर पकड़ रखा था, विक्रम की आवाज़ सुनते ही वह ढीला पड़ गया।</p>\n<p>नैना कुछ नहीं बोल पाई।</p>\n<p>विक्रम भी चुप रहा।</p>\n<p>दोनों तरफ सिर्फ साँसें थीं।</p>\n<p>लेकिन पंद्रह दिनों में पहली बार ख़ामोशी का मतलब डर नहीं था।</p>\n<p>कुछ देर बाद विक्रम बोला—</p>\n<p>“मुझे तुम्हें बताना है क्या हुआ था।”</p>\n<p>नैना ने आँखें बंद कर लीं।</p>\n<p>“बोलो।”</p>\n<p>“रिपोर्ट करते ही म्यांमार बॉर्डर भेज दिया गया। वहाँ सिग्नल नहीं था, और संपर्क की इजाज़त भी नहीं।”</p>\n<p>वह रुका।</p>\n<p>“मैं इतना भी नहीं बता पाया कि कुछ दिन फोन नहीं होगा।”</p>\n<p>नैना अब भी कुछ नहीं बोली।</p>\n<p>“सॉरी।”</p>\n<p>“तुम्हारी ग़लती नहीं थी।”</p>\n<p>“पता है।”</p>\n<p>विक्रम की आवाज़ धीमी हो गई।</p>\n<p>“फिर भी मुझे पता है उन दिनों ने तुम्हारे साथ क्या किया होगा… जब तुम्हें इनमें से कुछ भी मालूम नहीं था।”</p>\n<p>नैना ने बहुत देर बाद साँस छोड़ी।</p>\n<p>“अब तुम ठीक हो।”</p>\n<p>“हाँ।”</p>\n<p>उस वक्त उसके लिए बस इतना ही काफी था।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>खत विक्रम तक उसके सात दिन बाद पहुँचा।</p>\n<p>आर्मी पोस्ट अपनी ही रफ्तार से रास्ते तय करती थी। जब तक वह लिफाफा उसके हाथ में आया, विक्रम जान चुका था कि नैना ठीक है और नैना जान चुकी थी कि वह सुरक्षित है।</p>\n<p>दोपहर ढल रही थी।</p>\n<p>विक्रम मेस के बाहर खड़ा था जब उसने लिफाफा खोला।</p>\n<p>काग़ज़ खुलते ही विक्रम की नज़र उन हल्की जंग-सी भूरी पड़ चुकी पंक्तियों पर गई।</p>\n<p>पहली पंक्ति पूरी पढ़ने से पहले ही वह समझ गया कि वह क्या देख रहा है।</p>\n<p>उसका हाथ स्थिर हो गया।</p>\n<p>उसने तीनों पंक्तियाँ पढ़ीं।</p>\n<p>फिर दोबारा।</p>\n<p>काग़ज़ पकड़े विक्रम की मुट्ठी भिंच गई।</p>\n<p>फिर अपने ही ऊपर एक बेबस गुस्सा उठा।</p>\n<p>इतने दिन वह उससे संपर्क नहीं कर सकता था।</p>\n<p>उसमें उसकी कोई ग़लती नहीं थी।</p>\n<p>वह कुछ अलग कर भी नहीं सकता था।</p>\n<p>मगर इन सारी सच्चाइयों से उस तस्वीर में कुछ नहीं बदल रहा था जो अब उसके दिमाग में बन चुकी थी—नैना अकेली, सामने खाली काग़ज़, हाथ में ब्लेड, और वह ख़ुद उससे इतनी दूर कि उसे यह तक बताने का कोई रास्ता नहीं कि वह ज़िंदा है।</p>\n<p>विक्रम अपने शरीर पर लगी कोई चोट ज़्यादा आसानी से सह लेता।</p>\n<p>यह बेबसी उससे कहीं ज़्यादा भारी थी।</p>\n<p>विक्रम ने उसी शाम फोन किया।</p>\n<p>आवाज़ जितनी सामान्य रखना चाहता था, उतनी रही नहीं।</p>\n<p>“तुम्हारा खत मिला।”</p>\n<p>दूसरी तरफ कुछ पल चुप्पी रही।</p>\n<p>“अच्छा।”</p>\n<p>“नैना…”</p>\n<p>विक्रम ने काग़ज़ फिर देखा।</p>\n<p>“तुमने इसे खून से लिखा है।”</p>\n<p>नैना ने कुछ नहीं कहा।</p>\n<p>“ख़ुद को चोट क्यों पहुँचाई?”</p>\n<p>“चोट नहीं थी।”</p>\n<p>जवाब ज़रूरत से ज़्यादा जल्दी आया।</p>\n<p>फिर नैना ने ख़ुद ही बात ठीक की—</p>\n<p>“मतलब… शरीर वाली चोट नहीं। बस हल्की-सी चुभन थी। लगभग कुछ भी नहीं।”</p>\n<p>“फिर क्यों?”</p>\n<p>इस बार नैना काफी देर चुप रही।</p>\n<p>जब बोली तो उसकी आवाज़ में वह तेज़ी नहीं थी जो अक्सर मुश्किल बातों के सामने उसकी ढाल बन जाती थी।</p>\n<p>“क्योंकि जो दर्द था वो कहीं और था, विक्रम।”</p>\n<p>उसने साँस ली।</p>\n<p>“पंद्रह दिन तक ये न जानना कि तुम कहाँ हो, कैसे हो, ज़िंदा हो भी या…”</p>\n<p>वाक्य वहीं रुक गया।</p>\n<p>वह शब्द नैना से नहीं बोला गया।</p>\n<p>“वो तकलीफ़ उस छोटी-सी ब्लेड से कहीं ज़्यादा थी। शायद उस रात मुझे लगा कि जो भीतर हो रहा है उसका थोड़ा-सा निशान बाहर भी दिखाई देना चाहिए।”</p>\n<p>वह ख़ुद भी जैसे अपनी बात समझने की कोशिश कर रही थी।</p>\n<p>“ठीक से समझा नहीं सकती। शायद कुछ चीज़ें समझाने बैठो तो और ग़लत लगने लगती हैं।”</p>\n<p>उसकी आवाज़ टूट गई।</p>\n<p>और फिर नैना रोई।</p>\n<p>अँगूठे की उस मामूली चुभन के लिए नहीं।</p>\n<p>उन पंद्रह दिनों के लिए।</p>\n<p>हर उस रात के लिए जब फोन नहीं बजा।</p>\n<p>हर उस सुबह के लिए जब उसने ख़ुद को समझाया कि आज ख़बर आएगी।</p>\n<p>हर उस पल के लिए जब उसके पास डर था, मगर उसे रखने के लिए कोई दूसरा कंधा नहीं।</p>\n<p>विक्रम फोन पर रहा।</p>\n<p>बहुत कम बोला।</p>\n<p>दूरी के उस पार वह उसे बाँहों में नहीं भर सकता था, उसके बालों पर हाथ नहीं फेर सकता था, उसके पास बैठ नहीं सकता था।</p>\n<p>उस रात उसकी आवाज़ ही वह एक चीज़ थी जो वह नैना को दे सकता था।</p>\n<p>इसलिए वह वहीं रहा।</p>\n<p>जब तक उसका रोना धीरे-धीरे थमा नहीं।</p>\n<p>जब तक साँसें फिर बराबर नहीं हुईं।</p>\n<p>काफी देर बाद नैना बोली—</p>\n<p>“अब ठीक हूँ।”</p>\n<p>फिर कुछ पल रुककर—</p>\n<p>“बस तुम्हें पता होना चाहिए था कि वो पंद्रह दिन असल में कैसे थे। वो वाला जवाब नहीं जो मैं किसी और को देती।”</p>\n<p>उसकी आवाज़ बहुत धीमी थी।</p>\n<p>“सच वाला।”</p>\n<p>विक्रम ने आँखें बंद कर लीं।</p>\n<p>“अब पता है।”</p>\n<p>विक्रम के हाथ में अब भी वही काग़ज़ था।</p>\n<p>“और भूलूँगा नहीं।”</p>\n<p>कुछ पल बाद उसने कहा—</p>\n<p>“न खत।”</p>\n<p>फिर बहुत धीरे—</p>\n<p>“न ये कि उसे लिखने की कीमत तुम्हें क्या देनी पड़ी।”</p>\n<p>फोन रखने के बाद विक्रम ने काग़ज़ को बहुत सावधानी से तह किया।</p>\n<p>इतना छोटा कि उसकी वर्दी की छाती वाली जेब में आ जाए।</p>\n<p>वही जेब जिसमें कभी रेड्डी एक तस्वीर रखा करता था—किनारों से घिस चुकी उस लड़की की तस्वीर, जिसकी शादी कभी नहीं हो पाई और जिससे किया गया वादा कभी पूरा नहीं हुआ।</p>\n<p>विक्रम ने उस ख़याल को पूरा होने नहीं दिया।</p>\n<p>विक्रम ने नैना का खत जेब में रखा।</p>\n<p>फ्लैप बंद किया।</p>\n<p>और हथेली कुछ पल वहीं ठहरी रही, जैसे किसी वादे पर हाथ रखा हो।</p>"}, {"chapter": 21, "title": "अध्याय 19 — चार दिन, एक घर", "content": "<h1>अध्याय 19 — चार दिन, एक घर</h1>\n<p>म्यांमार बॉर्डर की उस ख़ामोश तैनाती के करीब दो महीने बाद विक्रम को अगली छुट्टी मिली।</p>\n<p>इस बार सिर्फ चार दिन।</p>\n<p>मगर पंद्रह दिनों की उस ख़ामोशी के बाद चार दिन भी किसी दौलत से कम नहीं लग रहे थे।</p>\n<p>नैना उसे लेने दिल्ली एयरपोर्ट पहुँची।</p>\n<p>पिछली विदाई वाले रेलवे प्लेटफॉर्म की घबराहट इस बार उसके चेहरे पर नहीं थी। विक्रम अराइवल गेट से बाहर निकला ही था—एक कंधे पर डफल बैग अब भी टँगा हुआ—कि नैना सीधे उसके पास गई और दोनों बाँहें उसकी गर्दन के चारों तरफ डाल दीं।</p>\n<p>सामान्य मुलाक़ात में जितनी देर कोई किसी को थामता है, उससे थोड़ी देर ज़्यादा वह उसी तरह उससे लगी रही।</p>\n<p>“तुम सच में यहाँ हो।”</p>\n<p>नैना की आवाज़ विक्रम के कंधे के पास दब गई।</p>\n<p>“हर बार तुम्हें देखकर पहले ख़ुद को यकीन दिलाना पड़ता है।”</p>\n<p>“यहाँ हूँ।”</p>\n<p>विक्रम मुस्कराया।</p>\n<p>“पूरे चार दिन।”</p>\n<p>नैना उससे अलग हुई।</p>\n<p>“चार दिन जिन्हें मैं सोने की तरह बचाकर रखने वाली हूँ।”</p>\n<p>नैना का फ्लैट विक्रम के लिए नया नहीं था। वह इसमें पहले भी आ चुका था।</p>\n<p>दो बेडरूम का वह छोटा-सा फ्लैट था—एक तरफ छोटा लिविंग रूम और किचनेट, एक कमरा नैना का और दूसरा छोटा कमरा जो अब ज़्यादातर सामान रखने के काम आता था। नैना को वहाँ रहते काफी वक्त हो चुका था और अब उस घर की हर चीज़ पर उसकी अपनी छाप थी।</p>\n<p>विक्रम का बैग छोटे कमरे के कोने में रखा था—बस पहली शाम तक; फिर वह उसे उठाकर बादशाहपुर अपने घर चला गया। नैना का फ्लैट उसके लिए दिन भर का ठिकाना था, रात का नहीं।</p>\n<p>पहले ही दिन उसने ख़ुद को रसोई की अलमारी से बिना पूछे गिलास निकालते पाया।</p>\n<p>सुबह वह बादशाहपुर से पहुँचता तो नैना पूछती नहीं—दो कप चाय बना देती।</p>\n<p>सुबह की धूप में दोनों कप की भाप एक-दूसरे में मिल जाती, जैसे वे हमेशा से वहीं रखे जाते रहे हों।</p>\n<p>नैना बर्तन धोती तो विक्रम पास खड़ा उन्हें पोंछकर रख देता। किसका काम क्या है, इस पर कोई बात नहीं हुई; दूसरी सुबह तक यही उनका तरीका बन गया था।</p>\n<p>दूसरी शाम नैना ने ठीक से खाना बनाया।</p>\n<p>अपनी माँ से सीखी हुई पनीर की सब्ज़ी, जिसे वह अकेले अपने लिए बनाने की मेहनत शायद ही कभी करती थी।</p>\n<p>विक्रम किचन के पास खड़ा उसे काम करते देख रहा था।</p>\n<p>“इतना सब करने की ज़रूरत नहीं थी।”</p>\n<p>नैना ने पलटकर उसे देखा।</p>\n<p>“ज़रूरत नहीं थी।”</p>\n<p>फिर वापस कड़ाही की तरफ मुड़ गई।</p>\n<p>“मन था।”</p>\n<p>“फ़र्क़?”</p>\n<p>“बहुत।”</p>\n<p>नैना ने चम्मच चलाते हुए कहा—</p>\n<p>“भूख लगी हो इसलिए खाना बनाना अलग बात है। किसी को कुछ ऐसा खिलाना हो जिस पर तुम्हें ख़ुद थोड़ा गर्व हो, वो अलग।”</p>\n<p>दोनों ने फर्श पर पालथी मारकर खाना खाया। प्लेटें घुटनों पर थीं और पीछे टीवी पर कोई पुरानी हिंदी फिल्म धीमी आवाज़ में चल रही थी।</p>\n<p>छोटे-से फ्लैट में ताज़े बने खाने की गर्म महक थी।</p>\n<p>और पहली बार उस महक में किसी के आने का इंतज़ार नहीं, किसी के होने का सुकून था।</p>\n<p>विक्रम ने दूसरी बार सब्ज़ी लेते हुए कहा—</p>\n<p>“इसकी आदत पड़ सकती है।”</p>\n<p>नैना ने तुरंत उसकी तरफ देखा।</p>\n<p>“ये सिर्फ पनीर की तारीफ है तो अभी साफ़ कर दो।”</p>\n<p>विक्रम हँसा।</p>\n<p>“पनीर से ज़्यादा की बात कर रहा हूँ।”</p>\n<p>नैना एक पल उसे देखती रही।</p>\n<p>“अच्छा है।”</p>\n<p>नैना ने अपनी प्लेट में नज़र झुका ली, मगर चेहरे पर आती मुस्कान छिपी नहीं।</p>\n<p>“क्योंकि मैंने सोचना शुरू कर दिया है कि इससे दोगुनी बड़ी किचन कैसी लगेगी।”</p>\n<p>विक्रम का हाथ एक पल के लिए रुक गया।</p>\n<p>नैना ने सहजता से आगे कहा—</p>\n<p>“और उसमें ठीक-ठाक कुर्सियाँ होंगी। हर बार फर्श पर नहीं बैठना पड़ेगा।”</p>\n<p>विक्रम अब भी उसे देख रहा था।</p>\n<p>नैना ने उसकी नज़र पकड़ ली।</p>\n<p>“क्या?”</p>\n<p>“कुछ नहीं।”</p>\n<p>“ऐसे मत देखो।”</p>\n<p>“कैसे?”</p>\n<p>“जैसे मैंने कुछ बहुत बड़ा बोल दिया।”</p>\n<p>विक्रम मुस्कराया।</p>\n<p>नैना ने रोटी का टुकड़ा तोड़ा।</p>\n<p>“मैं उन चीज़ों की कल्पना नहीं करती जिन्हें चाहती नहीं हूँ।”</p>\n<p>इस बार विक्रम ने कुछ नहीं कहा।</p>\n<p>कहने की ज़रूरत भी नहीं थी।</p>\n<p>तीसरे दिन की दोपहर दोनों सोफे पर बैठे थे।</p>\n<p>कहीं जाने का कोई कार्यक्रम नहीं था।</p>\n<p>दरवाज़े पर दस्तक हुई।</p>\n<p>नैना ने भौंहें सिकोड़कर देखा।</p>\n<p>“मैं किसी को एक्सपेक्ट नहीं कर रही।”</p>\n<p>दरवाज़ा खोला तो सामने उसकी छोटी बहन खड़ी थी—चेहरे पर ऐसी मुस्कान जैसे किसी को बिना बताए पहुँच जाना अपने-आप में कोई बड़ी जीत हो।</p>\n<p>“सुनैना?”</p>\n<p>नैना उसे देखती रह गई।</p>\n<p>“तुम यहाँ क्या—”</p>\n<p>“सीधे एयरपोर्ट से आ रही हूँ। घर पर किसी को नहीं बताया—न माँ को, न पापा को। आज तुम्हारे यहाँ रुकूँगी, कल घर जाकर ऐसे पहुँचूँगी जैसे अभी-अभी लैंड हुई हूँ।”</p>\n<p>बिना बाकायदा बुलाए वह अंदर आ गई।</p>\n<p>फिर सुनैना की नज़र सोफे से उठते विक्रम पर पड़ी।</p>\n<p>कदम वहीं रुक गए।</p>\n<p>“ओह।”</p>\n<p>नैना अब भी दरवाज़े के पास खड़ी थी।</p>\n<p>“तुमने बताया क्यों नहीं कि आ रही हो?”</p>\n<p>“क्योंकि सरप्राइज़ देना था।”</p>\n<p>सुनैना ने फिर विक्रम को देखा।</p>\n<p>“हालाँकि लगता है सरप्राइज़ दोनों तरफ हो गया।”</p>\n<p>सुनैना उसे बिना किसी झिझक के देख रही थी—ठीक उसी सीधेपन से जो नैना में भी था; सुनैना के भीतर उसका थोड़ा ज़्यादा शरारती रूप था।</p>\n<p>“आप ही हैं,” सुनैना ने कहा।</p>\n<p>विक्रम ने हाथ आगे बढ़ाया।</p>\n<p>“विक्रम।”</p>\n<p>फिर मुस्कराया।</p>\n<p>“और तुम वही बहन हो जिसके बारे में काफी कुछ सुन चुका हूँ।”</p>\n<p>सुनैना ने हाथ मिलाया। अब वह विक्रम को ठीक से देख रही थी—उसकी लंबाई, कंधों की बनावट, चेहरे की मजबूत, साफ़ रेखाएँ। एक पल के लिए सुनैना के चेहरे पर कुछ आया—तेज़, अनचाहा—और उतनी ही जल्दी गायब भी हो गया।</p>\n<p>“उम्मीद है ज़्यादातर अच्छा।”</p>\n<p>“ज़्यादातर,” नैना ने पीछे से कहा।</p>\n<p>सुनैना ने बहन की तरफ देखा।</p>\n<p>“सिर्फ ज़्यादातर?”</p>\n<p>“पहले फोन करना सीखो, फिर बाकी तारीफें मिलेंगी।”</p>\n<p>“फोन कर देती तो ये सब कैसे पता चलता?”</p>\n<p>सुनैना आर्मचेयर पर ऐसे बैठ गई जैसे पिछले कई महीनों से वहीं रह रही हो।</p>\n<p>नैना भी वापस सोफे पर आ गई।</p>\n<p>“बेडफोर्डशायर कैसा चल रहा है?”</p>\n<p>सुनैना के होंठों पर शरारती मुस्कान आई।</p>\n<p>“आयरनी से भरा हुआ।”</p>\n<p>“मतलब?”</p>\n<p>“मेरी मेन क्लास में चालीस स्टूडेंट हैं। पच्चीस इंडियन, पाँच पाकिस्तानी, चार बांग्लादेशी, तीन श्रीलंकन, दो नेपाली…”</p>\n<p>सुनैना ने नाटकीय विराम लिया।</p>\n<p>“और एक ब्रिटिश।”</p>\n<p>विक्रम हँस पड़ा।</p>\n<p>“बेचारा।”</p>\n<p>“वही तो। ग्रुप प्रोजेक्ट में जब कोई समोसे लेकर आता है तो सबसे ज़्यादा कन्फ्यूज़ वही दिखता है। कई बार भूल जाती हूँ कि मैं इंग्लैंड में हूँ। पूरा सबकॉन्टिनेंट बैठा है—बस ब्रिटिश राज गायब है और उसकी जगह एक बेचारा असली ब्रिटिश लड़का बैठा है।”</p>\n<p>तीनों हँसे।</p>\n<p>मगर सुनैना की हँसी कुछ ही क्षण में हल्की पड़ गई।</p>\n<p>“वैसे मज़ाक से हटकर सोचो तो बात दिलचस्प है।”</p>\n<p>नैना ने उसकी तरफ देखा।</p>\n<p>“पूरे देशों की डेमोग्राफी धीरे-धीरे बदलती रहती है। क्लासरूम में छोटी बात लगती है, मगर बीस-तीस साल बाद वही चीज़ पॉलिटिक्स बदल देती है—कौन वोट करता है, किसकी नुमाइंदगी होती है।”</p>\n<p>वह एक पल रुकी।</p>\n<p>“मुझे नहीं लगता ब्रिटेन ने अभी ठीक से सोचा है कि लंबे वक्त में इसका मतलब क्या होगा।”</p>\n<p>नैना उसे थोड़ी देर देखती रही।</p>\n<p>नैना की भौंहें ऊपर उठीं और होंठों पर वही मुस्कान आ गई, जो तब आती है जब कोई अपना छोटा अचानक बड़ा निकल आए।</p>\n<p>“तुम इतनी सीरियस कब से हो गई?”</p>\n<p>“हमेशा से थी।”</p>\n<p>सुनैना ने कंधे उचकाए।</p>\n<p>“बस पहले जोक पूरा होने देती हूँ।”</p>\n<p>फिर सुनैना की नज़र नैना और विक्रम के बीच घूमी।</p>\n<p>“वैसे घर में किसी एक को तो बोरिंग मगर ज़रूरी चीज़ों पर सोचना पड़ेगा। तुम दोनों पिछले कुछ महीनों से एक-दूसरे को देखने में इतने बिज़ी हो कि शायद कोई डेमोग्राफिक ट्रेंड नोटिस भी न किया हो।”</p>\n<p>“सुनैना।”</p>\n<p>“क्या? ग़लत बोल रही हूँ?”</p>\n<p>“माँ-पापा को जाकर सुनाना अपना लेक्चर।”</p>\n<p>“उन्हें लगता है जियोपॉलिटिक्स वो चीज़ है जो दूसरे देशों के साथ होती है।”</p>\n<p>इस बार विक्रम हँसी रोक नहीं पाया।</p>\n<p>अगला करीब एक घंटा सुनैना के सवालों में निकल गया।</p>\n<p>सुनैना सवाल पूछती भी ऐसे थी जैसे सिर्फ बातचीत कर रही हो, जबकि असल में सामने वाले को लगातार परख रही होती।</p>\n<p>विक्रम ने किसी जवाब को सजाने की कोशिश नहीं की।</p>\n<p>जो पूछा गया, उसका सीधा जवाब दिया।</p>\n<p>कहीं बातचीत के बीच विक्रम ने सुनैना के चेहरे पर वही बदलाव देखा जो कभी-कभी नैना के चेहरे पर आता था—जैसे भीतर कोई फ़ैसला हो चुका हो और उसे दुनिया के सामने घोषित करने की ज़रूरत न हो।</p>\n<p>कुछ देर बाद विक्रम पानी लेने किचन में गया।</p>\n<p>उसके जाते ही सुनैना अपनी बहन की तरफ झुकी।</p>\n<p>“अच्छा।”</p>\n<p>नैना ने उसे देखा।</p>\n<p>“क्या?”</p>\n<p>“अब समझ आया।”</p>\n<p>“क्या समझ आया?”</p>\n<p>“इतना हल्ला क्यों था।”</p>\n<p>“शुरू मत हो जाना।”</p>\n<p>“कुछ शुरू नहीं कर रही।”</p>\n<p>सुनैना ने आवाज़ थोड़ी और धीमी कर ली।</p>\n<p>“कह रही हूँ—काग़ज़ पर जैसा इंसान तुम चाहतीं, वैसा तो है ही। सामने उससे भी बेहतर है।”</p>\n<p>नैना ने कुछ नहीं कहा।</p>\n<p>“तमीज़ है। दिखावा नहीं करता। हर बात में ख़ुद को साबित करने की कोशिश नहीं करता।”</p>\n<p>सुनैना ने किचन की तरफ एक नज़र डाली।</p>\n<p>“और कम-से-कम दिखता ऐसा है कि ज़रूरत पड़े तो किसी की हिफ़ाज़त कर सके, सिर्फ बातें न करे।”</p>\n<p>“तुमने एक घंटे में पूरा कैरेक्टर सर्टिफिकेट बना दिया?”</p>\n<p>“मैं पत्रकार हूँ। जल्दी फ़ैसला करना पड़ता है।”</p>\n<p>नैना की हँसी निकल गई।</p>\n<p>सुनैना का चेहरा फिर थोड़ा गंभीर हुआ।</p>\n<p>“इसे जाने मत देना, नैना।”</p>\n<p>नैना की मुस्कान हल्की पड़ गई।</p>\n<p>“सीरियसली कह रही हूँ।”</p>\n<p>सुनैना ने उसकी आँखों में देखा।</p>\n<p>“जो भी हो, इसे जाने मत देना।”</p>\n<p>नैना का जवाब सीधा था।</p>\n<p>“इरादा नहीं है।”</p>\n<p>“अच्छा है। वरना मुझे यूके से फोन करके ‘मैंने कहा था’ बोलना पड़ेगा—और इंटरनेशनल कॉल बहुत महँगी पड़ती है।”</p>\n<p>विक्रम पानी लेकर लौट आया और बात वहीं बदल गई।</p>\n<p>विक्रम को पता भी नहीं चला कि उन तीस सेकंड में उसके बारे में एक फ़ैसला हो चुका था।</p>\n<p>सुनैना के आने के बाद छुट्टी के बाकी दिन वैसे नहीं रहे जैसे दोनों ने सोचे थे।</p>\n<p>दो लोगों की शांत दुनिया अचानक तीन लोगों की हो गई।</p>\n<p>डिनर देर तक खिंचता, फिल्म के बीच सुनैना अपनी राय देती रहती, फिर खाने पर भी राय, फिर फिल्म पर दोबारा राय।</p>\n<p>विक्रम सोफे के कोने में बैठा दोनों को देखता रहता—दोनों के बीच की वह पुरानी सहजता, छोटी नोकझोंक, आधी बात पर पूरी बात समझ लेना—और हर नोकझोंक पर उसकी मुस्कान थोड़ी और खिंच जाती।</p>\n<p>शाम तक विक्रम को निकलना पड़ा।</p>\n<p>रात घर पर बितानी थी। घर वाले उसका इंतज़ार कर रहे थे और यह वह ज़िम्मेदारी थी जिसे वह सिर्फ इसलिए टाल नहीं सकता था क्योंकि उसका मन अभी इस फ्लैट से जाने का नहीं था।</p>\n<p>नैना उसे दरवाज़े तक छोड़ने आई।</p>\n<p>“जाओ।”</p>\n<p>“इतनी जल्दी निकाल रही हो?”</p>\n<p>“मेरी बहन को तुम्हारे लिए सवालों का दूसरा सेट तैयार करने का मौका मिलने से पहले।”</p>\n<p>सोफे से सुनैना की आवाज़ आई—</p>\n<p>“सुन रही हूँ।”</p>\n<p>नैना ने बिना पलटे जवाब दिया—</p>\n<p>“सुनाने के लिए ही बोला।”</p>\n<p>विक्रम के होंठों पर हँसी आ गई।</p>\n<p>दरवाज़े पर पहुँचकर उसने एक बार फिर नैना की तरफ देखा।</p>\n<p>“चार दिन वैसे ही कम थे। अब शाम का एक टुकड़ा रास्ते में जाएगा।”</p>\n<p>“और छुट्टियाँ आएँगी।”</p>\n<p>नैना ने यह बात ऐसे कही जैसे सिर्फ उम्मीद नहीं जता रही हो।</p>\n<p>“मैं तब तक ज़ोर-ज़ोर से यही मानती रहूँगी जब तक इसे मानना मेरी मजबूरी न रह जाए।”</p>\n<p>विक्रम ने उसे अपनी बाँहों में लिया।</p>\n<p>इस बार बहुत थोड़ी देर के लिए—अगले कमरे में बैठी सुनैना का ख़याल दोनों को था।</p>\n<p>फिर वह निकल गया।</p>\n<p>सीढ़ियाँ उतरते हुए भी ऊपर से दोनों बहनों की हँसी सुनाई देती रही।</p>\n<p>वह हँसी सीढ़ियों तक उतरती रही, जैसे दो जोड़ी पाँव बिना आवाज़ उसके पीछे-पीछे आ रहे हों।</p>\n<p>उसके भीतर एक शांत-सी गर्माहट थी। दो ऐसी लड़कियाँ, जो अपने-अपने तरीके से उसके लिए मायने रखती थीं, एक ही कमरे में इतनी आसानी से घुल-मिल गई थीं जितनी उसने उम्मीद नहीं की थी।</p>\n<p>कैब में बैठने के बाद फ्लैट की रोशन खिड़की धीरे-धीरे पीछे छूटने लगी। मोड़ पर मुड़ते ही वह अँधेरे में गुम हो गई, जैसे किसी ने परदा गिरा दिया हो।</p>"}, {"chapter": 22, "title": "अध्याय 20 — घर की एक शाम", "content": "<h1>अध्याय 20 — घर की एक शाम</h1>\n<p>बादशाहपुर पहुँचते-पहुँचते अँधेरा हो चुका था। बादशाहपुर गुरुग्राम से बस दस किलोमीटर था, पर शाम की भीड़ ने उसे आधे घंटे से ज़्यादा का बना दिया था। आख़िरी हिस्सा उसी जानी-पहचानी सड़क से होकर जाता था जिसके दोनों ओर खेत फैले थे। हेडलाइट की रोशनी में बीच-बीच में धूल उठती और फिर पीछे अँधेरे में खो जाती। खिड़की खुली थी, और रात की हवा में कटी फसल और गोबर की मिट्टी-सी गंध थी—वही गंध जो शहर के किसी कोने में नहीं मिलती। शहर की रोशनी पीछे छूटती जा रही थी।</p>\n<p>घर करीब एक एकड़ पुश्तैनी ज़मीन पर बना था। चारदीवारी के किनारे आम और जामुन के वे पेड़ अब काफी बड़े हो चुके थे जिन्हें विक्रम के दादा ने लगाया था। गेट के पास टीन की छत के नीचे महिंद्रा थार खड़ी थी और उसके बगल में छोटे भाई की रॉयल एनफील्ड बुलेट। थोड़ा पीछे पशुओं के बाड़े के पास फार्मट्रैक 60 ट्रैक्टर दिन भर के काम के बाद खड़ा था। नीम के बड़े पेड़ के नीचे बँधी भैंसों की कभी-कभार आती आवाज़ के अलावा रात लगभग शांत थी।</p>\n<p>विक्रम की कैब भीतर आकर रुकी तो उसके पिता अब भी बरामदे में बैठे थे। बाकी घर रात के लिए लगभग सिमट चुका था।</p>\n<p>विक्रम को उतरते देख पिता उठे।</p>\n<p>“आ गया?”</p>\n<p>सवाल कम, उसके पहुँच जाने की तसल्ली ज़्यादा थी।</p>\n<p>“जी हाँ।”</p>\n<p>“खाना खा लिया?”</p>\n<p>“जी हाँ, रास्ते में खा लिया।”</p>\n<p>पिता ने सिर हिलाया।</p>\n<p>“ठीक है। जा, सो जा। सुबह बात करते हैं।”</p>\n<p>विक्रम उनके पास गया, झुककर पैर छुए। पिता का हाथ एक पल उसके सिर पर ठहरा, फिर हट गया।</p>\n<p>उनके बीच अपनापन जताने का तरीका हमेशा से ऐसा ही था—कम शब्दों वाला, मगर अधूरा नहीं।</p>\n<p>तीन दिन से घर से उसकी मुलाक़ात बस आते-जाते की थी। सबके साथ ठीक से बैठना अगली सुबह हुआ।</p>\n<p>बड़ा भाई विक्रम से पहले उठ चुका था और आँगन के उस पार पशुओं को देख रहा था। विक्रम को देखकर बड़े भाई ने वहीं से सिर हिलाया।</p>\n<p>“रात को आया?”</p>\n<p>“हाँ, देर हो गई थी।”</p>\n<p>“चाय?”</p>\n<p>“हाँ।”</p>\n<p>कुछ देर बाद छोटा भाई बाँह के नीचे किताबों का ढेर दबाए निकला।</p>\n<p>“मॉर्निंग, भैया।”</p>\n<p>इतना कहकर वह लगभग तुरंत वापस अपने कमरे की तरफ मुड़ गया। जाते-जाते भी किसी चैप्टर की लाइनें बुदबुदा रहा था जिसे परीक्षा के लिए याद कर रहा था।</p>\n<p>विक्रम मुस्कराकर उसे देखता रहा।</p>\n<p>नाश्ते के वक्त वह हमेशा की तरह चूल्हे के पास छोटी चौकी पर बैठ गया। माँ आग के सामने बैठी एक के बाद एक बाजरे की रोटियाँ बना रही थीं—हथेलियों के बीच थपथपाकर उन्हें फैलातीं, गर्म तवे पर डालतीं और आख़िर में सीधे आँच पर फुलाकर विक्रम की थाली में रख देतीं।</p>\n<p>लकड़ी के धुएँ और सिकते बाजरे की महक पूरे कमरे में भरी थी।</p>\n<p>विक्रम की थाली में गर्म रोटियों पर ताज़ा मक्खन रखा गया, साथ में धनिया की चटनी, थोड़ा-सा गुड़ और स्टील का लंबा गिलास भरकर ठंडी छाछ।</p>\n<p>विक्रम ने अभी पहली रोटी भी पूरी नहीं की थी कि माँ ने दूसरी विक्रम की थाली में रख दी।</p>\n<p>“तीन दिन से सुबह निकल जाता है और रात को लौटता है। कितना दुबला हो गया है।”</p>\n<p>विक्रम ने माँ की तरफ देखा।</p>\n<p>“माँ, मैं बिल्कुल ठीक हूँ।”</p>\n<p>“ठीक कहाँ है? वहाँ आर्मी वाले ढंग से खिलाते भी हैं कि नहीं?”</p>\n<p>“बहुत खिलाते हैं।”</p>\n<p>“जो मिलता है वो खा लेना और ढंग से खाना—दोनों अलग बात हैं। चुपचाप खा।”</p>\n<p>विक्रम ने विरोध करना छोड़ दिया।</p>\n<p>इस बहस में जीतने की उसकी उम्र कभी आई ही नहीं थी।</p>\n<p>पास बैठा बड़ा भाई फसल का पूरा हिसाब सुना रहा था—इतनी तफ़सील से जितनी किसी ने उससे माँगी भी नहीं थी। बड़े भाई की पत्नी अपने दोनों छोटे बच्चों को सँभाल रही थी, जो मौका मिलते ही कमरे के कोने में रखे अपने चाचा के फौजी बैग की तरफ भाग जाते।</p>\n<p>छोटा भाई बीच-बीच में अपनी परीक्षा के लिए याद किया कोई तथ्य बातचीत में डाल देता, चाहे उसका उस समय चल रही बात से कोई लेना-देना हो या नहीं।</p>\n<p>विक्रम चुपचाप खाता रहा।</p>\n<p>कई महीनों बाद घर पर रहने पर यही बात उसे सबसे ज़्यादा छूती थी—उसकी ग़ैरमौजूदगी ने यहाँ किसी चीज़ को रुकने पर मजबूर नहीं किया था, फिर भी उसके लौटते ही उसके लिए जगह वैसे ही बन जाती थी जैसे वह कहीं गया ही न हो।</p>\n<p>शाम ढलने के बाद घर के लोग भीतर लौटने लगे तो विक्रम पैदल चौधरी के खेत की तरफ निकल गया।</p>\n<p>घर से ज़्यादा दूर नहीं था। जब भी छुट्टी में आता, एक चक्कर वहाँ ज़रूर लगता। इस बार तीन दिन निकल गए थे; आज जाकर मौका मिला।</p>\n<p>फतेह सिंह चौधरी पशुओं के बाड़े के पास ही था। विक्रम पर नज़र पड़ते ही चौधरी के चेहरे पर चौड़ी मुस्कान फैल गई।</p>\n<p>वर्षों की खेती ने चौधरी के शरीर को किसी जिम से ज़्यादा मज़बूती दी थी—चौड़े कंधे, भरी हुई बाँहें, धूप में पकी त्वचा और आँखों के किनारों पर समय से पहले आई महीन लकीरें। घनी, बेपरवाह मूँछों के नीचे वह चेहरा गंभीर रहने की कोशिश भी करे तो ज़्यादा देर निभा न पाता। कुर्ते की बाँहें कोहनियों से ऊपर चढ़ी थीं और पैरों पर अब भी खेत की धूल लगी थी।</p>\n<p>चौधरी के हाथ रस्सियों, ट्रैक्टर और खेत के काम से बहुत पहले ही खुरदरे हो चुके थे।</p>\n<p>चौधरी को देखकर हमेशा लगता था कि मिट्टी ने उसे सिर्फ पाला नहीं, अपने पास रोक भी लिया है—और उसे कभी इससे शिकायत नहीं रही।</p>\n<p>चौधरी बोला—</p>\n<p>“तीन दिन से कहाँ गायब था? सुना था आया हुआ है।”</p>\n<p>फिर उसने विक्रम को खींचकर गले लगाया।</p>\n<p>“बैठ। चाय बनवाता हूँ।”</p>\n<p>दोनों फार्महाउस के बाहर चारपाइयों पर बैठ गए। ऊपर आसमान धीरे-धीरे गहरा रहा था और खेतों से झींगुरों की आवाज़ आने लगी थी। बरामदे में लटका एक नंगा बल्ब उनके बीच की ज़मीन पर पीली रोशनी का छोटा-सा घेरा बना रहा था, जिसके चारों तरफ पतंगे चक्कर काट रहे थे।</p>\n<p>चौधरी ने चाय का गिलास उसकी तरफ बढ़ाया।</p>\n<p>“कितने दिन की छुट्टी है?”</p>\n<p>“चार की थी। अब गिनती के घंटे बचे हैं।”</p>\n<p>“इसे छुट्टी कहते हैं?”</p>\n<p>विक्रम हँस दिया।</p>\n<p>चौधरी विक्रम को गौर से देखता रहा।</p>\n<p>“एक बात कहूँ?”</p>\n<p>“कह।”</p>\n<p>“इस बार कुछ अलग लग रहा है तू।”</p>\n<p>विक्रम ने भौंह उठाई।</p>\n<p>“क्या अलग?”</p>\n<p>“पता नहीं।”</p>\n<p>चौधरी ने फिर उसे देखा, जैसे सही शब्द तलाश रहा हो।</p>\n<p>“हल्का-सा। पहले से हल्का।”</p>\n<p>विक्रम ने कंधे उचका दिए और चाय का घूँट भर लिया।</p>\n<p>विक्रम ने कुछ नहीं बताया।</p>\n<p>चौधरी ने भी दोबारा नहीं पूछा।</p>\n<p>पुरानी दोस्ती की अपनी एक समझ होती है—कब सवाल करना है, और कब सामने वाले के चेहरे पर आए बदलाव को देखकर भी उसे वहीं छोड़ देना है।</p>\n<p>फिर बातें अपने पुराने रास्तों पर निकल गईं।</p>\n<p>स्कूल के दिनों के किस्से, गाँव के पुराने नाम, कौन कहाँ पहुँच गया, किसने क्या कर लिया, किसकी शादी हो गई और कौन अब भी वैसा ही था जैसा सालों पहले हुआ करता था।</p>\n<p>बातों का कोई मकसद नहीं था।</p>\n<p>इसी वजह से वे इतनी देर चलती रहीं।</p>\n<p>जब विक्रम वहाँ से उठा तब रात काफी हो चुकी थी।</p>\n<p>वापसी में वह उसी कच्चे रास्ते से धीरे-धीरे घर की तरफ चला। ऊपर आसमान तारों से भरा था—इतने साफ़ तारे दिल्ली या गुरुग्राम में शायद ही कभी दिखाई देते थे। सिर के ऊपर आकाशगंगा की धुँधली पट्टी दिखी, ठीक वैसी जैसी बचपन में इसी रास्ते पर लगती थी।</p>\n<p>विक्रम रास्ते के बीच एक पल रुक गया और गहरी साँस ली—मिट्टी, कटी फसल और दूर कहीं जलते उपलों की महक एक साथ भीतर उतरी।</p>\n<p>उस मिट्टी पर फिर कुछ देर खड़े होने की, जहाँ से वह निकला था; उन लोगों के बीच बैठने की, जो उसे तब से जानते थे जब उसके नाम के आगे कोई रैंक नहीं था।</p>\n<p>आर्मी उसे कितनी भी दूर ले जाए, यहाँ की कुछ चीज़ें उसके लौटने का इंतज़ार उसी पुराने ढंग से करती थीं।</p>\n<p>जेब में फोन हल्का-सा काँपा। नैना का संदेश था: \"पहुँच गए? सुनैना तुम्हारा पूरा बायोडाटा माँग रही है।\"</p>\n<p>विक्रम मुस्कराया और जवाब में सिर्फ इतना लिखा: \"पहुँच गया।\"</p>\n<p>उस रात विक्रम को नहीं पता था कि उसके अतीत का एक नाम फिर उसकी ज़िंदगी की तरफ बढ़ रहा है।</p>\n<p>और उसकी शुरुआत एक फोन कॉल से होनी थी।</p>"}, {"chapter": 23, "title": "अध्याय 21 — अतीत की एक आवाज़", "content": "<h1>अध्याय 21 — अतीत की एक आवाज़</h1>\n<p>एक शाम कमल का फोन आया।</p>\n<p>स्कूल के दिनों का पुराना दोस्त, जो अब ख़ुद पुलिस में था।</p>\n<p>तब तक विक्रम की छुट्टी ख़त्म हुए काफी वक्त बीत चुका था और वह वापस नॉर्थ-ईस्ट में अपनी पोस्ट पर लौट आया था। शाम ढल रही थी। वह ऑफिसर्स मेस के बाहर सीढ़ियों पर बैठा था, फोन कान से लगाए सामने तारबंदी के पार फैली पहाड़ियों को देख रहा था। जंगलों के पीछे दिन की आख़िरी रोशनी धीरे-धीरे बुझ रही थी और हवा में उस इलाके की वही नम, हरियाली से भरी गंध थी जो मौसम बदलने पर भी जैसे पूरी तरह जाती नहीं थी।</p>\n<p>दोनों की ढंग से बात हुए एक साल से ज़्यादा हो चुका था, इसलिए शुरुआत वहीं से हुई जहाँ ऐसे पुराने दोस्तों की बातचीत अक्सर होती है—पुराने नाम, स्कूल के किस्से, भूले-बिसरे मज़ाक और उन लोगों की ख़बरें जिनसे दोनों का रिश्ता अब बस यादों भर का रह गया था।</p>\n<p>कुछ देर बाद कमल ने पूछा, “और बता, कोई लव स्टोरी चल रही है कि नहीं? कश्मीर में कोई लड़की-वड़की तो मिली होगी। सुना है उधर की लड़कियाँ बड़ी खूबसूरत होती हैं।”</p>\n<p>विक्रम हँसा।</p>\n<p>“ग़लत जगह पकड़ ली तूने। जम्मू-कश्मीर से निकले महीनों हो गए। अब नॉर्थ-ईस्ट में हूँ—जगह अलग, मुश्किलें अलग। म्यांमार सीमा पर एक ऑपरेशन भी हुआ था, इससे ज़्यादा नहीं बता सकता। बस इतना कि टीम सही-सलामत लौट आई।”</p>\n<p>फिर थोड़ी देर रुककर बोला, “और खूबसूरती वाली बात ग़लत नहीं है। जहाँ भी पोस्टिंग रही, खूबसूरत लोग देखे हैं। लेकिन वहाँ हम इश्क करने नहीं जाते, कमल। जिन लोगों के बीच तैनात होते हैं, उन्हें हमारी हिफ़ाज़त चाहिए, हमारी उस तरह की नज़र नहीं। हमारा काम है उनका ख़याल रखना, उन्हें महफ़ूज़ रखना। ड्यूटी वही है, रोमांस नहीं।”</p>\n<p>एक पल चुप रहकर उसने आगे कहा, “वैसे भी किसी को खूबसूरत समझना और किसी से सच में मोहब्बत करना दो अलग बातें हैं। असली मोहब्बत के लिए कोई ऐसा चाहिए जो तुम्हें ठीक से समझे—तुम्हारी परवरिश, तुम्हारा माहौल, तुम्हारी छोटी-छोटी बातें… जिसे हर बात का मतलब समझाने की ज़रूरत न पड़े। वो समझ, वो ख़याल… छोड़, तू नहीं समझेगा।”</p>\n<p>कमल हँस पड़ा।</p>\n<p>“अरे, इतनी गहरी मोहब्बत शायद न समझूँ, फिलॉसफर साहब, लेकिन उसका लाइव वर्जन ज़रूर समझता हूँ। अब ये बता—तेरे वाला वही गहरा मामला है या बाकी हम लोगों की तरह अभी भी हल्के-फुल्के में काम चला रहा है?”</p>\n<p>विक्रम की मुस्कान कुछ नरम पड़ गई।</p>\n<p>“गहरा वाला।”</p>\n<p>इतना कहते ही उसे ख़ुद महसूस हुआ कि बात पहली बार उसके और नैना के बीच से निकलकर किसी तीसरे इंसान के सामने आई है। जो अब तक सिर्फ उन दोनों का था, उसे आवाज़ मिलते ही जैसे उसका वज़न थोड़ा और बढ़ गया।</p>\n<p>“कोई है,” उसने कहा। “और सीरियस है।”</p>\n<p>“कितना सीरियस?”</p>\n<p>“हिमाचल गए थे साथ। बस हम दोनों। कुछ दिन।”</p>\n<p>उसने नाम नहीं बताया।</p>\n<p>ज़रूरत भी नहीं थी।</p>\n<p>कुछ बातें इंसान अपने बहुत पुराने दोस्त से भी पूरी नहीं खोलता।</p>\n<p>कमल ने धीमी-सी सीटी बजाई।</p>\n<p>“हिमाचल तक पहुँच गए? फिर तो मामला सच में सीरियस है। अच्छा है, यार। बहुत टाइम लगा दिया तूने।”</p>\n<p>विक्रम हँसा।</p>\n<p>“और तू? तेरी कोई कहानी?”</p>\n<p>“कोई है,” कमल ने कहा। “बस शादी थोड़ी जल्दी हो गई थी उसकी।”</p>\n<p>“अच्छा। कौन है?”</p>\n<p>“तू भी जानता होगा उसे। बादशाहपुर की ही है, पुलिस में है।”</p>\n<p>“कौन?”</p>\n<p>“कविता।”</p>\n<p>पहाड़ियों के पीछे आख़िरी रोशनी इस तरह बुझ गई, जैसे किसी ने नाम सुनकर दिया फूँक दिया हो।</p>\n<p>देर तक विक्रम कुछ नहीं बोला।</p>\n<p>सीढ़ी के किनारे पर रखा उसका खाली हाथ एक बार कस गया, फिर ढीला पड़ गया।</p>\n<p>बिना बुलाए एक पुराना आँगन याद में खुल गया। चाय की ट्रे। मंगलवार की वे शामें। दो साल का वह हिस्सा जिसे उसने महीनों से जानबूझकर छुआ तक नहीं था।</p>\n<p>जब बोला तो आवाज़ उम्मीद से ज़्यादा सधी हुई थी।</p>\n<p>“अच्छा है… मुझे खुशी है तेरे लिए, कमल। सच में।”</p>\n<p>और काफी हद तक वह सच ही कह रहा था। शब्द दिखावे के नहीं थे, उन्हें बाहर आने में सामान्य से थोड़ा ज़्यादा वक्त लगा था।</p>\n<p>कमल ने उसकी चुप्पी को हैरानी समझा और बात आगे बढ़ा दी। फिर क्रिकेट आया, किसी पुराने दोस्त की शादी आई और बातचीत धीरे-धीरे किसी दूसरी दिशा में निकल गई।</p>\n<p>विक्रम जवाब देता रहा, हँसता भी रहा, लेकिन उसका मन बीच-बीच में उस पुराने आँगन तक लौट जाता जहाँ वह बहुत समय से नहीं गया था।</p>\n<p>कुछ हफ्ते बाद कमल ने कविता से फोन पर उस ऑपरेशन का ज़िक्र किया, जिसकी ख़बर कुछ महीने पहले आधी-अधूरी, सूत्रों के हवाले से चली थी—म्यांमार सीमा के पास एक क्रॉस-बॉर्डर स्ट्राइक, जिसमें एक आतंकी कैंप तबाह किया गया था। आधिकारिक पुष्टि कभी नहीं आई।</p>\n<p>कमल ने सहजता से बताया कि विक्रम ने ख़ुद फोन पर उस ऑपरेशन का ज़िक्र किया था—बस दो वाक्यों में। उसी की टीम थी। उसका पुराना स्कूल का दोस्त। बादशाहपुर का ही।</p>\n<p>विक्रम।</p>\n<p>नाम सुनते ही कविता चुप हो गई।</p>\n<p>आज भी उस नाम का कविता के भीतर कहीं वही असर था—अब वह इतना सीख चुकी थी कि उसे अपनी आवाज़ तक न पहुँचने दे।</p>\n<p>इतने समय में कविता को कभी पता ही नहीं चला था कि कमल और विक्रम एक-दूसरे को जानते हैं। यह तो और भी नहीं कि दोनों एक ही स्कूल में पढ़े थे, बचपन साथ गुज़रा था और एक-दूसरे को उन पुराने नामों से बुलाते थे जो अक्सर सिर्फ स्कूल के दोस्त याद रखते हैं।</p>\n<p>कविता की ज़िंदगी के दो हिस्से, जिन्हें उसने हमेशा एक-दूसरे से बिल्कुल अलग समझा था, दरअसल इतने दूर कभी थे ही नहीं।</p>\n<p>“तुमने उसे कुछ बताया?” कविता ने आख़िर पूछा। “हमारे बारे में?”</p>\n<p>“बिल्कुल नहीं। ऐसी बातें कोई यूँ बैठकर थोड़े बताता है।”</p>\n<p>कमल को जैसे सवाल में कुछ खास लगा ही नहीं।</p>\n<p>“हाँ, उसने किसी और का ज़िक्र ज़रूर किया था। सीरियस है शायद। दोनों हिमाचल गए थे साथ।”</p>\n<p>कविता की उँगलियाँ फोन पर ठहर गईं।</p>\n<p>वह कभी विक्रम के साथ हिमाचल नहीं गई थी।</p>\n<p>जिस भी लड़की के साथ विक्रम गया था, विक्रम की ज़िंदगी में उसे वह जगह मिली थी जो कविता को कभी नहीं मिली—एक पूरा सफ़र, खुले दिन में, बिना किसी से छिपे, बिना चुराए हुए वक्त के।</p>\n<p>उसके बाद कविता ने ज़्यादा कुछ नहीं कहा।</p>\n<p>फोन ख़त्म होने तक कविता के भीतर कोई पुराना हिस्सा उस प्रेम के लिए एक बार फिर शोक मना चुका था, जो उस रूप में कभी उसका था ही नहीं।</p>\n<p>तीन रात बाद, दस बजने के बाद, कविता ने विक्रम को फोन किया।</p>\n<p>उस वक्त डिपार्टमेंट लगभग शांत हो चुका था। गलियारे में कहीं एक ट्यूबलाइट लगातार भिनभिना रही थी और सामने की डेस्क से किसी कांस्टेबल के रेडियो की धीमी खरखराहट आ रही थी।</p>\n<p>दूसरी घंटी पर विक्रम ने फोन उठा लिया।</p>\n<p>कविता का नाम स्क्रीन पर देखते ही विक्रम की पीठ अपने-आप सीधी हो गई थी।</p>\n<p>“कविता।”</p>\n<p>“ऑपरेशन के बारे में सुना,” कविता ने कहा। “कमल से। उसने बताया तुमने लीड किया था। देर से ही सही, बधाई हो, मेजर साहब।”</p>\n<p>“थैंक यू।”</p>\n<p>आवाज़ सामान्य थी, मगर विक्रम उसे इतना जानता था कि उसके नीचे की सावधानी पहचान सके। कविता जब किसी बात को भीतर रोकने की कोशिश करती थी, उसकी आवाज़ कुछ ज़्यादा ही संभली हुई हो जाती थी।</p>\n<p>“पूरा गाँव तुम्हारी बात कर रहा है। तुम्हारे पापा तो ऐसे घूम रहे होंगे जैसे पूरा जिला उन्हीं का हो।”</p>\n<p>विक्रम के मुँह से हल्की हँसी निकली।</p>\n<p>“जितना दिखाएँगे उससे ज़्यादा खुश होंगे।”</p>\n<p>फिर विक्रम ने पूछा, “डिपार्टमेंट कैसा चल रहा है?”</p>\n<p>कविता बोली, “जैसा हमेशा चलता है। फाइलें, काग़ज़ और सीनियर अफसर जिन्हें लगता है ज़ोर से बोलना भी कोई मैनेजमेंट टेक्नीक है।”</p>\n<p>कविता हँसी, मगर उसकी हँसी एक पल देर से आई और ज़रूरत से कुछ ज़्यादा हल्की थी।</p>\n<p>कविता फिर बोली, “रामफल की माँ ने भी आख़िर पूछना छोड़ दिया है कि वीकेंड पर मैं कहाँ गायब रहती हूँ। शायद अब हिसाब रखना छोड़ दिया है।”</p>\n<p>इसके बाद दोनों काफी देर तक ऐसी बातों पर बात करते रहे जिनका कोई खास मतलब नहीं था—किसी रिश्तेदार की सगाई, पुराने बस स्टैंड के पास बनती सड़क, गाँव की छोटी-मोटी ख़बरें।</p>\n<p>ऊपर से देखा जाए तो यह दो पुराने दोस्तों की बिल्कुल सहज बातचीत थी।</p>\n<p>मगर उसके नीचे दोनों एक ही काम कर रहे थे—उन दो नामों से बची जगह को साधारण बातों से भर रहे थे जिन्हें कोई भी अपनी तरफ से छूना नहीं चाहता था।</p>\n<p>विक्रम की हर चुप्पी में नैना थी।</p>\n<p>कविता की हर चुप्पी में कमल।</p>\n<p>आख़िर कविता ने कहा, “अब रखती हूँ। बस ठीक से बधाई देनी थी। ऐसी बात पर सिर्फ मैसेज भेजना अच्छा नहीं लगा।”</p>\n<p>“अच्छा लगा कि तुमने फोन किया।”</p>\n<p>विक्रम ने सच कहा था—उन साधारण शब्दों से कहीं ज़्यादा सच जितना सुनाई दिया।</p>\n<p>फिर विक्रम के मुँह से निकला—</p>\n<p>“कविता…”</p>\n<p>“मत,” कविता ने तुरंत कहा, मगर आवाज़ में सख़्ती नहीं थी। “जो भी कहने वाले हो, आज मत कहो। आज इसे बस इतना ही रहने देते हैं—बधाई… और एक पुराने दोस्त की आवाज़। इससे ज़्यादा मुश्किल कुछ नहीं।”</p>\n<p>विक्रम पल भर चुप रहा।</p>\n<p>वह समझ गया।</p>\n<p>और उसने बात वहीं छोड़ दी।</p>\n<p>कविता ने कहा—“अपना ख़याल रखना, विक्रम।”</p>\n<p>इस बार कविता की आवाज़ बहुत धीमी थी।</p>\n<p>“तुम भी, कविता।”</p>\n<p>फिर लाइन कट गई।</p>\n<p>विक्रम ने मोबाइल अपने बगल वाली सीढ़ी पर रख दिया और काफी देर उसे दोबारा हाथ नहीं लगाया। सामने अँधेरे में डूबी पहाड़ियों को देखते हुए वह उन दस साधारण मिनटों को याद करता रहा—बातें नहीं, बल्कि बातों के बीच की छोटी चीज़ें; कविता की हँसी का एक पल देर से आना, और उसका “बधाई हो, मेजर साहब” कहना, जैसे उसने वह वाक्य फोन मिलाने से पहले कई बार अपने भीतर दोहराया हो।</p>\n<p>बगल की सीढ़ी पर फोन की स्क्रीन बुझ चुकी थी, और नीचे कहीं झींगुरों की आवाज़ और तेज़ हो गई।</p>\n<p>विक्रम ने उससे आगे कुछ समझने की कोशिश नहीं की।</p>\n<p>कुछ दरवाज़े, जब कोई औरत ख़ुद बंद कर चुकी हो, तो सिर्फ अपने सवालों की तसल्ली के लिए उन्हें दोबारा खोलना उसका हक नहीं था।</p>\n<p>उधर कविता फोन कटने के बहुत देर बाद तक उसे गोद में रखे बैठी रही। बाहर वही ट्यूबलाइट अब भी भिनभिना रही थी।</p>\n<p>कुछ मिनटों के लिए कविता ने ख़ुद को रोकना छोड़ दिया।</p>\n<p>दो साल।</p>\n<p>एक फोन लाइन।</p>\n<p>एक आँगन।</p>\n<p>और एक इंसान जो कभी पूरी तरह उसका नहीं हुआ था—और अब कभी हो भी नहीं सकता था।</p>\n<p>कविता ने अपना दुपट्टा ठीक किया, मेज़ की लाइट बंद की और उठ खड़ी हुई।</p>\n<p>ट्यूबलाइट की भिनभिनाहट कमरे में अकेली रह गई।</p>\n<p>बाकी दुनिया के लिए उसे फिर वही कविता बनना था जिसे उसकी ज़िंदगी उससे हर रोज़ माँगती थी—</p>\n<p>संभली हुई।</p>\n<p>काबिल।</p>\n<p>और अपने भीतर की बात अपने भीतर रखने वाली।</p>"}, {"chapter": 24, "title": "अध्याय 22 — आने वाले कल की बात", "content": "<h1>अध्याय 22 — आने वाले कल की बात</h1>\n<p>कविता के फोन के कुछ हफ्ते बाद विक्रम को फिर छुट्टी मिल गई। ऑपरेशन के बाद की हलचल अब पूरी तरह थम चुकी थी, और आर्मी ने फिर कुछ दिनों की छुट्टी दे दी।</p>\n<p>उस रात ग्यारह बज चुके थे।</p>\n<p>नैना के फ्लैट में अँधेरा था—बस बालकनी का दरवाज़ा खुला था। विक्रम शाम से नैना के पास था; रात उसे बादशाहपुर में अपने घर बितानी थी, मगर वक्त जाने कब ग्यारह के पार निकल गया था। दोनों सोफे पर बैठे थे, मगर बातों के बीच की चुप्पी लंबी होती जा रही थी। ऊपर पंखा धीमी रफ्तार से लगभग बेआवाज़ घूम रहा था और बाहर मुख्य सड़क से आती ट्रैफिक की हल्की-सी आवाज़ ही बता रही थी कि शहर का कुछ हिस्सा अब भी जाग रहा है। कभी-कभार कोई गाड़ी गुज़रती, और छत पर उसकी रोशनी एक पल दौड़कर बुझ जाती।</p>\n<p>उसी अँधेरे में नैना ने अचानक पूछा—</p>\n<p>“तुम्हें कितने बच्चे चाहिए?”</p>\n<p>विक्रम ने तुरंत जवाब नहीं दिया।</p>\n<p>पंखा घूमता रहा। विक्रम की उँगलियाँ सोफे के कुशन पर कुछ गिनने लगीं—एक, दो।</p>\n<p>“मैंने कभी ख़ुद को इसके बारे में ठीक से सोचने ही नहीं दिया,” विक्रम ने आख़िर कहा।</p>\n<p>“क्यों?”</p>\n<p>“क्योंकि सोचने लगूँगा तो सब सच लगने लगेगा। और मैंने बहुत वक्त ऐसे गुज़ारा है कि किसी ऐसी चीज़ की चाह ही मत रखो जो कभी तुमसे छिन सकती हो।”</p>\n<p>अँधेरे में वह कुछ देर शब्द टटोलता रहा—जैसे कोई अनजान कमरे में अँधेरे में बत्ती का बटन टटोलता है।</p>\n<p>“लेकिन अगर तुम पूछ रही हो… तो दो। शायद तीन, अगर तुम्हें ज़्यादा चाहिए हुए।”</p>\n<p>“दो…” नैना ने जैसे उस संख्या को मन ही मन अपने भविष्य में रखकर देखा। “मैं हमेशा सोचती थी मुझे तीन चाहिए। बड़ा-सा घर हो, खूब शोर हो… लेकिन अब लगता है शायद मुझे तीन बच्चे नहीं चाहिए थे। शायद मैं बस ऐसा घर चाहती थी जिसमें वैसी ख़ामोशी न हो जैसी कभी-कभी मेरे बचपन के घर में हुआ करती थी।”</p>\n<p>विक्रम ने उसकी तरफ देखा।</p>\n<p>“इतनी ख़ामोशी थी?”</p>\n<p>“बाबा अक्सर बाहर रहते थे। कभी पोस्टिंग, कभी ट्रेनिंग, कभी आर्मी को जहाँ उनकी ज़रूरत पड़ गई। घर माँ ने ही ज़्यादा संभाला।”</p>\n<p>नैना थोड़ा खिसककर उसके करीब आ गई। अँधेरे में उसका कंधा विक्रम के कंधे से लग गया।</p>\n<p>“बचपन में कई रात मैं जागती रहती थी। बाहर बजरी पर उनकी जीप के पहियों की आवाज़ सुनने के लिए। लगता था अभी आएगी… अभी गेट के बाहर रुकेगी। फिर कुछ रात वह आवाज़ आती ही नहीं थी और इंतज़ार करते-करते मेरी आँख लग जाती थी।”</p>\n<p>विक्रम ने छत की तरफ देखा। बाहर से किसी गाड़ी के पहियों की आवाज़ आई, और दोनों ने एक साथ साँस रोक ली—फिर आवाज़ आगे निकल गई।</p>\n<p>विक्रम की आवाज़ धीमी हो गई।</p>\n<p>“मैं तुम्हारे लिए ऐसी ज़िंदगी नहीं चाहता, नैना। मैं नहीं चाहता कि तुम रात भर किसी ऐसी जीप की आवाज़ सुनती रहो जो उस रात आने वाली ही नहीं है।”</p>\n<p>“मुझे पता है तुम नहीं चाहते।”</p>\n<p>“लेकिन किसी चीज़ को न चाहना और उसे रोक पाना एक बात नहीं होती, विक्रम।”</p>\n<p>“मैं महीनों से ख़ुद को समझा रही हूँ कि मैं ये ज़िंदगी संभाल सकती हूँ। तुम्हारी पोस्टिंग, तुम्हारा जाना, इंतज़ार… सब। लेकिन वो पंद्रह दिन याद हैं? जब तुम्हारी कोई ख़बर नहीं थी?”</p>\n<p>विक्रम ने कुछ नहीं कहा।</p>\n<p>“मैंने वो पंद्रह दिन निकाल तो लिए,” नैना बोली, “लेकिन किस हालत में निकाले, ये याद करना भी अच्छा नहीं लगता। कभी-कभी सोचती हूँ माँ ने बीस साल ये सब कैसे जिया होगा।”</p>\n<p>“तुम टूटी नहीं थीं।”</p>\n<p>“बहुत करीब पहुँच गई थी।”</p>\n<p>नैना की साँस अँधेरे में थोड़ी असमान हो गई।</p>\n<p>“और फिर मैं हमारे बच्चों के बारे में सोचती हूँ… अगर कभी हुए तो। क्या वे भी वैसे ही बड़े होंगे जैसे मैं हुई? सड़क पर किसी गाड़ी की आवाज़ सुनकर सोचेंगे कि बाबा आए हैं? उस हफ्ते कितना डरना है, ये अपनी माँ का चेहरा देखकर समझेंगे?”</p>\n<p>वह चुप रही।</p>\n<p>फिर बहुत धीमे बोली—</p>\n<p>“मुझे समझ नहीं आता कि ये सब जानते हुए भी तुम्हारे साथ वही ज़िंदगी चाहना मुझे ख़ुदग़र्ज़ बनाता है… या तुम्हें इतना चाहना कि फिर भी कोशिश करना चाहती हूँ।”</p>\n<p>विक्रम उसकी तरफ मुड़ गया।</p>\n<p>अँधेरे में उसने नैना का हाथ ढूँढ़ा और अपनी हथेली में ले लिया। विक्रम की आवाज़ में जो काँपना नहीं आया था, वह उसकी उँगलियों में बहुत हल्का-सा मौजूद था।</p>\n<p>“ये तुम्हें ख़ुदग़र्ज़ नहीं बनाता।”</p>\n<p>विक्रम ने उसका हाथ अपने सीने पर रख लिया, ठीक वहीं जहाँ नैना अक्सर अपना हाथ रखती थी।</p>\n<p>“बल्कि मुझे लगता है, यही बात तुम्हें वैसी माँ बनाएगी जैसी मैं अपने बच्चों के लिए चाहूँगा। जो किसी फ़ैसले की कीमत पहले देखती है, फिर उसे चुनती है। सिर्फ इसलिए आँखें बंद नहीं कर लेती कि कीमत है ही नहीं।”</p>\n<p>नैना चुप रही।</p>\n<p>“मैं तुमसे ये वादा नहीं कर सकता कि मेरी जीप हर बार वक्त पर घर के बाहर आकर रुकेगी। ऐसा वादा मैं अपनी माँ से भी नहीं कर सकता था, और तुमसे भी नहीं कर सकता।”</p>\n<p>विक्रम की उँगलियाँ नैना के हाथ पर और कस गईं।</p>\n<p>“लेकिन एक वादा कर सकता हूँ। हमारे जितने भी बच्चे होंगे, उन्हें कभी ये शक नहीं होगा कि उनके पिता को उनके पास घर लौटना कितना पसंद था। हर बार। चाहे लौटने में कभी ज़रूरत से ज़्यादा वक्त ही क्यों न लग जाए।”</p>\n<p>पंखा घूमता रहा, और बीच-बीच में नैना के दुपट्टे का सिरा उसकी साँस के साथ हिलता रहा।</p>\n<p>नैना ने तुरंत कुछ नहीं कहा।</p>\n<p>अँधेरे में नैना का दूसरा हाथ अपने चेहरे तक गया। उसने आँखों के पास की नमी चुपचाप पोंछ ली, इसलिए कि उसकी आवाज़ में वह बात न उतर आए जिसे वह अभी शब्द नहीं देना चाहती थी।</p>\n<p>थोड़ी देर बाद नैना की आवाज़ फिर संभली हुई थी, मगर पहले से कहीं नरम।</p>\n<p>“दो।”</p>\n<p>“हूँ?”</p>\n<p>“मैंने तय कर लिया। दो बच्चे।”</p>\n<p>विक्रम के होंठों पर हल्की मुस्कान आई।</p>\n<p>नैना ने कहा, “और घर में ख़ामोशी नहीं होगी। तुम बाहर भी हुए तो मैं इतना शोर करूँगी कि तुम्हारे हिस्से की कमी भी पूरी हो जाए, जब तक तुम वापस नहीं आ जाते।”</p>\n<p>“मुझे मंज़ूर है।”</p>\n<p>“होना भी चाहिए।”</p>\n<p>नैना पूरी तरह विक्रम के करीब सिमट आई और अपना सिर उसकी ठोड़ी के नीचे टिका दिया।</p>\n<p>उसके बाद काफी देर तक दोनों ने कुछ नहीं कहा।</p>\n<p>फिर नैना की साँसें धीरे-धीरे नींद की लय में उतरने लगीं, और विक्रम जागता रहा।</p>\n<p>अब उसका मन अनचाहे उस हिसाब की तरफ चला गया जिससे वह पूरी शाम बचता रहा था। पोस्टिंग अगर हमेशा की तरह चली तो अगला आदेश बहुत कम वक्त देकर आ सकता था, और उसके बाद अगली छुट्टी कब मिलेगी, इसका कोई भरोसा नहीं था।</p>\n<p>विक्रम ने नैना को नहीं जगाया।</p>\n<p>बताया भी नहीं।</p>\n<p>घड़ी में बारह बजने को थे। उसे बादशाहपुर लौटना था—घर पर माँ अब भी जागी होंगी। उसने कुशन खिसकाकर नैना का सिर सोफे पर टिकाया और शॉल उसके कंधों तक खींच दिया। उँगलियाँ छुड़ाते हुए नैना की उँगलियाँ नींद में बस पल भर कसीं, और विक्रम कुछ देर उन्हें अपनी हथेली में बंद रखे बैठा रहा—फिर धीरे से छुड़ा लीं।</p>\n<p>दरवाज़ा उसने बाहर से खींचकर बंद किया। ताला हल्की खट की आवाज़ के साथ अपनी जगह बैठ गया।</p>\n<p>सीढ़ियाँ उतरते हुए बाहर किसी गाड़ी के पहियों की आवाज़ आई, और विक्रम पल भर को ठिठक गया—फिर आगे बढ़ गया।</p>\n<p>उस रात उन्होंने पहली बार अपने बच्चों की बात की थी।</p>\n<p>भविष्य अभी आया नहीं था।</p>\n<p>मगर पहली बार दोनों ने उसे एक ही घर के भीतर खड़े होकर देखा था।</p>"}, {"chapter": 25, "title": "अध्याय 23 — मुझे वैसा ही रहने देना", "content": "<h1>अध्याय 23 — मुझे वैसा ही रहने देना</h1>\n<p>छुट्टी का वह रविवार, करने को कुछ खास नहीं था।</p>\n<p>नैना के फ्लैट के फर्श पर दोनों आमने-सामने बैठे नैना की पुरानी तस्वीरों का एक डिब्बा खंगाल रहे थे। यह नैना का ही ख़याल था। डिब्बे का ढक्कन खुलते ही हर बार पुराने काग़ज़ और हल्की-सी सीलन की मिली-जुली गंध बाहर आती। खिड़की के पास चंदन की अगरबत्ती लगभग बुझने को थी और दोपहर की ठहरी हुई रोशनी में उसके धुएँ की पतली लकीर ही कमरे की अकेली चीज़ थी जो लगातार हिल रही थी।</p>\n<p>एक तस्वीर हाथ में आते ही नैना अचानक चुप हो गई।</p>\n<p>काफी देर तक बस उसे देखती रही।</p>\n<p>“क्या हुआ?” विक्रम ने पूछा।</p>\n<p>नैना ने तस्वीर उसकी ओर बढ़ा दी।</p>\n<p>तस्वीर में वह शायद सोलह साल की थी। किसी धूल भरे मैदान में खड़ी, एक कंधे पर क्रिकेट का बल्ला टिकाए कैमरे की तरफ खुलकर हँस रही थी। बाल छोटे थे, चेहरे पर बेफिक्री थी और खड़े होने के अंदाज़ में भी कुछ ऐसा था जैसे दुनिया में अपनी जगह घेरने के लिए उसे किसी की इजाज़त की ज़रूरत कभी पड़ी ही न हो। धूल भरे मैदान की धूप तस्वीर के भीतर से अब भी चमक रही थी।</p>\n<p>नैना ने तस्वीर वापस ले ली और उसे देखती रही।</p>\n<p>“मैं बहुत लाउड हुआ करती थी।”</p>\n<p>विक्रम मुस्कराया। “सिर्फ हुआ करती थी?”</p>\n<p>नैना ने उसकी तरफ देखा, मगर मुस्कराई नहीं।</p>\n<p>“आवाज़ की बात नहीं कर रही। मैं… पूरी की पूरी ऐसी थी। जो चाहिए होता था, खुलकर कहती थी। टीचर्स से बहस करती थी। बाबा से कह दिया था कि मुझे पुलिस में जाना है, जबकि उस उम्र में मुझे ठीक से पता भी नहीं था कि पुलिस की नौकरी होती क्या है। मुझे ये बात अच्छी लगती थी कि एक लड़की वो काम करना चाहती है जिसकी उससे कोई उम्मीद नहीं करता।”</p>\n<p>नैना की उँगली तस्वीर के किनारे पर धीरे-धीरे फिरती रही, जैसे उस काग़ज़ के भीतर मौजूद लड़की तक पहुँचने का कोई रास्ता वहीं से निकलता हो।</p>\n<p>“पता नहीं कब थोड़ी शांत हो गई। शर्मीली नहीं हुई—वो मैं आज भी नहीं हूँ। बस… संभलकर रहने लगी। ये समझने लगी कि कहाँ मुझे कितनी जगह लेनी चाहिए और कितनी दूसरों के लिए छोड़ देनी चाहिए।”</p>\n<p>विक्रम ने कहा, “मेरे साथ तो तुम शांत नहीं रहती।”</p>\n<p>“वही तो,” नैना बोली।</p>\n<p>इस बार नैना ने सीधे विक्रम की आँखों में देखा।</p>\n<p>“तुम्हारे साथ मैं ख़ुद को रोकती नहीं हूँ। और कभी-कभी इसी बात से डर लगता है। क्योंकि मुझे नहीं पता शादी के बाद इसका क्या होगा। जब घर संभालना होगा, तुम्हारे परिवार की अपनी उम्मीदें होंगी, बच्चे होंगे जिन्हें एक माँ की ज़रूरत शायद उस लड़की से ज़्यादा होगी जो कभी सिर्फ अपनी इच्छा से पुलिस अफसर बनना चाहती थी।”</p>\n<p>“इन सब से तुम बदल क्यों जाओगी?” विक्रम ने पूछा।</p>\n<p>नैना की आवाज़ में हल्की धार आ गई।</p>\n<p>“क्योंकि मैंने अपने आसपास लगभग हर औरत को बदलते देखा है।”</p>\n<p>नैना की नज़र विक्रम से हटकर सामने दीवार पर टिक गई।</p>\n<p>“मेरी माँ भी पहले ऐसी नहीं थीं जैसी अब हैं। उनकी पुरानी तस्वीरें देखी हैं मैंने। बाबा के दोस्तों से राजनीति पर बहस करती थीं। हर चीज़ पर अपनी राय होती थी।”</p>\n<p>नैना ने तस्वीर पलटकर देखी, फिर दोबारा सीधी कर ली।</p>\n<p>“फिर पता नहीं कब वह ख़ुद होने के साथ-साथ पत्नी रहने के बजाय बस पत्नी होती चली गईं। मुझे नहीं लगता किसी ने एक दिन उनसे उनकी ज़िंदगी छीन ली। शायद वह ख़ुद ही अपने हिस्से की छोटी-छोटी चीज़ें एक-एक करके पीछे रखती गईं… और एक दिन इतना कुछ पीछे छूट चुका था कि जो औरत कभी हर बात पर अपनी राय रखती थी, उसकी जगह बहुत कम बची।”</p>\n<p>विक्रम चुप रहा।</p>\n<p>नैना को यह कहने में जितना वक्त लगा था, उतना वक्त विक्रम ने उसे दिया।</p>\n<p>“मैं वैसी नहीं होना चाहती।”</p>\n<p>अब नैना की आवाज़ धीमी पड़ गई थी। तस्वीर उसके हाथों में कुछ ज़्यादा कस गई।</p>\n<p>“मैं नहीं चाहती कि पंद्रह साल बाद किसी दिन ये फोटो देखूँ और मुझे लगे कि इसमें खड़ी लड़की कभी मैं थी ही नहीं। मैं तब भी बेकार की बातों पर ज़रूरत से ज़्यादा बहस करना चाहती हूँ। मैं तब भी चाहती हूँ कि कहीं थोड़ी-सी ज़मीन हो जिसके काग़ज़ों पर मेरा अपना नाम लिखा हो।”</p>\n<p>वह रुकी।</p>\n<p>“और मुझे ये भी नहीं पता कि किसी इंसान से इसका वादा कैसे माँगा जाता है। क्योंकि शायद ये वादा करना उसके हाथ में भी नहीं होता।”</p>\n<p>विक्रम ने धीरे से तस्वीर उसके हाथ से ली और बगल में रख दी।</p>\n<p>फिर तस्वीर की जगह उसके दोनों हाथ अपने हाथों में ले लिए।</p>\n<p>“मैं ये वादा नहीं कर सकता कि दुनिया कभी तुमसे तुम्हारे हिस्से छीनने की कोशिश नहीं करेगी। मैंने अपनी माँ के साथ भी ऐसा होते देखा है।”</p>\n<p>विक्रम की आवाज़ में कोई बड़ी घोषणा नहीं थी।</p>\n<p>“लेकिन इतना वादा कर सकता हूँ कि छीनने वालों में मैं कभी नहीं रहूँगा।”</p>\n<p>नैना की आँखें उस पर टिक गईं।</p>\n<p>“तुम्हें ऊँची आवाज़ में बहस करनी है तो करो। मैं उसी कमरे में बैठकर सुनना चाहूँगा, तुम्हें चुप कराने के लिए नहीं। तुम्हें अपने नाम की ज़मीन चाहिए तो ज़मीन तुम्हारे नाम पर होगी, सिर्फ मेरे नाम पर नहीं।”</p>\n<p>विक्रम ने उसके हाथ हल्के से दबाए।</p>\n<p>“तुम्हें अपने बारे में जिस भी चीज़ के खो जाने का डर है, मैं नहीं चाहता कि तुम उसे मेरे लिए छोड़ो।”</p>\n<p>विक्रम ने एक पल बगल में रखी तस्वीर की ओर देखा।</p>\n<p>“मुझे इसी लड़की से मोहब्बत हुई है, नैना। बस अब ये बड़ी हो गई है।”</p>\n<p>नैना की आँखें उससे नहीं हटीं।</p>\n<p>“मुझे इसका छोटा किया हुआ रूप नहीं चाहिए। कभी नहीं।”</p>\n<p>थोड़ी देर वह चुप रही।</p>\n<p>नैना की उँगली फिर तस्वीर के किनारे तक गई और धीरे से उस पर फिरने लगी।</p>\n<p>“मैंने ये बात कभी किसी को नहीं बताई,” नैना ने आख़िर कहा। “सुनैना को भी नहीं। शायद आज से पहले मैंने भी इसे इतने साफ़ शब्दों में कभी नहीं सोचा था।”</p>\n<p>“अच्छा किया मुझे बता दिया,” विक्रम ने कहा।</p>\n<p>“हाँ।”</p>\n<p>नैना ने तस्वीर फिर उठाई।</p>\n<p>सोलह साल की उस लड़की को देर तक देखा और इस बार उसे बाकी तस्वीरों के बीच दबाकर रखने के बजाय सबसे ऊपर रख दिया—जैसे इतने साल बाद उसे उसकी अपनी जगह वापस दे रही हो।</p>\n<p>फिर नैना ने विक्रम की ओर देखा।</p>\n<p>“मुझे लाउड ही रखना, विक्रम।”</p>\n<p>विक्रम चुपचाप उसे देखता रहा।</p>\n<p>“हमारे साथ जो भी हो… ज़िंदगी हम दोनों को जहाँ भी ले जाए, मुझसे वादा करो कि मुझे लाउड ही रहने दोगे।”</p>\n<p>“वादा।”</p>\n<p>विक्रम ने कहा, और उस वक्त जितनी सच्चाई से कोई कह सकता था, उतनी ही सच्चाई से कहा।</p>\n<p>शांत दोपहर में ऐसा वादा करना आसान था। चंदन की अगरबत्ती लगभग बुझ चुकी थी और अभी ज़िंदगी ने उन दोनों से उस वादे को साबित करने के लिए कुछ माँगा भी नहीं था।</p>\n<p>विक्रम यह बात जानता था।</p>\n<p>फिर भी उसने वादा किया।</p>\n<p>अगरबत्ती की राख की आख़िरी लकीर हिली और बिखर गई।</p>\n<p>विक्रम के मन में एक ख़याल ज़रूर आया—</p>\n<p>जब इस वादे की परीक्षा होगी, ज़िंदगी पहले किसे आजमाएगी?</p>"}, {"chapter": 26, "title": "अध्याय 24 — बात महाकाल की नहीं थी", "content": "<h1>अध्याय 24 — बात महाकाल की नहीं थी</h1>\n<p>बात इतनी छोटी-सी थी कि झगड़े के बीच दोनों में से कोई ठीक-ठीक नहीं बता सकता था कि वह इतनी बड़ी कैसे हो गई। कभी-कभी एक छोटी-सी चिंगारी को बस सही सूखा मौसम मिल जाता है, और फिर आग उस बात से कहीं आगे निकल जाती है जहाँ से वह शुरू हुई थी।</p>\n<p>नैना ने विक्रम की अगली छुट्टी के लिए उज्जैन जाने का प्लान बना लिया था—महाकाल के दर्शन के लिए। पूरा वीकेंड तय कर दिया था, जबकि विक्रम ने अभी यह भी पक्का नहीं किया था कि उसे कितनी छुट्टी मिलेगी। यह इस छुट्टी की नहीं, अगली बार की योजना थी।</p>\n<p>गुरुवार की शाम थी। नैना ने खाने के लिए सब्ज़ी चढ़ा रखी थी, जो बातचीत बढ़ते-बढ़ते लगभग भुला दी गई। गैस पर धीमी आँच में पकती सब्ज़ी की खुशबू अब धीरे-धीरे जलने की गंध में बदल रही थी। बंद खिड़की के उस पार सोहना रोड का ट्रैफिक हमेशा की तरह शोर कर रहा था—शहर को उनके झगड़े से कोई लेना-देना नहीं था।</p>\n<p>“तुम्हें मुझसे पूछ लेना चाहिए था,” विक्रम ने कहा।</p>\n<p>विक्रम की आवाज़ में जितनी सख़्ती वह चाहता था, उससे कुछ ज़्यादा आ गई।</p>\n<p>“मुझे नहीं लगा मंदिर जाने का प्लान बनाने के लिए तुम्हारी परमिशन चाहिए।”</p>\n<p>“मैंने ये नहीं कहा, और तुम जानती हो। मैं सिर्फ कह रहा हूँ कि हम दोनों का पूरा वीकेंड तय करने से पहले एक बार पूछ तो सकती थीं कि मैं उस वक्त फ्री भी हूँ या नहीं। अगर छुट्टी नहीं मिली तो? अगर ड्यूटी ने रोक लिया तो?”</p>\n<p>“तो तुम कह दोगे आर्मी को तुम्हारी ज़रूरत है—जैसे हमेशा होती है। और मैं अकेली चली जाऊँगी, जैसे बहुत-सी जगह तुम्हारे बिना जाती रही हूँ।”</p>\n<p>नैना की आवाज़ में अब वह पुरानी धार उतर आई थी जिसे कभी विक्रम पसंद करता था, मगर इस वक्त वही धार चुभ रही थी।</p>\n<p>“अपनी ज़िंदगी तुम्हारी छुट्टियों और पोस्टिंग के हिसाब से चलाने की आदत हो गई है मुझे, विक्रम। बस ये नहीं पता था कि अपना कोई प्लान बनाने से पहले भी तुम्हारी इजाज़त लेनी पड़ेगी।”</p>\n<p>“ये बात ठीक नहीं है,” विक्रम ने कहा। वह रसोई के दरवाज़े पर बाँहें बाँधे खड़ा था।</p>\n<p>“और महाकाल ही क्यों? तुमने पहले कभी नहीं कहा कि तुम्हें वहाँ जाना है।”</p>\n<p>नैना का चेहरा ज़रा-सा बदल गया।</p>\n<p>नैना ने हाथ में पकड़ा चम्मच नीचे रख दिया। गैस पर कड़ाही से धुआँ उठने लगा था। किसी ने उधर नहीं देखा।</p>\n<p>“क्योंकि मुझे डर लग रहा है, विक्रम।”</p>\n<p>विक्रम की बाँहें अपने-आप ढीली हो गईं।</p>\n<p>“मुझे डर है कि अगर बाबा हमारे ख़िलाफ़ हो गए तो क्या होगा। मैंने अपनी कितनी सहेलियों के रिश्ते सिर्फ इसलिए टूटते देखे हैं कि घरवाले लव मैरिज के लिए तैयार नहीं हुए।”</p>\n<p>वह रुकी।</p>\n<p>“मैं महाकाल के सामने जाकर कुछ माँगना चाहती थी। ऐसी चीज़ जिसे शायद अभी खुलकर माँगने का हक भी पूरी तरह नहीं है मुझे—कि आगे जो भी आए, हम दोनों उसमें साथ रहें।”</p>\n<p>अब नैना की आवाज़ में गुस्सा कम था।</p>\n<p>“मैं तुम्हें ये सब तब तक नहीं बताना चाहती थी जब तक ख़ुद नहीं समझ लेती कि मेरे भीतर चल क्या रहा है। इसलिए मैंने बस प्लान बना दिया। ग़लत तरीके से बनाया, ज़ाहिर है… क्योंकि जिसके लिए ये सब था, उसी से पूछना भूल गई।”</p>\n<p>“तुमने मुझे बताया नहीं कि तुम्हें अपने पापा को लेकर इतना डर लग रहा है।”</p>\n<p>“क्योंकि उसे बोल देती तो वह और सच लगने लगता।”</p>\n<p>नैना ने नज़र फेर ली। बाँहें अब भी सीने पर बँधी थीं, मगर उनमें पहले वाली अकड़ नहीं रही थी।</p>\n<p>“जिन चीज़ों में तुम्हारी जान ख़तरे में पड़ती है, उनमें मेरी कोई राय नहीं चलती। मैं जानती हूँ। मुझे लगा कम-से-कम इतना तो कर सकती हूँ कि हम दोनों के लिए किसी मंदिर में जाकर कुछ माँग लूँ। और अब हम यहाँ खड़े एक वीकेंड को लेकर लड़ रहे हैं।”</p>\n<p>“ऑपरेशन में तुम्हारी राय कैसे शामिल करूँ, नैना? आर्मी मुझे उस तरह की गुंजाइश देती ही नहीं।”</p>\n<p>“मैं तुमसे आर्मी के साथ बैठकर अपनी ड्यूटी तय करने को नहीं कह रही।”</p>\n<p>नैना ने तुरंत विक्रम की तरफ देखा।</p>\n<p>“मैं सिर्फ ये चाहती हूँ कि तुम मुझे उस इंसान की तरह देखो जिसके डर भी उतने ही मायने रखते हैं जितने तुम्हारे। फ़ैसले में राय देना एक बात है, और डर का सुना जाना दूसरी—मुझे नहीं लगता तुमने अभी तक इस फ़र्क़ को पूरी तरह समझा है।”</p>\n<p>“तो मुझे साफ़-साफ़ बताया करो कि तुम्हें मुझसे चाहिए क्या। मुझसे अंदाज़ा लगाने की उम्मीद मत रखो।”</p>\n<p>नैना ने बिना देर किए कहा—</p>\n<p>“बताना ही तो सबसे मुश्किल है।”</p>\n<p>बस इतना।</p>\n<p>मगर उन शब्दों का वज़न किसी लंबी शिकायत से ज़्यादा था।</p>\n<p>विक्रम चुप हो गया।</p>\n<p>“मैं तुमसे लड़ने की कोशिश नहीं कर रही,” नैना ने थोड़ी देर बाद कहा। आवाज़ अब धीमी थी, जैसे गुस्सा जलकर थकान में बदल चुका हो। “मैं कई हफ्तों से अपने भीतर एक बात दबाकर बैठी थी। आज ग़लत तरीके से बाहर आ गई। और अब हम मंदिर जाने पर चिल्ला रहे हैं, जबकि बात कभी मंदिर की थी ही नहीं।”</p>\n<p>कुछ पल दोनों वहीं खड़े रहे।</p>\n<p>साँसें ज़रूरत से कुछ तेज़ थीं और वह छोटा-सा फ्लैट अचानक इतना छोटा लगने लगा था जैसे अभी-अभी कही गई सारी बातें उसकी दीवारों में समा नहीं पा रही हों।</p>\n<p>“मैं थोड़ी देर बाहर जा रही हूँ।”</p>\n<p>नैना ने जवाब का इंतज़ार नहीं किया।</p>\n<p>दरवाज़ा नैना के पीछे कुछ ज़्यादा ज़ोर से बंद हुआ—इतना नहीं कि उसे पटकना कहा जाए, मगर इतना ज़रूर कि विक्रम देर तक उस आवाज़ को सुनता रहा।</p>\n<p>कमरे में अकेला रह जाने के बाद विक्रम ने गैस बंद की। कड़ाही की तली में सब्ज़ी काली पड़ चुकी थी।</p>\n<p>उसने पूरे झगड़े को दोबारा अपने भीतर चलने दिया। उसे मानना पड़ा कि नैना पूरी तरह ग़लत नहीं थी।</p>\n<p>विक्रम नैना से मोहब्बत करने का एक तरीका सीख चुका था—उसकी हिफ़ाज़त करना, उसका ख़याल रखना, फ़ैसले लेना और फिर उन्हें जितना हो सके नरमी से उसके सामने रख देना। अपने मन में वह इसे परवाह समझता रहा था।</p>\n<p>मगर नैना की तरफ से कई बार वही परवाह उसकी ज़िंदगी को उसके लिए तय कर देने जैसी लगी थी।</p>\n<p>और इन सबके नीचे वह अपने पिता को लेकर एक डर अकेली उठाए घूम रही थी, इतना चुपचाप कि विक्रम ने उसके वज़न को पहचाना तक नहीं।</p>\n<p>उधर नैना बिना किसी मंज़िल के अपनी बिल्डिंग के आसपास की सड़क पर चलती रही। शाम की हल्की ठंड से बचने के लिए नैना ने बाँहें अपने चारों ओर समेट रखी थीं और वही झगड़ा अपने हिस्से से दोबारा देख रही थी।</p>\n<p>सोहना रोड की पीली बत्तियों के नीचे उसकी परछाईं कभी लंबी होती, कभी सिमट जाती।</p>\n<p>नैना ने अपनी दुआ एक ट्रैवल प्लान के भीतर रख दी थी और उम्मीद की थी कि विक्रम बिना बताए समझ जाएगा कि उस प्लान के भीतर क्या माँगा जा रहा है।</p>\n<p>करीब एक घंटे बाद नैना लौटी।</p>\n<p>गुस्सा रास्ते में कहीं छूट चुका था। शाम की ठंडी हवा ने वह काम कर दिया था जो थोड़ी देर पहले वे दोनों नहीं कर पाए थे।</p>\n<p>दरवाज़े पर खड़ी होकर नैना ने कहा, “सॉरी। मैंने आवाज़ ऊँची कर दी। और तुमसे पूछे बिना प्लान बना दिया।”</p>\n<p>“आवाज़ के लिए सॉरी मत बोलो।”</p>\n<p>विक्रम उठकर उसके पास आया।</p>\n<p>“ज़्यादातर बातों में तुम सही थीं। मैं कई बार फ़ैसले ख़ुद कर लेता हूँ और फिर तुम्हें बताता हूँ, जबकि मुझे उन्हें तुम्हारे साथ मिलकर तय करना चाहिए। आज तक मुझे ये फ़र्क़ ठीक से दिखाई नहीं दिया था।”</p>\n<p>नैना चुपचाप सुनती रही।</p>\n<p>“और मुझे ये भी नहीं पता था कि तुम अपने पापा को लेकर इतने वक्त से ये डर अकेली लिए घूम रही हो। दोनों बातों के लिए सॉरी।”</p>\n<p>नैना के कंधों में जो तनाव अब तक बचा हुआ था, वह थोड़ा ढीला पड़ा।</p>\n<p>“मैं दोबारा ऐसे नहीं लड़ना चाहती। इतनी छोटी-सी बात इतनी जल्दी इतनी बड़ी हो गई… थोड़ा डर लगा मुझे।”</p>\n<p>“मुझे भी।”</p>\n<p>विक्रम ने उसका हाथ थामा और इस बार नैना ने उसे पीछे नहीं खींचा।</p>\n<p>“मैं नहीं चाहता कि तुम्हें अपनी ही ज़िंदगी के बारे में फ़ैसले सुनने का इंतज़ार करना पड़े। मैं तुम्हारे साथ ज़िंदगी बनाना चाहता हूँ, नैना—पहले अकेले सब तय करके बाद में तुम्हें ख़बर नहीं देना चाहता।”</p>\n<p>विक्रम ने नैना की उँगलियाँ अपने हाथ में और कस लीं।</p>\n<p>“और हमारे बारे में जो डर हैं, उन्हें भी अकेले मत उठाया करो। तुम्हारे पापा हों या आगे कुछ और—जो भी आएगा, हम दोनों का होगा। मैं नहीं चाहता कि तुम हमारे हिस्से की दुआ भी किसी मंदिर में अकेली माँगने जाओ।”</p>\n<p>नैना के चेहरे की बची हुई सख़्ती आख़िर पिघल गई।</p>\n<p>“बस यही सुनना चाहती थी।”</p>\n<p>नैना उसके करीब आई और माथा विक्रम के सीने पर टिका दिया।</p>\n<p>फिर वहीं खड़े-खड़े बोली, “मैं अभी भी उज्जैन जाना चाहती हूँ। बस इस बार चाहती हूँ कि तुम भी मेरे साथ चलो—अगर आर्मी जाने दे। और इसलिए नहीं कि मैंने तारीख़ें तय कर दी हैं। इसलिए कि तुम ख़ुद वहाँ होना चाहते हो।”</p>\n<p>“मैं वहाँ होना चाहता हूँ।”</p>\n<p>नैना ने सिर उठाकर उसकी तरफ देखा।</p>\n<p>विक्रम ने कहा—</p>\n<p>“उसके लिए भी… और उसके बाद जो कुछ आएगा, उसके लिए भी।”</p>\n<p>उस शाम दोनों ने नैना के पिता का नाम फिर नहीं लिया।</p>\n<p>मगर वह बात कमरे से गई भी नहीं।</p>\n<p>वह वहीं कहीं उनके बीच ठहरी रही—बिना जल्दबाज़ी किए, अपने वक्त का इंतज़ार करती हुई।</p>\n<p>क्योंकि कुछ बातें आने से पहले कोई शोर नहीं करतीं।</p>\n<p>बस धीरे-धीरे करीब आती रहती हैं।</p>"}, {"chapter": 27, "title": "अध्याय 25 — महाकाल", "content": "<h1>अध्याय 25 — महाकाल</h1>\n<p>अगली छुट्टी आई तो विक्रम बादशाहपुर से बैग लेकर दोपहर में ही नैना के फ्लैट पहुँच गया। शाम को वहीं से उन्होंने नई दिल्ली रेलवे स्टेशन के लिए कैब ली और ट्रेन आने से काफी पहले पहुँच गए। रात की ट्रेन थी, अगले दिन उज्जैन पहुँचाने वाली—करीब पंद्रह घंटे का सफ़र।</p>\n<p>रिज़र्वेशन एसी थ्री-टियर के बी-3 कोच में था, सीट नंबर 41 और 44, दोनों लोअर बर्थ। नैना ने बुकिंग के वक्त इस बात का खास ख़याल रखा था।</p>\n<p>बैग सीट के नीचे रखते हुए नैना ने कहा, “चलती ट्रेन में आधी रात को सीढ़ी चढ़ने का मेरा कोई इरादा नहीं है। लोअर बर्थ मिलेगी, वरना कुछ नहीं।”</p>\n<p>धीरे-धीरे डिब्बा भरने लगा। दो हिस्से छोड़कर एक परिवार अपने दो छोटे बच्चों के साथ बैठा था; सामने कुछ दूरी पर एक बुज़ुर्ग दंपती ने ट्रेन चलने से पहले ही टिफिन खोल लिया था। ऊपर की जगह में बैग ठूँसने की आवाज़ें, सीटें ढूँढ़ते लोग और बीच-बीच में निकलता चायवाला—रेल का वही जाना-पहचाना संसार उनके चारों ओर बसने लगा।</p>\n<p>दिल्ली पूरी तरह पीछे भी नहीं छूटी थी कि विक्रम ने चायवाले से दो कप ले लिए। प्यास से ज़्यादा आदत में।</p>\n<p>शाम से नैना कुछ शांत थी, मगर वह पिछली लड़ाई के बाद वाली संभली हुई चुप्पी नहीं थी। वह खिड़की से बाहर सरकते अँधेरे को देखती रही और उसका हाथ दोनों के बीच बर्थ पर विक्रम के हाथ में ढीला-सा पड़ा रहा। काँच में दोनों के चेहरे धुँधले पड़ते और बाहर की रोशनियाँ उनके बीच से गुज़र जातीं।</p>\n<p>आधी रात के बाद, जब दोनों अब भी जाग रहे थे, नैना ने कहा, “मैंने शायद कभी ऐसे मंदिर का सफ़र नहीं किया।”</p>\n<p>“कैसे?” विक्रम ने पूछा।</p>\n<p>“सिर्फ कुछ माँगने के लिए। मंदिर जाती रही हूँ, लेकिन ज़्यादातर आदत में… या माँ को साथ चाहिए होता था इसलिए। ऐसा पहली बार है कि मैं किसी एक बात को लेकर जा रही हूँ।”</p>\n<p>“क्या माँगोगी?” विक्रम ने पूछा।</p>\n<p>नैना चुप रही।</p>\n<p>“पता नहीं माँगने से पहले उसे बोलना चाहिए या नहीं। बेवकूफ़ी है शायद, लेकिन लगता है पहले ही कह दिया तो जिस किस्मत के भरोसे उसे वहाँ तक पहुँचना है, उसका थोड़ा असर यहीं खर्च हो जाएगा।”</p>\n<p>विक्रम मुस्कराया।</p>\n<p>“तो मत बताओ। मैं भी कुछ माँग लूँगा। बाद में हिसाब मिलाना ज़रूरी नहीं है।”</p>\n<p>नैना के चेहरे पर हल्की-सी मुस्कान आई।</p>\n<p>“तुम क्या माँगोगे?”</p>\n<p>“शायद वही जो तुम नहीं बता रही।”</p>\n<p>विक्रम ने नैना का हाथ हल्के से दबाया।</p>\n<p>“मुझे नहीं लगता हम दोनों को उसे बोलने की ज़रूरत है। दोनों जानते हैं।”</p>\n<p>मथुरा के आगे कहीं ट्रेन अपनी स्थिर लय पकड़ चुकी थी। बर्थ लगने के बाद दोनों ने पतले कंबल खोल लिए। बाहर छोटे कस्बों की रोशनियाँ अब पहले से ज़्यादा दूरी पर दिखाई देतीं और अँधेरे में पीछे छूट जातीं।</p>\n<p>भोपाल पहुँचते-पहुँचते दोनों फिर पूरी तरह जाग चुके थे।</p>\n<p>सुबह का वक्त होने के बावजूद प्लेटफॉर्म में नींद का कोई निशान नहीं था। ऊपर रेलवे की वही कटी-छँटी अंग्रेज़ी में अनाउंसमेंट बार-बार दोहराई जा रही थी और बाकी आवाज़ों को चीरती हुई कहीं से पुकार उठ रही थी—</p>\n<p>“चाय… गरम चाय…”</p>\n<p>दोनों थोड़ी देर पैर सीधे करने के लिए नीचे उतर आए और दो कुल्हड़ ले लिए। चाय इतनी गर्म थी कि तुरंत पीना मुश्किल और इतनी मीठी कि स्टेशन की चाय होने में कोई शक नहीं रह जाता था।</p>\n<p>खुले दरवाज़े के पास खड़े होकर वे उसे पीते रहे। आसपास कुलियों और यात्रियों की आवाज़ें थीं, अनाउंसमेंट था, दूर किसी दूसरी ट्रेन के ब्रेक की लंबी-सी फुफकार थी।</p>\n<p>कुल्हड़ दोनों हथेलियों में थामे नैना ने कहा, “ऐसी सुबहों की आदत पड़ सकती है मुझे—शोर, कोई प्लान नहीं और ज़रूरत से ज़्यादा मीठी चाय।”</p>\n<p>“हमारी आम सुबहों से तो बेहतर है।”</p>\n<p>“बहुत बेहतर।”</p>\n<p>थोड़ी देर में ट्रेन फिर चल पड़ी। भोपाल के आगे किसी स्टेशन से नाश्ता लिया और बाकी सफ़र आसानी से कट गया। खिड़की के बाहर मध्य प्रदेश का भूगोल अपना रंग और उतार-चढ़ाव बदलता रहा।</p>\n<p>उज्जैन जंक्शन पर उतरते-उतरते दोपहर करीब आ चुकी थी। ट्रेन तय समय से कुछ देर पीछे थी, मगर इतनी नहीं कि दोनों को फ़र्क़ पड़ता। शहर जाग चुका था और प्लेटफॉर्म तक कहीं दूर बजती मंदिर की घंटियाँ सुनाई दे रही थीं।</p>\n<p>महाकाल मंदिर स्टेशन से मुश्किल से दो किलोमीटर था। आगे का रास्ता उन्होंने ऑटो से तय किया।</p>\n<p>पुराने शहर की ओर बढ़ते हुए क्षिप्रा एक झलक के लिए दिखाई दी—चौड़ी, शांत गति से बहती हुई; घाटों पर स्नान करते लोगों और रोज़मर्रा की हलचल के बीच जैसे सदियों से शहर की अपनी रफ्तार से बेपरवाह।</p>\n<p>उज्जैन की चाल में भी कुछ ऐसा था मानो यहाँ दिन घड़ी देखकर नहीं, मंदिर की घंटियों के साथ आगे बढ़ता हो।</p>\n<p>मंदिर सामने आया तो उसका प्रभाव उसकी ऊँचाई से ज़्यादा उसकी मौजूदगी में था। हल्के आसमान के सामने नक्काशीदार पत्थरों की परतों में ऊपर उठता शिखर—भूमिज, मराठा और चालुक्य स्थापत्य की अलग-अलग छापें, जिन्हें सदियों के निर्माण और पुनर्निर्माण ने एक-दूसरे पर रखा था। कुछ भी पूरी तरह एक जैसा नहीं था, फिर भी सब मिलकर ऐसा लगता था जैसे वह इमारत अपने किसी एक हिस्से से कहीं ज़्यादा पुरानी हो।</p>\n<p>बाहरी द्वार से ही श्रद्धालुओं की कतार शुरू हो चुकी थी। हवा में धूप-अगरबत्ती की गंध और मंत्रों का धीमा स्वर घुला था। वे आँगनों से होते हुए आगे बढ़ते रहे; बाहर बढ़ती गर्मी के बावजूद पैरों के नीचे पत्थर अब भी ठंडा था।</p>\n<p>गर्भगृह जितना करीब आता गया, नैना उतनी ही शांत होती गई। नैना की उँगलियाँ विक्रम के हाथ पर कसती चली गईं।</p>\n<p>आख़िरी सीढ़ियाँ उतरकर जब वे धरातल से नीचे बने गर्भगृह में पहुँचे, तो जैसे बाहर का शहर वहीं ऊपर छूट गया।</p>\n<p>हवा तक अलग महसूस होती थी—धुएँ से भारी, भस्म की मिट्टी-सी गंध और वर्षों से जलते घी के दीपकों की महक अपने भीतर समेटे हुए।</p>\n<p>सामने दक्षिणमुखी ज्योतिर्लिंग था—बारह ज्योतिर्लिंगों में महाकाल की वह विशिष्टता जिसे कतार आगे बढ़ाते हुए पुजारी ने लगभग सहज ढंग से कहा, मगर जाने क्यों वह छोटी-सी बात विक्रम के भीतर अपेक्षा से कहीं गहरी उतर गई।</p>\n<p>प्राचीन काला पत्थर उस सुबह की चढ़ी भस्म, फूलों और दूसरी पूजन सामग्री के नीचे मुश्किल से दिखाई दे रहा था। आसपास जलते दीपकों की काँपती नारंगी लौ कभी उसे उजाले में लाती, कभी फिर छाया में छोड़ देती। पुजारी अपनी पूजा में उसी सहज लय से लगे थे जो हजारों बार दोहराए गए कर्म से आती है।</p>\n<p>नैना ने आँखें बंद कर लीं।</p>\n<p>नैना के होंठ बहुत धीमे हिल रहे थे, मगर विक्रम ने शब्द सुनने की कोशिश नहीं की। नैना का खाली हाथ अपने सीने पर टिका था, जैसे भीतर की किसी चीज़ को वहीं थामे रखना चाहती हो। विक्रम ने नैना को इतनी स्थिरता से कभी नहीं देखा था—नींद में भी नहीं।</p>\n<p>थोड़ी देर बाद विक्रम ने भी आँखें बंद कर लीं।</p>\n<p>और हैरानी की बात यह थी कि विक्रम को अपनी दुआ सोचनी नहीं पड़ी।</p>\n<p>न प्रमोशन।</p>\n<p>न अगली पोस्टिंग में अपनी सलामती।</p>\n<p>न अपने लिए कुछ और।</p>\n<p>विक्रम ने बस इतना माँगा कि जिस ज़िंदगी को वे दोनों धीरे-धीरे साथ बुन रहे थे, उसके और उनके बीच जो कुछ भी खड़ा हो—एक पिता का डर, दूरियाँ, अपनी ड्यूटी या कोई ऐसी मुश्किल जिसका नाम वे अभी जानते भी न हों—वह रास्ता रोकने के बजाय किसी तरह रास्ते से हट जाए।</p>\n<p>बस इतना।</p>\n<p>जब दोनों सीढ़ियाँ चढ़कर वापस धूप में आए, नैना की आँखों में नमी थी। वह रो नहीं रही थी; जैसे भीतर कुछ इतना भर गया हो कि आँखों तक आ पहुँचा हो और अब उतरने के लिए थोड़ा वक्त माँग रहा हो।</p>\n<p>“ठीक हो?” विक्रम ने पूछा।</p>\n<p>“ठीक से भी ज़्यादा।”</p>\n<p>नैना ने आँखों के किनारे पोंछे और ख़ुद पर हल्का-सा हँस दी।</p>\n<p>“पता नहीं मुझे क्या हो गया था। ज़िंदगी में न जाने कितने मंदिर देखे हैं। लेकिन यहाँ… कुछ अलग लगा। जैसे एक ही वक्त में मन पर कुछ वज़न भी रख दिया हो और कुछ उतार भी दिया हो।”</p>\n<p>विक्रम ने कहा, “शायद साथ का असर है।”</p>\n<p>नैना ने उसे देखा।</p>\n<p>“शायद।”</p>\n<p>फिर नैना ने विक्रम का हाथ थाम लिया।</p>\n<p>संकरी गलियों से लौटते हुए शहर अपनी सामान्य ज़िंदगी में व्यस्त था। कहीं ठेले पर प्रसाद बिक रहा था, चमकीली साड़ियों में कुछ औरतें फोन पर तस्वीरें देख रही थीं, बच्चे श्रद्धालुओं और दुकानों के बीच से रास्ता बनाकर दौड़ रहे थे। पीछे कहीं क्षिप्रा पर अब भी दोपहर की रोशनी ठहरी हुई थी।</p>\n<p>कुछ दूर चलने के बाद नैना ने कहा, “मन हल्का लग रहा है, विक्रम। मैं यहाँ अपने भीतर कुछ लेकर आई थी जिसे मैंने तुमसे भी पूरी तरह माना नहीं था… लगता है उसका थोड़ा हिस्सा यहीं छोड़ दिया।”</p>\n<p>“अच्छी बात है।”</p>\n<p>“हाँ।”</p>\n<p>नैना चलते-चलते अचानक रुक गई और विक्रम की तरफ मुड़ गई। लोग दोनों ओर से निकलते रहे; उस भीड़ के बीच उस पल जैसे उसे किसी की परवाह नहीं थी।</p>\n<p>“मैं तुमसे प्यार करती हूँ।”</p>\n<p>विक्रम उसे देखता रहा।</p>\n<p>“शायद जितनी साफ़ तरह से, जितनी बार मुझे ये कहना चाहिए था, मैंने नहीं कहा। जितना इसका मतलब मेरे लिए है, उतना शब्दों में रखा ही नहीं।”</p>\n<p>नैना की आवाज़ में इस बार कोई झिझक नहीं थी।</p>\n<p>“मैं तुमसे प्यार करती हूँ, विक्रम। और आज इतने लोगों के बीच ये कहने से डर नहीं लग रहा।”</p>\n<p>“मैं भी तुमसे प्यार करता हूँ।”</p>\n<p>कुछ डर महीनों तक चुपचाप ढोने से बेहतर किसी मंदिर में एक बार कह देना था।</p>\n<p>वे दो दिन और उज्जैन में रहे। कोई खास योजना नहीं बनाई। छोटी जगहों पर खाना खाया, शामें नदी के किनारे बिताईं और कभी बहुत कुछ, कभी बिल्कुल बेकार की बातें करते रहे—उस बेफिक्री से जो अक्सर तभी लौटती है जब दो लोग मिलकर कोई भारी चीज़ थोड़ी देर के लिए ज़मीन पर रख चुके हों।</p>\n<p>वापसी की ट्रेन में बैठने तक उस छोटे-से फ्लैट में उनके बीच जो कुछ दरका था, वह पहले से मजबूत होकर जुड़ चुका था। इसलिए नहीं कि झगड़ा हुआ ही नहीं था, बल्कि इसलिए कि उन्होंने उसे सिर्फ बीत जाने नहीं दिया—उससे कुछ सीखा भी था।</p>\n<p>विक्रम की छुट्टी ख़त्म होने से पहले एक मंगलवार की शाम वे फिर लीजर वैली गए।</p>\n<p>वही पुरानी बेंच।</p>\n<p>वही गुलमोहर।</p>\n<p>मगर इस बार पेड़ वैसा नहीं था जैसा उनकी पहली मुलाक़ात के दिन था।</p>\n<p>वह पूरी तरह खिल चुका था।</p>\n<p>ऊपर शाखाओं पर नारंगी-लाल फूल इतने घने थे कि बेंच के ऊपर जैसे आग के रंग की एक छत तन गई हो।</p>\n<p>नैना ने सिर उठाकर देर तक उसे देखा।</p>\n<p>“हम कभी इसे ऐसे खिला हुआ देखकर यहाँ नहीं बैठे।”</p>\n<p>“नहीं।”</p>\n<p>“हर बार या तो खाली था, या बस कलियाँ आने लगी थीं। पहली बार लग रहा है जैसे ये वैसा दिख रहा है जैसा इसे होना चाहिए।”</p>\n<p>विक्रम ने ऊपर देखा।</p>\n<p>“पता नहीं क्यों… सही वक्त लगता है इसे ऐसे देखने का।”</p>\n<p>“मुझे भी।”</p>\n<p>नैना की नज़र पेड़ से उतरकर विक्रम पर आ गई और चेहरे पर धीरे-धीरे एक नरमी फैल गई।</p>\n<p>“मुझे ये जगह बहुत पसंद है, विक्रम। कभी-कभी लगता है हमारी कहानी यहीं से शुरू हुई थी… और उसका कुछ हिस्सा तब से यहीं रह गया।”</p>\n<p>वह चुप रही।</p>\n<p>जब दोबारा बोली तो आवाज़ पहले से धीमी थी।</p>\n<p>“तुम जानते हो न… मैं तुम्हारे बिना रह तो लूँगी। रहना सीख भी लूँगी।”</p>\n<p>विक्रम ने उसकी ओर देखा, मगर बीच में कुछ नहीं कहा।</p>\n<p>“पर वैसी नहीं रहूँगी जैसी अब हूँ। ये सोचकर ही सच में डर लगता है। मेरी हर भावना जाने कब तुमसे जुड़ती चली गई, मुझे ख़ुद पता नहीं चला।”</p>\n<p>नैना ने ऊपर फैली शाखाओं की तरफ देखा।</p>\n<p>“अगर ये पेड़ हमारी बात सुन सकता है तो आज इसे गवाह रहने दो।”</p>\n<p>फिर नैना की नज़र वापस विक्रम पर आई।</p>\n<p>“इसी डर की वजह से मैं महाकाल जाना चाहती थी। इसीलिए वहाँ वही माँगा जो माँगा।”</p>\n<p>नैना ने धीरे से साँस छोड़ी।</p>\n<p>“और अब दिल शांत है, विक्रम। सच में।”</p>\n<p>उसी समय ऊपर कहीं से गुलमोहर की एक पंखुड़ी शाखा से छूटी।</p>\n<p>हवा में धीरे-धीरे घूमती हुई नीचे आई और नैना की खुली हथेली पर आकर ठहर गई।</p>\n<p>नैना देर तक उसे देखती रही।</p>\n<p>चेहरे पर जो भाव आया, उसे विक्रम पढ़ नहीं पाया।</p>\n<p>वह चुप रही।</p>\n<p>फिर अपनी उँगलियाँ धीरे से बंद कर लीं—</p>\n<p>और उस छोटी-सी पंखुड़ी को हथेली में सहेज लिया।</p>\n<p>“सुन रहा है,” उसने लगभग ख़ुद से कहा।</p>\n<p>विक्रम ने उसका हाथ थाम लिया—पंखुड़ी अब भी उसकी उँगलियों के बीच थी—और देर तक कुछ नहीं बोला। उसके साथ उस पेड़ के नीचे बैठा रहा, जिसने आख़िर वह सब पहन लिया था जो बनना सीखने में उसे पूरा एक साल लगा था।</p>\n<p>उस पल दोनों में से किसी ने ध्यान नहीं दिया कि पूरा खिला हुआ पेड़ वही पेड़ भी होता है, जो चुपचाप, बिना किसी को दिखे, अपने फूल छोड़ने का काम शुरू कर चुका होता है।</p>"}, {"chapter": 28, "title": "अध्याय 26 — माँ से कही हुई बात", "content": "<h1>अध्याय 26 — माँ से कही हुई बात</h1>\n<p>नैना माँ के पास उस दोपहर आई जब पिता घर पर नहीं थे।</p>\n<p>रसोई में उसकी माँ रोटियाँ बना रही थीं। लोई के चकले पर पड़ने की मुलायम थपक, गर्म तवे पर रोटी डालते ही उठती हल्की-सी सिसकारी और गेहूँ व घी की वही जानी-पहचानी खुशबू कमरे में भरी थी, जो नैना के बचपन की न जाने कितनी शामों से इस रसोई का हिस्सा रही थी।</p>\n<p>नैना माँ के पास रखे छोटे स्टूल पर उसी तरह बैठ गई जैसे बचपन में बैठा करती थी। बात सीधे कहनी थी, मगर शब्द फिर भी रास्ता घुमाकर ढूँढ़ रहे थे।</p>\n<p>“माँ… मुझे इस बार तुमसे एक बात ठीक से करनी है। सिर्फ तस्वीरें दिखाकर नहीं।”</p>\n<p>माँ ने आटे से नज़र नहीं उठाई, लेकिन बेलन की रफ्तार थोड़ी धीमी पड़ गई।</p>\n<p>“विक्रम के बारे में?”</p>\n<p>“हाँ।”</p>\n<p>नैना ने एक साँस ली।</p>\n<p>“मैं उससे शादी करना चाहती हूँ।”</p>\n<p>बेलन एक पल के लिए रुक गया।</p>\n<p>लोई की थपक बंद हो गई और रसोई में सिर्फ तवे की हल्की सरसराहट रह गई।</p>\n<p>बस एक पल।</p>\n<p>फिर माँ ने रोटी बेलनी शुरू कर दी, मगर अब पहले से धीमे।</p>\n<p>“मैं सोच रही थी ये बात कब आएगी,” उन्होंने कहा। “जिस दिन शादी की तस्वीरें दिखा रही थी, उसी दिन तेरी आवाज़ में सुन लिया था। लगा नहीं था साफ़-साफ़ कहने में इतना वक्त लगाएगी।”</p>\n<p>“मुझे समझ नहीं आ रहा था कैसे कहूँ। जब तक बात सिर्फ मेरी ज़िंदगी में चुपचाप चल रही थी, तब तक वह मेरी थी। ये कह देने के बाद… अब तुम्हें और पापा को भी उसके बारे में फ़ैसला करना पड़ेगा।”</p>\n<p>माँ ने रोटी तवे पर डाली, हाथ दुपट्टे से पोंछे और पहली बार पूरी तरह नैना की ओर मुड़ीं।</p>\n<p>“तू पक्की है? शादी की बात कर रही है? सिर्फ… जो अभी तुम दोनों के बीच है उसकी नहीं?”</p>\n<p>“पूरी तरह पक्की हूँ।”</p>\n<p>माँ देर तक नैना को देखती रहीं।</p>\n<p>माँ की आँखों में हैरानी नहीं थी। उन्होंने आटे की परात थोड़ी दूर खिसका दी—जैसे इस बात के लिए जगह बना रही हों।</p>\n<p>“तुझे पता है तेरे पापा आसानी से नहीं मानेंगे।”</p>\n<p>“पता है।”</p>\n<p>“मैंने उस दिन भी कहा था। आर्मी… उनके लिए सिर्फ यही एक शब्द काफी होगा आधा मन बंद कर लेने के लिए, लड़के को ठीक से जानने से पहले।”</p>\n<p>नैना ने बहुत धीमे कहा, “तुम्हारी वजह से?”</p>\n<p>माँ की आँखों का भाव ज़रा-सा बदल गया।</p>\n<p>“मतलब… तुम्हारी ज़िंदगी जैसी रही उसकी वजह से?”</p>\n<p>जवाब नहीं आया।</p>\n<p>“उस दिन जो कहा था, याद है?”</p>\n<p>“सब याद है।”</p>\n<p>नैना ने आगे बढ़कर माँ का हाथ पकड़ लिया।</p>\n<p>“मुझे सच-सच बताओ। क्या इतना मुश्किल था जितना तुमने उस दिन कहा था?”</p>\n<p>माँ की नज़र दोनों के जुड़े हाथों पर टिक गई।</p>\n<p>जब बोलीं तो आवाज़ में अचानक उम्र कुछ ज़्यादा सुनाई दी।</p>\n<p>“कुछ साल उससे भी मुश्किल थे। कुछ आसान भी। बेटी को ऐसी ज़िंदगी समझाना आसान नहीं होता जब उसने उसे ख़ुद जिया न हो।”</p>\n<p>माँ ने नैना की हथेली एक बार दबाई।</p>\n<p>“मैंने तुझसे कहा था न—दिल जो कर रहा है उसे करने दे, मगर आँखें खुली रखना। अगर सच कहूँ तो मुझे नहीं लगता तूने आँखें उतनी खुली रखीं।”</p>\n<p>नैना कुछ नहीं बोली।</p>\n<p>“लेकिन अब उसका कोई मतलब नहीं। जो होना था, हो चुका। अब ज़रूरी ये है कि आगे क्या करना है।”</p>\n<p>“पापा से बात करोगी?”</p>\n<p>माँ ने लंबी साँस छोड़ी।</p>\n<p>उस साँस में थकान आज की नहीं थी।</p>\n<p>“मुझे पता है क्या करना है। मैं ये नहीं कहूँगी कि बात अच्छी जाएगी। तेरे पापा को मैं जानती हूँ; बातचीत शुरू होने से पहले ही लगभग बता सकती हूँ कि ख़त्म कहाँ होगी।”</p>\n<p>फिर उन्होंने बेटी की तरफ देखा।</p>\n<p>“लेकिन पूरा वज़न तेरे मुँह से उन पर पड़ने से पहले ज़मीन थोड़ी नरम कर देना मेरा काम है।”</p>\n<p>नैना के चेहरे पर हल्की-सी मुस्कान आई।</p>\n<p>“धन्यवाद।”</p>\n<p>“अभी मत दे धन्यवाद।”</p>\n<p>माँ ने आटे से लगी उँगली उसकी ओर उठाई।</p>\n<p>“मैं सिर्फ पहले बात कर रही हूँ। फ़ैसला तेरे पापा का होगा।”</p>\n<p>“और मेरा?”</p>\n<p>माँ नैना को देखती रहीं।</p>\n<p>“तेरा फ़ैसला तो तू मुझे अभी बता चुकी है।”</p>\n<p>उन शब्दों के बाद नैना के कंधे ढीले पड़ गए।</p>\n<p>माँ ने तवे की तरफ मुड़ते हुए कहा, “और एक बात—अगर तेरे पापा नहीं माने तो इसका मतलब ये नहीं कि वह तुझे समझते नहीं या तुझसे कम प्यार करते हैं। कई बार माँ-बाप जिस चीज़ से अपने बच्चे को बचाना चाहते हैं, वही चीज़ उनके अपने पुराने घाव से निकल रही होती है।”</p>\n<p>“मुझे पता है।”</p>\n<p>“अभी तुझे लगता है पता है।” माँ ने रोटी पलटी।</p>\n<p>“देखते हैं जब वह सामने बैठकर ख़ुद कहेंगे तब कितना पता रहता है।”</p>\n<p>नैना चुप हो गई।</p>\n<p>थोड़ी देर बाद माँ ने जैसे ख़ुद से कहा, “बच्चों को चीज़ों से बचाना भी अजीब काम है। वे चाहें या न चाहें, माँ-बाप को लगता रहता है यही उनका काम है।”</p>\n<p>फिर माँ ने आटे लगे हाथ से नैना का चेहरा एक पल के लिए छुआ और थकी-सी मुस्कान के साथ कहा—</p>\n<p>“आज रात मुझे उससे बात करने दे। उसके बाद ज़रूरत पड़ी तो तू ख़ुद बात करना। लेकिन पहले मुझे जाने दे।”</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>रात को खाना ख़त्म होने और घर शांत हो जाने के बाद नैना की माँ बरामदे में अपने पति के पास जाकर बैठीं।</p>\n<p>बाहर बगीचे में कहीं कोई आवारा कुत्ता दो बार भौंका और फिर चुप हो गया। रास्ते के किनारे कतार में लगे गेंदे के फूलों की हल्की, कुछ कड़वी-सी गंध ठंडी होती हवा में घुल रही थी।</p>\n<p>उन्होंने बिना बात घुमाए सब बता दिया।</p>\n<p>वह देर तक चुप बैठे रहे। जबड़ा कसा हुआ था और नज़र अँधेरे बगीचे में कहीं स्थिर।</p>\n<p>फिर सिर्फ एक शब्द कहा—</p>\n<p>“आर्मी।”</p>\n<p>उस एक शब्द में जितना कुछ था, उसकी पत्नी पहले से जानती थी।</p>\n<p>“मुझे पता है।”</p>\n<p>“तुम्हें तो सबसे पहले इसे रोकना चाहिए था। जिस दिन उसने पहली बार उस लड़के का ज़िक्र किया था, उसी दिन।”</p>\n<p>“मैंने कोशिश की थी। अपने तरीके से। जिस दिन तस्वीरें दिखाईं, उसी दिन कहा था आँखें खुली रखना।”</p>\n<p>उनकी आवाज़ स्थिर थी, लेकिन उसके नीचे पुरानी थकान की महीन परत थी।</p>\n<p>“वह आज मेरे पास प्यार करने की इजाज़त माँगने नहीं आई थी। वह बताने आई थी कि उसका दिल अपना फ़ैसला कई हफ्ते पहले कर चुका है।”</p>\n<p>पति ने कुछ नहीं कहा।</p>\n<p>“मैं भी कभी इक्कीस साल की थी,” उन्होंने धीरे से कहा। “मुझे भी याद है अपने दिल के फ़ैसले के लिए किसी की इजाज़त की कितनी कम ज़रूरत महसूस होती थी।”</p>\n<p>बरामदे में थोड़ी देर सिर्फ रात रही।</p>\n<p>फिर उन्होंने कहा, “मैं तुमसे आज ही हाँ कहने को नहीं कह रही। बस उससे ख़ुद बात करना। ठीक से। कोई फ़ैसला करने से पहले उसकी बात सुनना। इतना तो उसका हक है—अपने पिता के मुँह से निकले साफ़ शब्द, माँ के ज़रिए पहुँची चेतावनी नहीं।”</p>\n<p>वह बहुत देर और चुप रहे।</p>\n<p>गेट के बाहर बजरी पर किसी गाड़ी के पहिए रुके और आगे बढ़ गए। दोनों ने सुना, किसी ने सिर नहीं घुमाया।</p>\n<p>फिर जब बोले तो आवाज़ पहले से भारी थी।</p>\n<p>“बात करूँगा।”</p>\n<p>उन्होंने पहली बार पत्नी की तरफ पूरी तरह देखा। उनके चेहरे पर वह कच्चापन था जो वर्षों बाद भी बहुत कम बाहर आता था।</p>\n<p>“लेकिन एक बात तुम भी समझो। क्योंकि इस बातचीत में मैं क्या लेकर बैठने वाला हूँ, उसे इस घर में तुमसे बेहतर कोई नहीं जानता।”</p>\n<p>वह रुके।</p>\n<p>“मैंने देखा है उस ज़िंदगी ने तुम्हारे साथ क्या किया। अपनी तरफ से भी जिया और तुम्हारी तरफ से भी जितना देख सकता था, देखा। इतने साल बाद भी अपनी बेटी को वही बोझ उठाते देखने की इच्छा नहीं है मुझमें।”</p>\n<p>उन्होंने आगे कुछ नहीं कहा।</p>\n<p>कहने की ज़रूरत भी नहीं थी।</p>\n<p>उस डर के नीचे एक पुराना दुख था, जो वर्षों में ख़त्म नहीं हुआ था—बस इंसान ने उसके साथ रहना सीख लिया था। अपनी सर्विस के उन सालों का हिसाब, जिनमें उन्हें हमेशा लगता रहा कि उनकी वर्दी ने उनकी पत्नी से उतना माँग लिया जितना किसी मोहब्बत को माँगने का हक नहीं होना चाहिए था।</p>\n<p>वह कर्ज जिसे वह आज तक पूरा चुका नहीं पाया था।</p>\n<p>और जिसे विरासत की तरह अपनी बेटी के हाथों में देने का उनका कोई इरादा नहीं था।</p>\n<p>नैना की माँ ने बहुत धीरे कहा—</p>\n<p>“मुझे पता है।”</p>\n<p>फिर थोड़ी देर बाद—</p>\n<p>“लेकिन मैंने वह सब इसलिए उठाया क्योंकि तुमसे इतनी मोहब्बत थी कि उठा सकी। उसकी भी कोई कीमत है। जब नैना से बात करना, तो उस हिस्से को मत भूल जाना।”</p>\n<p>उन्होंने जवाब नहीं दिया।</p>\n<p>कंधों में वर्षों से अटका कोई तनाव एक पल के लिए थोड़ा ढीला पड़ा, जैसे रात के उस सुनसान बरामदे में बहुत देर से रोकी हुई साँस आख़िर चुपचाप बाहर निकल गई हो।</p>\n<p>उस समय दोनों में से किसी को नहीं मालूम था कि जिस लड़के को लेकर वे बैठकर बात कर रहे थे, उसने उनकी बातचीत का इंतज़ार करने का फ़ैसला ही नहीं किया था।</p>\n<p>कुछ ही दिनों में विक्रम ख़ुद उस दरवाज़े पर खड़ा होने वाला था—</p>\n<p>बिना बुलाए नहीं,</p>\n<p>मगर बिना किसी औपचारिकता की आड़ लिए।</p>\n<p>सिर्फ इतना माँगने कि फ़ैसला सुनाने से पहले एक बार उसकी बात भी सुन ली जाए।</p>"}, {"chapter": 29, "title": "अध्याय 27 — उसके पिता के सामने", "content": "<h1>अध्याय 27 — उसके पिता के सामने</h1>\n<p>किसी औपचारिक बात की शुरुआत होने से पहले विक्रम ने ख़ुद जाकर नैना के पिता से मिलने की ज़िद की।</p>\n<p>नैना चाहती थी कि बात थोड़ी सहज तरह से शुरू हो—किसी पारिवारिक मुलाक़ात में, किसी ऐसे मौके पर जहाँ विक्रम की मौजूदगी अपने साथ इतना साफ़ मकसद लेकर न आए। लेकिन विक्रम तैयार नहीं हुआ।</p>\n<p>“पहले एक बार मैं ख़ुद उनसे बात करना चाहता हूँ। मेरे घरवाले तुम्हारे घर आएँ, उससे पहले। दो परिवार सामने बैठें उससे पहले।”</p>\n<p>“अकेले?”</p>\n<p>“हाँ।”</p>\n<p>उसने कुछ पल रुककर कहा, “अगर उन्हें मना ही करना है तो पहले मैं उनके मुँह से सुनूँ। मेरे माँ-पापा को उस इंकार के सामने बैठाने से पहले।”</p>\n<p>रविवार की सुबह वह बादशाहपुर से कार लेकर गुरुग्राम के बाहर नैना के पुश्तैनी घर पहुँचा।</p>\n<p>घर बहुत बड़ा नहीं था, मगर सलीके से रखा हुआ था। सामने छोटे-से बगीचे में रास्ते के दोनों ओर गेंदे के पौधे सीधी कतारों में लगे थे—जैसे इस घर का मालिक खूबसूरती में भी थोड़ा अनुशासन पसंद करता हो।</p>\n<p>विक्रम ने कपड़े भी वैसे ही चुने थे जैसे कोई फौजी उस दिन चुनता है जब वर्दी नहीं पहननी, मगर दिन फिर भी मामूली नहीं है—सादी, ठीक नाप की कमीज़, प्रेस की हुई पतलून, चमकाए हुए काले जूते और उनसे मिलती बेल्ट। कुछ दिखावटी नहीं, लेकिन कुछ भी लापरवाह भी नहीं।</p>\n<p>दरवाज़ा खुला तो सामने खड़े आदमी को देखकर विक्रम एक पल ठहरा।</p>\n<p>नैना के पिता करीब पचास के थे, मगर उम्र अभी उनके शरीर पर ढील बनकर नहीं उतरी थी। कंधे अब भी चौड़े थे और पीठ उस सहज सीध में थी जो वर्षों तक ‘सावधान’ की मुद्रा में खड़े रहने के बाद आदेश नहीं रहती, इंसान की आदत बन जाती है। कनपटियों के पास बाल सफ़ेद हो चुके थे, मगर आँखों की धार में कोई उम्र नहीं आई थी।</p>\n<p>उन्होंने विक्रम को सिर से पैर तक एक बार देखा।</p>\n<p>बस कुछ सेकंड।</p>\n<p>उतने ही, जितने एक पुराने सैनिक को सामने खड़े दूसरे सैनिक को पढ़ने के लिए चाहिए होते हैं।</p>\n<p>“कैप्टन राठौड़।”</p>\n<p>उन्होंने पूछा नहीं था, पहचान लिया था।</p>\n<p>नैना के पिता को पता था कि कौन आने वाला है।</p>\n<p>“सर। मिलने के लिए धन्यवाद।”</p>\n<p>“अंदर आओ।”</p>\n<p>बैठक छोटी और व्यवस्थित थी। दीवार पर कुछ पुरानी तस्वीरें थीं। एक में नैना के पिता बहुत कम उम्र के, आर्मी ड्रेस में खड़े थे; पास कुछ ऐसे मेडल की तस्वीरें थीं जिन्हें विक्रम दो दशक पुराने एक अभियान से पहचानता था। एक फीकी पड़ चुकी तस्वीर में उनकी पत्नी उनके साथ थीं—दोनों इतने जवान कि वर्तमान में बैठे आदमी से उनका रिश्ता पहचानने में एक पल लगता था।</p>\n<p>दोनों आमने-सामने बैठ गए।</p>\n<p>कुछ देर बाद नैना की माँ चाय रख गईं—उनकी उँगलियों पर आटे का हल्का-सा निशान अब भी था। जाते हुए उनकी नज़र विक्रम पर कुछ पल ठहरी—जैसे चेहरे से वह जवाब पढ़ लेना चाहती हों जो इस कमरे में अभी दिया भी नहीं गया था।</p>\n<p>दरवाज़ा बंद हुआ।</p>\n<p>नैना के पिता ने कोई भूमिका नहीं बाँधी।</p>\n<p>“मेरी बेटी का हाथ माँगने आए हो।”</p>\n<p>विक्रम सीधा बैठा रहा।</p>\n<p>“जी, सर।”</p>\n<p>“तो साफ़-साफ़ कहो। मुझे बात घुमाने वाले आदमी कभी पसंद नहीं रहे।”</p>\n<p>“मैं नैना से शादी करना चाहता हूँ। मेरे परिवार की तरफ से कोई औपचारिक बात शुरू हो, उससे पहले मैं चाहता था कि आप ये बात सीधे मुझसे सुनें।”</p>\n<p>नैना के पिता कुछ देर उसे देखते रहे।</p>\n<p>विक्रम ने उस ख़ामोशी में ख़ुद को स्थिर रखा। वह समझ रहा था कि सवाल शुरू होने से पहले भी उसे परखा जा रहा था।</p>\n<p>“शॉर्ट सर्विस कमीशन?”</p>\n<p>“जी, सर।”</p>\n<p>“दस साल?”</p>\n<p>“जी।”</p>\n<p>“उसके बाद?”</p>\n<p>“अभी पूरी तरह तय नहीं किया। शायद कोई सरकारी सेवा। कुछ साल हैं, ठीक से सोचने के लिए।”</p>\n<p>“और उन कुछ सालों में पोस्टिंग होंगी। ट्रांसफर होंगे। ऐसे ऑपरेशन होंगे जिनके बारे में तुम अपनी पत्नी को तब तक नहीं बता सकोगे जब तक वे ख़त्म न हो जाएँ।”</p>\n<p>उनकी आवाज़ में कठोरता नहीं थी।</p>\n<p>बस वह ठहराव था जो किसी ऐसी बात में आता है जिसे आदमी किताब से नहीं, ज़िंदगी से जानता हो।</p>\n<p>“मैं ठीक-ठीक जानता हूँ तुम क्या हो, कैप्टन। बहुत साल पहले मैं भी तुम्हीं था। जवान, मजबूत… और इस भरोसे से भरा कि मोहब्बत इतनी मजबूत होती है कि इस ज़िंदगी का हर वज़न उठा लेगी।”</p>\n<p>“सर—”</p>\n<p>उन्होंने हाथ हल्का-सा उठा दिया।</p>\n<p>“पहले मेरी बात पूरी होने दो।”</p>\n<p>विक्रम चुप हो गया।</p>\n<p>“मैं तुम्हारे चरित्र पर सवाल नहीं उठा रहा। जितना सुना है, अच्छे आदमी हो। स्थिर हो। शायद ऐसे अफसर भी हो जिस पर उसके जवान अपनी जान का भरोसा कर सकें। ये बात मैं हल्के में नहीं कहता।”</p>\n<p>उन्होंने चाय का कप मेज़ पर रख दिया।</p>\n<p>“मसला तुम नहीं हो, कैप्टन राठौड़। मसला वह ज़िंदगी है जो तुम्हारे साथ आती है। मैंने बीस साल से ज़्यादा वही ज़िंदगी अपनी पत्नी के साथ जी है। और मैंने देखा है उसने उसके साथ क्या किया।”</p>\n<p>विक्रम की नज़र अनायास दीवार पर लगी उस पुरानी तस्वीर की ओर गई जिसमें दोनों बहुत जवान थे।</p>\n<p>“मैं अपनी बेटी के साथ वही होते नहीं देखना चाहता।”</p>\n<p>“मैं ख़तरा समझता हूँ, सर। जितनी ईमानदारी से सोच सकता था, मैंने इस बारे में सोचा है।”</p>\n<p>“सोचना और उसके भीतर जीना दो अलग चीज़ें हैं।”</p>\n<p>नैना के पिता थोड़ा आगे झुके।</p>\n<p>“मेरी पत्नी ने हमारी आधी शादी ऐसे बिताई कि कई-कई दिन उसे पता नहीं होता था मैं ज़िंदा हूँ या नहीं। मैंने ऐसी चीज़ें मिस कीं जो किसी पिता को नहीं करनी चाहिए थीं। एक बार चोट लेकर घर आया और उसे पूरी बात कभी बता भी नहीं पाया, क्योंकि पूरी बात बताने का हक ही मेरा नहीं था।”</p>\n<p>“वह हर बार अकेली संभालती रही। और बहुत अच्छे से संभाला, क्योंकि मजबूत औरत है। मगर मजबूत होना कीमत न चुकाना नहीं होता। मैंने वह कीमत साल-दर-साल, थोड़ा-थोड़ा उसके भीतर जमा होते देखी है।”</p>\n<p>कमरे में कुछ देर सिर्फ पंखे की धीमी आवाज़ रही।</p>\n<p>दोनों के बीच रखी चाय अब ठंडी हो चुकी थी।</p>\n<p>विक्रम के पास कोई चतुर जवाब नहीं था। यह तर्क किसी पुराने ख़याल या अहंकार पर खड़ा नहीं था—इसके नीचे एक इंसान की पूरी शादी थी। उसकी नज़र फिर दीवार की उस तस्वीर पर गई, और इस बार देर तक वहीं रुकी रही।</p>\n<p>“मैं आपको ऐसी ज़िंदगी का वादा नहीं कर सकता जिसमें इसकी कोई कीमत न हो, सर। ऐसा कहूँगा तो आपका अपमान होगा।”</p>\n<p>नैना के पिता ने उसकी तरफ देखा।</p>\n<p>“अच्छा है कि कम-से-कम इतना समझते हो।”</p>\n<p>फिर उन्होंने दोनों हाथ आपस में बाँध लिए।</p>\n<p>“क्या तुम्हें लगता है, आज तुम यहाँ जो भी कहोगे, उससे वह बदल जाएगा जो मैं पहले से जानता हूँ?”</p>\n<p>विक्रम ने जवाब नहीं दिया।</p>\n<p>“अट्ठाईस साल मैंने 18 ग्रेनेडियर्स को दिए हैं। तोलोलिंग—तेरह जून। उसके तीन हफ्ते बाद टाइगर हिल। उन दो पहाड़ों के बीच मेरी बटालियन ने चौंतीस जवान खोए। अठहत्तर और जवानों को स्ट्रेचर पर नीचे लाए।”</p>\n<p>उन्होंने ये आँकड़े सपाट आवाज़ में कहे—वैसे, जैसे कोई इंसान उन गिनतियों को दोहराता है जिन्हें वह इतनी बार पढ़ चुका हो कि अब वे ताज़ा चोट नहीं करतीं।</p>\n<p>“उस साल पूरा देश जोश में डूबा था, कैप्टन। हर छत पर तिरंगा। उन लड़कों के लिए मोमबत्तियाँ, जिनके नाम लोगों ने अख़बार के पहले पन्ने से सीखे और महीने भर में भूल गए।”</p>\n<p>उन्होंने खिड़की की ओर देखा, फिर वापस।</p>\n<p>“वह गर्व मैंने भी महसूस किया था। मगर बाद में, जब शोर थम गया, मैं उन दो पहाड़ों के बीच फिर खड़ा हुआ—और तब मैंने वह देखा जो अख़बारों ने कभी नहीं छापा। जिन माँ-बाप ने उस जोश में बेटे खोए, उस जोश ने उनकी मरम्मत कभी नहीं की। देश अगली सुर्ख़ी की ओर बढ़ गया। वे परिवार कहीं नहीं बढ़े। उन्होंने बस एक ऐसा खालीपन उठाना सीख लिया, जिसे हम बाकी लोग घर जाकर भूल सकते थे।”</p>\n<p>कुछ देर वह कप को मेज़ पर धीरे-धीरे घुमाते रहे, पिए बिना।</p>\n<p>“उन्हीं दो पहाड़ों के बीच—पीछे तोलोलिंग, सामने टाइगर हिल—मैंने ख़ुद से पूरा हिसाब माँगा कि उस गर्मी में मैंने असल में क्या जीता, और क्या खोया।”</p>\n<p>उन्होंने विक्रम की आँखों में सीधे देखा।</p>\n<p>“जो जीता, वह देश का गर्व था। गाँव, जो अब चैन से सोते थे क्योंकि एक हाईवे खुला रहा। जो खोया, वह मेरे सीने के कहीं ज़्यादा पास था। उस साल मैं पैंतीस का था—इतना सीनियर कि अपनी कमान में बीस-बाईस साल के लड़कों को उस पहाड़ पर भेज सकूँ। इतना सीनियर कि मेरी उम्र के किसी भी इंसान को जितनी चिट्ठियाँ माँओं को नहीं लिखनी चाहिए, उससे कहीं ज़्यादा लिख चुका था।”</p>\n<p>“बटालियन कोई पोस्टिंग नहीं होती, कैप्टन—भर्ती के पोस्टर चाहे जो कहें। वह एक परिवार होता है, जिसे तुमने चुना नहीं। उस परिवार के जितने लोग मैंने तीन हफ्तों में दफ़नाए और कंधों पर नीचे उतारे, उतने ज़्यादातर लोग पूरी ज़िंदगी के मामूली दुख में नहीं दफ़नाते।”</p>\n<p>इस बार वह विक्रम को गौर से देखते रहे।</p>\n<p>“नैना ने मुझे तुम्हारे दोस्त के बारे में बताया था। रेड्डी—जो शहीद हुए।”</p>\n<p>उनकी आवाज़ धीमी हो गई। उसमें कुछ लगभग नरम उतर आया।</p>\n<p>“मैं जानता हूँ इतने करीबी दोस्त का जाना आदमी के साथ क्या करता है। मैंने यह अपने से बेहतर इंसानों के साथ होते देखा है। ख़ुद भी जिया है, एक से ज़्यादा बार। अगर एक इंसान के जाने ने तुम्हें उतना गहरा काटा है जितना मुझे लगता है—तो वही ज़ख़्म चौंतीस बार सोचो। और फिर सोचो कि उसके बाद का हर साल इस डर में बीते कि अगला पहाड़ फिर वही माँगेगा।”</p>\n<p>फिर बोले—</p>\n<p>“मैं भी कभी तुम्हारी उम्र का था। कारगिल से बरसों पहले। नॉर्थ-ईस्ट में ऑपरेशन करता था—छोटी-छोटी मुठभेड़ें जीतता, जिनकी ख़बर किसी अख़बार तक नहीं पहुँचती; दोस्तों को उसी चुपचाप तरीके से खोता, जिसका शोक बटालियन के बाहर कोई ठीक से नहीं मनाता। बेख़ौफ़—वैसे, जैसे सिर्फ उस उम्र का इंसान हो सकता है।”</p>\n<p>“और आज जब तुम्हें वहाँ बैठा देखता हूँ तो कोई अजनबी लड़का नहीं दिखता। कई दशक पहले का अपना चेहरा दिखता है—उस समय का, जब मुझे अभी यह समझ नहीं आया था कि मेरी बेख़ौफ़ ज़िंदगी की कीमत मुझसे ज़्यादा वे लोग चुकाएँगे जो मुझसे प्यार करते हैं।”</p>\n<p>उन्होंने कुर्सी की पीठ से शरीर थोड़ा आगे किया।</p>\n<p>“मैं तुम्हें डराने के लिए नहीं कह रहा। तुम मेरे घर में बैठकर मेरी बेटी माँग रहे हो, इसलिए कह रहा हूँ कि तुमने अभी पूरा हिसाब नहीं लगाया है। मैं रिटायरमेंट के बाद से वही हिसाब लगाता आया हूँ।”</p>\n<p>“सर, अपनी सर्विस के ख़तरे समझता हूँ।”</p>\n<p>“अपने लिए।”</p>\n<p>जवाब तुरंत आया।</p>\n<p>“मैं उस हिसाब की बात नहीं कर रहा।”</p>\n<p>वह विक्रम को देखते रहे।</p>\n<p>“तुम पैरा एसएफ़ हो, कैप्टन। जिस इंसान ने ख़तरे के बीच अपना घर बना लिया हो, वह उसकी चाबी किसी और के हाथ में देकर उसे सुरक्षित जगह नहीं कह सकता।”</p>\n<p>विक्रम ने पूछा, “फिर ऐसा क्या है जिससे आपको भरोसा होगा?”</p>\n<p>जवाब आने में एक पल भी नहीं लगा।</p>\n<p>“रेज़िग्नेशन।”</p>\n<p>विक्रम चुप हो गया।</p>\n<p>शब्द छोटा था।</p>\n<p>उसके भीतर जो माँगा गया था, वह नहीं।</p>\n<p>आज उसके कंधे पर सितारे नहीं थे, फिर भी उसे वे वहीं महसूस हुए। आर्मी सिर्फ उसकी नौकरी नहीं थी। उसके खड़े होने के ढंग से लेकर बोलने तक, ज़िम्मेदारी समझने से लेकर ख़ुद अपनी कीमत समझने तक—सब उसी वर्दी के भीतर बना था।</p>\n<p>वह तुरंत कोई बड़ा वादा नहीं करना चाहता था।</p>\n<p>कुछ देर सचमुच उस माँग को अपने भीतर तौलता रहा।</p>\n<p>फिर बोला—</p>\n<p>“ये छोटी बात नहीं है, सर।”</p>\n<p>“मुझे पता है।”</p>\n<p>“लेकिन नैना के लिए कर सकता हूँ।”</p>\n<p>नैना के पिता की आँखें बहुत स्थिर हो गईं।</p>\n<p>“शादी के बाद,” विक्रम ने कहा। “मुझे उतना वक्त दीजिए। मैं रेज़ाइन कर दूँगा।”</p>\n<p>उनके चेहरे पर कोई राहत नहीं आई।</p>\n<p>“इस वक्त वहाँ बैठकर तुमने फ़ैसला किया है कि तुम ये करोगे। तुम्हारी नीयत पर मुझे शक नहीं।”</p>\n<p>“मुझे इस बात पर शक है कि ज़िंदगी तुम्हें वह वादा पूरा करने तक उसी जगह खड़ा रहने देगी जहाँ अभी हो।”</p>\n<p>विक्रम कुछ कहने ही वाला था कि उन्होंने आगे कहा—</p>\n<p>“ड्यूटी किसी इंसान के वादे पूरे होने का शराफत से इंतज़ार नहीं करती, कैप्टन। चाहे वह वादा कितनी ही सच्ची नीयत से किया गया हो।”</p>\n<p>“मैंने ज़िंदगी में कोई कमिटमेंट नहीं तोड़ा, सर।”</p>\n<p>पहली बार नैना के पिता की आँखों में कोई ऐसी बात दिखी जो बहस से भी पुरानी थी।</p>\n<p>“वादा मैंने भी कभी जानबूझकर नहीं तोड़ा, कैप्टन। वे टूटे, क्योंकि ड्यूटी ने उन्हें टूटने दिया।”</p>\n<p>उनकी नज़र कुछ देर अपने हाथों पर टिक गई।</p>\n<p>“मेरे परिवार ने वह सब जिया जो सैनिकों के परिवार जीते हैं। और उसका पूरा वज़न मुझे बहुत बाद में पता चला। टुकड़ों में। जैसे किसी इंसान को सालों बाद वे बातें मालूम होती हैं जिन्हें उसकी पत्नी ने उस वक्त यह सोचकर उससे छिपा लिया था कि वहाँ बैठकर वह उनका कर भी क्या लेगा।”</p>\n<p>कमरे की हवा जैसे कुछ भारी हो गई।</p>\n<p>“नैना बचपन में एक बार अस्पताल में भर्ती हुई थी।”</p>\n<p>विक्रम की आँखें उनकी ओर उठीं।</p>\n<p>“करीब-करीब मर गई थी।”</p>\n<p>उनकी आवाज़ में कोई नाटकीयता नहीं थी।</p>\n<p>इसी वजह से शब्द और गहरे लगे।</p>\n<p>“‘करीब-करीब’ वाला हिस्सा मुझे महीनों बाद पता चला। मेरे लिए बात हल्की करके बताई गई थी।”</p>\n<p>उन्होंने साँस ली।</p>\n<p>“मैं उस वक्त मणिपुर में था। उग्रवादियों के ख़िलाफ़ ऑपरेशन में। ऐसी जगह जहाँ हफ्ते निगल लिए जाते थे और इंसान को पता भी नहीं चलता।”</p>\n<p>“छुट्टी मंज़ूर नहीं हुई। हो भी जाती तो ढाई हजार किलोमीटर दूर अस्पताल के उस बिस्तर तक पहुँचने में करीब एक हफ्ता लग जाता।”</p>\n<p>उनकी नज़र सीधे विक्रम पर आ टिकी।</p>\n<p>“और शायद वह बिस्तर मेरा एक हफ्ता इंतज़ार नहीं करता।”</p>\n<p>विक्रम के पास कहने को कुछ नहीं था।</p>\n<p>“मेरी पत्नी उस अस्पताल में अकेली खड़ी थी, कैप्टन। ऐसे फॉर्म पर दस्तख़त कर रही थी जिन्हें वह पूरी तरह समझती भी नहीं थी। ऐसे फ़ैसले ले रही थी जो किसी माँ को अपने पति के बिना नहीं लेने चाहिए। अपनी बेटी को ज़िंदगी के लिए लड़ते देख रही थी।”</p>\n<p>उनकी आवाज़ अब बहुत धीमी थी।</p>\n<p>“और मैं उससे इतनी दूर अपने कमरे में बैठा था जितनी दूर बहुत-से आदमी अपनी पूरी ज़िंदगी में घर से नहीं जाते। मुझे पता तक नहीं था कि मेरे घर में कोई ज़िंदगी के लिए लड़ रहा है।”</p>\n<p>उन्होंने नज़र फेर ली।</p>\n<p>“हफ्तों बाद एक चिट्ठी पहुँची। तब तक नैना ठीक हो चुकी थी।”</p>\n<p>विक्रम ने बहुत धीमे कहा, “सर… मैं समझ सकता हूँ—”</p>\n<p>“नहीं।”</p>\n<p>आवाज़ ऊँची नहीं हुई।</p>\n<p>“इस बात को तुम अभी समझ नहीं सकते। क्योंकि इस जगह पर तुम्हारी परीक्षा हुई ही नहीं है।”</p>\n<p>फिर उन्होंने जो कहा, उसमें पहली बार पिता सैनिक से बड़ा हो गया।</p>\n<p>“मैंने नैना को जानबूझकर वैसा बड़ा किया जैसा वह है—लाउड, बेख़ौफ़, अपने बाप से भी बिना डरे बहस करने वाली। मेरी पूरी अनुशासित ज़िंदगी में शायद वही एक चीज़ थी जिसे मैं आर्मी की इजाज़त के बिना बिल्कुल अपने तरीके से बना सका।”</p>\n<p>विक्रम को नैना की वह तस्वीर याद आई जो उसने कभी उसे दिखाई थी—सोलह साल की नैना, कंधे पर क्रिकेट का बल्ला, दुनिया से अपनी जगह माँगने के बजाय उसे अपना मानकर खड़ी।</p>\n<p>“अगर उसकी शादी तुमसे होती है तो मुझे डर है कि मैं वही सब उससे भी धीरे-धीरे छिनते देखूँगा।”</p>\n<p>उन्होंने विक्रम की आँखों में देखते हुए कहा—</p>\n<p>“इसलिए नहीं कि तुम कभी उस पर हाथ उठाओगे। या जानबूझकर उसे छोटा करोगे। मुझे उसका डर नहीं है।”</p>\n<p>उनकी आवाज़ अब लगभग थक चुकी थी।</p>\n<p>“डर ये है कि जो औरत हर दिन किसी अनहोनी के साथ जीती है, वह धीरे-धीरे ख़ुद को छोटा करना सीख जाती है। कोई उसे सिखाता नहीं। वह अपने आप सीखती जाती है।”</p>\n<p>इस बार विक्रम ने तुरंत जवाब नहीं दिया।</p>\n<p>क्योंकि उसके पास उस डर को झूठा कहने का कोई ईमानदार तरीका नहीं था।</p>\n<p>“मैं आपको ये वादा नहीं कर सकता कि नैना कभी ख़ुद को छोटा नहीं करेगी, सर। और ये दिखावा भी नहीं करूँगा कि मेरे पास ऐसा कोई जवाब है जो आपका डर ख़त्म कर दे।”</p>\n<p>वह सीधा उनकी ओर देखता रहा।</p>\n<p>“लेकिन जो बात मैं नैना से कह चुका हूँ, वही आपसे कह सकता हूँ। मैं अपनी पूरी कोशिश करूँगा कि इस ज़िंदगी की कीमत उसे कभी अकेले न उठानी पड़े।”</p>\n<p>विक्रम रुका।</p>\n<p>“मैं इस मामले में ग़लती पहले ही कर चुका हूँ। पंद्रह दिन उसे ये तक नहीं पता था कि मैं ज़िंदा हूँ या नहीं। मैंने पहले से ठीक तरह नहीं बताया था कि ऐसा हो सकता है। उसने वे पंद्रह दिन कैसे निकाले, मैं जानता हूँ।”</p>\n<p>“उस ग़लती ने मुझे कुछ सिखाया है।”</p>\n<p>फिर उसने बहुत साफ़ कहा—</p>\n<p>“मैं अभी कोई पूरा बना हुआ आदमी नहीं हूँ, सर। नैना से सही तरह प्यार करना अभी सीख रहा हूँ। लेकिन सीख रहा हूँ। और सीखना बंद नहीं करूँगा।”</p>\n<p>नैना के पिता काफी देर उसे देखते रहे।</p>\n<p>चेहरे पर एक परछाईं-सी आई और चली गई; विक्रम उसे पढ़ नहीं पाया।</p>\n<p>“ईमानदार जवाब है।”</p>\n<p>कुछ देर बाद उन्होंने कहा—</p>\n<p>“लेकिन मेरा जवाब नहीं बदलता, कैप्टन। मुझे अफसोस है।”</p>\n<p>विक्रम की उँगलियाँ अपने घुटनों पर स्थिर रहीं।</p>\n<p>“मुझे यकीन है तुमने जो कहा, हर शब्द सच में कहा। मैं भी अपनी पत्नी से किए हर वादे के वक्त यही मानता था कि उसे निभाऊँगा।”</p>\n<p>उनकी आवाज़ में अब गुस्सा बिल्कुल नहीं था।</p>\n<p>“सिर्फ किसी बात को पूरे दिल से चाह लेना हमेशा काफी नहीं होता कि यह ज़िंदगी एक इंसान और उसके पीछे खड़ी औरत से क्या माँगेगी।”</p>\n<p>“सर—”</p>\n<p>“मैंने नैना की शादी की बात दूसरी जगह शुरू कर दी है।”</p>\n<p>कमरे में कुछ जैसे एकदम स्थिर हो गया।</p>\n<p>“परिवार को बरसों से जानता हूँ। लड़का स्थिर नौकरी में है। हर शाम घर लौटता है। कोई ऑपरेशन नहीं। कोई पंद्रह दिन की ख़ामोशी नहीं।”</p>\n<p>उन्होंने नज़र नहीं हटाई।</p>\n<p>“मुझे पता है अभी नैना यह नहीं चाहती। मैं उससे सिर्फ इतना कह रहा हूँ कि बीस साल बाद वह क्या चाहेगी, उसके बारे में शायद मुझे आज उससे थोड़ा ज़्यादा पता है।”</p>\n<p>सम्मान के साथ चल रही यह बातचीत अपनी आख़िरी जगह पर पहुँच चुकी थी। विक्रम ने घुटनों पर रखे हाथ सीधे कर लिए, जैसे उठने की तैयारी कर रहा हो।</p>\n<p>फिर भी उसने पूछा—</p>\n<p>“एक सवाल पूछ सकता हूँ, सर?”</p>\n<p>“पूछो।”</p>\n<p>“अगर आपकी बेटी उस जगह खड़ी होती जहाँ कभी आपकी पत्नी खड़ी थीं… और वह आपसे कहती कि उसे इतना भरोसा दीजिए कि वह ये ज़िंदगी ख़ुद चुन सके—तब भी आप उसे मना कर देते?”</p>\n<p>नैना के पिता का जबड़ा एक पल को कसा।</p>\n<p>बहुत थोड़ी देर के लिए।</p>\n<p>फिर ढीला पड़ गया।</p>\n<p>“पता नहीं।”</p>\n<p>“यही ईमानदार जवाब है, कैप्टन। मुझे नहीं पता।”</p>\n<p>उन्होंने कुछ क्षण बाद कहा—</p>\n<p>“लेकिन आज मुझे उस सवाल का जवाब नहीं देना है। आज मेरी बेटी उस तरफ नहीं खड़ी जहाँ मैं कभी खड़ा था। वह वहाँ खड़ी है जहाँ मेरी पत्नी खड़ी थी।”</p>\n<p>उनकी आँखों में वर्षों पुरानी कोई तस्वीर अब भी जीवित थी।</p>\n<p>“और उस तरफ खड़े होने की कीमत मैं जानता हूँ।”</p>\n<p>वह उठ गए।</p>\n<p>विक्रम भी समझ गया कि मुलाक़ात ख़त्म हो चुकी है।</p>\n<p>वह खड़ा हुआ।</p>\n<p>“मेरी बात सुनने के लिए धन्यवाद, सर।”</p>\n<p>फिर कुछ पल रुककर बोला—</p>\n<p>“आप जो भी फ़ैसला लें, मैं उसके पीछे की वजह का सम्मान करता हूँ। मुझे नहीं लगता आपका डर ग़लत है।”</p>\n<p>उसकी आवाज़ में पहली बार हल्की-सी थकान उतर आई।</p>\n<p>“बस काश उसकी कीमत वह न होती जो अब हम दोनों को चुकानी पड़ेगी।”</p>\n<p>मेज़ पर दोनों कप ज्यों-के-त्यों रह गए—ठंडी चाय, जिसे किसी ने नहीं पिया।</p>\n<p>नैना के पिता उसे दरवाज़े तक छोड़ने आए।</p>\n<p>चौखट पर पहुँचकर वह एक पल रुके, हाथ दरवाज़े के फ्रेम पर टिका रहा।</p>\n<p>“एक बात और, कैप्टन।”</p>\n<p>विक्रम मुड़ा।</p>\n<p>“अगर हालात अलग होते… अगर मैं ख़ुद वह ज़िंदगी न जी चुका होता जो जी है… तो शायद तुम्हें दामाद के रूप में पसंद करता।”</p>\n<p>उनके चेहरे पर मुस्कान नहीं थी।</p>\n<p>“और ये बात उस इंसान से आ रही है जो ऐसी बातें आसानी से नहीं कहता।”</p>\n<p>विक्रम ने बस सिर झुका दिया।</p>\n<p>कुछ मिनट बाद वह कार की तरफ लौट रहा था। रास्ते के दोनों ओर गेंदे की कतारें वैसी ही सीधी खड़ी थीं—बिना झुके, इस घर की तरह।</p>\n<p>कार मुड़ी तो बजरी पर पहियों की आवाज़ देर तक पीछे आती रही। शीशे में चौखट पर खड़े नैना के पिता दिखते रहे—एक हाथ अब भी फ्रेम पर।</p>\n<p>ऊपर आसमान बिल्कुल साफ़ था—इतना उदासीन कि जैसे नीचे उस घर में अभी-अभी किसी की पूरी आने वाली ज़िंदगी के बारे में कोई फ़ैसला हुआ ही न हो।</p>\n<p>आशीर्वाद नहीं मिला था।</p>\n<p>बस इंकार की वह शक्ल मिली थी जिसमें दरवाज़ा बंद नहीं होता, पर खुलता भी नहीं।</p>"}, {"chapter": 30, "title": "अध्याय 28 — आपने ही मुझे आवाज़ दी थी", "content": "<h1>अध्याय 28 — आपने ही मुझे आवाज़ दी थी</h1>\n<p>बरामदा बिल्कुल वैसा ही था।</p>\n<p>वही कुर्सी, उतरती हुई शाम, सामने धीरे-धीरे शांत होता बगीचा—जैसे पिछली बातचीत के बाद समय यहाँ से आगे बढ़ा ही न हो। फ़र्क़ बस इतना था कि रास्ते के किनारे खिले गेंदे के फूलों की खुशबू आज कुछ हल्की, कुछ ज़्यादा कड़वी लग रही थी और दूर किसी मंदिर की घंटी हवा में बजते हुए शाम को धीरे-धीरे घंटों में बाँट रही थी।</p>\n<p>नैना ने इस बार बैठने के लिए नहीं पूछा।</p>\n<p>सीधे सामने आकर बैठ गई।</p>\n<p>“वह आपसे मिलने आया था।”</p>\n<p>वह पूछ नहीं रही थी, बता रही थी।</p>\n<p>“हाँ।”</p>\n<p>“और आपने मना कर दिया।”</p>\n<p>पिता ने वह अख़बार नीचे रख दिया जिसे वह काफी देर से पढ़ने का सिर्फ दिखावा कर रहे थे।</p>\n<p>“हाँ। कर दिया।”</p>\n<p>नैना की पीठ सीधी थी। गोद में रखे दोनों हाथ चुप थे, मगर उँगलियाँ इतनी कसकर गुँथी थीं कि पोरें सफ़ेद पड़ गई थीं।</p>\n<p>“मैं वजह आपसे सुनना चाहती हूँ। माँ से नहीं। किसी और के ज़रिए नहीं। आप मेरी तरफ देखकर अपने शब्दों में बताइए कि आपने मना क्यों किया।”</p>\n<p>पिता कुछ देर उसे देखते रहे। चेहरे पर हल्की-सी नरमी आई।</p>\n<p>उन्होंने नैना के चेहरे पर ज़िद ढूँढी। वह नहीं मिली।</p>\n<p>उससे कहीं ज़्यादा ठोस कोई चीज़ मिली।</p>\n<p>“जो तुम्हारी माँ से कहा, वही विक्रम से भी कहा। मैंने देखा है इस ज़िंदगी ने तुम्हारी माँ से क्या लिया। वही तुम्हारे साथ होते नहीं देख सकता।”</p>\n<p>“ये आपकी वजह है। मैं जानना चाहती हूँ कि क्या ये वजह मेरे लिए भी सही है।”</p>\n<p>“सही-ग़लत की बात नहीं है, नैना। मैं निष्पक्ष फ़ैसला सुनाने नहीं बैठा। मैं तुम्हारा पिता हूँ। तुम्हें बचाने की कोशिश कर रहा हूँ।”</p>\n<p>उनकी आवाज़ में झुंझलाहट की हल्की धार आई, मगर नैना से ज़्यादा उस स्थिति के लिए जिसमें वह ख़ुद फँस चुके थे।</p>\n<p>“तुम्हें लगता है मुझे इसमें खुशी मिल रही है? तुम्हें सामने बैठकर मुझे ऐसे देखते हुए कि जैसे मैंने तुमसे कुछ छीन लिया हो?”</p>\n<p>उन्होंने साँस छोड़ी।</p>\n<p>“मुझे पता है मैं क्या छीन रहा हूँ। क्योंकि उसके दूसरे रास्ते को बीस साल से ऊपर जी चुका हूँ।”</p>\n<p>“तो मुझे भी जीने दीजिए।”</p>\n<p>जवाब बिना रुके आया।</p>\n<p>“मुझे भी आँखें खोलकर वही चुनाव करने दीजिए, जो आपने और माँ ने किया था।”</p>\n<p>“तुमने अभी वह ज़िंदगी जी ही नहीं है। तुम्हें पता नहीं तुम क्या माँग रही हो।”</p>\n<p>“आपको भी नहीं पता था, बाबा, जब आपने माँ से शादी की थी।”</p>\n<p>नैना थोड़ा आगे झुकी।</p>\n<p>गले में कसाव था, मगर आवाज़ अब भी सधी हुई।</p>\n<p>“किसी को पहले से नहीं पता होता कि वह क्या चुन रहा है। जब तक ज़िंदगी के भीतर पहुँच नहीं जाते, उसके पूरे मतलब का किसे पता होता है? किसी इंसान को चुनने का मतलब ही यही है।”</p>\n<p>वह रुकी नहीं।</p>\n<p>“मैंने उसे लोगों के बीच बैठकर मेरे बारे में पूछे गए हर सवाल का जवाब देते देखा है। मैंने उसे अपने दोस्त रेड्डी की शहादत का दुख उठाते देखा और फिर भी अगली शाम मेरे पास आते देखा, क्योंकि वह अपना दुख मेरा बोझ नहीं बनाना चाहता था।”</p>\n<p>“मैंने उसे पंद्रह दिन की उस ख़ामोशी के बाद हफ्तों ख़ुद को दोष देते देखा है। जितनी बार मैंने नहीं कहा, उससे ज़्यादा बार उसने माफ़ी माँगी।”</p>\n<p>नैना ने सीधे पिता की आँखों में देखा।</p>\n<p>“मैं जानती हूँ किस इंसान को चुन रही हूँ, बाबा। मुझे उससे बचाने की ज़रूरत नहीं कि कहीं आगे जाकर मुझे पता चले वह कैसा है।”</p>\n<p>एक लंबी ख़ामोशी रही।</p>\n<p>पिता की आँखों के पीछे कोई उधेड़बुन चल रही थी।</p>\n<p>ज़िद नहीं।</p>\n<p>दुख।</p>\n<p>“अपनी माँ जैसी लग रही हो,” उन्होंने आख़िर बहुत धीमे कहा। “वह भी मुझसे ऐसे ही बहस करती थी। वही ज़िद। सिर्फ इसलिए मुझे आख़िरी बात नहीं कहने देती थी कि मैं उम्र में बड़ा हूँ और मुझे लगता है मैं ज़्यादा जानता हूँ।”</p>\n<p>“शायद माँ ठीक करती थीं।”</p>\n<p>उनके चेहरे पर बहुत हल्की, थकी हुई-सी मुस्कान आई और चली गई।</p>\n<p>“शायद।”</p>\n<p>“और आपने ही मुझे सिखाया था कि सवाल पूछना बदतमीज़ी नहीं होती,” नैना ने कहा। “आपने ही मुझे आवाज़ दी थी, बाबा। आज उसे वापस मत माँगिए।”</p>\n<p>पिता की नज़र एक पल को नीचे चली गई।</p>\n<p>उन्होंने हथेली चेहरे पर फेर ली। शाम की उतरती रोशनी में वह अचानक नैना को अपनी उम्र से भी कुछ बड़े लगे।</p>\n<p>“लेकिन मुझे चाहने में उसका सही होना उन सालों को उसके लिए आसान नहीं बना पाया, नैना।”</p>\n<p>नैना चुप रही।</p>\n<p>फिर पूछा—</p>\n<p>“वह खुश थीं, बाबा?”</p>\n<p>पिता की नज़र उस पर ठहर गई।</p>\n<p>“इतना सब होने के बाद भी… क्या उन्हें खुशी थी कि उन्होंने आपको चुना?”</p>\n<p>जवाब देर से आया।</p>\n<p>“मुझे लगता है, हाँ।”</p>\n<p>उनकी आवाज़ भर्रा गई थी।</p>\n<p>“कभी सीधे पूछने की हिम्मत नहीं हुई। डर था कि कहीं जवाब ऐसा न हो जिसे सुनकर मैं बाकी ज़िंदगी ख़ुद के साथ न रह पाऊँ।”</p>\n<p>नैना की आँखें नम होने लगीं, मगर उसने पलकें नहीं झुकाईं।</p>\n<p>“तो मुझे भी वही सवाल ख़ुद से पूछने का मौका दीजिए। इतने साल बाद।”</p>\n<p>उसकी आवाज़ अब धीमी थी।</p>\n<p>“आज ही मेरे लिए उसका जवाब मत तय कर दीजिए सिर्फ इसलिए कि आपको डर है मेरा जवाब मुझे कितनी कीमत चुकवाएगा। कीमत मेरी है, बाबा। मुझे उसे तौलने दीजिए—जैसे माँ ने अपनी कीमत ख़ुद तौली थी।”</p>\n<p>शाम उनके चारों ओर और गहरी हो गई।</p>\n<p>किसी ने उठकर बत्ती नहीं जलाई।</p>\n<p>बगीचे में गेंदे पहले अपना रंग खोते गए, फिर सिर्फ आकार रह गए और आख़िर अँधेरे में वे भी घुलने लगे। कई घर छोड़कर कोई कुत्ता भौंका; शांत होती हवा में आवाज़ साफ़ यहाँ तक आई।</p>\n<p>पिता काफी देर कुछ नहीं बोले।</p>\n<p>फिर कहा—</p>\n<p>“मैं तुम्हारी बात सुन रहा हूँ।”</p>\n<p>नैना ने नज़र नहीं हटाई।</p>\n<p>“इतना ज़रूर जान लो। तुम्हारा एक भी शब्द अनसुना नहीं जा रहा। आख़िर मैं जो भी फ़ैसला करूँ।”</p>\n<p>“लेकिन जवाब अब भी वही है।”</p>\n<p>उन्होंने तुरंत जवाब नहीं दिया।</p>\n<p>“मुझे नहीं पता।”</p>\n<p>नैना ने उन्हें देखा।</p>\n<p>पूरी बातचीत में पहली बार उन्होंने ये शब्द ऐसे कहे थे जिनके पीछे कोई बचाव नहीं था।</p>\n<p>“मुझे थोड़ा वक्त दो, नैना। हमेशा के लिए नहीं। बस इतना कि आज तुमने जो कहा है, उसे ठीक से अपने भीतर रखकर देख सकूँ। अपने किसी पुराने घाव से तुरंत जवाब नहीं देना चाहता।”</p>\n<p>“और वह दूसरी बात?” नैना ने पूछा। “जो आपने उधर शुरू की है।”</p>\n<p>“जब तक मैं सोच न लूँ, वह आगे नहीं बढ़ेगी।”</p>\n<p>बस इतना सुनते ही गुँथी हुई उँगलियों की पोरें ढीली पड़ गईं। जिस संयम को वह पूरे समय दोनों हाथों से पकड़े बैठी थी, वह उसकी पकड़ से निकल गया।</p>\n<p>आँसू चुपचाप गिरने लगे।</p>\n<p>“इधर आ।”</p>\n<p>पिता की आवाज़ पहली बार उस शाम पूरी तरह पिता की थी।</p>\n<p>उन्होंने पास पड़ी चारपाई पर जगह थपथपाई।</p>\n<p>नैना बस एक पल झिझकी, फिर उठकर उनके पास बैठ गई।</p>\n<p>उन्होंने बाँह उसके कंधों के चारों ओर रखी और उसे अपने पास खींच लिया—वैसे ही जैसे बचपन में खींचते थे, जब वह इतनी छोटी थी कि उनके एक तरफ पूरी की पूरी समा जाती थी।</p>\n<p>दूसरा हाथ उसके सिर पर आया।</p>\n<p>उँगलियाँ धीरे-धीरे उसके बाल पीछे करती रहीं।</p>\n<p>वही पुराना ढंग।</p>\n<p>बचपन में किसी बुरे सपने से रोते हुए उठ जाने पर भी वह उसे इसी तरह शांत करते थे।</p>\n<p>नैना कुछ देर उनके कंधे से लगी रही।</p>\n<p>फिर पूछा—</p>\n<p>“आप सच में सोचेंगे?”</p>\n<p>“हाँ।”</p>\n<p>“सिर्फ मुझे चुप कराने के लिए नहीं कह रहे?”</p>\n<p>“नहीं।”</p>\n<p>उनका हाथ उसके बालों में चलता रहा।</p>\n<p>“मैं वादा करता हूँ, तुम्हारी कही हर बात पर सोचूँगा।”</p>\n<p>नैना ने आँखें बंद कर लीं।</p>\n<p>बरामदे की ख़ामोशी में पिता की धड़कन उसे उतनी साफ़ सुनाई दे रही थी जितनी बहुत सालों से नहीं सुनी थी।</p>\n<p>यह वही सीना था जिस पर बचपन में वह उनकी जीप का इंतज़ार करते-करते सो जाया करती थी।</p>\n<p>वही पिता।</p>\n<p>वही बेटी।</p>\n<p>बस अब वह जिस चीज़ का इंतज़ार कर रही थी, उसकी आवाज़ किसी सड़क से नहीं आने वाली थी।</p>\n<p>फिर जैसे उसे अचानक कोई डर छू गया हो, उसने बहुत धीमे पूछा—</p>\n<p>“आप मुझसे नाराज़ तो नहीं हैं?”</p>\n<p>पिता का चेहरा उसी पल बदल गया।</p>\n<p>“नाराज़?”</p>\n<p>उन्होंने उसका चेहरा दोनों हाथों में लिया।</p>\n<p>“तुम्हें सच में लगता है मैं तुमसे नाराज़ हूँ?”</p>\n<p>“पता नहीं।”</p>\n<p>“नैना, मैं तुम्हारे साथ बेरहम नहीं हो रहा।”</p>\n<p>उनकी आवाज़ भी अब पहले जैसी सपाट नहीं थी।</p>\n<p>“आज जो भी हूँ, बेरहम नहीं हूँ। मैं तुम्हारे लिए डरा हुआ हूँ। और कई बार पिता का डर बाहर से बेरहमी जैसा दिखता है, जबकि भीतर उसका दिल उतना ही टूट रहा होता है जितना बेटी का।”</p>\n<p>नैना ने कोई जवाब नहीं दिया।</p>\n<p>“अभी प्यार जैसा नहीं लग रहा, बाबा।”</p>\n<p>“मुझे पता है।”</p>\n<p>उन्होंने उसके सिर को अपने सीने से लगा लिया।</p>\n<p>“प्यार हमेशा वैसा महसूस नहीं होता जैसा हम चाहते हैं। खासकर उस बाप का प्यार जिसने इतना कुछ देखा हो कि भरोसा करना भी डर के बिना न आता हो।”</p>\n<p>उन्होंने उसके सिर पर अपने होंठ रखे—वैसे ही जैसे बचपन में न जाने कितनी बार किया था।</p>\n<p>“तुम मेरी ज़िंदगी की सबसे अच्छी चीज़ हो, नैना।”</p>\n<p>“ये बहस, ये डर… यहाँ तक कि उस लड़के को दिया मेरा ‘ना’ भी—सब उसी जगह से आया है जहाँ मैं तुमसे इतना प्यार करता हूँ कि उसे ठीक से बोलना भी नहीं आता।”</p>\n<p>उन्होंने उसे और करीब कर लिया।</p>\n<p>“गुस्सा रहना मुझसे। लेकिन ये बात मत भूलना।”</p>\n<p>नैना अब सचमुच रो पड़ी।</p>\n<p>पिता ने कुछ और नहीं कहा।</p>\n<p>बस उसे थामे रहे और हाथ उसी पुरानी लय में उसके बालों पर चलता रहा, जब तक उसकी साँसें धीरे-धीरे फिर बराबर नहीं हो गईं।</p>\n<p>उस बरामदे में आख़िर ऐसी ख़ामोशी उतर आई जिसमें किसी एक को सही साबित करने की ज़रूरत नहीं थी।</p>\n<p>वह ख़ामोशी पिता के डर को भी जगह दे रही थी।</p>\n<p>और बेटी के दुख को भी।</p>\n<p>यह ‘हाँ’ नहीं थी।</p>\n<p>मगर उस सपाट इंकार से ज़्यादा ज़रूर थी जिसे कुछ दिन पहले विक्रम इसी घर के दरवाज़े से अपने साथ बाहर ले गया था।</p>\n<p>दूर मंदिर की घंटी कब की चुप हो चुकी थी।</p>\n<p>और उस पूरी शाम के दर्द के नीचे नैना कम-से-कम एक बात पकड़कर बैठी रही—</p>\n<p>उसके पिता का फ़ैसला जो भी हो, उसकी जड़ में मोहब्बत ही होगी।</p>"}, {"chapter": 31, "title": "अध्याय 29 — आख़िरी जवाब", "content": "<h1>अध्याय 29 — आख़िरी जवाब</h1>\n<p>उन्होंने एक हफ्ता लिया।</p>\n<p>और उस पूरे हफ्ते नैना ने अपने पिता को ज़िंदगी में पहली बार इतनी गौर से देखा।</p>\n<p>सुबह की चाय पर वह पहले से कुछ देर ज़्यादा बैठे रहते—चाय ठंडी हो जाती, फिर भी हाथ कप पर रखे रहते। कभी अख़बार का एक ही पन्ना बहुत देर तक खुला रहता। एक-दो बार ऐसा भी हुआ कि उन्होंने नैना की तरफ देखा, जैसे कुछ कहने वाले हों, फिर नज़र फेर ली।</p>\n<p>नैना ने कुछ नहीं पूछा।</p>\n<p>पिछली शाम उन्होंने उससे वक्त माँगा था।</p>\n<p>इस बार वह उन्हें वह वक्त देना चाहती थी।</p>\n<p>रविवार की शाम उन्होंने ख़ुद उसे बरामदे में बुलाया।</p>\n<p>वही जगह।</p>\n<p>वही कुर्सी।</p>\n<p>ऊपर घूमते पंखे से हर चक्कर के साथ आती बहुत हल्की-सी टिक की आवाज़, ढलती रोशनी और मौसम के पहले मच्छर, जिन्होंने शाम की हवा में अपनी मौजूदगी दर्ज करानी शुरू कर दी थी।</p>\n<p>नैना उनके सामने बैठी।</p>\n<p>और उनके पहला शब्द बोलने से पहले ही जान गई—</p>\n<p>एक हफ्ते ने जवाब को नरम ज़रूर किया था।</p>\n<p>बदला नहीं था।</p>\n<p>“तुमने उस दिन जो कुछ कहा था, मैंने सब सोचा है।”</p>\n<p>नैना चुप रही।</p>\n<p>“एक भी बात यूँ ही नहीं छोड़ी। ये तुम जान लो।”</p>\n<p>नैना ने कहा—</p>\n<p>“लेकिन…”</p>\n<p>पिता ने उसकी आँखों में देखा।</p>\n<p>“लेकिन मेरा जवाब अब भी ‘ना’ है, नैना।”</p>\n<p>इस बार शब्द में पिछली कठोरता नहीं थी।</p>\n<p>सिर्फ थकान थी।</p>\n<p>ऐसी थकान जो किसी दूसरे को हराने के बाद नहीं, ख़ुद से कई दिन लड़ने के बाद आती है।</p>\n<p>“इसलिए नहीं कि मुझे उस पर भरोसा नहीं। इसलिए भी नहीं कि मुझे तुम पर भरोसा नहीं है।”</p>\n<p>उन्होंने साँस ली।</p>\n<p>“लेकिन जिस डर के बारे में तुम मुझसे कह रही हो कि उसे छोड़ दूँ, उसे मैंने बीस साल से ऊपर जिया है। तुम्हारे बहुत अच्छे तर्क भी एक हफ्ते में उन सालों को मेरे भीतर से निकाल नहीं सकते।”</p>\n<p>उनकी आवाज़ और धीमी हुई।</p>\n<p>“काश निकाल पाते।”</p>\n<p>नैना की उँगलियाँ अपनी गोद में आपस में बँधी रहीं।</p>\n<p>“मैंने कोशिश की है इस पूरे हफ्ते। सच में की है।”</p>\n<p>“नहीं कर पाया।”</p>\n<p>नैना बिल्कुल स्थिर बैठी रही।</p>\n<p>उसका एक हिस्सा यह जवाब पहले ही जानता था।</p>\n<p>दूसरा हिस्सा अब भी उस एक शब्द की उम्मीद कर रहा था जिसे सुनने के लिए वह महाकाल तक गई थी।</p>\n<p>पिता ने आगे कहा—</p>\n<p>“जिस परिवार का मैंने ज़िक्र किया था, उनसे इस हफ्ते फिर बात हुई है।”</p>\n<p>नैना की आँखें उनकी ओर उठीं।</p>\n<p>“अच्छे लोग हैं। लड़का भी ठीक है। समझदार है, स्थिर नौकरी है। हर शाम घर लौटता है।”</p>\n<p>उन्होंने जैसे ख़ुद महसूस किया कि ये बातें इस वक्त बेटी के लिए कितनी बेमानी हैं।</p>\n<p>“मुझे पता है अभी इनमें से कोई बात तुम्हारे लिए मायने नहीं रखती।”</p>\n<p>“फिर?”</p>\n<p>“मैं चाहता हूँ तुम भरोसा करो कि कभी रखेगी।”</p>\n<p>नैना का चेहरा नहीं बदला।</p>\n<p>“अभी तुम प्यार में हो। मैं उस प्यार को छोटा नहीं कह रहा। लेकिन एक दिन यही तुम चालीस साल की शादी के भीतर खड़ी होगी—हर दिन, हर सुबह, हर शाम उसी ज़िंदगी को जीते हुए।”</p>\n<p>“मैं तुमसे कह रहा हूँ कि शायद उस नैना को आज की नैना से कुछ अलग चीज़ों की ज़रूरत होगी।”</p>\n<p>नैना ने बहुत देर बाद कहा—</p>\n<p>“आप मुझसे उस नैना पर भरोसा करने को कह रहे हैं जो अभी बनी ही नहीं… उस नैना से ज़्यादा जो आपके सामने बैठी है।”</p>\n<p>पिता की आँखों में दर्द उतर आया।</p>\n<p>“हाँ।”</p>\n<p>उन्होंने बात से बचने की कोशिश नहीं की।</p>\n<p>“और मुझे पता है ये कितना ग़लत सुनाई देता है।”</p>\n<p>उन्होंने आगे बढ़कर उसका हाथ अपने हाथ में ले लिया।</p>\n<p>“मुझे पता है मेरे फ़ैसला कर देने से तुम विक्रम से प्यार करना बंद नहीं कर दोगी। दिल फौजी नहीं होता, नैना। बाप चाहे जितना चाहे, उसे हुक्म देकर सावधान की मुद्रा में खड़ा नहीं किया जा सकता।”</p>\n<p>नैना की आँखें भर आईं।</p>\n<p>“तो फिर आप मुझसे क्या चाहते हैं?”</p>\n<p>“उस रिश्ते को होने दो।”</p>\n<p>शब्द बहुत धीरे आए।</p>\n<p>“और वक्त को अपना काम करने दो। कुछ चीज़ें वक्त के साथ हल्की होती हैं। कुछ साफ़ होने लगती हैं। मैंने लोगों के साथ ऐसा होते देखा है।”</p>\n<p>“और अगर मेरे साथ नहीं हुआ तो?”</p>\n<p>पिता चुप हो गए।</p>\n<p>नैना का हाथ अब भी उनके हाथ में था।</p>\n<p>“अगर चालीस साल बाद भी मुझे उसी ज़िंदगी की याद आती रही जिसे मुझे चुनने ही नहीं दिया गया?”</p>\n<p>उनके पास जवाब नहीं था।</p>\n<p>जबड़ा कस गया।</p>\n<p>बरामदे की मद्धम रोशनी में उनकी आँखों में भी नमी चमक रही थी।</p>\n<p>बहुत देर तक दोनों चुप रहे।</p>\n<p>फिर पिता बोले—</p>\n<p>“मुझे माफ़ करना।”</p>\n<p>आवाज़ पहली बार टूट गई।</p>\n<p>नैना ने उनकी ओर देखा।</p>\n<p>“मुझे पता है माफ़ी मेरे फ़ैसले को बदलती नहीं। फिर भी चाहता हूँ तुम इसे सुनो।”</p>\n<p>उन्होंने उसका हाथ और कसकर पकड़ लिया।</p>\n<p>“जो दर्द इस फ़ैसले से तुम्हें होगा, उसके लिए मुझे अफसोस है। लेकिन जिस दर्द को मैं तुमसे दूर रखने की कोशिश कर रहा हूँ, उसके लिए मुझे अफसोस नहीं है।”</p>\n<p>“क्योंकि उस दर्द को मैं तुमसे ज़्यादा जानता हूँ।”</p>\n<p>शायद पिता होने की सबसे कठिन जगह यही थी—जहाँ इंसान अपने बच्चे का दिल तोड़ते हुए भी ख़ुद को समझाता रहता है कि वह उसी दिल की हिफ़ाज़त कर रहा है।</p>\n<p>नैना उठी।</p>\n<p>पिता को लगा, वह चली जाएगी।</p>\n<p>लेकिन वह उनके सामने आकर नीचे बैठ गई, दोनों हाथ उनके घुटनों पर रख दिए।</p>\n<p>इस घर में बेटियाँ पिता के पैर छूकर अपनी बात नहीं कहती थीं। मगर यह मुद्रा उसके बहुत करीब थी—इतनी नीचे कि उसमें बहस से ज़्यादा विनती थी।</p>\n<p>“बाबा… मेरी तरफ देखिए।”</p>\n<p>उसकी आवाज़ काँप रही थी।</p>\n<p>मगर आँखें ऊपर थीं।</p>\n<p>“मैं आपसे कैप्टन राठौड़ की होने वाली पत्नी बनकर नहीं माँग रही।”</p>\n<p>पिता की उँगलियाँ कुर्सी के हत्थे पर कस गईं।</p>\n<p>“मैं आपकी वही बेटी बनकर माँग रही हूँ जो आपकी जीप का इंतज़ार करते-करते आपकी छाती पर सो जाती थी।”</p>\n<p>उनके चेहरे की कठोरता टूट गई।</p>\n<p>“आपने मुझसे कहा था—एक बार नहीं, कई बार—कि मुझे कभी ऐसी जगह खड़ा नहीं करेंगे जहाँ मुझे आपसे प्यार करने और अपनी ज़िंदगी जीने में से किसी एक को चुनना पड़े।”</p>\n<p>नैना की आँखों से आँसू उतरने लगे।</p>\n<p>“आपको शायद याद भी नहीं होगा। मैं शायद सात साल की थी।”</p>\n<p>उसने साँस खींची।</p>\n<p>“मुझे याद है, बाबा।”</p>\n<p>पिता कुछ नहीं बोले।</p>\n<p>“आपने मुझे लाउड बनाया।”</p>\n<p>उस एक शब्द में उसके बचपन से लेकर आज तक की पूरी नैना आकर खड़ी हो गई।</p>\n<p>“आपने मुझे सिखाया कि जो चाहती हूँ उसे बोलूँ। अपनी बात निगलूँ नहीं। माँ की तरह हर बात अपने भीतर रखकर छोटी न होती जाऊँ।”</p>\n<p>उसके हाथ उनके घुटनों पर और कस गए।</p>\n<p>“मैं वही कर रही हूँ आज।”</p>\n<p>आवाज़ टूटने लगी।</p>\n<p>“ठीक वही, जो आपने मुझे करना सिखाया।”</p>\n<p>उसने आँसू पोंछे, मगर नए आँसू उनकी जगह आ गए।</p>\n<p>“और आज आप ही मुझसे कह रहे हैं कि इसे निगल जाऊँ।”</p>\n<p>पिता की आँखें उससे हट नहीं सकीं।</p>\n<p>“मुझे समझ नहीं आता, बाबा… ये दोनों बातें एक ही इंसान के भीतर कैसे सही हो सकती हैं।”</p>\n<p>“नैना…”</p>\n<p>“बाबा, प्लीज़।”</p>\n<p>‘प्लीज़’ शब्द उसके गले में आधा ही निकला।</p>\n<p>“मैं कोई केस नहीं लड़ रही आपसे।”</p>\n<p>वह रो रही थी, फिर भी शब्द रोकना नहीं चाहती थी।</p>\n<p>“मैं आपकी बेटी हूँ। मैंने आपसे ज़िंदगी में कभी कुछ इस तरह नहीं माँगा।”</p>\n<p>उसने चेहरा पोंछा।</p>\n<p>“और मैं ये भी नहीं कह रही कि अपनी पूरी ज़िंदगी भूल जाइए। जो जानते हैं, उसे भूलिए मत। बस विक्रम को भी उसी ईमानदारी से देखिए।”</p>\n<p>वह रुकी।</p>\n<p>“वह शादी के बाद आर्मी छोड़ने को तैयार है।”</p>\n<p>पिता की आँखें हल्की-सी झुकीं।</p>\n<p>“आप जानते हैं इसका क्या मतलब है। वह सिर्फ नौकरी नहीं छोड़ रहा होगा। वह अपनी पूरी वयस्क ज़िंदगी की पहचान छोड़ने को तैयार है।”</p>\n<p>नैना ने सिर हिलाया।</p>\n<p>“मैं आँखें बंद करके उसके पीछे नहीं जा रही। महीनों से उसे देखा है। दुख में। अपराधबोध में। ग़लती करते हुए भी… और ग़लती समझकर ख़ुद को ठीक करते हुए भी।”</p>\n<p>फिर उसने वही बात उनके सामने रखी जिससे वह ख़ुद भी बच नहीं सकते थे।</p>\n<p>“आपने पूरी ज़िंदगी इंसान को कुछ सेकंड में पढ़ना सीखा है।”</p>\n<p>पिता स्थिर हो गए।</p>\n<p>“जब वह उस दिन आपके सामने बैठा था, आपने क्या देखा?”</p>\n<p>“कोई लापरवाह लड़का?”</p>\n<p>एक पल।</p>\n<p>“या ऐसा इंसान जिसने आपको वह सच भी बताया जो उसके ख़िलाफ़ जाता था?”</p>\n<p>पिता ने नज़र नहीं हटाई।</p>\n<p>“मुझे पता है तुम आँखें बंद करके नहीं चल रही, बेटा।”</p>\n<p>“यही तो इसे इतना मुश्किल बनाता है।”</p>\n<p>उन्होंने आँखें बंद कर लीं।</p>\n<p>“तुम कोई छोटी चीज़ माँग रही होती तो बिना सोचे दे देता।”</p>\n<p>जब आँखें खुलीं तो उनमें पिता का डर पूरी तरह उघड़ा हुआ था।</p>\n<p>“तुम मुझसे कह रही हो कि मैं तुम्हें जोखिम में डाल दूँ।”</p>\n<p>नैना ने बिना झिझके कहा—</p>\n<p>“तो डाल दीजिए।”</p>\n<p>उसकी आवाज़ में न काँप थी, न झिझक।</p>\n<p>“जोखिम मेरा है।”</p>\n<p>उसने अपने आँसू पोंछे।</p>\n<p>“मुझे लेने दीजिए।”</p>\n<p>“मैं वह उन्नीस साल की लड़की नहीं हूँ जो माँ थीं, जब उनकी शादी हुई थी। मेरे सामने आपकी पूरी ज़िंदगी है। उनकी पूरी ज़िंदगी है। मुझे पहले से मालूम है इस रास्ते पर क्या हो सकता है।”</p>\n<p>उसने कहा—</p>\n<p>“फिर भी मैं उसे चुन रही हूँ।”</p>\n<p>पिता चुप रहे। जब बोले तो आवाज़ और नीचे उतर आई थी—उसमें अब लगभग विनती थी।</p>\n<p>“तुम सच में जानती हो, नैना, विक्रम कौन है? मैं जानता हूँ—उसकी फाइल से, उन लोगों से जो उसके साथ सर्विस कर चुके हैं।”</p>\n<p>नैना चुप रही।</p>\n<p>“वह कोई ऐसा फौजी नहीं जो दफ़्तर में बैठकर शांत पोस्टिंग के दिन गिन रहा हो। वह पैरा एसएफ़ है। साल-दर-साल एक्टिव ऑपरेशन। हमेशा गोली के आसपास—और हमेशा अपनी सरहद के भीतर भी नहीं। इससे ज़्यादा साफ़ मैं नहीं कहूँगा। इस घर में तो बिल्कुल नहीं।”</p>\n<p>“ऐसे जवानों को आम मायनों में घर-परिवार नहीं मिलता। छुट्टियाँ मिलती हैं—दो ऑपरेशनों के बीच छीनी हुई—और एक पत्नी, जो उन खाली जगहों के बीच जीना सीख लेती है।”</p>\n<p>“ज़्यादातर लोग एसएससी में आसान रास्ता लेते हैं। उसने जानबूझकर मुश्किल रास्ता चुना। एक बार नहीं, दो बार।”</p>\n<p>“और उसके रेज़िग्नेशन की बात, नैना—वह सच्चे मन से कही गई है। फिर भी तुम इंडियन आर्मी को नहीं जानती। ऐसे अफसर को सेना यूँ जाने नहीं देती। आज शॉर्ट सर्विस कमीशन है, कल परमानेंट कर देगी। तब वह चाहकर भी वर्दी नहीं उतार पाएगा—वह सेना के लिए एसेट है, और सेना अपना एसेट कभी नहीं छोड़ती।”</p>\n<p>नैना के हाथ अब भी उनके घुटनों पर थे। उसने कुछ नहीं कहा।</p>\n<p>“ऐसे लोग किसी पत्नी, किसी बच्चे या किसी ससुर के डर के लिए चढ़ना नहीं छोड़ते, नैना। और वही आगे बढ़ना परिवार से वह सब छीन लेता है, जिसे खोने का सौदा उसने कभी किया ही नहीं था।”</p>\n<p>“मैंने उसके जैसे दर्जनों नौजवान अफसर देखे हैं, और हर एक को साल-दर-साल वही चुपचाप फ़ैसला करते देखा है—तब भी, जब दीवार पर टँगी उनकी शादी की तस्वीरें बहुत पहले फीकी पड़ चुकी थीं।”</p>\n<p>फिर उन्होंने बेटी की आँखों में देखा।</p>\n<p>“और यह जोखिम कभी सिर्फ तुम्हारा था ही नहीं, नैना। उस दिन से नहीं, जिस दिन मैंने तुम्हें पहली बार गोद में लिया था।”</p>\n<p>उनकी हमेशा नपी-तुली रहने वाली आवाज़ अब किसी ऐसी चीज़ में बदल गई थी, जो नैना ने उनसे पहले कभी नहीं सुनी थी।</p>\n<p>“मैंने फ़ैसला कर लिया है। यह नहीं कहूँगा कि आसान था। यह भी नहीं कहूँगा कि मुझे इस पर पूरा यकीन है। लेकिन फ़ैसला यही है।”</p>\n<p>पिता का चेहरा थक गया।</p>\n<p>जैसे एक हफ्ते से भीतर चल रही लड़ाई अब शब्दों में नहीं, शरीर पर उतर आई हो।</p>\n<p>लेकिन इस बार उन्होंने “वक्त दो” नहीं कहा।</p>\n<p>वक्त वह ले चुके थे।</p>\n<p>और उसका जवाब नैना के सामने था।</p>\n<p>नैना ने यह भी समझ लिया।</p>\n<p>कुछ फ़ैसले इंसान से जीतकर नहीं लिए जा सकते।</p>\n<p>और कुछ हारें ऐसी होती हैं जिनमें सामने वाला दुश्मन भी नहीं होता।</p>\n<p>सिर्फ कोई अपना होता है—</p>\n<p>जो आपको खोना नहीं चाहता,</p>\n<p>और उसी कोशिश में आपसे वह चीज़ छीन लेता है जिसके बिना आप ख़ुद को पूरा नहीं देख पाते।</p>\n<p>नैना धीरे-धीरे उठी।</p>\n<p>पिता ने उसका हाथ पकड़ लिया।</p>\n<p>“मुझसे नफ़रत मत करना।”</p>\n<p>वह वहीं रुक गई।</p>\n<p>इतने वर्षों में उसने अपने पिता की आवाज़ में ऐसी असहायता कभी नहीं सुनी थी।</p>\n<p>उसने उनकी तरफ देखा।</p>\n<p>“नहीं कर सकती।”</p>\n<p>बस इतना।</p>\n<p>“लेकिन अभी समझ भी नहीं सकती।”</p>\n<p>उन्होंने सिर झुका लिया।</p>\n<p>नैना ने अपना हाथ उनके हाथ से नहीं छुड़ाया।</p>\n<p>कुछ देर दोनों वैसे ही रहे।</p>\n<p>फिर पिता ने उसे अपने पास खींच लिया।</p>\n<p>इस बार वह भी नहीं रुकी।</p>\n<p>उनके कंधे से लगते ही फिर रो पड़ी।</p>\n<p>पिता की हथेली उसके सिर पर थी।</p>\n<p>लेकिन आज वह पुरानी हथेली किसी बुरे सपने से जगाकर उसे यह नहीं कह सकती थी कि सब ठीक है।</p>\n<p>क्योंकि इस बार जिस चीज़ से बेटी डर रही थी—</p>\n<p>वह सपना नहीं था।</p>\n<p>और उसे सच करने वाला इंसान वही था जिसकी छाती से लगकर वह रो रही थी।</p>\n<p>बरामदे में रात उतरती रही।</p>\n<p>पंखा ऊपर अपनी धीमी टिक के साथ घूमता रहा।</p>\n<p>और पिता-बेटी एक-दूसरे को थामे रहे—इतने करीब कि एक-दूसरे की साँस सुन सकते थे, और उस एक फ़ैसले में इतने दूर कि कोई शब्द बीच की जगह भर नहीं सकता था।</p>\n<p>कुछ देर बाद नैना ने धीरे से कहा—</p>\n<p>“मुझे उसे बताना होगा।”</p>\n<p>पिता को पूछने की ज़रूरत नहीं थी कि किसे।</p>\n<p>“जानता हूँ।”</p>\n<p>“आसान नहीं होगा।”</p>\n<p>“इस पूरे मामले में कुछ भी आसान नहीं रहा, बेटा। वह हिस्सा भी नहीं होगा।”</p>\n<p>उन्होंने उसका हाथ एक बार दबाया, फिर छोड़ दिया।</p>\n<p>“जो भी कहना, जैसे भी कहना—मुझे भरोसा है कि तुम उसे उसी गरिमा से कहोगी जिससे आज की पूरी बातचीत में कहती रही हो। जिस बेटी का दिल मैंने अभी तोड़ा है, उस पर यह भरोसा करना मेरे लिए कम बात नहीं।”</p>\n<p>नैना उठी। पैर उसके नीचे ठीक से टिक नहीं रहे थे। वह बिना कुछ कहे घर के भीतर चली गई।</p>\n<p>जवाब आख़िर मिल चुका था।</p>\n<p>और कभी-कभी आख़िरी जवाब का सबसे बड़ा दुख यही होता है—</p>\n<p>उसके बाद उम्मीद को रखने के लिए कोई अगला सवाल नहीं बचता।</p>"}, {"chapter": 32, "title": "अध्याय 30 — जो उसे कहना था", "content": "<h1>अध्याय 30 — जो उसे कहना था</h1>\n<p>नैना ने विक्रम को गुलमोहर वाले पार्क में बुलाया।</p>\n<p>उसी बेंच पर।</p>\n<p>दोनों में से किसी ने नहीं पूछा कि आज के लिए उसने यही जगह क्यों चुनी थी।</p>\n<p>शायद कुछ जगहें रिश्तों में इतनी भीतर उतर जाती हैं कि उनके पास लौटने की वजह बतानी नहीं पड़ती।</p>\n<p>विक्रम उसके कुछ कहने से पहले ही समझ गया था।</p>\n<p>पिछले महीनों में उसने नैना के चेहरे को इतना पढ़ लिया था कि एक हफ्ते की ख़ामोशी और उस शाम बेंच तक आते उसके भारी कदमों का मतलब उससे छिप नहीं सकता था।</p>\n<p>वह उसके पास बैठ गया।</p>\n<p>जैसे जवाब सुनने नहीं—</p>\n<p>सहने आया हो।</p>\n<p>“उन्होंने मना कर दिया,” विक्रम ने धीमे से कहा। यह पूछना नहीं था—बस वह बात थी जो वह पहले से जानता था।</p>\n<p>“हाँ।”</p>\n<p>नैना की आवाज़ स्थिर थी, मगर उस स्थिरता की कीमत विक्रम सुन सकता था।</p>\n<p>“फाइनल।”</p>\n<p>उसने सामने देखा।</p>\n<p>“जो कुछ कह सकती थी, सब कहा। कुछ बातें तो मुझे ख़ुद नहीं पता थीं कि मेरे भीतर हैं, जब तक उनके सामने खड़े होकर कह नहीं दीं।”</p>\n<p>उसने बात को थोड़ा हल्का करना चाहा।</p>\n<p>नहीं कर पाई।</p>\n<p>“कुछ नहीं बदला।”</p>\n<p>विक्रम चुप रहा।</p>\n<p>उसकी नज़र सामने उसी गुलमोहर पर थी जो कभी उनके पहली बार मिलने पर लगभग खाली था और अब फिर फूलों से भरा खड़ा था।</p>\n<p>“अब?”</p>\n<p>उसने पूछा।</p>\n<p>नैना ने साँस छोड़ी।</p>\n<p>“जिस परिवार से बाबा बात कर चुके हैं… वही। लड़का अच्छा है, ऐसा कहते हैं। स्थिर है। सुरक्षित है। वह सब कुछ है जो बाबा ने तय किया है कि मुझे चाहिए—सिवाय उसके जो मैं सच में चाहती हूँ।”</p>\n<p>उसका जबड़ा कस गया।</p>\n<p>“इसके आगे मेरे पास कोई प्लान नहीं है, विक्रम। इतने आख़िरी जवाब के साथ क्या किया जाता है, मुझे सच में नहीं पता।”</p>\n<p>विक्रम उसे देखता रहा।</p>\n<p>“हम अब भी लड़ सकते हैं।”</p>\n<p>नैना ने उसकी ओर देखा।</p>\n<p>“साथ में। ठीक से। अगर बात वहाँ तक पहुँचे तो… हम शादी कर सकते हैं। अपने आप। लोग करते हैं।”</p>\n<p>“मत कहो।”</p>\n<p>आवाज़ नरम थी।</p>\n<p>मगर उसमें कोई जगह नहीं थी।</p>\n<p>विक्रम चुप हो गया।</p>\n<p>“मैंने उसके बारे में भी सोचा है,” नैना ने कहा। “जितना मानना चाहती हूँ, उससे ज़्यादा।”</p>\n<p>उसने अपने हाथों की तरफ देखा।</p>\n<p>“लेकिन मैं नहीं कर सकती।”</p>\n<p>“क्यों?”</p>\n<p>“इसलिए नहीं कि तुमसे इतना प्यार नहीं करती।”</p>\n<p>उसने तुरंत उसकी तरफ देखा।</p>\n<p>“इसलिए कि मुझे पता है उसकी कीमत माँ को चुकानी पड़ेगी। एक तरफ उनका पति, दूसरी तरफ उनकी बेटी… और मेरे एक फ़ैसले के बाद दोनों शायद ज़िंदगी भर एक-दूसरे के लिए अजनबी हो जाएँ।”</p>\n<p>नैना की आवाज़ धीमी हो गई।</p>\n<p>“माँ ने मुझे पूरी ज़िंदगी सिर्फ प्यार और सब्र से पाला है। एक दिन भी बदले में अपने लिए कुछ नहीं माँगा।”</p>\n<p>उसने सिर हिलाया।</p>\n<p>“मैं उस पूरी ज़िंदगी का जवाब उनका घर तोड़कर नहीं दे सकती।”</p>\n<p>विक्रम के चेहरे पर दर्द उतर आया।</p>\n<p>“तो हम बस होने दें ये सब? तुम्हारे पिता तुम्हारे लिए फ़ैसला कर दें?”</p>\n<p>नैना की आँखों में उसी पल कुछ तेज़ हुआ—विक्रम के ख़िलाफ़ नहीं, उस अर्थ के ख़िलाफ़ जो उसके शब्दों में अनजाने आ गया था।</p>\n<p>“मैं उन्हें अपने लिए चुनने नहीं दे रही।”</p>\n<p>वह सीधी बैठ गई।</p>\n<p>“मैं उस पिता का सम्मान करना चुन रही हूँ जिसने इक्कीस साल में मुझे एक बार भी अपने प्यार पर शक करने की वजह नहीं दी। मैं उनके फ़ैसले से नफ़रत कर सकती हूँ और फिर भी उनके प्यार पर भरोसा कर सकती हूँ।”</p>\n<p>उसकी आवाज़ हल्की काँपी।</p>\n<p>“दोनों अलग बातें हैं।”</p>\n<p>फिर वह बोली—</p>\n<p>“और अभी मुझे ख़ुद भी ये फ़र्क़ मानना ज़रूरी है।”</p>\n<p>कुछ देर वह चुप रही।</p>\n<p>अपने भीतर की अगली बात को जैसे सही जगह से उठा रही हो।</p>\n<p>“तुम मुझे जानते हो, विक्रम। मैं उन लड़कियों में कभी नहीं रही जो सिर्फ इसलिए किसी बात के आगे सिर झुका दें कि परंपरा ऐसा कहती है।”</p>\n<p>“जानता हूँ।”</p>\n<p>“जिन नियमों को ग़लत समझा, तोड़े हैं। और फिर रात को बैठकर उनके टुकड़े भी नहीं गिने।”</p>\n<p>विक्रम के होंठों पर बहुत हल्की, दुखी-सी पहचान आई।</p>\n<p>“जानता हूँ।”</p>\n<p>“लेकिन ये वैसा नहीं है।”</p>\n<p>वह उसकी ओर पूरी तरह मुड़ी।</p>\n<p>“मुझे चाहिए तुम ये फ़र्क़ समझो। क्योंकि मुझे पता है तुम अभी भी कहीं न कहीं इंतज़ार कर रहे हो कि मैं एक और नियम तोड़ दूँ—जैसे हमेशा तोड़ती आई हूँ।”</p>\n<p>उसकी आँखों में आँसू थे।</p>\n<p>मगर उनके पीछे की नैना अब भी वैसी ही थी।</p>\n<p>लाउड।</p>\n<p>सीधी।</p>\n<p>अपनी बात से पीछे न हटने वाली।</p>\n<p>“ये कभी परंपरा की बात थी ही नहीं। न किसी ‘अच्छी बेटी’ के फर्ज की। न गाँव की उम्मीदों की। न उन उधार के नियमों की जिन्हें मैंने ज़िंदगी में कभी आँख बंद करके माना ही नहीं।”</p>\n<p>“नैना—”</p>\n<p>“मुझे पूरा कह लेने दो।”</p>\n<p>“मैं जो कुछ हूँ… मेरे भीतर की हर वह चीज़ जिससे तुमने प्यार किया, मेरी आवाज़, मेरी ज़िद, वह ‘लाउड’ लड़की जिसे तुमने कभी बदलने की कोशिश नहीं की—मैंने ये सब अकेले नहीं बनाया।”</p>\n<p>उसकी आँख से एक आँसू उतर आया।</p>\n<p>उसने लगभग झुँझलाकर उसे पोंछ दिया।</p>\n<p>“मुझे दिया गया है ये सब। सालों तक। बहुत सोचकर। बहुत सँभालकर। पिता चाहते तो मुझे चुप रहने वाली बेटी बना सकते थे। नहीं बनाया।”</p>\n<p>उसने साँस ली।</p>\n<p>“और माँ ने भी कभी नहीं कहा।”</p>\n<p>अब उसकी आवाज़ में दर्द था।</p>\n<p>“तो उन्होंने मेरे भीतर जो कुछ भरा है, मैं उसी को लेकर उस एक दरवाज़े से कैसे निकल जाऊँ जिसे उन्होंने मुझसे न खोलने को कहा है?”</p>\n<p>विक्रम चुप था।</p>\n<p>“अगर मैं ऐसा करती हूँ तो मैं बहादुर नहीं हो जाऊँगी। आज़ाद भी नहीं।”</p>\n<p>“मैं बस वह बेटी बन जाऊँगी जिसने जो कुछ पाया, उसे उसी दिन खर्च कर दिया जिस दिन उसे सँभालकर रखने की कोई कीमत सामने आई।”</p>\n<p>विक्रम ने कहा—</p>\n<p>“तो उसकी जगह ख़ुद को ख़त्म कर दोगी?”</p>\n<p>नैना ने उसकी ओर देखा।</p>\n<p>“यही कर रही हो न? अपनी खुशी जला दोगी ताकि बाकी किसी को उसकी राख न उठानी पड़े?”</p>\n<p>“नहीं।”</p>\n<p>जवाब तुरंत आया।</p>\n<p>“मैं ख़ुद को ख़त्म नहीं कर रही, विक्रम।”</p>\n<p>वह थोड़ा उसके करीब हुई।</p>\n<p>“मैं बस अपने हाथों से अपने परिवार में आग लगाने वाली नहीं बनना चाहती।”</p>\n<p>नैना ने उसकी आँखों में देखा।</p>\n<p>“दोनों में फ़र्क़ है। चाहे तुम्हें यहाँ बैठकर अभी वह फ़र्क़ दिखाई न दे।”</p>\n<p>“तो मुझे समझाओ।”</p>\n<p>विक्रम की आवाज़ में पहली बार कच्चापन उतर आया।</p>\n<p>“क्योंकि यहाँ से मुझे दोनों एक ही चीज़ लग रही हैं।”</p>\n<p>नैना ने लंबी साँस ली।</p>\n<p>“मेरे पिता ने इस देश को अपनी ज़िंदगी के वे साल दिए हैं जिन्हें इंसान आम तौर पर अपने लिए रखता है।”</p>\n<p>विक्रम शांत हो गया।</p>\n<p>“अपने बच्चों को बड़ा होते देखने के साल। हर शाम घर लौटने के साल। खाने की उस मेज़ पर बैठने के साल जहाँ मेरी याद में शायद ही कभी सारी कुर्सियाँ भरी रही हों।”</p>\n<p>“मेरे बचपन का आधा हिस्सा उनसे खाली था, विक्रम। और उन्होंने कभी हमें ये महसूस नहीं होने दिया कि उस खालीपन की कीमत उन्होंने भी चुकाई है।”</p>\n<p>विक्रम ने कहा, “मुझे पता है तुम्हारे पिता ने क्या दिया है।”</p>\n<p>नैना ने सिर हिलाया।</p>\n<p>“नहीं। उस तरह नहीं जैसे मुझे पता है।”</p>\n<p>उसकी नज़र कहीं दूर चली गई।</p>\n<p>“मैं उस खाली कुर्सी के साथ बड़ी हुई हूँ।”</p>\n<p>उसकी नज़र बेंच के उस खाली सिरे पर गई, जहाँ कोई नहीं बैठा था।</p>\n<p>कुछ देर गुलमोहर की पत्तियों के बीच से आती हवा ही उनके बीच बोलती रही।</p>\n<p>“ये कभी इतना आसान हिसाब नहीं था कि एक तरफ मेरे परिवार की इज़्ज़त रख दो और दूसरी तरफ मेरी खुशी।”</p>\n<p>नैना फिर उसकी ओर मुड़ी।</p>\n<p>“ये उस पिता और माँ की बात है जिन्होंने जानबूझकर ऐसी बेटी पाली जो आज यहाँ बैठकर उनसे असहमत हो सकती है।”</p>\n<p>उसकी आवाज़ अब धीमी नहीं थी।</p>\n<p>“एक ऐसे समाज में जहाँ लड़कियों को हर दिन थोड़ा कम बोलना, थोड़ा कम माँगना, थोड़ा कम जगह घेरना सिखाया जाता है—तुम समझते हो हरियाणा के एक मध्यमवर्गीय घर में ऐसी बेटी पालना कितनी बड़ी बात है?”</p>\n<p>विक्रम ने कुछ नहीं कहा।</p>\n<p>उसे बोलने दिया।</p>\n<p>“अगर मैं आज उनके ख़िलाफ़ घर छोड़ दूँ क्योंकि वह मेरे प्यार से डरते हैं, तो बाहर खड़ा कोई दूसरा पिता इससे क्या सीखेगा?”</p>\n<p>उसकी आँखें चमक रही थीं।</p>\n<p>“ये नहीं कि प्यार जीत गया।”</p>\n<p>“वह सीखेगा कि लाउड बेटी पालना ख़तरनाक है।”</p>\n<p>विक्रम बिल्कुल स्थिर हो गया।</p>\n<p>“कि उसे जितनी आज़ादी दोगे, किसी दिन उसी आज़ादी के सहारे वह तुम्हारा घर छोड़ जाएगी।”</p>\n<p>नैना की आवाज़ काँपी, लेकिन शब्द नहीं।</p>\n<p>“मैं किसी डरते हुए पिता के लिए वह सबूत नहीं बनूँगी कि बेटी को ज़्यादा आसमान दोगे तो एक दिन वह उसी आसमान से उड़कर हमेशा के लिए चली जाएगी।”</p>\n<p>आँसू अब उसकी पलकों से निकल आए थे।</p>\n<p>“मैं नहीं चाहती कि कहीं कोई पिता मेरी कहानी देखकर अपनी बेटी को मेरे जितना लाउड न होने दे।”</p>\n<p>उसने कहा—</p>\n<p>“उस कीमत पर भी नहीं, विक्रम।”</p>\n<p>एक साँस।</p>\n<p>“तुम्हारे लिए भी नहीं।”</p>\n<p>दूसरी।</p>\n<p>“हमारे लिए भी नहीं।”</p>\n<p>विक्रम काफी देर कुछ नहीं बोला।</p>\n<p>उसके भीतर जैसे कोई चीज़ एक साथ बहुत भारी और बहुत शांत हो गई थी।</p>\n<p>“मुझे नहीं पता इसे कैसे स्वीकार करूँ।”</p>\n<p>आख़िर उसने कहा।</p>\n<p>“और मैं ये दिखावा भी नहीं करना चाहता कि कर सकता हूँ।”</p>\n<p>नैना ने सिर हिलाया।</p>\n<p>“मैं तुमसे आसानी से स्वीकार करने को कह भी नहीं रही।”</p>\n<p>उसकी आँखें अब आँसुओं से भरी थीं।</p>\n<p>“शायद मैंने भी नहीं किया है।”</p>\n<p>नैना ने बेंच पर रखा विक्रम का हाथ अपने हाथ में ले लिया।</p>\n<p>“बस एक बात जानना।”</p>\n<p>विक्रम उसकी तरफ मुड़ा।</p>\n<p>“हम जो महसूस करते हैं, उसका अंत नहीं हो रहा।”</p>\n<p>उसकी उँगलियाँ उसके हाथ के चारों ओर बंद हो गईं।</p>\n<p>“हमें जो ज़िंदगी साथ बनानी थी, शायद उसका हो रहा है।”</p>\n<p>विक्रम की साँस जैसे बीच में अटक गई।</p>\n<p>“लेकिन मुझे नहीं लगता दस साल बाद की कोई नैना होगी… या बीस साल बाद की… जिसके भीतर इसका कुछ हिस्सा नहीं रहेगा।”</p>\n<p>उसने उसका हाथ हल्के से दबाया।</p>\n<p>“तुम्हारा कुछ हिस्सा।”</p>\n<p>“नैना—”</p>\n<p>“प्लीज़, मुझे पूरा कह लेने दो। मैं ये दोबारा नहीं कह पाऊँगी।”</p>\n<p>अब वह पूरी तरह उसकी ओर थी।</p>\n<p>“तुमने मुझे मेरी ज़िंदगी के सबसे अच्छे महीने दिए हैं।”</p>\n<p>विक्रम की आँखें उससे नहीं हटीं।</p>\n<p>“तुमने मुझे बताया कि किसी ऐसे इंसान का प्यार कैसा होता है जो मुझे सच में देखता है।”</p>\n<p>उसकी आवाज़ टूटने लगी।</p>\n<p>“मेरे किसी छोटे, आसान, कम बोलने वाले रूप को नहीं।”</p>\n<p>वह मुस्कुराने की कोशिश करके रह गई।</p>\n<p>“मुझे।”</p>\n<p>एक आँसू उसके गाल से उतर गया।</p>\n<p>“इसके बाद जो भी हो… मेरी शादी जिससे भी हो, ज़िंदगी जहाँ भी जाए… ये बात कभी नहीं बदलेगी।”</p>\n<p>नैना ने उनका जुड़ा हुआ हाथ देखा।</p>\n<p>“इसे कोई हमसे वापस नहीं ले सकता।”</p>\n<p>फिर बहुत धीमे—</p>\n<p>“बाबा भी नहीं।”</p>\n<p>विक्रम को अपनी आवाज़ पर भरोसा नहीं था।</p>\n<p>इसलिए उसने जवाब नहीं दिया।</p>\n<p>बस उसका हाथ पकड़े रहा।</p>\n<p>दोनों उसी गुलमोहर के नीचे बैठे थे जो इस बार फूलों से भरा था—और अपने बीच उस दुख को थामे हुए थे जो सबसे कठिन इसलिए था क्योंकि इसमें दोष देने के लिए कोई आसान चेहरा नहीं था।</p>\n<p>न कोई धोखा।</p>\n<p>न कोई बेवफाई।</p>\n<p>न कोई खलनायक।</p>\n<p>बस एक पिता का बीस साल से भी पुराना डर—</p>\n<p>जिसे न नैना का प्यार मिटा सका,</p>\n<p>न विक्रम का।</p>\n<p>काफी देर बाद विक्रम ने पूछा—</p>\n<p>“कब?”</p>\n<p>नैना समझ गई।</p>\n<p>“शादी?”</p>\n<p>उसने सिर हिलाया।</p>\n<p>“जल्दी।”</p>\n<p>उसने आँखें पोंछीं।</p>\n<p>“शायद बाबा चाहते हैं जल्दी तय हो जाए। इससे पहले कि हम दोनों में से कोई उनका मन बदलने का कोई नया तरीका ढूँढ़ ले।”</p>\n<p>उसमें हल्की-सी पुरानी नैना थी।</p>\n<p>लेकिन आज उस वाक्य पर दोनों में से कोई हँसा नहीं।</p>\n<p>“मैं तुम्हें ख़ुद बताना चाहती थी। ठीक से।”</p>\n<p>नैना ने कहा।</p>\n<p>“किसी और से सुनो उससे पहले।”</p>\n<p>विक्रम ने बहुत देर बाद बस इतना कहा—</p>\n<p>“थैंक यू।”</p>\n<p>दो शब्द।</p>\n<p>जिनमें वह बात कहीं नहीं समा सकती थी जिसके लिए उसने उन्हें कहा था।</p>\n<p>फिर दोनों वहीं बैठे रहे।</p>\n<p>किसी को जल्दी नहीं थी।</p>\n<p>दोनों जानते थे कि उनमें से जो पहले उठेगा, वह इस शाम को एक कदम और अंत की तरफ ले जाएगा।</p>\n<p>लेकिन इतना दोनों जानते थे कि शादी के बाद उनका यह रूप—यह नैना और यह विक्रम, जो एक-दूसरे के सामने बिना किसी रिश्ते का नाम माँगे इतने पूरे थे—फिर नहीं रहेगा।</p>\n<p>और यह बेंच।</p>\n<p>यह पेड़।</p>\n<p>यह शाम।</p>\n<p>यह दुख।</p>\n<p>इनमें से कोई भी उनके भीतर से कभी पूरी तरह नहीं जाएगा।</p>\n<p>बहुत देर की उस ख़ामोशी में आख़िर नैना ने अपने भीतर बची आख़िरी पकड़ भी छोड़ दी।</p>\n<p>वह धीरे से उसकी ओर झुकी और सिर उसकी गोद में रख दिया—वैसे ही जैसे न जाने कितनी बार पहले रख चुकी थी।</p>\n<p>लेकिन आज आँसू वैसे नहीं थे।</p>\n<p>अब उन्हें सँभालकर रखने की कोई वजह नहीं बची थी।</p>\n<p>उसके कंधे काँपने लगे।</p>\n<p>विक्रम ने कुछ नहीं कहा।</p>\n<p>उसका हाथ नैना के बालों में उतर गया और उसी धीमी, पहचानी हुई लय में चलता रहा जिसे दोनों के बीच अब शब्दों की ज़रूरत नहीं थी।</p>\n<p>उसका अपना गला भी कई बार भर आया।</p>\n<p>मगर उसने उसे रोका।</p>\n<p>आज नैना को उसके दुख की बराबरी नहीं चाहिए थी।</p>\n<p>उसे बस इतना चाहिए था कि जब वह टूटे—</p>\n<p>विक्रम वहीं रहे।</p>\n<p>काफी देर बाद नैना की आवाज़ उसकी गोद से आई—</p>\n<p>“सॉरी।”</p>\n<p>विक्रम का हाथ नहीं रुका।</p>\n<p>“किसलिए?”</p>\n<p>“मैंने सोचा था बिना इस तरह टूटे पूरी बात कह लूँगी।”</p>\n<p>“उसके लिए मुझसे कभी माफ़ी मत माँगना।”</p>\n<p>उसने बहुत धीरे कहा—</p>\n<p>“कभी नहीं।”</p>\n<p>नैना वैसे ही पड़ी रही।</p>\n<p>और विक्रम उसके बालों में हाथ फेरता रहा, आँसू थम जाने के बहुत देर बाद तक।</p>\n<p>कुछ दुख समझाए नहीं जाते।</p>\n<p>उनके पास बैठा जाता है।</p>\n<p>उस शाम उन्होंने वही किया।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>मैं उस शाम उनके ऊपर अपने पूरे शबाब में खड़ा था।</p>\n<p>मेरी कोई शाख ऐसी नहीं थी जिस पर फूल न हों। नारंगी आग-से मेरे फूल हर ओर फैले थे—वही रंग जिसे उन दोनों की पहली दोपहर मैं उन्हें दे नहीं पाया था। तब मैं लगभग खाली था, जैसे मौसम ने मुझे रोक रखा हो, जैसे खिलने से पहले मैं ख़ुद भी किसी बात का इंतज़ार कर रहा था।</p>\n<p>मुझे वह पहली दोपहर आज भी याद है।</p>\n<p>पेड़ तस्वीरों में याद नहीं रखते। हमारी याद कहीं और बसती है—छाल की तहों में, जड़ों के अँधेरे में, मौसमों के लौटने में; ठीक वैसे जैसे कोई पुराना घाव बरसों बाद भी शरीर को याद रहता है, भले मन ने उसकी तारीख़ गिननी छोड़ दी हो।</p>\n<p>मुझे याद हैं वे दो अजनबी।</p>\n<p>एक-दूसरे के पास बैठे हुए, फिर भी अपने बीच थोड़ी-सी जगह बचाए हुए।</p>\n<p>नज़रें कभी मिलतीं, कभी बचतीं।</p>\n<p>और एक आवाज़—</p>\n<p>जिसे उस दिन पहली बार एक चेहरा मिला था।</p>\n<p>मैं तब नहीं जानता था कि वे मेरे नीचे कितनी बार लौटेंगे। नहीं जानता था कि मेरी छाँव उनकी खामोशियों को पहचानेगी, कि मेरी शाखों के नीचे उनके हाथ एक-दूसरे तक पहुँचना सीखेंगे, कि मेरे मौसम बदलते-बदलते उनका रिश्ता भी किसी अनकहे से निकलकर इतना गहरा हो जाएगा कि एक दिन उसी जगह बैठकर उन्हें उसके अंत का बोझ उठाना पड़ेगा।</p>\n<p>मुझे उसके बाद की हर मामूली शाम याद है—एक के ऊपर एक जमा होती हुई, जैसे मिट्टी धीरे-धीरे बारिश को अपने भीतर जमा करती है। वह धुंध वाली शाम, जब खाली पार्क में उसने पहली बार इस बेंच को अपना कहा था। वर्दी में ही बैठी एक लड़की, पास रखी टोपी, और उसका बोझ—जिसे उसने बिना झिझके सौंपा और जिसे बिना झिझके थाम लिया गया। फिर उसका अपना दुख, जो उसी सावधानी से उसे लौटाया गया। चीड़ की महक का एक वादा, जो किसी पहाड़ तक गया और लौट आया।</p>\n<p>और वह शाम भी, कुछ ही दिन पहले की, जब उसने कहा था कि वह उसके बिना नहीं रह सकती—कि उसने ख़ुद से भी कभी इतनी मोहब्बत नहीं की—और मुझसे गवाह बनने को कहा था। तब मैंने अपनी एक पंखुड़ी सीधी उसकी खुली हथेली पर गिराया था, ताकि बिना दोबारा कहे उसे पता रहे कि मैंने हर शब्द सुना है।</p>\n<p>आज वे फिर मेरे नीचे थे।</p>\n<p>लेकिन अब उनके बीच कोई अनजान जगह नहीं बची थी।</p>\n<p>वे एक-दूसरे को जानते थे।</p>\n<p>ज़रूरत से भी ज़्यादा।</p>\n<p>और मैं—</p>\n<p>जो उनकी पहली मुलाक़ात के दिन उन्हें एक पूरा फूल तक नहीं दे पाया था—</p>\n<p>आज उनके ऊपर इतना खिला हुआ था कि मेरी शाखाएँ अपने ही रंग के बोझ से झुकी जा रही थीं।</p>\n<p>नीचे नैना का सिर विक्रम की गोद में था।</p>\n<p>उसके कंधे काँप रहे थे।</p>\n<p>विक्रम का हाथ उसके बालों में उसी धीमी लय में चल रहा था जिसमें वह न जाने कितनी बार उसे सँभाल चुका था।</p>\n<p>मैं उनकी हर बात सुन रहा था। मगर मेरे पास उन्हें जवाब देने को कोई आवाज़ नहीं थी—और दुख को समझने के लिए वैसे भी शब्दों की ज़रूरत नहीं होती।</p>\n<p>अगर मैं बोल पाता, तो उन्हें वह सब बताता जो मैंने देखा था—दो लोगों का धीरे-धीरे, बार-बार एक-दूसरे को चुनना; ऐसे महीने, जो मेरी जगह से देखने पर उन सब चीज़ों में सबसे तेज़ बढ़े थे जिन्हें मैंने कभी उगते देखा। उन्हें बताता कि यह कितना दुर्लभ था—मेरी छाँव से अनगिनत मामूली दोपहरें गुज़रीं, और उनमें से कितनी कम कभी ऐसी दिखीं। उनसे कहता कि इसे अंत मत बनने दो—कि कुछ चीज़ें तभी खोती हैं, जब उन्हें उठाए चलने वाले उन्हें खोया हुआ मान लें।</p>\n<p>मगर मेरे पास इनमें से किसी बात के लिए आवाज़ नहीं थी। सिर्फ फूल थे—और अब फूल ही मेरी आख़िरी भाषा बचे थे।</p>\n<p>इसलिए मैंने उन्हें जाने दिया—वैसे ही, जैसे पहले भी सैकड़ों चीज़ों को जाने दिया था, जिन्हें रोकने की ताकत मेरे पास कभी नहीं थी।</p>\n<p>पहले एक पंखुड़ी छूटी।</p>\n<p>फिर दूसरी।</p>\n<p>फिर एक पूरा फूल।</p>\n<p>वही नारंगी रंग, जिसे सीखने में मुझे एक पूरा मौसम लगा था, अब मुझसे वैसे झर रहा था जैसे आँखों से आँसू झरते हैं—धीरे, अनचाहे, और एक बार निकल जाने के बाद किसी की ताकत में नहीं कि उन्हें वापस वहीं पहुँचा दे जहाँ से वे टूटे थे।</p>\n<p>उस शाम मुझे लगा, जैसे पूरा पार्क चुपचाप एक-दूसरे से बात करना सीख गया हो।</p>\n<p>मेरी इस एक बेंच पर जो हो रहा था, उसकी ख़बर बिना किसी आवाज़ के पेड़ से पेड़ तक पहुँच रही थी—उस भाषा में जिसे केवल जड़ें समझती हैं।</p>\n<p>दूर गेट के पास खड़ा पलाश भी उस समय अपने पूरे रंग में था।</p>\n<p>कुछ देर बाद उसने भी अपनी आग छोड़नी शुरू कर दी।</p>\n<p>उसकी नारंगी पंखुड़ियाँ मेरी पंखुड़ियों के साथ रास्ते पर उतरने लगीं।</p>\n<p>और प्रवेश के पास खड़ा अमलतास—</p>\n<p>जिसका पीला रंग अक्सर खुशियों का रंग होता है, शादियों का, शुभ ख़बरों का—</p>\n<p>उसने भी अपनी लंबी सुनहरी लड़ियों से फूल गिराने शुरू कर दिए।</p>\n<p>उस शाम उसका सोना भी उत्सव जैसा नहीं लग रहा था।</p>\n<p>जैसे कोई हमेशा खुश रहने वाली चीज़ पहली बार रोना सीख रही हो।</p>\n<p>कुछ ही मिनटों में रास्ता नारंगी और सुनहरे फूलों से भर गया।</p>\n<p>मैं अपने रंग में रो रहा था।</p>\n<p>पलाश अपने रंग में।</p>\n<p>अमलतास अपने।</p>\n<p>और हमारे नीचे बैठे वे दो इंसान, जिन्हें हमारी इस ख़ामोश भाषा का एक शब्द भी सुनाई नहीं दे सकता था, फिर भी उसी बरसात के बीच बैठे रहे—</p>\n<p>एक ऐसी बारिश में,</p>\n<p>जो शायद वह सब कह रही थी</p>\n<p>जिसे हममें से कोई भी आवाज़ देकर नहीं कह सकता था।</p>\n<p>मैं नहीं जानता था कि उस शाम अपने आख़िरी फूल गिराते हुए मुझे फिर कभी ऐसा प्रेम देखने को मिलेगा या नहीं।</p>\n<p>ऐसा प्रेम जो पूरा था।</p>\n<p>जो अपनी मर्ज़ी से दिया गया था।</p>\n<p>जिसमें किसी ने किसी को धोखा नहीं दिया था।</p>\n<p>और फिर भी जिसे वह अंत नहीं मिला जिसका वह हकदार था।</p>\n<p>लेकिन मैं जा भी कहाँ सकता था?</p>\n<p>पेड़ों के हिस्से में जाना नहीं आता।</p>\n<p>हम वहीं खड़े रहते हैं जहाँ हमें जड़ें मिली होती हैं—लोग आते हैं, बैठते हैं, प्रेम करते हैं, वादे करते हैं, बिछड़ जाते हैं… और हम उनके बाद भी उसी जगह खड़े रह जाते हैं।</p>\n<p>इसलिए मैं भी वहीं खड़ा रहा।</p>\n<p>अपनी उसी मिट्टी में।</p>\n<p>उसी बेंच के ऊपर।</p>\n<p>चुप।</p>\n<p>जड़ों में बँधा हुआ।</p>\n<p>और उम्मीद भी करता हुआ।</p>\n<p>किसी अगली दोपहर की।</p>\n<p>किसी अगली आवाज़ की जिसे पहली बार कोई चेहरा मिले।</p>\n<p>किसी अगली लड़की और किसी अगले लड़के की, जो मेरी छाँव में आकर बैठें और कुछ देर बाद उनका एक हाथ दूसरे हाथ को वैसे ही ढूँढ़ ले जैसे कभी इन दोनों ने एक-दूसरे को ढूँढ़ लिया था।</p>\n<p>बस अगली बार—</p>\n<p>अगर मेरे फूलों से कुछ माँगा जाए—</p>\n<p>तो मैं केवल इतना चाहूँगा कि मुझे किसी कहानी का अंत इस तरह न देखना पड़े।</p>\n<p>अगली बार जो दो लोग मेरे नीचे प्रेम में पड़ें—</p>\n<p>उन्हें साथ रहने दिया जाए।</p>\n<p>और कहानी को वहाँ तक पहुँचने दिया जाए,</p>\n<p>जहाँ तक नैना और विक्रम की कहानी</p>\n<p>कभी पहुँच नहीं सकी।</p>"}, {"chapter": 33, "title": "अध्याय 31 — आख़िरी शाम", "content": "<h1>अध्याय 31 — आख़िरी शाम</h1>\n<p>पिता के आख़िरी इनकार को एक हफ्ता हो चुका था, जब नैना के भीतर अपने दुख से अलग एक और डर धीरे-धीरे जगह बनाने लगा—वैसे ही जैसे आग बुझ जाने के बाद किसी घर में ठंड उतरती है; पहले महसूस नहीं होती, फिर अचानक पता चलता है कि वह हर कमरे में फैल चुकी है।</p>\n<p>उस शाम गुलमोहर की बेंच पर विक्रम एक बार भी नहीं रोया था।</p>\n<p>नैना पिछले कई दिनों से इसी बात के बारे में सोच रही थी।</p>\n<p>अब उसे लगने लगा था कि वह स्थिरता मज़बूती नहीं थी। शायद विक्रम अपने भीतर किसी चीज़ को इतनी ताकत से रोके हुए था कि वही रोकना ख़तरनाक हो सकता था। वह ऐसे जवानों को जानती थी, जिन्हें दुख को शब्द देने से ज़्यादा उसे भीतर बंद रखना सिखाया जाता है।</p>\n<p>वह ऐसा नहीं होने दे सकती थी।</p>\n<p>कम-से-कम अपनी वजह से नहीं।</p>\n<p>इसलिए शादी से तीन दिन पहले जब उसने विक्रम को फोन किया, तो वह सिर्फ आख़िरी बार मिलने के लिए नहीं था। वह चाहती थी कि इस रात के बाद विक्रम उससे और ज़्यादा टूटा हुआ नहीं, जितना संभव हो उतना सँभला हुआ लौटे।</p>\n<p>फोन उठते ही नैना ने कहा—</p>\n<p>“मैं तुमसे मिलना चाहती हूँ।”</p>\n<p>कुछ पल बाद—</p>\n<p>“एक बार और। सब बदलने से पहले।”</p>\n<p>“जहाँ कहो।”</p>\n<p>“लड़ने के लिए नहीं।”</p>\n<p>नैना ने जल्दी से कहा, जैसे यह बात पहले साफ़ कर देना ज़रूरी हो।</p>\n<p>“मैं बाबा का मन बदलवाने के लिए फोन नहीं कर रही। न तुम्हारे साथ भागने के लिए। पिछले तीन दिनों से रात-रात भर जागकर जो भी रास्ते दिमाग में आए हैं, मैं एक-एक करके सब सोच चुकी हूँ… और छोड़ चुकी हूँ।”</p>\n<p>लाइन पर कुछ क्षण ख़ामोशी रही।</p>\n<p>“बस एक शाम चाहिए, विक्रम।”</p>\n<p>उसकी आवाज़ हल्की पड़ गई।</p>\n<p>“बाद में याद रखने के लिए कुछ।”</p>\n<p>“मैं आऊँगा।”</p>\n<p>विक्रम ने बिना किसी सवाल के कहा।</p>\n<p>“जहाँ तुम चाहो।”</p>\n<p>फोन पर फिर ख़ामोशी हुई।</p>\n<p>इतनी लंबी कि विक्रम को लगा दूसरी तरफ नैना रो रही है और नहीं चाहती कि उसे आवाज़ सुनाई दे।</p>\n<p>जब वह फिर बोली तो आवाज़ पतली थी, मगर सँभली हुई।</p>\n<p>“थैंक यू… बहस न करने के लिए।”</p>\n<p>“अभी तुम्हें जो चाहिए, उससे बहस करने का हक नहीं है मुझे।”</p>\n<p>विक्रम ने कहा।</p>\n<p>“सिर्फ देने का है।”</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>विक्रम उससे पहले पहुँच गया था।</p>\n<p>शहर के किनारे का वह रिज़ॉर्ट उसने बहुत सोचकर चुना था—फैले हुए सँवरे लॉन, भीतर ही एक शांत रेस्तराँ, और उसके सामने पानी के भीतर से रोशन होता स्विमिंग पूल, जिसकी हल्की सुनहरी रोशनी रात में भी जैसे अपने लिए थोड़ी-सी चमक बचाकर रखे हुए थी।</p>\n<p>वह जगह ऐसी शामों के लिए बनी लगती थी जिन्हें लोग ठीक से याद रखना चाहते हैं—सालगिरहें, प्रस्ताव, ज़िंदगी के वे छोटे-बड़े अवसर जिन्हें बाद में किसी तारीख़ से ज़्यादा एक एहसास की तरह याद किया जाता है।</p>\n<p>विक्रम ने जानबूझकर ऐसी जगह चुनी थी जहाँ नैना पहले कभी न आई हो।</p>\n<p>जहाँ इस शाम में किसी और स्मृति की हिस्सेदारी न हो।</p>\n<p>और इतनी खूबसूरत कि जिस बात को यह रात अपने भीतर रखने वाली थी, उसके सामने जगह छोटी न लगे।</p>\n<p>वह मेज़ पर बैठा अपने गिलास को उँगलियों के बीच धीरे-धीरे घुमा रहा था और मन ही मन मिलने के न जाने कितने तरीके बनाकर मिटा चुका था।</p>\n<p>कोई भी ठीक नहीं लग रहा था।</p>\n<p>आख़िरी शाम के लिए सही पहला वाक्य शायद होता ही नहीं।</p>\n<p>नैना हरे रंग में आई।</p>\n<p>शादी वाले लहँगे का गहरा, सजा हुआ हरा नहीं—एक साधारण, मुलायम हरा कुर्ता, जैसा वह किसी और आम शाम को पहन सकती थी—वैसा हरा, जैसा गुलमोहर में फूलों से पहले आता है।</p>\n<p>विक्रम ने उसे देखते ही समझ लिया कि वह आने से पहले रो चुकी है और फिर बहुत सावधानी से चेहरे से उसके निशान मिटाकर आई है।</p>\n<p>वह सामने बैठी।</p>\n<p>विक्रम ने कहा—</p>\n<p>“बहुत खूबसूरत लग रही हो।”</p>\n<p>“मत कहो।”</p>\n<p>नैना ने तुरंत रोक दिया।</p>\n<p>“आज नहीं। तुमने ऐसी बातें शुरू कर दीं तो मैं डिनर तक नहीं पहुँच पाऊँगी।”</p>\n<p>फिर भी उसके होंठों पर छोटी-सी मुस्कान आ गई।</p>\n<p>सच्ची।</p>\n<p>और सिर्फ इतना सामान्य कह पाने से ही उसके कंधों का तनाव थोड़ा उतर गया।</p>\n<p>उन्होंने ज़रूरत से ज़्यादा खाना मँगाया।</p>\n<p>शायद इसलिए कि ऑर्डर देना भी उस असली बातचीत को कुछ देर और टालने का तरीका था जो दोनों के बीच मेज़ के नीचे कहीं पहले से बैठी थी।</p>\n<p>काफी देर तक वे उन्हीं बातों पर बोलते रहे जिनका आज की रात से कोई लेना-देना नहीं था—एक फिल्म जो नैना ने देखी थी और विक्रम को बताना भूल गई थी; बचपन का उसका कुत्ता जो हर शाम गेट पर उसके पिता की जीप का इंतज़ार करता था; ट्रेनिंग के दिनों की एक घटना जो इतने महीनों में भी किसी तरह विक्रम ने नहीं सुनी थी।</p>\n<p>वह अपनी ही किसी याद पर हँसती तो विक्रम उसे देखता रहता।</p>\n<p>बाल पीछे करती।</p>\n<p>पानी का गिलास उठाती।</p>\n<p>बात करते हुए अचानक आँखें बड़ी कर लेती।</p>\n<p>और हर छोटी चीज़ को वह अपने भीतर कहीं रखता जा रहा था।</p>\n<p>जानबूझकर।</p>\n<p>लगभग बेचैनी से।</p>\n<p>जैसे इंसान किसी ऐसी चीज़ को याद नहीं करता—</p>\n<p>उसे अपने भीतर बचाता है</p>\n<p>जिसे वह पहले से जानता हो कि खोने वाला है।</p>\n<p>दूसरा कोर्स लगभग ख़त्म होने के बाद नैना ने काँटा नीचे रखा।</p>\n<p>“मैंने तुम्हें कभी नहीं बताया कि उस दिन सुनैना ने मुझसे क्या कहा था।”</p>\n<p>विक्रम तुरंत समझ गया।</p>\n<p>“जब वह तुम्हारे फ्लैट पर अचानक आई थी?”</p>\n<p>“हाँ।”</p>\n<p>“मैंने बहुत सोचा था उस दिन उसने क्या कहा।”</p>\n<p>“मुझे पता है।”</p>\n<p>नैना ने पानी का गिलास मेज़ पर धीरे-धीरे आधा घुमाया।</p>\n<p>“कई हफ्तों तक तुम्हारे चेहरे पर देखती रही कि तुम जानना चाहते हो। लेकिन तब मैं ख़ुद भी उसे ज़ोर से कहने के लिए तैयार नहीं थी।”</p>\n<p>वह कुछ पल नीचे देखती रही।</p>\n<p>“उसने कहा था—इस इंसान को जाने मत देना। ज़िंदगी में दूसरा ऐसा नहीं मिलेगा।”</p>\n<p>विक्रम चुप रहा।</p>\n<p>“उसने कहा था, मुझे जो बात मानने में महीनों लगे, उसे उसने तुम्हारे साथ एक दोपहर बिताकर समझ लिया था।”</p>\n<p>नैना की आँखें उसकी ओर उठीं।</p>\n<p>“कि तुम मुझे संभाल सकते हो। मुझे चलाने की कोशिश नहीं करोगे… मुझे संभाल सकते हो।”</p>\n<p>उसकी आवाज़ में हल्की मुस्कान आई।</p>\n<p>“उसने कहा था कमज़ोर इंसान मेरे जैसी औरत को अपने हिसाब से छोटा करने लगेगा, ताकि उससे प्यार करना आसान हो जाए। और उससे भी छोटा इंसान शायद मेरे साथ खड़ा होना ही मुश्किल समझेगा।”</p>\n<p>विक्रम की आँखें उससे नहीं हटीं।</p>\n<p>“उसने कहा था तुम दोनों में से कोई नहीं हो। तुम्हारी शांति में भी अपना जुनून है—तुम्हें अपनी बात मनवाने के लिए आवाज़ ऊँची नहीं करनी पड़ती।”</p>\n<p>अब नैना की आँखें भर आई थीं।</p>\n<p>“और उसने कहा था अगर मैंने तुम्हें जाने दिया तो ज़िंदगी की सबसे बड़ी ग़लती होगी।”</p>\n<p>उसने एक गीली साँस छोड़ी—जो आधी हँसी थी, आधी रुलाई।</p>\n<p>दर्द उस साँस से कहीं बड़ा था।</p>\n<p>“मेरी छोटी बहन ने तुम्हें एक दोपहर जानकर ये कहा था।”</p>\n<p>उसने गहरी साँस ली।</p>\n<p>“और मैं आज यहाँ बैठी हूँ… शायद उसे सबसे बुरे तरीके से सही साबित करने के लिए।”</p>\n<p>“तुम उसे सही साबित नहीं कर रही।”</p>\n<p>विक्रम ने कहा।</p>\n<p>“किसी से प्यार करना और फिर किसी ऐसी चीज़ की वजह से उसे खो देना जिस पर तुम दोनों का बस नहीं था—इससे उसकी बात ग़लत नहीं हो जाती।”</p>\n<p>नैना उसे देखती रही।</p>\n<p>“बस दुनिया उतनी आसान नहीं निकली जितनी उसे उस दोपहर लगी थी।”</p>\n<p>“मुझे बचाने का अच्छा तरीका है।”</p>\n<p>“तुम्हें बचा नहीं रहा।”</p>\n<p>विक्रम की आवाज़ स्थिर थी।</p>\n<p>“सच में यही मानता हूँ।”</p>\n<p>नैना ने मेज़ के पार हाथ बढ़ाया और उसका हाथ पकड़ लिया।</p>\n<p>गर्म कमरे में भी उसकी उँगलियाँ ठंडी थीं।</p>\n<p>“मैं पूरी रात का कोई ऐसा रूप ढूँढ़ रही हूँ जिसमें मुझे लगे कि मैं तुम्हारे साथ ग़लत नहीं कर रही।”</p>\n<p>उसने कहा।</p>\n<p>“अभी तक नहीं मिला।”</p>\n<p>“तुम मेरे साथ ग़लत नहीं कर रही, नैना।”</p>\n<p>“तो इसे क्या कहूँ?”</p>\n<p>उसकी आँखें सीधे उसकी आँखों में थीं।</p>\n<p>“जिस इंसान से ज़िंदगी में सबसे ज़्यादा प्यार किया, उसी के ऊपर अपने पिता को चुन रही हूँ।”</p>\n<p>विक्रम ने उसकी हथेली पलटी और उसकी लकीरों पर उँगली फिराई—वही पुरानी आदत, जैसे जवाब देने से पहले कुछ पल वहीं से उधार ले रहा हो।</p>\n<p>“मैं इसे वही प्यार कहूँगा जो तुम अपने परिवार से करती हो।”</p>\n<p>नैना की आँखों में एक परछाईं-सी हिली।</p>\n<p>“तुमने मुझे चुनना बंद नहीं किया। तुम उन्हें भी चुन रही हो, क्योंकि उनसे भी प्यार करती हो—बस दूसरे ढंग से।”</p>\n<p>उसने उसकी हथेली अपने सीने से लगा ली।</p>\n<p>“तुम जानती हो तुम्हारे पिता से टकराने की कीमत तुम्हारी माँ चुकाएँगी। और तुम इतनी ख़ुदग़र्ज़ नहीं हो कि अपनी खुशी उठा लो और उसका हिसाब बाकी लोगों के नाम छोड़ दो।”</p>\n<p>उसकी आवाज़ नरम हुई।</p>\n<p>“इसे हार मत कहो।”</p>\n<p>एक पल।</p>\n<p>“शायद ये प्यार का सबसे मुश्किल रूप है—जिसमें सबसे बड़ी कीमत वही देता है जो प्यार कर रहा होता है।”</p>\n<p>नैना कुछ नहीं बोली।</p>\n<p>बहुत देर तक उसका हाथ पकड़े रही।</p>\n<p>फिर लगभग फुसफुसाकर कहा—</p>\n<p>“मुझे नहीं पता तुम्हारे बिना अपनी ज़िंदगी कैसे जीऊँगी।”</p>\n<p>“जी लोगी।”</p>\n<p>विक्रम ने झूठी आसानी से नहीं कहा।</p>\n<p>“आसानी से नहीं। कई साल तक ऐसी जगहों पर मेरी याद आएगी जहाँ तुम्हें ख़ुद उम्मीद नहीं होगी।”</p>\n<p>विक्रम ने उसकी आँखों में देखा।</p>\n<p>“लेकिन जी लोगी। क्योंकि जितने लोगों को मैंने जाना है, उनमें सबसे मजबूत तुम हो।”</p>\n<p>फिर—</p>\n<p>“और अब जो भी ज़िंदगी बनाओगी, उसमें हमारा कुछ हिस्सा रहेगा। चाहे कभी उसका नाम लो या नहीं।”</p>\n<p>विक्रम चुप रहा।</p>\n<p>फिर उसके चेहरे पर कोई फ़ैसला उतर आया।</p>\n<p>“एक बात कहूँ?”</p>\n<p>“कहो।”</p>\n<p>“और इसे सिर्फ ऐसी बात समझकर मत सुनना जो लोग बिछड़ते वक्त अंत को थोड़ा कम दर्दनाक बनाने के लिए कह देते हैं।”</p>\n<p>नैना स्थिर हो गई।</p>\n<p>विक्रम ने उसकी आँखों में देखते हुए कहा—</p>\n<p>“एक दिन मैं तुम तक पहुँचूँगा।”</p>\n<p>नैना की भौंहें हल्की सिकुड़ीं।</p>\n<p>“सालों बाद। बिना हमारे रास्ते दोबारा मिले। बिना मेरे सामने आए।”</p>\n<p>“न फोन पर।”</p>\n<p>एक ठहराव।</p>\n<p>“न दरवाज़े पर दस्तक देकर।”</p>\n<p>नैना बस उसे देख रही थी।</p>\n<p>“उसका वक्त मैं तय नहीं कर पाऊँगा। वह पहले से ख़बर देकर नहीं आएगा। किसी चिट्ठी की तरह अपना नाम लेकर भी नहीं।”</p>\n<p>विक्रम के शब्द अब जैसे उसी रात से आगे किसी ऐसी जगह जा रहे थे जिसे दोनों में से कोई देख नहीं सकता था।</p>\n<p>“वह ऐसे आएगा जैसे बहुत लंबे सूखे के बाद पहली बारिश आती है। बिना बुलाए। बिना तारीख़ बताए। लेकिन पहली बूँद गिरने से पहले ही मिट्टी जैसे जान लेती है कि पानी आने वाला है।”</p>\n<p>नैना की उँगलियाँ उसके हाथ पर कस गईं।</p>\n<p>“तुम किसी बिल्कुल साधारण जगह पर होगी। किसी ऐसे काम में लगी हुई जिसका मुझसे कोई रिश्ता नहीं होगा।”</p>\n<p>वह रुका।</p>\n<p>“और अचानक तुम्हारे भीतर सब कुछ एक पल के लिए शांत हो जाएगा।”</p>\n<p>उसकी आवाज़ अब लगभग फुसफुसाहट थी।</p>\n<p>“वैसा ठहराव… जैसे बारिश से ठीक पहले हवा साँस रोक लेती है और आसमान को याद आता है कि उसे बरसना है।”</p>\n<p>नैना की आँखों में नमी चमकी।</p>\n<p>“वह ठहराव मैं होऊँगा।”</p>\n<p>विक्रम ने कहा।</p>\n<p>“तुम तक पहुँचने का मेरा आख़िरी तरीका।”</p>\n<p>विक्रम ने उसका हाथ थामे रखा।</p>\n<p>“और उस पल तुम्हें समझ आएगा कि हमारे बीच जो था, वह कितना गहरा था।”</p>\n<p>नैना बहुत देर चुप रही।</p>\n<p>“ये नामुमकिन वादा है।”</p>\n<p>“शायद।”</p>\n<p>विक्रम के चेहरे पर बहुत हल्की मुस्कान आई।</p>\n<p>“फिर भी कर रहा हूँ।”</p>\n<p>विक्रम ने उसकी आँखों से नज़र नहीं हटाई।</p>\n<p>“और जब कभी ऐसा हो… ये शाम याद रखना। ये वाक्य याद रखना।”</p>\n<p>एक साँस।</p>\n<p>“ताकि तुम्हें पता हो—मैंने अपना वादा निभाया।”</p>\n<p>कुछ पल बाद उसके चेहरे पर गंभीरता और गहरी हो गई।</p>\n<p>“और एक कर्ज भी है।”</p>\n<p>नैना की आँखें प्रश्न में उठीं।</p>\n<p>“तुम्हारी वो तीन लाइनें।”</p>\n<p>नैना की साँस एक पल को रुकी।</p>\n<p>विक्रम उन्हें भूल ही नहीं सकता था।</p>\n<p>खून से लिखे वे तीन वाक्य—</p>\n<p><b>मैं इंतज़ार कर रही हूँ।<br/>\nतुमने वादा किया है कि लौटोगे।<br/>\nज़िंदा लौटना, विक्रम।</b></p>\n<p>विक्रम ने कहा—</p>\n<p>“एक शब्द नहीं भूला।”</p>\n<p>नैना की आँखों से आँसू निकल आए।</p>\n<p>“ऐसी चीज़ का कर्ज शायद पूरी तरह कभी चुकता नहीं होता।”</p>\n<p>विक्रम की आवाज़ भारी हो गई।</p>\n<p>“लेकिन जितना वक्त लगे… जैसे भी हो… उनका जवाब दूँगा।”</p>\n<p>वह उसकी ओर झुका।</p>\n<p>“तीन लाइनों में नहीं।”</p>\n<p>हल्की-सी साँस।</p>\n<p>“इतना बड़ा जवाब जितना उन तीन लाइनों का हक है।”</p>\n<p>नैना का चेहरा थोड़ा टूट गया।</p>\n<p>इतने महीनों से दोनों ने उन पंक्तियों को इस तरह सामने रखकर कभी बात नहीं की थी।</p>\n<p>“तुमने मुझे इन महीनों में जितना दिया है, उसका पूरा हिसाब शायद ज़िंदगी भर नहीं चुका पाऊँगा।”</p>\n<p>विक्रम ने कहा।</p>\n<p>“लेकिन ये कर्ज…”</p>\n<p>उसने उसका हाथ कसकर पकड़ा।</p>\n<p>“ये ज़रूर चुकाऊँगा।”</p>\n<p>नैना ने जवाब नहीं दिया।</p>\n<p>बस सिर हिला दिया।</p>\n<p>उसे नहीं मालूम था कि वह इस वादे पर क्यों भरोसा कर रही है।</p>\n<p>बस कर रही थी।</p>\n<p>फिर विक्रम ने कहा—</p>\n<p>“एक वादा मुझे भी चाहिए तुमसे।”</p>\n<p>“क्या?”</p>\n<p>“शादी के बाद… तुम्हारे और तुम्हारे पति के बीच चाहे जितनी नज़दीकी हो जाए, चाहे तुम्हें लगे अच्छे रिश्ते में हर सच बताया जाना चाहिए…”</p>\n<p>उसकी आवाज़ और गंभीर हो गई।</p>\n<p>“हमारे बारे में उसे मत बताना।”</p>\n<p>नैना का चेहरा बदल गया।</p>\n<p>“कभी नहीं, नैना। मुझसे वादा करो।”</p>\n<p>“तुम्हें नहीं लगता शादी सच पर बननी चाहिए?”</p>\n<p>“मुझे लगता है शादी उस चीज़ पर बननी चाहिए जिसमें दो लोग एक-दूसरे से ठीक तरह प्यार करने के लिए सुरक्षित रह सकें।”</p>\n<p>विक्रम ने कहा।</p>\n<p>“हर सच देना ज़रूरी नहीं होता। कुछ सच सामने वाले को देने से ज़्यादा उस इंसान को चोट पहुँचाते हैं जिसने उन्हें जिया है।”</p>\n<p>“मैं ख़ुद को बचाने के लिए नहीं कह रहा। मैं वहाँ रहूँगा ही नहीं।”</p>\n<p>उसकी आँखें नैना पर थीं।</p>\n<p>“मैंने देखा है जलन इंसान की याद में उस औरत को भी बदल देती है जिससे वह प्यार करता है, जबकि वह औरत असल में बदली तक नहीं होती।”</p>\n<p>उसकी आवाज़ नरम हुई।</p>\n<p>“मैं वह ख़तरा तुम्हारे पास नहीं छोड़ना चाहता।”</p>\n<p>नैना काफी देर उसे देखती रही।</p>\n<p>उसके चेहरे पर असहमति अब भी थी।</p>\n<p>वह अभी भी पूरी तरह नहीं मानती थी कि किसी सच को न कहना भी कभी-कभी किसी रिश्ते की रक्षा हो सकता है।</p>\n<p>“वादा करो, नैना।”</p>\n<p>इस बार विक्रम की आवाज़ में आग्रह था।</p>\n<p>“प्लीज़।”</p>\n<p>बहुत देर बाद उसने कहा—</p>\n<p>“वादा करती हूँ।”</p>\n<p>विक्रम ने उसकी आँखों में कुछ क्षण और देखा।</p>\n<p>फिर बात वहीं छोड़ दी।</p>\n<p>आख़िर वादों के साथ इससे ज़्यादा किया भी क्या जा सकता है—</p>\n<p>उन्हें मान लिया जाता है,</p>\n<p>खासकर उन वादों को जिन्हें टूटते या निभते देखने के लिए आप वहाँ मौजूद नहीं होंगे।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>डिनर के बाद नैना ने कहा—</p>\n<p>“कहीं शांत जगह चलें?”</p>\n<p>“बात करने?”</p>\n<p>नैना ने सिर हिलाया।</p>\n<p>“नहीं।”</p>\n<p>फिर—</p>\n<p>“बस अभी ख़त्म नहीं होना चाहती।”</p>\n<p>विक्रम ने उसी रिज़ॉर्ट में एक कमरा लिया हुआ था।</p>\n<p>पहले से।</p>\n<p>लेकिन इस बार वह किसी चुराई हुई रात जैसा नहीं था।</p>\n<p>न कोई जल्दबाज़ी।</p>\n<p>न किसी से छिपने की ज़रूरत।</p>\n<p>अभी नैना की शादी नहीं हुई थी।</p>\n<p>छिपाने के लिए बस एक सच था—</p>\n<p>तीन दिन बाद दुनिया जिस तरह रिश्तों को पहचानती है, उस तरह वह किसी और की हो जाएगी।</p>\n<p>कमरा बड़ा था, रोशनी मुलायम। शीशे की पूरी दीवार के उस पार वही लॉन फैला था और नीचे पूल की सुनहरी रोशनी अब भी अँधेरे पानी में चुपचाप जल रही थी।</p>\n<p>दरवाज़ा बंद हुआ।</p>\n<p>फिर भी दोनों किसी चीज़ की ओर जल्दी नहीं बढ़े।</p>\n<p>नैना ने सैंडल उतारी और पलंग के किनारे बैठ गई।</p>\n<p>विक्रम उसके पास।</p>\n<p>काफी देर तक वे बस बात करते रहे।</p>\n<p>धीरे।</p>\n<p>बिना किसी मंज़िल के।</p>\n<p>उस एक बात के चारों ओर घूमते हुए जिसका नाम दोनों अभी नहीं लेना चाहते थे।</p>\n<p>कब विक्रम ने हाथ बढ़ाकर उसके बालों में लगी पिन खोलनी शुरू की, दोनों में से किसी ने उस क्षण को दर्ज नहीं किया।</p>\n<p>उसने बहुत सावधानी से पिन निकाली।</p>\n<p>बाल धीरे-धीरे खुलकर उसके कंधों पर आ गए।</p>\n<p>वैसे ही जैसे विक्रम को हमेशा अच्छे लगते थे।</p>\n<p>नैना ने उसे रोका नहीं।</p>\n<p>कुछ कहा भी नहीं।</p>\n<p>बस उसके चेहरे से थोड़ी-सी थकान उतर गई।</p>\n<p>फिर वह उसके करीब खिसकी और सिर उसकी छाती पर रख दिया।</p>\n<p>जैसे न जाने कितनी बार पहले रखा था।</p>\n<p>विक्रम का हाथ उसके बालों में चला गया।</p>\n<p>नैना की उँगलियाँ उसकी शर्ट पर बेवजह आकृतियाँ बनाती रहीं।</p>\n<p>कभी दोनों बात करते।</p>\n<p>कभी चुप हो जाते।</p>\n<p>उस साधारण-सी नज़दीकी को जितना खींच सकते थे, खींचते रहे—क्योंकि अब साधारण चीज़ें ही सबसे ज़्यादा कीमती थीं।</p>\n<p>“एक बात समझना।”</p>\n<p>नैना ने उसकी छाती से लगे-लगे कहा।</p>\n<p>“मैंने तुमसे प्यार किया है।”</p>\n<p>विक्रम का हाथ उसके बालों में चलता रहा।</p>\n<p>“पूरा।”</p>\n<p>उसने आँखें बंद कर लीं।</p>\n<p>“ऐसा नहीं कि दस साल बाद घर-गृहस्थी और ज़िंदगी के बीच इसे अपनी जवानी का कोई दौर कहकर समझा दूँगी।”</p>\n<p>उसकी आवाज़ काँपी।</p>\n<p>“इसके बाद ज़िंदगी जहाँ भी जाए… ये सच था।”</p>\n<p>उसने चेहरा उठाकर उसे देखा।</p>\n<p>“हम सच थे।”</p>\n<p>विक्रम ने कहा—</p>\n<p>“सिर्फ तुम्हारी तरफ से नहीं।”</p>\n<p>उसकी उँगलियाँ नैना के बालों में ठहर गईं।</p>\n<p>“तुम्हारे पिता कुछ भी मानें। दुनिया इस कहानी के बारे में कुछ भी माने जिसे वह कभी पूरा जानेगी ही नहीं…”</p>\n<p>उसने नैना की आँखों में देखा।</p>\n<p>“मैंने भी तुमसे प्यार किया है।”</p>\n<p>फिर—</p>\n<p>“तुम्हारे पूरे रूप से। सिर्फ आसान हिस्सों से नहीं।”</p>\n<p>नैना उठकर उसके सामने बैठ गई।</p>\n<p>“तो आज इसे कोई प्रदर्शन मत बनाना।”</p>\n<p>विक्रम चुप रहा।</p>\n<p>“और ये सोचकर जल्दी मत करना कि रात ख़त्म हो जाएगी।”</p>\n<p>उसकी आवाज़ एक पल टूटी।</p>\n<p>“रात तो वैसे भी ख़त्म होगी।”</p>\n<p>फिर ख़ुद को सँभालकर—</p>\n<p>“मैं चाहती हूँ हर मिनट जितना खिंच सकता है, उतना खिंचे।”</p>\n<p>विक्रम ने सिर हिलाया।</p>\n<p>“ठीक है।”</p>\n<p>“और विक्रम…”</p>\n<p>वह रुकी।</p>\n<p>“मेरे साथ वैसे रहना जैसे पहली बार थे।”</p>\n<p>उसकी आँखें उससे नहीं हटीं।</p>\n<p>“काँच समझकर मत छूना।”</p>\n<p>एक साँस।</p>\n<p>“ऐसी लड़की की तरह भी नहीं जिसे तुम अभी से खो चुका मान रहे हो।”</p>\n<p>उसने उसका हाथ अपने हाथ में लिया।</p>\n<p>“मैं अभी यहीं हूँ।”</p>\n<p>और फिर—</p>\n<p>“आज भी तुम्हें चुन रही हूँ। एक आख़िरी बार। मेरे पास जितना कुछ बचा है, उस सबके साथ।”</p>\n<p>विक्रम ने उसे अपने करीब खींच लिया।</p>\n<p>बिना किसी घोषणा के।</p>\n<p>जैसे पहली बार दोनों को वहाँ तक पहुँचने के लिए शब्दों की ज़रूरत नहीं पड़ी थी।</p>\n<p>आज भी नहीं पड़ी।</p>\n<p>इस बार कोई जल्दी नहीं थी।</p>\n<p>न पहाड़ वाली पहली रात की वह अनजान बेचैनी, न वह भूख जिसने तब दोनों को ख़ुद चौंका दिया था।</p>\n<p>यह उससे अलग था।</p>\n<p>धीमा।</p>\n<p>गहरा।</p>\n<p>हर ठहराव ज़रूरत से एक पल ज़्यादा—क्योंकि अब अगली बार के लिए कुछ बचाकर रखने का कोई अर्थ नहीं था।</p>\n<p>विक्रम ने उसके चेहरे को दोनों हाथों में लिया।</p>\n<p>कुछ क्षण बस उसे देखा।</p>\n<p>जैसे आँखें भी स्मृति बना सकती हों।</p>\n<p>फिर उसने माथा उसके माथे से टिका दिया।</p>\n<p>नैना ने आँखें बंद कर लीं।</p>\n<p>कमरे की मुलायम रोशनी, शीशे के पार अँधेरा, नीचे पानी में ठहरी सुनहरी चमक—</p>\n<p>धीरे-धीरे सब पीछे छूटता गया।</p>\n<p>फिर रोशनी बुझ गई।</p>\n<p>“मेरे साथ रहना।”</p>\n<p>नैना ने अँधेरे में फुसफुसाकर कहा।</p>\n<p>वह उसे कहीं जाने से रोक नहीं रही थी।</p>\n<p>बस उस क्षण में पूरा चाहती थी।</p>\n<p>“बस मेरे साथ रहना।”</p>\n<p>“मैं यहीं हूँ।”</p>\n<p>विक्रम ने उसे और करीब कर लिया।</p>\n<p>“आज रात कहीं नहीं जा रहा।”</p>\n<p>बाहर रात अपने समय से चल रही थी।</p>\n<p>अंदर दोनों उसे जितना हो सके रोक लेना चाहते थे।</p>\n<p>बाद में, जब कमरा फिर शांत हुआ, नैना की आँखों के किनारों से आँसू चुपचाप बह गए।</p>\n<p>न उसने उन्हें छिपाया।</p>\n<p>न विक्रम ने पोंछने की कोशिश की।</p>\n<p>बस उसे थामे रहा—और पहली बार उस रात ख़ुद को पूरी तरह यह महसूस करने दिया कि सुबह उससे क्या छीनने वाली है।</p>\n<p>उसके बाद भी दोनों बहुत देर तक अलग नहीं हुए।</p>\n<p>जैसे जो पहले हिलेगा वही रात को आगे बढ़ा देगा।</p>\n<p>नैना की उँगलियाँ उसकी पीठ पर बिना किसी मकसद के धीमी रेखाएँ बनाती रहीं।</p>\n<p>“एक दिन का भी अफसोस नहीं है मुझे।”</p>\n<p>नैना ने आख़िर कहा।</p>\n<p>आवाज़ भरी हुई थी।</p>\n<p>“एक भी नहीं।”</p>\n<p>कुछ पल बाद—</p>\n<p>“आज का भी नहीं… जबकि ये शायद ज़िंदगी की सबसे मुश्किल चीज़ है जो मैंने की है।”</p>\n<p>“मुझे भी नहीं।”</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>वे ठीक से सोए ही नहीं।</p>\n<p>रात के बचे हुए घंटे एक-दूसरे के पास लेटे, कभी बातें करते, कभी लंबे समय तक चुप रहते हुए गुज़रते रहे।</p>\n<p>वे ऐसी यादें एक-दूसरे को सौंपते रहे जिन्हें दोनों चाहते थे कि दूसरा भूल न जाए; ऐसी छोटी स्वीकारोक्तियाँ भी, जिनके लिए इतने महीनों में कभी सही वक्त नहीं मिला था।</p>\n<p>नैना ने उसे अपने बचपन के उन जन्मदिनों के बारे में बताया जिनमें पिता घर नहीं आ पाए थे—इतने कि अब वह आसानी से गिन भी नहीं सकती थी। जन्मदिन जैसी छोटी चीज़ के लिए छुट्टी कहाँ मिलती थी।</p>\n<p>किसी ऐसे ही जन्मदिन पर उसने ख़ुद से वादा किया था कि जिसे वह प्यार करेगी, उसे कभी उस तरह के इंतज़ार का अर्थ नहीं जानने देगी।</p>\n<p>विक्रम ने कहा—</p>\n<p>“जान चुकी हो।”</p>\n<p>नैना उसकी ओर देखती रही।</p>\n<p>“मेरी पोस्टिंग के हर ख़ामोश दिन में तुमने उसी इंतज़ार का थोड़ा-सा हिस्सा जिया है।”</p>\n<p>विक्रम ने नज़रें झुका लीं।</p>\n<p>“और कभी-कभी ख़ुद से नफ़रत होती है कि तुमसे इतना प्यार करके भी वही चीज़ तुम्हें दे दी जिससे तुम हमेशा बचना चाहती थीं।”</p>\n<p>नैना ने अपनी हथेली उसके सीने पर रख दी।</p>\n<p>ठीक दिल के ऊपर।</p>\n<p>“ख़ुद से नफ़रत मत करना।”</p>\n<p>“नैना—”</p>\n<p>“हालात से करो। बाबा के डर से कर लो, अगर गुस्सा कहीं रखना ही है।”</p>\n<p>उसकी हथेली वहीं रही।</p>\n<p>“लेकिन अपने उन हिस्सों से मत करना जिन्होंने मुझे ये महीने दिए।”</p>\n<p>“ये मेरी ज़िंदगी के सबसे अच्छे महीने हैं।”</p>\n<p>एक आँसू निकल गया।</p>\n<p>“इन्हें अपनी माफ़ी मत बनाना, विक्रम।”</p>\n<p>रात और गहरी हुई।</p>\n<p>और उसी गहराई में, बहुत देर तक ख़ुद को थामे रहने के बाद, विक्रम के भीतर भी कुछ आख़िर टूट गया।</p>\n<p>पूरी शाम वह सँभला रहा था।</p>\n<p>डिनर पर।</p>\n<p>कमरे में।</p>\n<p>नैना के आँसुओं के बीच।</p>\n<p>हर जगह वही इंसान जो उसके लिए अडिग रहता आया था।</p>\n<p>लेकिन अब, जब नैना की साँसें उसकी छाती पर कुछ शांत हुईं, उसके भीतर की पकड़ अचानक ढीली पड़ गई।</p>\n<p>वह बिना सोचकर करवट बदला और अपना सिर नैना की गोद में रख दिया।</p>\n<p>ठीक वैसे—</p>\n<p>जैसे नैना न जाने कितनी बार उसकी गोद में रख चुकी थी।</p>\n<p>नैना एक पल को ठिठकी।</p>\n<p>फिर उसकी उँगलियाँ अपने आप विक्रम के बालों में उतर गईं।</p>\n<p>वही लय।</p>\n<p>वही धीरज।</p>\n<p>बस इस बार सहारा देने वाला और सहारा लेने वाला बदल गए थे।</p>\n<p>और विक्रम रो पड़ा।</p>\n<p>सचमुच।</p>\n<p>नैना ने उसे इतने महीनों में इस तरह कभी नहीं देखा था।</p>\n<p>उसके कंधे काँप रहे थे।</p>\n<p>आवाज़ लगभग नहीं थी।</p>\n<p>और उसी वजह से उसका रोना और ज़्यादा गहरा लगता था—जैसे कोई इंसान जिसे ज़िंदगी ने रोना भी ठीक से नहीं सिखाया, पहली बार बिना तरीका जाने अपने दुख के सामने हार गया हो।</p>\n<p>नैना का अपना दुख कुछ देर के लिए पीछे चला गया।</p>\n<p>उसने बस उसके बालों में हाथ फेरते हुए कहा—</p>\n<p>“मैं हूँ।”</p>\n<p>विक्रम ने आँखें नहीं उठाईं।</p>\n<p>“छोड़ दो ख़ुद को।”</p>\n<p>उसकी उँगलियाँ उसके बालों में चलती रहीं।</p>\n<p>“मैं यहीं हूँ।”</p>\n<p>काफी देर बाद विक्रम ने टूटी हुई आवाज़ में कहा—</p>\n<p>“मुझे नहीं आता ये।”</p>\n<p>“शायद बचपन के बाद कभी इस तरह नहीं रोया।”</p>\n<p>उसने साँस खींची।</p>\n<p>“पता नहीं क्या करना होता है।”</p>\n<p>“कुछ नहीं करना होता।”</p>\n<p>नैना ने कहा।</p>\n<p>“बस होने दो।”</p>\n<p>उसकी हथेली उसके सिर पर टिकी रही।</p>\n<p>“जब तक ख़त्म नहीं होता, मैं कहीं नहीं जा रही।”</p>\n<p>विक्रम बहुत देर वैसे ही रहा।</p>\n<p>धीरे-धीरे उसके कंधों का काँपना कम हुआ।</p>\n<p>लेकिन उसके बाद भी दोनों ने काफी देर कुछ नहीं कहा।</p>\n<p>उस रात पहली बार नैना की ताकत ने विक्रम को उसी तरह थामा था—</p>\n<p>जैसे इतने समय से उसकी ताकत नैना को थामती आई थी।</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>भोर के करीब कमरे के बाहर आसमान का सबसे दूर वाला किनारा हल्का होने लगा।</p>\n<p>और जैसे ही रात के ख़त्म होने का पहला सबूत दिखाई दिया, नैना की बची हुई हिम्मत भी टूट गई।</p>\n<p>इस बार आँसू रेस्तराँ वाले नहीं थे।</p>\n<p>न सँभले हुए।</p>\n<p>न चुपचाप पोंछे जा सकने वाले।</p>\n<p>उसका पूरा शरीर काँप रहा था।</p>\n<p>“मुझे नहीं पता तुम्हें अलविदा कैसे कहूँ।”</p>\n<p>काफी देर बाद वह बोल पाई।</p>\n<p>आवाज़ कच्ची थी।</p>\n<p>“दिमाग को समझाने की कोशिश कर रही हूँ कि ये आख़िरी बार है।”</p>\n<p>उसने विक्रम को कसकर पकड़ लिया।</p>\n<p>“कुछ दिनों के लिए आख़िरी नहीं।”</p>\n<p>साँस टूटी।</p>\n<p>“आख़िरी।”</p>\n<p>उसकी आँखें बंद थीं।</p>\n<p>“इस पूरी ज़िंदगी में।”</p>\n<p>विक्रम की पकड़ उसके चारों ओर और कस गई।</p>\n<p>“इतनी बड़ी बात दिमाग में टिकती ही नहीं। हर बार पकड़ने की कोशिश करती हूँ तो फिसल जाती है।”</p>\n<p>“मुझे पता है।”</p>\n<p>अब विक्रम की आवाज़ भी स्थिर नहीं थी।</p>\n<p>“मैं भी पूरी रात उसे पकड़ने की कोशिश कर रहा हूँ।”</p>\n<p>नैना उसके सीने से लगी रही।</p>\n<p>“अब कभी किसी छोटी बात पर डिनर के बीच तुमसे लड़ूँगी नहीं।”</p>\n<p>उसकी आवाज़ आँसुओं में टूट रही थी।</p>\n<p>“फिर कभी इस तरह सो नहीं पाऊँगी… तुम्हारा हाथ मेरे बालों में।”</p>\n<p>एक साँस।</p>\n<p>“तुम्हारी आवाज़ फोन के दूसरी तरफ फिर कभी वैसे नहीं सुनूँगी जैसे इतने महीनों से सुनती आई हूँ।”</p>\n<p>उसने आँखें बंद कर लीं।</p>\n<p>“एक इंसान कैसे जीता है ये जानते हुए कि उसकी ज़िंदगी की इतनी सारी चीज़ें एक ही रात में आख़िरी बार हो रही हैं?”</p>\n<p>विक्रम ने उसे और करीब कर लिया।</p>\n<p>अब दोनों काँप रहे थे।</p>\n<p>“तो जितना बचा है उसे अंत गिनने में मत खर्च करो।”</p>\n<p>उसने मुश्किल से कहा।</p>\n<p>“बस यहीं रहो।”</p>\n<p>नैना ने सिर उठाया।</p>\n<p>“अभी।”</p>\n<p>विक्रम ने उसकी आँखों में देखा।</p>\n<p>“इसके बाद कुछ नहीं।”</p>\n<p>उसने माथा उसके माथे से लगा दिया।</p>\n<p>“बस ये।”</p>\n<p>नैना ने सिर हिला दिया।</p>\n<p>फिर दोनों चुप हो गए।</p>\n<p>बाहर रोशनी धीरे-धीरे बदलती रही।</p>\n<p>अंदर हर गुज़रता सेकंड दोनों को उतनी ही साफ़ क्रूरता से बता रहा था कि यह समय दोबारा कभी उनका नहीं होगा।</p>\n<p>बहुत देर बाद नैना ने कहा—</p>\n<p>“आई लव यू।”</p>\n<p>विक्रम की आँखें बंद हो गईं।</p>\n<p>“एक बार और ठीक से कहना था।”</p>\n<p>उसने उसके चेहरे को छुआ।</p>\n<p>“जब तक मुझे कहने का हक है।”</p>\n<p>आँसू फिर बह निकले।</p>\n<p>“मैं तुमसे प्यार करती हूँ, विक्रम।”</p>\n<p>फिर धीरे-धीरे—</p>\n<p>“आज के बाद मैं जो भी बनूँ… किसी की पत्नी, किसी की माँ… मेरे भीतर कहीं एक हिस्सा ज़िंदगी भर तुमसे प्यार करता रहेगा।”</p>\n<p>उसकी आवाज़ लगभग फुसफुसाहट में बदल गई।</p>\n<p>“चाहे मुझे उसकी इजाज़त हो या नहीं।”</p>\n<p>विक्रम की आँखों से भी अब आँसू निकल आए।</p>\n<p>इस बार उसने उन्हें रोका नहीं।</p>\n<p>“मैं भी तुमसे प्यार करता हूँ।”</p>\n<p>उसने कहा।</p>\n<p>“और ज़िंदगी भर करता रहूँगा।”</p>\n<p>उसने नैना का हाथ अपने हाथ में ले लिया।</p>\n<p>“दस साल बाद का मैं हो या तीस साल बाद का… मेरे किसी भी रूप के भीतर यह सुबह कहीं न कहीं रहेगी।”</p>\n<p class=\"scenebreak\">*&#160;&#160;*&#160;&#160;*</p>\n<p>जब आख़िर नैना कपड़े पहनने लगी तो उसकी उँगलियाँ इतनी काँप रही थीं कि कुर्ते के बटन ठीक से बंद नहीं हो रहे थे।</p>\n<p>विक्रम उसके सामने आकर खड़ा हो गया।</p>\n<p>कुछ नहीं कहा।</p>\n<p>बस एक-एक बटन धीरे-धीरे बंद कर दिया।</p>\n<p>उसके अपने हाथ भी पूरी तरह स्थिर नहीं थे।</p>\n<p>अब दोनों रो रहे थे।</p>\n<p>छिपाने को कुछ नहीं बचा था।</p>\n<p>दो लोग आख़िरी बार एक-दूसरे को कपड़े पहना रहे थे—</p>\n<p>उसी कोमलता से</p>\n<p>जिससे कभी पहली बार उन्होंने अपने बीच की सारी सावधानियाँ उतारी थीं।</p>\n<p>दरवाज़े पर पहुँचकर नैना रुक गई।</p>\n<p>फिर पलटी।</p>\n<p>विक्रम वहीं खड़ा था।</p>\n<p>उसने हाथ बढ़ाकर उसके चेहरे को छुआ।</p>\n<p>उँगलियाँ धीरे-धीरे उसके चेहरे पर चलीं—</p>\n<p>जैसे आँखों से याद कर लेना काफी न हो,</p>\n<p>जैसे त्वचा भी अपनी अलग स्मृति रखती हो।</p>\n<p>“ये अलविदा है।”</p>\n<p>इस बार उसने शब्द पूरा कहा।</p>\n<p>न उससे बची।</p>\n<p>न उसे नरम किया।</p>\n<p>“अगली बार तक नहीं।”</p>\n<p>उसकी आवाज़ टूट गई।</p>\n<p>“जल्दी मिलेंगे भी नहीं।”</p>\n<p>वह उसे देखती रही।</p>\n<p>“अलविदा, विक्रम।”</p>\n<p>एक आँसू उसके चेहरे से उतर गया।</p>\n<p>“उस हर ज़िंदगी के लिए भी… जो अब हमें साथ नहीं मिलेगी।”</p>\n<p>विक्रम ने उसका हाथ अपने चेहरे पर कुछ पल और रहने दिया।</p>\n<p>“अलविदा, नैना।”</p>\n<p>फिर उसकी हथेली को धीरे से पकड़ा।</p>\n<p>“हर एक दिन के लिए शुक्रिया।”</p>\n<p>उसकी आवाज़ भर्रा गई।</p>\n<p>“मैं ज़िंदगी भर इस बात के लिए शुक्रगुज़ार रहूँगा कि मुझे वे दिन मिले… ये जानते हुए भी कि आख़िर में यह सुबह आने वाली थी।”</p>\n<p>नैना एक कदम आगे बढ़ी।</p>\n<p>और उससे लिपट गई।</p>\n<p>इस बार उस आलिंगन में कुछ भी सँभला हुआ नहीं था।</p>\n<p>विक्रम ने भी उसे उतनी ही ताकत से पकड़ लिया।</p>\n<p>दरवाज़े पर दोनों बहुत देर वैसे ही खड़े रहे।</p>\n<p>किसी की हिम्मत नहीं हुई पहले हाथ ढीले करने की।</p>\n<p>नैना के आँसू उसकी शर्ट में उतरते रहे।</p>\n<p>विक्रम के आँसू उसके बालों में।</p>\n<p>अब किसी को मजबूत दिखना नहीं था।</p>\n<p>न एक-दूसरे के लिए।</p>\n<p>न अपने लिए।</p>\n<p>आख़िर नैना गई।</p>\n<p>पहला कदम उसी ने पीछे लिया।</p>\n<p>फिर दूसरा।</p>\n<p>विक्रम दरवाज़े पर खड़ा रहा।</p>\n<p>उसका हाथ अपनी पकड़ से निकलते महसूस किया।</p>\n<p>उसके कदम कॉरिडोर में धीरे-धीरे दूर होते सुने—जैसे बजरी पर कोई गाड़ी धीमी पड़ती जाए।</p>\n<p>जब तक वह दिखाई देती रही, देखता रहा।</p>\n<p>फिर वह मुड़ी।</p>\n<p>और चली गई।</p>\n<p>विक्रम फिर भी वहीं खड़ा रहा।</p>\n<p>बहुत देर तक।</p>\n<p>चेहरा आँसुओं से भीगा हुआ।</p>\n<p>बाहर सुबह की धूसर रोशनी फैल रही थी।</p>\n<p>और उसे मालूम था—</p>\n<p>नैना का हाथ उसकी पकड़ से छूटने का वह क्षण,</p>\n<p>कॉरिडोर में दूर होती उसकी आहट,</p>\n<p>उस सुबह का वही फीका रंग—</p>\n<p>यही आख़िरी स्मृति थी जो ज़िंदगी ने उन दोनों को एक-दूसरे की मौजूदगी में दी थी।</p>\n<p>इसके बाद जो कुछ रहेगा,</p>\n<p>वह याद होगा।</p>\n<p>और याद, चाहे कितनी भी सावधानी से बचाकर रखी जाए, किसी मौजूद इंसान की जगह नहीं ले सकती।</p>\n<p>जैसे आग की तस्वीर में उसका आकार तो बचा रहता है—</p>\n<p>उसकी गर्मी नहीं।</p>"}];
